window.AURA_TEAMS_DATA = [{ "index": 1, "id": "6aa4f34d64f0bd98ae1fdc42", "registrationId": "AURA2K26-UVEV4Z", "rawTeamName": "AuraInnovators_1789195081879", "folderName": "AuraInnovators_1789195081879", "folderRelPath": "assets/Teams/AuraInnovators_1789195081879", "projectTitle": "Smart Autonomous Solar UAV", "teamSize": 3, "teamAffiliation": "mixed", "aliahMembers": 2, "otherInstitutionMembers": 1, "teamLeaderName": "Tariq Ali", "teamLeaderEmail": "tariq_1789195081879@example.com", "teamLeaderPhone": "9876543210", "teamMemberDetails": "Tariq Ali | Aliah | CSE | 4th Year\r\nSamir Khan | Aliah | ECE | 3rd Year\r\nAlex Roy | IIT | ME | 3rd Year", "hardwareProjectCategories": ["Robotics", "Drone / Autonomous Systems", "AI-Enabled Hardware"], "prototypeType": "Autonomous System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Crop disease surveillance is expensive and manual. Our autonomous solar UAV surveys fields and detects pests in real time.", "solutionDescription": "Crop disease surveillance is expensive and manual. Our autonomous solar UAV surveys fields and detects pests in real time.", "innovationDescription": "Crop disease surveillance is expensive and manual. Our autonomous solar UAV surveys fields and detects pests in real time.", "workingPrinciple": "Solar panels trickle-charge custom 4S LiPo battery pack while flight controller runs PX4 autopilot and Jetson Nano processes NDVI imagery.", "majorHardwareComponents": ["Pixhawk 6C", "Jetson Nano", "Multispectral Camera", "Solar MPPT", "LiPo 4S 5000mAh"], "useAi": true, "useIot": true, "powerSource": "solar", "intendedBeneficiaries": ["Agriculture", "Rural Communities"], "potentialImpact": "Empowers smallholder farmers with low-cost early disease detection.", "productPotential": "yes", "prototypeDevelopmentCost": 25000, "auraDemoHighlight": "Live hover demonstration and live multispectral video transmission.", "safetyHazards": ["drone_flying_equipment", "high_power_batteries", "moving_rotating_machinery"], "safetyPrecautions": "Geofencing, propeller guards, automatic RTL on low battery.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-12T06:38:05.046Z", "updatedAt": "2026-10-11T17:31:06.939Z", "abstract": { "originalName": "uav_abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789195083/aura-registrations/abstract-docs/uav_abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/AuraInnovators_1789195081879/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/AuraInnovators_1789195081879/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789195083/aura-registrations/id-cards/yubry0q1m0exjr6bywe5.png", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/AuraInnovators_1789195081879/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789195083/aura-registrations/id-cards/ldzvrczpfvv64oumjcay.png", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/AuraInnovators_1789195081879/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789195083/aura-registrations/id-cards/u40oolxatgp1xaillkit.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/AuraInnovators_1789195081879/4.jpg", "url": null, "exists": false }] }, { "index": 2, "id": "6aaad470dcdc33dcd527b262", "registrationId": "AURA2K26-2BPHM7", "rawTeamName": "Proto-Electra", "folderName": "Proto-Electra", "folderRelPath": "assets/Teams/Proto-Electra", "projectTitle": "Modification of Charging and Regenerative Breaking in EVs", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "Amlan Samanta", "teamLeaderEmail": "workspace.amlan11@gmail.com", "teamLeaderPhone": "9733910946", "teamMemberDetails": "Member 1: Sumaiya Azmi, Ph No: 8101220373, Email: sumaiyaazmi2025@gmail.com\r\nMember 2: Sania Molla, Ph No: 9332633658, Email: saniamolla4739@gmail.com", "hardwareProjectCategories": ["IoT & Smart Devices", "Robotics"], "prototypeType": "Robotic System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Working on the smart wireless fast-charging concepts, regenerative braking system of EVs.", "solutionDescription": "Working on the smart wireless fast-charging concepts, regenerative braking system of EVs.", "innovationDescription": "Working on the smart wireless fast-charging concepts, regenerative braking system of EVs.", "workingPrinciple": "The system operates on an embedded real-time feedback loop managed by a central microcontroller. Ultrasonic sensors continuously emit high-frequency acoustic pulses and measure the time-of-flight of the reflected echo to determine the distance of forward obstacles. If a barrier is detected within a predefined threshold (e.g., 20 cm), the microcontroller sends PWM signals to an H-bridge motor driver, halting the DC gear motors and executing a timed directional turn to chart a clear path. Simultaneously, auxiliary analog and digital sensors (such as DHT11 for temperature/humidity) sample environmental parameters at periodic intervals. These readings are parsed and instantly updated on a local I2C display interface to provide real-time telemetry.", "majorHardwareComponents": ["Microcontroller: Arduino Uno (ATmega328P) / ESP32 development board\nSensing Units: HC-SR04 Ultrasonic Sensor", "DHT11 Temperature & Humidity Sensor\nActuation & Drive: L298N Dual H-Bridge Motor Driver Module", "2x TT Gear DC Motors", "1x Micro Servo Motor (SG90)\nPower Management: 2x 18650 Li-ion batteries (7.4V nominal) with LM2596 step-down buck converter (regulated 5V logic rail)\nDisplay & Chassis: 16x2 I2C LCD screen", "custom acrylic robot chassis", "caster wheel", "toggle switch."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public"], "potentialImpact": "Hazardous Environment Inspection: Replaces human personnel in tight, toxic, or unstable structures—such as collapsed buildings, chemical storage rooms, or underground pipelines—to assess physical integrity and ambient safety without risking human life.\r\nCost-Effective Industrial Automation: Serves as a modular, low-cost baseline for automated internal logistics, periodic warehouse monitoring, and routine floor inspections in small-to-medium enterprises (SMEs) that cannot afford complex enterprise robotic fleets.\r\nPrecision Agriculture & Greenhouses: Automates localized microclimate surveying in indoor farming facilities, detecting hot spots or humidity pockets directly at canopy level for targeted climate control.\r\nDisaster Response & First-Line Reconnaissance: Provides first responders with rapid ground-truth environmental data (air temperature, path accessibility, structural clearances) before rescue crews enter compromised disaster sites.", "productPotential": "yes", "prototypeDevelopmentCost": 6000, "auraDemoHighlight": "Tangible Autonomous Decision-Making: Unlike standard remote-controlled rovers, it demonstrates full edge-level autonomy—processing ultrasonic spatial data in real time to calculate clearances and execute collision-avoidance maneuvers without external human intervention.\r\nLow-Cost Engineering Feasibility: Proves that an industrial-grade inspection and monitoring concept can be functional, reliable, and deployable under ₹2,000 using standard embedded hardware.\r\nCompact Multi-Disciplinary Integration: Combines mechanical chassis dynamics, precise H-bridge motor driver PWM control, low-voltage power regulation, and live sensor telemetry into a single unified mobile unit.\r\nModular, Scalable Architecture: Serves as a versatile physical testbed that can be quickly upgraded with additional payload modules—such as gas detectors, thermal probes, or wireless communication—with zero foundational redesign.", "safetyHazards": ["high_voltage", "moving_rotating_machinery", "water_near_electrical_equipment"], "safetyPrecautions": "Battery Protection: Integrated BMS prevents overcharge, deep discharge, and short circuits in the 18650 Li-ion cells to eliminate fire risk.\r\nElectrical Isolation: Independent voltage regulation via an LM2596 buck converter shields sensitive microcontroller logic from inductive back-EMF voltage spikes.\r\nInductive Clamp Diodes: Built-in flyback diodes on the motor driver suppress transient surges from DC gear motors.\r\nFirmware Fail-Safes: Hard-coded emergency stall logic instantly cuts motor power if forward distance drops below a critical threshold (under 5 cm).", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-16T17:40:00.944Z", "updatedAt": "2026-10-11T17:31:18.45Z", "abstract": { "originalName": "EV_Wireless_Charging_Regen_Abstract (1).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789580399/aura-registrations/abstract-docs/EV_Wireless_Charging_Regen_Abstract%20%281%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Proto-Electra/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Proto-Electra/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789580399/aura-registrations/id-cards/y24o32paooxuwiqteubn.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Proto-Electra/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789580399/aura-registrations/id-cards/v2vh3tslcr80d0zywuap.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Proto-Electra/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789580399/aura-registrations/id-cards/ncjwssdarbrhwzzpoclo.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Proto-Electra/4.jpg", "url": null, "exists": false }] }, { "index": 3, "id": "6aab8e37d78f9ec1b3b4926a", "registrationId": "AURA2K26-DE3VV6", "rawTeamName": "Rising Alpha", "folderName": "Rising Alpha", "folderRelPath": "assets/Teams/Rising Alpha", "projectTitle": "FIREGAURD AUTONOMOUS FIRE - RESPONSE ROBOT CAR", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "Sudipta Manna", "teamLeaderEmail": "sudiptamanna946@gmail.com", "teamLeaderPhone": "9339742946", "teamMemberDetails": "Md Ibrahim Sk    |    Aliah University (Newtown)   |    Electrical Engineering   |   2nd  Year   |    7384762656\r\nMd Iunus Nabi Biswas   |   Aliah university (Newtown)   |    Electrical Engineering   |   2nd Year   |   9641294933", "hardwareProjectCategories": ["Robotics", "Embedded Systems", "Automation & Control", "Mechatronics", "Safety & Security Systems"], "prototypeType": "Autonomous System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Problem Statement:\r\nFire incidents can spread rapidly, while approaching a fire manually can expose people to high temperature, smoke, flames, and other hazards. Conventional firefighting methods may also face difficulties when the fire location is difficult or unsafe to access. A compact autonomous system capable of detecting and responding to a fire can help reduce human exposure during initial firefighting.\r\nHardware Solution:\r\nWe propose FireGuard, an autonomous fire-response robotic vehicle based on an ESP32 microcontroller. The robot uses multiple flame sensors to detect the direction of a fire and a temperature sensor to monitor the surrounding thermal condition. It autonomously moves toward the detected fire and uses ultrasonic sensing mounted on a servo mechanism to detect obstacles and select a safer path. A motor-driven water pump and directional nozzle are used to spray water toward the detected fire. An audio module and speaker provide alerts such as “Fire detected” during operation.\r\nInnovation:\r\nThe innovation lies in integrating fire detection, temperature monitoring, autonomous movement, obstacle avoidance, directional firefighting, and audio alerting into a single compact robotic platform. The system prioritizes fire-response safety by allowing obstacle detection to override movement commands when an obstacle is encountered.", "solutionDescription": "Problem Statement:\r\nFire incidents can spread rapidly, while approaching a fire manually can expose people to high temperature, smoke, flames, and other hazards. Conventional firefighting methods may also face difficulties when the fire location is difficult or unsafe to access. A compact autonomous system capable of detecting and responding to a fire can help reduce human exposure during initial firefighting.\r\nHardware Solution:\r\nWe propose FireGuard, an autonomous fire-response robotic vehicle based on an ESP32 microcontroller. The robot uses multiple flame sensors to detect the direction of a fire and a temperature sensor to monitor the surrounding thermal condition. It autonomously moves toward the detected fire and uses ultrasonic sensing mounted on a servo mechanism to detect obstacles and select a safer path. A motor-driven water pump and directional nozzle are used to spray water toward the detected fire. An audio module and speaker provide alerts such as “Fire detected” during operation.\r\nInnovation:\r\nThe innovation lies in integrating fire detection, temperature monitoring, autonomous movement, obstacle avoidance, directional firefighting, and audio alerting into a single compact robotic platform. The system prioritizes fire-response safety by allowing obstacle detection to override movement commands when an obstacle is encountered.", "innovationDescription": "Problem Statement:\r\nFire incidents can spread rapidly, while approaching a fire manually can expose people to high temperature, smoke, flames, and other hazards. Conventional firefighting methods may also face difficulties when the fire location is difficult or unsafe to access. A compact autonomous system capable of detecting and responding to a fire can help reduce human exposure during initial firefighting.\r\nHardware Solution:\r\nWe propose FireGuard, an autonomous fire-response robotic vehicle based on an ESP32 microcontroller. The robot uses multiple flame sensors to detect the direction of a fire and a temperature sensor to monitor the surrounding thermal condition. It autonomously moves toward the detected fire and uses ultrasonic sensing mounted on a servo mechanism to detect obstacles and select a safer path. A motor-driven water pump and directional nozzle are used to spray water toward the detected fire. An audio module and speaker provide alerts such as “Fire detected” during operation.\r\nInnovation:\r\nThe innovation lies in integrating fire detection, temperature monitoring, autonomous movement, obstacle avoidance, directional firefighting, and audio alerting into a single compact robotic platform. The system prioritizes fire-response safety by allowing obstacle detection to override movement commands when an obstacle is encountered.", "workingPrinciple": "FireGuard Autonomous Fire-Response Robot Car is designed as an embedded autonomous robotic system controlled by an ESP32 microcontroller. The system integrates fire detection, temperature monitoring, obstacle avoidance, navigation toward the fire, and water-based fire suppression.\r\nThe workflow begins with three flame sensors positioned to detect the presence and approximate direction of a flame. When a flame is detected, the ESP32 processes the sensor signals and determines the direction in which the robot should move. A temperature sensor provides additional information about the surrounding thermal condition and can support fire-event confirmation.\r\nDuring movement, an ultrasonic sensor mounted on a servo motor continuously scans the surroundings. The ultrasonic sensor measures the distance to obstacles using the time-of-flight principle. If an obstacle is detected in the robot's path, the ESP32 gives obstacle avoidance higher priority than normal movement. The servo rotates the ultrasonic sensor to scan different directions, allowing the controller to select a safer available path and adjust the robot's movement.\r\nAfter reaching a suitable position near the detected fire, the ESP32 activates a DC water pump through a motor/relay driver. Water is delivered through a directional nozzle toward the detected flame. The flame-sensor readings can be used to determine the required spraying direction.\r\nAn audio module and speaker provide predefined voice alerts, such as “Fire detected” or “Fire alarm.” The entire system operates according to programmed decision logic, enabling automatic sensing, movement, obstacle avoidance, and fire-response actions with minimal human intervention.", "majorHardwareComponents": ["ESP32 Development Board – Main controller for sensing", "decision-making and control.\n3× Flame Sensors – Detect the presence and direction of fire.\nTemperature Sensor – Monitors surrounding temperature.\nUltrasonic Sensor (HC-SR04) – Detects obstacles and measures distance.\nServo Motor – Rotates the ultrasonic sensor for environmental scanning.\n4× DC Gear Motors – Drive the four wheels of the robot.\nMotor Driver – Controls the direction and speed of the DC motors.\nDC Water Pump – Pumps water for fire suppression.\nServo Motor / Nozzle Mechanism – Directs the water spray toward the fire.\nAudio Module + Speaker – Provides predefined fire-alert messages.\nBattery/Power Supply – Provides power to the controller", "motors", "sensors and pump.\nRobot Chassis & Wheels – Mechanical structure of the vehicle."], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Industry", "Rural Communities", "Urban Communities", "Government / Public Services"], "potentialImpact": "FireGuard can benefit firefighters, industrial workers, building occupants, and communities by providing an autonomous first-response system for small or developing fire incidents. It can be particularly useful in locations where approaching a fire may expose people to heat, smoke, or other hazards.\r\nCompared with conventional manual first-response methods, FireGuard aims to improve safety and response by combining multiple functions in one robotic platform. It can detect a flame, monitor temperature, move toward the detected fire, identify obstacles and change its path, and activate a water pump for suppression. An audio alert can also notify nearby people of fire detection. The integration of automatic sensing, movement, obstacle avoidance, and firefighting reduces the need for continuous human intervention during the initial response.\r\nThe system is designed as a low-cost, compact prototype that can potentially be adapted for indoor industrial areas, workshops, warehouses, and other suitable environments.", "productPotential": "potentially", "prototypeDevelopmentCost": 3500, "auraDemoHighlight": "FireGuard stands out because it brings together fire detection, autonomous movement, obstacle avoidance, and initial fire suppression in a single compact robotic platform. Instead of requiring a person to immediately approach a potentially dangerous fire, the robot is designed to detect the fire, determine its direction, move toward it, and respond by activating a water-spraying mechanism.\r\nThe most impressive aspect of FireGuard is its priority-based autonomous decision-making. While moving toward a fire, the robot continuously checks its surroundings using an ultrasonic sensor. If an obstacle appears, obstacle avoidance takes priority over the fire-directed movement, allowing the robot to search for a safer path rather than simply continuing forward.\r\nThe use of multiple flame sensors also enables the robot to estimate the direction of the fire, while a temperature sensor provides additional environmental information. A servo-mounted ultrasonic sensor allows wider environmental scanning, and an audio module can provide immediate alerts when fire is detected.\r\nFireGuard is not presented as a replacement for professional firefighting systems. Instead, it demonstrates how embedded electronics, sensors, robotics, and automatic decision-making can work together to create a potential first-response safety system. Its modular design also provides scope for future improvements and real-world adaptation.", "safetyHazards": ["high_temperature", "moving_rotating_machinery", "fire_combustion", "water_near_electrical_equipment"], "safetyPrecautions": "The proposed FireGuard robot incorporates multiple safeguards to improve the safety of the system and people nearby. The ESP32 control system will include an emergency stop/power-disconnection mechanism so the robot can be stopped immediately during abnormal operation. Obstacle detection using the ultrasonic sensor will have higher priority than normal movement, helping prevent collisions. The motors, servo mechanisms and rotating parts will be securely mounted, with wiring routed away from moving components. Electrical connections will be insulated and the battery/power section will be securely enclosed and protected against short circuits or overheating. \r\n\r\nBecause the system uses water near electronic components, the water tank, pump and tubing will be physically separated from sensitive electronics and checked for leakage. The robot will not be intended for use on energized electrical fires, since water can create serious electrical hazards. \r\n\r\nFire-related testing, if conducted, will be performed only under responsible adult supervision in a controlled environment with appropriate fire-safety arrangements. The prototype will also include an audio alert such as “Fire detected” to provide an immediate warning.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-17T06:52:39.675Z", "updatedAt": "2026-10-11T17:31:25.835Z", "abstract": { "originalName": "Project Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789627959/aura-registrations/abstract-docs/Project%20Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Rising Alpha/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Rising Alpha/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789627958/aura-registrations/id-cards/g181wycyjilvx6beewg4.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Rising Alpha/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789627958/aura-registrations/id-cards/wcpvlnrprew8exltk6d3.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Rising Alpha/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789627958/aura-registrations/id-cards/zitk6rbfzeilayrbribi.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Rising Alpha/4.jpg", "url": null, "exists": false }] }, { "index": 4, "id": "6aafaabd6a8988e44e2def9f", "registrationId": "AURA2K26-B3WW38", "rawTeamName": "ResQBot", "folderName": "ResQBot", "folderRelPath": "assets/Teams/ResQBot", "projectTitle": "Smart Search and Rescue Rover for Hazardous Environment", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Vivek Kumar Thakur", "teamLeaderEmail": "vivekkumarthakur744@gmail.com", "teamLeaderPhone": "6296469997", "teamMemberDetails": "Sukanta Pal | Aliah University | Electronics  and Communication | 3rd Year | 9647126162\r\nSamir Maity | Aliah University | Electronics  and Communication | 3rd Year | 8392048750\r\nMousumi Paul | Aliah University | Electronics  and Communication | 3rd Year | 8927843793", "hardwareProjectCategories": ["IoT & Smart Devices", "Robotics", "Embedded Systems", "Electronics & Communication"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Problem Statement\r\nDuring disasters such as earthquakes, building collapses, mine accidents, cylinder blasts, fires, and industrial accidents, rescue teams may have to enter areas containing smoke, toxic gases, high temperatures, unstable structures, and hidden obstacles. Entering such areas without knowing the conditions can expose rescuers to additional danger.\r\nThere is a need for a low-cost, remotely operated system that can enter a hazardous area first and provide rescuers with real-time information about the environment.\r\n2. Proposed Solution\r\nResQBot is a compact, remotely operated search-and-rescue rover designed to act as a first-response reconnaissance system. The rover can be deployed into an affected area and remotely controlled through a wireless connection.\r\nIt provides:\r\n1. Live video for visual inspection\r\n2. Gas/smoke detection using MQ-2\r\n3. Temperature monitoring using DHT11\r\n4. Obstacle/distance detection using HC-SR04\r\n5. Hazard alerts using buzzer and LEDs\r\n6. 4-wheel movement for indoor navigation\r\n7. Wireless communication with the operator\r\nThe collected information helps rescue teams assess hazardous conditions before physically entering the area.\r\n3. Innovation Details\r\n1. Multi-Sensor Hazard Reconnaissance\r\nResQBot combines visual, gas, temperature, and distance sensing in one platform, providing a broader picture of the hazardous environment rather than relying only on a camera.\r\n2. Low-Cost Implementation\r\nThe system uses an ESP32-S3-based platform and readily available components, making the prototype accessible for low-cost rescue and disaster-response applications.\r\n3. Human-First-Responder Approach\r\nResQBot acts as a robotic scout, entering hazardous areas ahead of rescuers and providing information that can support safer human intervention.\r\n4. Modular Architecture\r\nThe platform can be upgraded according to the disaster scenario with thermal cameras, advanced gas sensors, microphones/speakers, or AI-based person detection. The ground rover can also be adapted into a tracked/stair-climbing robot or a drone/quadrotor for rough, inaccessible, or aerial environments.\r\n5. Remote Operation\r\nThe operator can control ResQBot from a safer location while receiving live video and sensor information, enabling remote assessment of the affected area.", "solutionDescription": "1. Problem Statement\r\nDuring disasters such as earthquakes, building collapses, mine accidents, cylinder blasts, fires, and industrial accidents, rescue teams may have to enter areas containing smoke, toxic gases, high temperatures, unstable structures, and hidden obstacles. Entering such areas without knowing the conditions can expose rescuers to additional danger.\r\nThere is a need for a low-cost, remotely operated system that can enter a hazardous area first and provide rescuers with real-time information about the environment.\r\n2. Proposed Solution\r\nResQBot is a compact, remotely operated search-and-rescue rover designed to act as a first-response reconnaissance system. The rover can be deployed into an affected area and remotely controlled through a wireless connection.\r\nIt provides:\r\n1. Live video for visual inspection\r\n2. Gas/smoke detection using MQ-2\r\n3. Temperature monitoring using DHT11\r\n4. Obstacle/distance detection using HC-SR04\r\n5. Hazard alerts using buzzer and LEDs\r\n6. 4-wheel movement for indoor navigation\r\n7. Wireless communication with the operator\r\nThe collected information helps rescue teams assess hazardous conditions before physically entering the area.\r\n3. Innovation Details\r\n1. Multi-Sensor Hazard Reconnaissance\r\nResQBot combines visual, gas, temperature, and distance sensing in one platform, providing a broader picture of the hazardous environment rather than relying only on a camera.\r\n2. Low-Cost Implementation\r\nThe system uses an ESP32-S3-based platform and readily available components, making the prototype accessible for low-cost rescue and disaster-response applications.\r\n3. Human-First-Responder Approach\r\nResQBot acts as a robotic scout, entering hazardous areas ahead of rescuers and providing information that can support safer human intervention.\r\n4. Modular Architecture\r\nThe platform can be upgraded according to the disaster scenario with thermal cameras, advanced gas sensors, microphones/speakers, or AI-based person detection. The ground rover can also be adapted into a tracked/stair-climbing robot or a drone/quadrotor for rough, inaccessible, or aerial environments.\r\n5. Remote Operation\r\nThe operator can control ResQBot from a safer location while receiving live video and sensor information, enabling remote assessment of the affected area.", "innovationDescription": "1. Problem Statement\r\nDuring disasters such as earthquakes, building collapses, mine accidents, cylinder blasts, fires, and industrial accidents, rescue teams may have to enter areas containing smoke, toxic gases, high temperatures, unstable structures, and hidden obstacles. Entering such areas without knowing the conditions can expose rescuers to additional danger.\r\nThere is a need for a low-cost, remotely operated system that can enter a hazardous area first and provide rescuers with real-time information about the environment.\r\n2. Proposed Solution\r\nResQBot is a compact, remotely operated search-and-rescue rover designed to act as a first-response reconnaissance system. The rover can be deployed into an affected area and remotely controlled through a wireless connection.\r\nIt provides:\r\n1. Live video for visual inspection\r\n2. Gas/smoke detection using MQ-2\r\n3. Temperature monitoring using DHT11\r\n4. Obstacle/distance detection using HC-SR04\r\n5. Hazard alerts using buzzer and LEDs\r\n6. 4-wheel movement for indoor navigation\r\n7. Wireless communication with the operator\r\nThe collected information helps rescue teams assess hazardous conditions before physically entering the area.\r\n3. Innovation Details\r\n1. Multi-Sensor Hazard Reconnaissance\r\nResQBot combines visual, gas, temperature, and distance sensing in one platform, providing a broader picture of the hazardous environment rather than relying only on a camera.\r\n2. Low-Cost Implementation\r\nThe system uses an ESP32-S3-based platform and readily available components, making the prototype accessible for low-cost rescue and disaster-response applications.\r\n3. Human-First-Responder Approach\r\nResQBot acts as a robotic scout, entering hazardous areas ahead of rescuers and providing information that can support safer human intervention.\r\n4. Modular Architecture\r\nThe platform can be upgraded according to the disaster scenario with thermal cameras, advanced gas sensors, microphones/speakers, or AI-based person detection. The ground rover can also be adapted into a tracked/stair-climbing robot or a drone/quadrotor for rough, inaccessible, or aerial environments.\r\n5. Remote Operation\r\nThe operator can control ResQBot from a safer location while receiving live video and sensor information, enabling remote assessment of the affected area.", "workingPrinciple": "ResQBot is a remotely operated search-and-rescue robot designed to inspect hazardous environments and provide real-time information to rescuers. The ESP32-S3 acts as the main controller, coordinating the camera, sensors, motors, alerts, and wireless communication.\r\nPower & Initialization: The battery powers the ESP32-S3, camera, sensors, and motor driver. The system initializes and establishes Wi-Fi communication with the operator.\r\nRemote Movement: The operator sends movement commands wirelessly. The ESP32-S3 controls the motor driver to operate the four motors, allowing forward, backward, left, and right movement.\r\nLive Monitoring: The camera captures and transmits live video, allowing operators to inspect the affected area remotely.\r\nEnvironmental Monitoring: The MQ-2 detects smoke and combustible gases, the DHT11 measures temperature and humidity, and the HC-SR04 detects nearby obstacles.\r\nHazard Alerts: When sensor readings cross predefined limits, the ESP32-S3 activates the buzzer and LEDs to alert the operator.\r\nData Transmission: Sensor readings and camera information are transmitted wirelessly to the operator for continuous monitoring.\r\nWorking Flow:\r\nSensors + Camera → ESP32-S3 → Wi-Fi → Operator\r\nOperator → Wi-Fi → ESP32-S3 → Motor Driver → Motors", "majorHardwareComponents": ["ESP32 S3 WROOM 1 N16R8 module - Microcontroller board\nMQ-2 - Gas/Smoke Sensor \nDHT11 - Temperature Sensor\nHC-SR04 - Ultrasonic Sensor\nL298N - Motor Driver\n4WD Robot chassis and wheels", "SG90 - Servo Motor\n18650 Li-ion batteries - Power Supply\nLM296 DC-DC Buck controller \nBuzzers", "LEDs", "Resistors", "Jumper wires", "Breadboard"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Healthcare", "Government / Public Services"], "potentialImpact": "Improves rescuer safety: Allows hazardous areas to be inspected remotely before rescuers enter.\r\nFaster situation assessment: Live video and sensor data can help teams understand conditions such as smoke, gas, temperature, and obstacles.\r\nEarly hazard detection: Gas/smoke and temperature monitoring can provide warnings about potentially dangerous conditions.\r\nUseful in multiple emergencies: The concept can be adapted for fires, building collapses, industrial accidents, gas leaks, and other hazardous indoor environments.\r\nLow-cost accessibility: Uses relatively affordable and widely available components, making the concept suitable for educational institutions, emergency-response research, and future low-cost deployments.\r\nExpandable for future needs: Thermal imaging, improved gas sensing, audio communication, AI-based person detection, tracked mobility, or aerial platforms could extend its capabilities.", "productPotential": "yes", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "Real-World Problem: Designed around situations such as earthquake, building collapses, mine accidents, fires, cylinder blasts, and industrial accidents.\r\n1. Live Remote Monitoring: Provides real-time video and sensor information while the operator remains at a safer distance.\r\n2. Multiple Hazard Sensors: Combines gas/smoke, temperature, humidity, and obstacle detection in one compact platform.\r\n3. Practical Robotics: Integrates ESP32-S3, wireless communication, motor control, sensing, and camera streaming into a single working system.\r\n4. Upgradeable Design: The platform can be expanded with thermal cameras, advanced gas sensors, audio communication, and AI-based person detection.\r\n5. Future Adaptability: The core system can potentially be adapted to different robotic platforms, including tracked/stair-climbing robots or aerial drones, depending on the environment.\r\n6. Low-Cost Approach: Uses accessible hardware to demonstrate a concept that can be further developed into a more capable disaster-response system.", "safetyHazards": ["none", "water_near_electrical_equipment"], "safetyPrecautions": "Protected power connections: Proper voltage regulation and insulated connections are used to prevent short circuits and component damage.\r\nBattery safety: Li-ion batteries are securely mounted and handled using appropriate charging and protection circuitry.\r\nSecure wiring: Jumper wires and electronic modules are firmly connected and insulated to reduce the risk of loose connections.\r\nMotor safety: Moving parts are kept clear during testing, and the motors are operated only when the rover is in a safe position.\r\nRemote operation: The rover is controlled from a safe distance to reduce direct exposure to hazardous environments.\r\nSensor limitations considered: Sensor readings are treated as indicative information, not as certified life-safety measurements.\r\nEnvironmental limits: The prototype is not intentionally exposed to extreme heat, active flames, explosive atmospheres, or structurally unstable areas during testing.\r\nControlled testing: Individual sensors, motors, and communication modules are tested separately before full-system operation.\r\nEmergency shutdown: A physical ON/OFF switch is provided to quickly disconnect the system's power when required.\r\nHuman safety priority: ResQBot is intended to assist professional rescue operations and does not replace trained personnel or certified safety equipment.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-20T09:43:25.988Z", "updatedAt": "2026-10-11T17:31:30.438Z", "abstract": { "originalName": "AI_Search_and_Rescue_Robot_Abstract.docx - Google Docs.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789897405/aura-registrations/abstract-docs/AI_Search_and_Rescue_Robot_Abstract.docx%20-%20Google%20Docs.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/ResQBot/Abstract.pdf", "isDocx": false, "exists": true, "extractedText": "" }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/ResQBot/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789897405/aura-registrations/id-cards/d3dlq5ep1r5srayz1xlg.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/ResQBot/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789897405/aura-registrations/id-cards/jaasqy5kz1xckkee2p7a.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/ResQBot/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789897405/aura-registrations/id-cards/zeqhksopj4cmyoyharqq.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/ResQBot/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1789897405/aura-registrations/id-cards/zgmdjyhatjax05qosy72.jpg", "exists": true }] }, { "index": 5, "id": "6ab148e942e7208b6f7b2503", "registrationId": "AURA2K26-8SV27G", "rawTeamName": "TEAM- AXO TRACK", "folderName": "TEAM- AXO TRACK", "folderRelPath": "assets/Teams/TEAM- AXO TRACK", "projectTitle": "AI-Based Multisensor Railway Track Health Monitoring and Smart Analysis System", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "ARSHIL AHAMED MOLLAH", "teamLeaderEmail": "arshilmollah@gmail.com", "teamLeaderPhone": "9883004410", "teamMemberDetails": "1. SK MOHAMMAD ALI -  ALIAH UNIVERSITY- ELECTRICAL ENGINEERING- 3RD YR-  9332309632\r\n2. SOYEB AKHTAR- ALIAH UNIVERSITY- ELECTRICAL ENGINEERING-  3RD YR-  9002317678\r\n3. SK KHADEM ALI- ALIAH UNIVERSITY- ELECTRICAL ENGINEERING- 2ND YR-  967148783", "hardwareProjectCategories": ["IoT & Smart Devices"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Problem Statement-\r\nRailway tracks are continuously subjected to heavy loads, vibration, weather conditions, corrosion, and mechanical stress. These factors can lead to cracks, surface defects, deformation, and other track irregularities. If such defects are not identified and monitored at an early stage, they may develop further and require costly maintenance. Conventional inspection can also be time-consuming and may not provide continuous monitoring of every track section.\r\nThe key problem addressed by TEAM AXO TRACK is to develop an automated, affordable, and intelligent railway track inspection system capable of detecting defects, identifying their location, analyzing their severity, and maintaining a digital record of track condition.\r\n\r\n2. Proposed Solution-\r\nTEAM AXO TRACK proposes an AI-based multisensor railway track health monitoring system mounted on a small inspection vehicle. The vehicle travels along a railway-track prototype and continuously collects inspection data.\r\nA camera module captures images of the rail and uses computer vision/AI to identify visible cracks and surface defects. An ultrasonic sensor provides additional measurements that can help identify changes in rail condition or geometry. A wheel encoder or GPS/GNSS module records the position of detected anomalies.\r\nAll collected data are processed by a Smart Analyzer, which combines the sensor information and evaluates the condition of each inspected track section. The system generates a prototype Track Health Index and categorizes the condition as Normal, Warning, or Critical according to predefined project thresholds.\r\nThe system also generates a Track Health Report containing defect images, locations, sensor readings, detection confidence, health status, and inspection history.\r\n\r\n3. Innovation-\r\nThe major innovation of AXO TRACK is the integration of AI-based crack detection, ultrasonic sensing, location tracking, sensor-data analysis, and automated health reporting into one platform.\r\nInstead of simply detecting a crack, the system provides a broader assessment:\r\nDetect → Locate → Analyze → Assess → Report\r\nKey innovative features include:\r\nAI-based visual crack and defect detection\r\nMultisensor data fusion\r\nRail deformation/irregularity monitoring\r\nDefect location mapping\r\nTrack Health Index\r\nHistorical health comparison\r\nAutomated digital inspection reports\r\nReal-time dashboard and alerts\r\n\r\nThus, AXO TRACK aims to transform a basic railway defect detector into an intelligent track-health monitoring and inspection system suitable for prototype-level demonstration and future development.", "solutionDescription": "1. Problem Statement-\r\nRailway tracks are continuously subjected to heavy loads, vibration, weather conditions, corrosion, and mechanical stress. These factors can lead to cracks, surface defects, deformation, and other track irregularities. If such defects are not identified and monitored at an early stage, they may develop further and require costly maintenance. Conventional inspection can also be time-consuming and may not provide continuous monitoring of every track section.\r\nThe key problem addressed by TEAM AXO TRACK is to develop an automated, affordable, and intelligent railway track inspection system capable of detecting defects, identifying their location, analyzing their severity, and maintaining a digital record of track condition.\r\n\r\n2. Proposed Solution-\r\nTEAM AXO TRACK proposes an AI-based multisensor railway track health monitoring system mounted on a small inspection vehicle. The vehicle travels along a railway-track prototype and continuously collects inspection data.\r\nA camera module captures images of the rail and uses computer vision/AI to identify visible cracks and surface defects. An ultrasonic sensor provides additional measurements that can help identify changes in rail condition or geometry. A wheel encoder or GPS/GNSS module records the position of detected anomalies.\r\nAll collected data are processed by a Smart Analyzer, which combines the sensor information and evaluates the condition of each inspected track section. The system generates a prototype Track Health Index and categorizes the condition as Normal, Warning, or Critical according to predefined project thresholds.\r\nThe system also generates a Track Health Report containing defect images, locations, sensor readings, detection confidence, health status, and inspection history.\r\n\r\n3. Innovation-\r\nThe major innovation of AXO TRACK is the integration of AI-based crack detection, ultrasonic sensing, location tracking, sensor-data analysis, and automated health reporting into one platform.\r\nInstead of simply detecting a crack, the system provides a broader assessment:\r\nDetect → Locate → Analyze → Assess → Report\r\nKey innovative features include:\r\nAI-based visual crack and defect detection\r\nMultisensor data fusion\r\nRail deformation/irregularity monitoring\r\nDefect location mapping\r\nTrack Health Index\r\nHistorical health comparison\r\nAutomated digital inspection reports\r\nReal-time dashboard and alerts\r\n\r\nThus, AXO TRACK aims to transform a basic railway defect detector into an intelligent track-health monitoring and inspection system suitable for prototype-level demonstration and future development.", "innovationDescription": "1. Problem Statement-\r\nRailway tracks are continuously subjected to heavy loads, vibration, weather conditions, corrosion, and mechanical stress. These factors can lead to cracks, surface defects, deformation, and other track irregularities. If such defects are not identified and monitored at an early stage, they may develop further and require costly maintenance. Conventional inspection can also be time-consuming and may not provide continuous monitoring of every track section.\r\nThe key problem addressed by TEAM AXO TRACK is to develop an automated, affordable, and intelligent railway track inspection system capable of detecting defects, identifying their location, analyzing their severity, and maintaining a digital record of track condition.\r\n\r\n2. Proposed Solution-\r\nTEAM AXO TRACK proposes an AI-based multisensor railway track health monitoring system mounted on a small inspection vehicle. The vehicle travels along a railway-track prototype and continuously collects inspection data.\r\nA camera module captures images of the rail and uses computer vision/AI to identify visible cracks and surface defects. An ultrasonic sensor provides additional measurements that can help identify changes in rail condition or geometry. A wheel encoder or GPS/GNSS module records the position of detected anomalies.\r\nAll collected data are processed by a Smart Analyzer, which combines the sensor information and evaluates the condition of each inspected track section. The system generates a prototype Track Health Index and categorizes the condition as Normal, Warning, or Critical according to predefined project thresholds.\r\nThe system also generates a Track Health Report containing defect images, locations, sensor readings, detection confidence, health status, and inspection history.\r\n\r\n3. Innovation-\r\nThe major innovation of AXO TRACK is the integration of AI-based crack detection, ultrasonic sensing, location tracking, sensor-data analysis, and automated health reporting into one platform.\r\nInstead of simply detecting a crack, the system provides a broader assessment:\r\nDetect → Locate → Analyze → Assess → Report\r\nKey innovative features include:\r\nAI-based visual crack and defect detection\r\nMultisensor data fusion\r\nRail deformation/irregularity monitoring\r\nDefect location mapping\r\nTrack Health Index\r\nHistorical health comparison\r\nAutomated digital inspection reports\r\nReal-time dashboard and alerts\r\n\r\nThus, AXO TRACK aims to transform a basic railway defect detector into an intelligent track-health monitoring and inspection system suitable for prototype-level demonstration and future development.", "workingPrinciple": "## WORKING PRINCIPLE\r\n\r\nThe **TEAM AXO TRACK** system works by continuously scanning a railway track using a mobile inspection vehicle equipped with a **camera, ultrasonic sensor, and location measurement system**. The vehicle moves along the track and collects data from different sections.\r\n\r\nFirst, the **camera module** continuously captures images or video of the railway rails. An AI-based computer vision system processes these images to identify **visible cracks, surface defects, and geometric irregularities**. The detected defects are marked along with their approximate position and confidence level.\r\n\r\nAt the same time, the **ultrasonic sensor** collects distance-related measurements from the rail and surrounding track structure. These measurements provide additional information that can help identify abnormal changes in track condition or geometry.\r\n\r\nA **wheel encoder** measures the distance travelled by the inspection vehicle, allowing each detected defect to be associated with a specific position on the track. GPS/GNSS can be used when the system is tested outdoors.\r\n\r\nThe collected camera, ultrasonic, and location data are transferred to the **Smart Analyzer**, where the information is combined and analyzed. Based on predefined project thresholds, the system determines the condition of the inspected track section and generates a **Track Health Index**.\r\n\r\nFinally, the system produces a **Track Health Report** containing detected defects, locations, images, sensor measurements, severity, and health status. Historical reports can also be compared to monitor changes in track condition over time.\r\n\r\n**Overall Process:**\r\n**Track Scanning → Data Collection → AI Detection → Sensor Fusion → Health Analysis → Track Health Index → Digital Report**", "majorHardwareComponents": ["1.RASPBERRY Pi.\n2.ULTRASONIC SENSOR.\n3.CAMERA MODULE.\n4.GPS MODULE.\n5.BUZZER."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Transportation"], "potentialImpact": "POTENTIAL OF THE PROJECT-\r\n\r\nThe project has significant potential for developing a smart, automated, and scalable railway track monitoring system. By combining AI-based image analysis with ultrasonic sensing and location tracking, the system can move beyond traditional periodic inspection toward continuous and data-driven track condition monitoring.\r\n\r\nIts potential applications include:\r\n\r\nEarly identification of visible cracks and surface defects\r\nDetection and monitoring of track deformation and irregularities\r\nAutomated mapping of defects to their locations\r\nGeneration of digital track health records\r\nComparison of track conditions over multiple inspections\r\nSupporting maintenance teams in identifying sections that need detailed inspection\r\nReducing manual inspection effort and inspection time\r\nIntegration with railway monitoring and maintenance systems\r\n\r\nWith further development, the system could incorporate larger datasets, improved AI models, higher-resolution cameras, advanced ultrasonic inspection techniques, and cloud-based data storage. This could enable predictive maintenance, where changes in track condition are monitored over time and maintenance can be planned before defects become more serious.\r\n\r\nThe concept can also be adapted for railway inspection robots, autonomous vehicles, metro systems, industrial rail networks, and other rail-based infrastructure.\r\n\r\nOverall, the project provides a foundation for transforming railway inspection from a mainly manual process into a smart, automated, data-driven track monitoring system.", "productPotential": "yes", "prototypeDevelopmentCost": 4000, "auraDemoHighlight": "## WHY IS THE PROJECT WORTH SELLING IN INDIA?\r\n\r\nIndia has one of the world’s largest railway networks, creating a strong need for efficient and reliable track inspection and maintenance. This project has commercial potential because it combines **AI-based visual inspection, ultrasonic sensing, location tracking, and automated reporting** in a compact system.\r\n\r\nIts key value in India includes:\r\n\r\n* **Reduces manual inspection effort** by automating initial defect detection.\r\n* **Saves time and resources** by quickly identifying sections requiring detailed inspection.\r\n* **Detects visible cracks and surface defects** at an early stage.\r\n* **Provides accurate defect locations** for easier follow-up inspection.\r\n* **Generates digital Track Health Reports**, improving maintenance record management.\r\n* **Offers a scalable solution** for railway networks, metro systems, industrial railways, and private railway infrastructure.\r\n* **Supports future predictive maintenance** through historical track-condition data.\r\n\r\nThe system can be developed as a **cost-effective Indian railway technology solution**, with opportunities for hardware sales, inspection services, software, and maintenance support.\r\n\r\n**Selling Point:**\r\n“An AI-powered, affordable railway inspection platform designed to make track monitoring faster, smarter, and more data-driven for India’s growing railway infrastructure.”\r\n\r\nActual railway deployment would require extensive field validation and compliance with applicable railway safety standards.", "safetyHazards": ["none"], "safetyPrecautions": "SAFETY PRECAUTIONS BUILT INTO THE PROTOTYPE\r\n\r\nThe prototype is designed with basic safety features to ensure safe operation of the inspection vehicle and its electronic components.\r\n\r\nLow-voltage operation: The prototype uses low-voltage DC power to reduce electrical hazards.\r\nInsulated wiring: Proper insulation and secure connections help prevent short circuits and accidental contact.\r\nProtected electronics:  The Raspberry Pi, sensors, and other electronic components are securely mounted inside a protective enclosure.\r\nEmergency stop:  A manual stop control can immediately stop the vehicle's motors during testing.\r\nMotor control: Motor speed is kept low to prevent sudden movement and reduce the risk of mechanical damage.\r\nObstacle protection:  The vehicle is operated at controlled speed and can be stopped if an obstacle is detected.\r\nBattery protection:  Appropriate voltage regulation and battery protection are used to prevent overvoltage and overheating.\r\nSecure sensor mounting:  Camera and ultrasonic sensors are firmly mounted to maintain stable measurements during movement.\r\nControlled testing environment:  Testing is performed on a miniature prototype track in a controlled area, away from operational railway lines.\r\nSoftware safety: The system can generate warnings when abnormal sensor readings or system conditions are detected.\r\n\r\nThese precautions make the prototype safer for **laboratory and demonstration use** while providing a foundation for additional safety measures required for future real-world railway deployment.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-21T15:10:33.556Z", "updatedAt": "2026-10-11T17:31:35.419Z", "abstract": { "originalName": "abstract 1.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1790002742/aura-registrations/abstract-docs/abstract%201", "filename": "Abstract.docx", "relPath": "assets/Teams/TEAM- AXO TRACK/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "TEAM AXO TRACK\n\nABSTRACT\n\nAI-Based Multisensor Railway Track Health Monitoring and Smart Analysis System\n\nThis project proposes an intelligent railway track health monitoring system designed to detect, analyze, locate, and report track defects using a combination of computer vision, ultrasonic sensing, and data analytics. The system is based on a mobile inspection platform that travels along a railway-track prototype while continuously collecting information from multiple sensing modules. A camera is used to identify visible rail cracks, surface defects, and geometric irregularities. An ultrasonic sensing module is used to obtain distance-related measurements and provide additional information about changes in the rail condition. A wheel encoder or GPS/GNSS module provides the location of detected anomalies, depending on whether the system is operated on a laboratory prototype or an outdoor track.\n\nThe collected sensor data are processed by a Smart Analyzer implemented on a computing platform such as a Raspberry Pi. The analyzer combines the outputs of the different sensing modules to reduce reliance on a single measurement and to identify potential track anomalies. Computer-vision algorithms or an AI-based defect-detection model can classify visible defects and estimate their location and dimensions. Ultrasonic measurements are evaluated for changes that may indicate rail-position irregularities or deformation. Based on these observations, the system generates a prototype Track Health Index and classifies the observed condition into categories such as Normal, Warning, or Critical using predefined project thresholds.\n\nThe proposed system also maintains an inspection history and generates a detailed Track Health Report containing the track identification, inspection date and time, detected defects, captured images, sensor readings, defect locations, estimated severity, AI confidence, and recommended inspection priority. Historical measurements can be compared to identify changes in track condition over repeated inspections. A dashboard can provide real-time visualization of sensor status, defect locations, health trends, and alerts. The project therefore integrates embedded systems, robotics, computer vision, ultrasonic sensing, artificial intelligence, data logging, and condition monitoring into a single railway inspection platform. The prototype is intended as an academic demonstration, and its health index, thresholds, and maintenance recommendations would require validation against applicable railway engineering standards before any real-world safety-critical deployment." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/TEAM- AXO TRACK/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790003432/aura-registrations/id-cards/hrc3qzaao75wsl66ldvj.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/TEAM- AXO TRACK/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790003432/aura-registrations/id-cards/omyqtzzp9tadokmqz6vj.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/TEAM- AXO TRACK/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790003432/aura-registrations/id-cards/mxfeigmyftmn0qlmsxmj.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/TEAM- AXO TRACK/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790003433/aura-registrations/id-cards/it41egpq59xbe39uollk.jpg", "exists": true }] }, { "index": 6, "id": "6ab765a7d27ac77549de015e", "registrationId": "AURA2K26-NYK9D8", "rawTeamName": "War tech", "folderName": "War tech", "folderRelPath": "assets/Teams/War tech", "projectTitle": "Kawach", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "Zain mallick", "teamLeaderEmail": "mzayn3908@gmail.com", "teamLeaderPhone": "9199977855", "teamMemberDetails": "Daniyal ajmal\r\nAliah university \r\nECE\r\n3rd", "hardwareProjectCategories": ["Electrical Systems"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Project Title: Low-Cost  Counter-Unmanned Aerial System (C-UAS) Prototype\r\nProblem Statement\r\nUnmanned Aerial Vehicles (UAVs) present significant security risks, including airspace intrusions, smuggling, and surveillance. Commercial Counter-UAS (C-UAS) systems—reliant on costly radar and high-power jammers—are economically inaccessible for academic institutions. There is a lack of affordable, hands-on prototypes demonstrating core electronic warfare concepts at a research level.\r\nProposed Solution & System Architecture\r\nThis project presents an accessible, low-cost (₹3,000–₹6,000) small-scale C-UAS prototype designed for educational demonstration. Built on commercial off-the-shelf components, the system integrates a complete detect-track-engage workflow across three main stages:\r\n1. Detection: A 24 GHz millimeter-wave radar module (LD2410) continuously scans the target area. It transmits microwave signals and analyzes reflected echoes to calculate range, relative velocity via Doppler shift, and target motion. Detection telemetry is relayed over UART to a central ESP32 microcontroller.\r\n2. Target Locking & Tracking: The ESP32 filters incoming radar data to isolate target trajectories. Once verified, it executes a closed-loop tracking algorithm that calculates azimuth and elevation vectors, driving a 2-DOF pan-tilt servo mechanism. This continuously aligns the directional neutralization payload toward the target, demonstrating autonomous fire-control orientation.\r\n3. Neutralization (Effector Stage): The architecture supports two lab-safe, low-power effector modes:\r\n Option A (RF Jamming / Soft-Kill): Generates targeted 2.4 GHz ISM band continuous wave/noise signals via ESP32 or CC1101, disrupting the command link of small test drones to force failsafe modes (RTH or land).\r\n Option B (Electromagnetic Transient Demo): Uses a high-voltage pulse circuit (capacitor discharge bank and coil triggered via MOSFET) to produce controlled, short-range electromagnetic interference for test-circuit disruption in a shielded setup.\r\nInnovation & Academic Impact\r\n Cost Accessibility: Delivers a functional multi-stage C-UAS framework at under 1% of the cost of commercial setups.\r\n Modular Integration: Combines mmWave sensing, microcontroller-driven target tracking, pan-tilt actuation, and electronic countermeasures into a single unified hardware stack.\r\n Hands-on Pedagogy: Serves as a practical platform for teaching radar signal processing, control systems, and electronic warfare fundamentals.\r\n Extensibility: Provides a foundation for future upgrades, including computer vision fusion, multi-frequency jamming, or machine learning-based drone signal classification.", "solutionDescription": "Project Title: Low-Cost  Counter-Unmanned Aerial System (C-UAS) Prototype\r\nProblem Statement\r\nUnmanned Aerial Vehicles (UAVs) present significant security risks, including airspace intrusions, smuggling, and surveillance. Commercial Counter-UAS (C-UAS) systems—reliant on costly radar and high-power jammers—are economically inaccessible for academic institutions. There is a lack of affordable, hands-on prototypes demonstrating core electronic warfare concepts at a research level.\r\nProposed Solution & System Architecture\r\nThis project presents an accessible, low-cost (₹3,000–₹6,000) small-scale C-UAS prototype designed for educational demonstration. Built on commercial off-the-shelf components, the system integrates a complete detect-track-engage workflow across three main stages:\r\n1. Detection: A 24 GHz millimeter-wave radar module (LD2410) continuously scans the target area. It transmits microwave signals and analyzes reflected echoes to calculate range, relative velocity via Doppler shift, and target motion. Detection telemetry is relayed over UART to a central ESP32 microcontroller.\r\n2. Target Locking & Tracking: The ESP32 filters incoming radar data to isolate target trajectories. Once verified, it executes a closed-loop tracking algorithm that calculates azimuth and elevation vectors, driving a 2-DOF pan-tilt servo mechanism. This continuously aligns the directional neutralization payload toward the target, demonstrating autonomous fire-control orientation.\r\n3. Neutralization (Effector Stage): The architecture supports two lab-safe, low-power effector modes:\r\n Option A (RF Jamming / Soft-Kill): Generates targeted 2.4 GHz ISM band continuous wave/noise signals via ESP32 or CC1101, disrupting the command link of small test drones to force failsafe modes (RTH or land).\r\n Option B (Electromagnetic Transient Demo): Uses a high-voltage pulse circuit (capacitor discharge bank and coil triggered via MOSFET) to produce controlled, short-range electromagnetic interference for test-circuit disruption in a shielded setup.\r\nInnovation & Academic Impact\r\n Cost Accessibility: Delivers a functional multi-stage C-UAS framework at under 1% of the cost of commercial setups.\r\n Modular Integration: Combines mmWave sensing, microcontroller-driven target tracking, pan-tilt actuation, and electronic countermeasures into a single unified hardware stack.\r\n Hands-on Pedagogy: Serves as a practical platform for teaching radar signal processing, control systems, and electronic warfare fundamentals.\r\n Extensibility: Provides a foundation for future upgrades, including computer vision fusion, multi-frequency jamming, or machine learning-based drone signal classification.", "innovationDescription": "Project Title: Low-Cost  Counter-Unmanned Aerial System (C-UAS) Prototype\r\nProblem Statement\r\nUnmanned Aerial Vehicles (UAVs) present significant security risks, including airspace intrusions, smuggling, and surveillance. Commercial Counter-UAS (C-UAS) systems—reliant on costly radar and high-power jammers—are economically inaccessible for academic institutions. There is a lack of affordable, hands-on prototypes demonstrating core electronic warfare concepts at a research level.\r\nProposed Solution & System Architecture\r\nThis project presents an accessible, low-cost (₹3,000–₹6,000) small-scale C-UAS prototype designed for educational demonstration. Built on commercial off-the-shelf components, the system integrates a complete detect-track-engage workflow across three main stages:\r\n1. Detection: A 24 GHz millimeter-wave radar module (LD2410) continuously scans the target area. It transmits microwave signals and analyzes reflected echoes to calculate range, relative velocity via Doppler shift, and target motion. Detection telemetry is relayed over UART to a central ESP32 microcontroller.\r\n2. Target Locking & Tracking: The ESP32 filters incoming radar data to isolate target trajectories. Once verified, it executes a closed-loop tracking algorithm that calculates azimuth and elevation vectors, driving a 2-DOF pan-tilt servo mechanism. This continuously aligns the directional neutralization payload toward the target, demonstrating autonomous fire-control orientation.\r\n3. Neutralization (Effector Stage): The architecture supports two lab-safe, low-power effector modes:\r\n Option A (RF Jamming / Soft-Kill): Generates targeted 2.4 GHz ISM band continuous wave/noise signals via ESP32 or CC1101, disrupting the command link of small test drones to force failsafe modes (RTH or land).\r\n Option B (Electromagnetic Transient Demo): Uses a high-voltage pulse circuit (capacitor discharge bank and coil triggered via MOSFET) to produce controlled, short-range electromagnetic interference for test-circuit disruption in a shielded setup.\r\nInnovation & Academic Impact\r\n Cost Accessibility: Delivers a functional multi-stage C-UAS framework at under 1% of the cost of commercial setups.\r\n Modular Integration: Combines mmWave sensing, microcontroller-driven target tracking, pan-tilt actuation, and electronic countermeasures into a single unified hardware stack.\r\n Hands-on Pedagogy: Serves as a practical platform for teaching radar signal processing, control systems, and electronic warfare fundamentals.\r\n Extensibility: Provides a foundation for future upgrades, including computer vision fusion, multi-frequency jamming, or machine learning-based drone signal classification.", "workingPrinciple": "anti-drone system works in three stages: detection → tracking/locking → neutralization. a) Detection (Radar / RF sensing) • A mmWave radar module (e.g., LD2410) continuously scans the airspace in front of it. • The radar transmits microwave signals and analyzes the reflected echoes from moving objects.[nqdefense +2] • When a drone enters the detection zone, the radar measures: • Distance (range) • Relative speed (Doppler shift) • Direction (angle within its field of view) • This data is sent over UART to the microcontroller (ESP32/Arduino). In more advanced real systems, radar is combined with RF monitoring (listening to 2.4/5.8 GHz control links) and cameras, but for a small-scale project, radar alone demonstrates the core idea.[zentechnologies +2] b) Target Locking & Tracking • The microcontroller processes the radar data and decides whether the detected object matches a “drone-like” signature (moving, at certain range/speed). • If a threat is confirmed, the controller: • Commands two servos (pan & tilt) to orient the antenna/neutralizer toward the target direction. • Continuously updates servo angles as the radar provides new position data, creating a simple closed-loop tracking system. • This mimics a real target-locking system used in military C‑UAS (Counter-Unmanned Aircraft Systems). Neutralization : Low-power EMP-like pulse  • A small high-voltage pulse circuit (capacitor + spark gap + coil) is triggered by the microcontroller via a MOSFET/transistor. • The pulse creates a brief electromagnetic burst that can upset or reset a nearby test circuit, demonstrating the EMP concept. • Real systems use", "majorHardwareComponents": ["LD2420", "ESP32", "two servo motors(MG996)", "DC-DC bost module", "capacitor", "12v battery", "jumpers wires."], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["Government / Public Services"], "potentialImpact": "Anti-drone (C‑UAS) systems are increasingly important because drones are now used everywhere—from delivery and agriculture to surveillance and attacks.\r\nKey application areas:\r\n•\tCritical infrastructure protection\r\n•\tAirports, power plants, refineries, data centers, and government buildings need to detect and stop unauthorized drones that could spy, drop payloads, or cause accidents.[zentechnologies +2]\r\n•\tMilitary and border security\r\n•\tArmies use C‑UAS to defend bases, convoys, and forward positions from reconnaissance and attack drones, especially after lessons from conflicts like Ukraine.[uasdefense +1]\r\n•\tPrisons and secure facilities\r\n•\tDrones are used to smuggle contraband into prisons; counter-drone jammers and detection systems reduce this risk.[github]\r\n•\tEvent security\r\n•\tLarge public events (stadiums, concerts, political rallies) use C‑UAS to prevent drone-based surveillance or attacks.[nqdefense +1]\r\n•\tCivil aviation safety\r\n•\tPreventing drone incursions near airports avoids flight disruptions and potential collisions.", "productPotential": "yes", "prototypeDevelopmentCost": 4500, "auraDemoHighlight": "Relevance to current threats\r\n•\tDrone misuse (smuggling, spying, attacks) is a real and growing problem globally and in India. Your project addresses a high-impact, modern security challenge.[nqdefense +2]\r\n•\tIntegration of multiple technologies\r\n•\tCombines radar sensing, embedded systems, control theory (servo tracking), and RF/EMP concepts in one system.\r\n•\tShows understanding of sensor fusion, real-time processing, and actuation.\r\n•\tScalable concept\r\n•\tAlthough small, the architecture (detect → track → neutralize) is the same as in professional C‑UAS systems used by militaries and airports.[zentechnologies +2]\r\n•\tCost-effective innovation\r\n•\tDemonstrates that core ideas can be explored with very low-cost hardware, making advanced defense concepts accessible to students and researchers.[uasdefense +1]\r\n•\tInterdisciplinary learning\r\n•\tBridges electronics, communication, programming, and basic electromagnetics, which is excellent for a college project and future R&D.", "safetyHazards": ["none", "high_voltage"], "safetyPrecautions": "Use current-limited power supplies; avoid direct connection to mains for HV sections.\r\n•\tFor HV pulse circuits:\r\n•\tUse proper insulation on all high-voltage points.\r\n•\tKeep HV components inside a metal enclosure connected to earth ground where possible.\r\n•\tAdd bleeder resistors across capacitors to discharge them after power-off.\r\n•\tNever touch HV parts while powered; wait and verify discharge with a multimeter.\r\nRF safety\r\n•\tKeep RF transmission power as low as possible while still demonstrating the effect.\r\n•\tDo not operate RF jamming near:\r\n•\tWi-Fi routers used for important work\r\n•\tMedical equipment\r\n•\tAny communication systems outside your lab\r\n•\tLimit tests to short durations and document all tests.\r\nOperational safety\r\n•\tDo not test on real drones in open sky, near airports, roads, or crowds.\r\n•\tUse only toy drones inside the lab, under supervision.\r\n•\tEnsure no one stands directly in front of the HV antenna during pulse tests.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-26T06:26:47.321Z", "updatedAt": "2026-10-11T17:31:42.27Z", "abstract": { "originalName": "Kawach.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790404005/aura-registrations/abstract-docs/Kawach.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/War tech/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/War tech/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790404006/aura-registrations/id-cards/efttfvul5j7uxnnay3n7.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/War tech/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790404006/aura-registrations/id-cards/zypsstxl8xsc4kzx5gfg.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/War tech/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/War tech/4.jpg", "url": null, "exists": false }] }, { "index": 7, "id": "6ab7d7f238ddaf2dc688577e", "registrationId": "AURA2K26-ARTBG4", "rawTeamName": "Robotics & Things", "folderName": "Robotics & Things", "folderRelPath": "assets/Teams/Robotics & Things", "projectTitle": "SMART POLICE PATROL ROBOT", "teamSize": 4, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 4, "teamLeaderName": "LOKESH BANNERJEE", "teamLeaderEmail": "lokeshbanerjee2007@gmail.com", "teamLeaderPhone": "8479015939", "teamMemberDetails": "RAJEN PATI | NARULA INSTITUTE OF TECHNOLOGY | ECE(B.TECH) | 1ST YEAR | +91 77184 21756\r\n\r\nMIRZA MAHAMMAD FAIZ | NARULA INSTITUTE OF TECHNOLOGY | ECE(B.TECH) | 1ST YEAR | +91 78108 51015\r\n\r\nPRITAM DAS | NARULA INSTITUTE OF TECHNOLOGY | ECE(B.TECH) | 1ST YEAR | +91 92397 95183", "hardwareProjectCategories": ["Robotics"], "prototypeType": "Robotic System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Real-Life Problem Statement\r\nTraditional security patrols in large campuses, warehouses, and restricted zones still rely heavily on manual human oversight — a model that is costly, physically demanding, and increasingly unreliable as fatigue sets in during long, repetitive surveillance shifts. Continuous monitoring of hazardous, isolated, or high-risk perimeter zones further exposes personnel to safety risks that automation could largely remove.\r\n2. The Hardware Solution\r\nOur answer is a compact, low-cost autonomous Smart Patrol Robot built on an Arduino Uno with a dual-motor drive chassis. A servo-mounted HC-SR04 ultrasonic sensor performs a continuous 180-degree sweep for real-time obstacle detection, while an ESP32-CAM streams live video to a remote operator. Onboard red/blue warning LEDs and a buzzer deliver instant, visible deterrence the moment a threat is detected.\r\n3. Project Innovation & Creativity\r\nWhat sets this project apart is how it democratizes smart surveillance — fusing autonomous navigation, on-site deterrence, and live remote streaming into one modular platform built from readily available parts. The rotating sensor-sweep algorithm handles obstacle avoidance without expensive LiDAR, while the low-power pan-tilt camera delivers genuinely enterprise-style patrol capability at a fraction of commercial system costs, proving effective security automation doesn't have to be out of reach for smaller institutions and budgets.", "solutionDescription": "1. Real-Life Problem Statement\r\nTraditional security patrols in large campuses, warehouses, and restricted zones still rely heavily on manual human oversight — a model that is costly, physically demanding, and increasingly unreliable as fatigue sets in during long, repetitive surveillance shifts. Continuous monitoring of hazardous, isolated, or high-risk perimeter zones further exposes personnel to safety risks that automation could largely remove.\r\n2. The Hardware Solution\r\nOur answer is a compact, low-cost autonomous Smart Patrol Robot built on an Arduino Uno with a dual-motor drive chassis. A servo-mounted HC-SR04 ultrasonic sensor performs a continuous 180-degree sweep for real-time obstacle detection, while an ESP32-CAM streams live video to a remote operator. Onboard red/blue warning LEDs and a buzzer deliver instant, visible deterrence the moment a threat is detected.\r\n3. Project Innovation & Creativity\r\nWhat sets this project apart is how it democratizes smart surveillance — fusing autonomous navigation, on-site deterrence, and live remote streaming into one modular platform built from readily available parts. The rotating sensor-sweep algorithm handles obstacle avoidance without expensive LiDAR, while the low-power pan-tilt camera delivers genuinely enterprise-style patrol capability at a fraction of commercial system costs, proving effective security automation doesn't have to be out of reach for smaller institutions and budgets.", "innovationDescription": "1. Real-Life Problem Statement\r\nTraditional security patrols in large campuses, warehouses, and restricted zones still rely heavily on manual human oversight — a model that is costly, physically demanding, and increasingly unreliable as fatigue sets in during long, repetitive surveillance shifts. Continuous monitoring of hazardous, isolated, or high-risk perimeter zones further exposes personnel to safety risks that automation could largely remove.\r\n2. The Hardware Solution\r\nOur answer is a compact, low-cost autonomous Smart Patrol Robot built on an Arduino Uno with a dual-motor drive chassis. A servo-mounted HC-SR04 ultrasonic sensor performs a continuous 180-degree sweep for real-time obstacle detection, while an ESP32-CAM streams live video to a remote operator. Onboard red/blue warning LEDs and a buzzer deliver instant, visible deterrence the moment a threat is detected.\r\n3. Project Innovation & Creativity\r\nWhat sets this project apart is how it democratizes smart surveillance — fusing autonomous navigation, on-site deterrence, and live remote streaming into one modular platform built from readily available parts. The rotating sensor-sweep algorithm handles obstacle avoidance without expensive LiDAR, while the low-power pan-tilt camera delivers genuinely enterprise-style patrol capability at a fraction of commercial system costs, proving effective security automation doesn't have to be out of reach for smaller institutions and budgets.", "workingPrinciple": "Working Principles\r\n​The Smart Police Patrol Robot operates through an intelligent, synchronized synergy of hardware sensing, localized processing, and wireless monitoring.\r\n​Autonomous Navigation & Scanning: Powered by an Arduino Uno, the patrol Robot moves forward on patrol mode while a servo-mounted ultrasonic sensor continuously measures distances to map the immediate environment.  \r\n​Real-Time Obstacle Avoidance: Upon detecting a barrier within a predefined threshold, the system halts movement, commands the servo to sweep left and right to analyze clearance gaps, calculates the safest pathway, and executes a calculated avoidance maneuver.  \r\n​Active Threat Deterrence: When a security trigger or warning condition is met, the system instantly engages local deterrents by flashing high-visibility red and blue status LEDs alongside an active audio buzzer.  \r\n​Wireless Surveillance Stream: Concurrently, an integrated ESP32-CAM module streams live video footage over a wireless network, allowing operators to conduct remote observation without requiring physical movement.", "majorHardwareComponents": ["Major Hardware Components\n​Arduino Uno: The central processing brain that executes navigation logic and coordinates all system inputs and outputs.  \n​L298N Motor Driver: Manages current distribution and directional control for the rover's mobility system.  \n​4 Geared DC Motors & Chassis: Provides robust 4-wheel drive locomotion designed for smooth terrain traversal.  \n​HC-SR04 Ultrasonic Sensor: Actively measures real-time distances to detect obstacles along the patrol route.  \n​SG90 Servo Motor: Powers a dynamic 180-degree sweep mechanism to expand the sensor and camera field of view.  \n​ESP32-CAM Module: Streams live video feeds wirelessly to enable remote observation and monitoring.  \n​Red & Blue LEDs & Active Buzzer: Delivers high-visibility flashing warning indicators and audio signals for immediate local threat deterrence.  \n​20V Battery Pack & 5V Buck Converter: Supplies energy to the system while ensuring stable voltage regulation across sensitive logic and drive circuits."], "useAi": true, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public"], "potentialImpact": "POTENTIAL REAL-WORLD IMPACT (under 250 words)\r\nThe Smart Police Patrol Robot addresses the shortage of continuous human patrol coverage in campuses, warehouses, and restricted zones. By automating routine surveillance, it reduces manpower strain on security personnel while ensuring round-the-clock monitoring of vulnerable areas.\r\nCampus and industrial security teams benefit directly — the robot's obstacle-aware navigation and live visual monitoring let a single operator oversee multiple zones remotely instead of relying on physical foot patrols. The red/blue LED and buzzer alert system provides instant local warning during abnormal conditions, improving response time to intrusions or hazards.\r\nFor warehouse operators, the platform offers a low-cost alternative to expensive commercial security robots, making autonomous patrol accessible to smaller organizations with limited budgets. Its modular design means it can scale from a basic obstacle-avoidance patroller to a more advanced system with GPS route logging and video analytics — without redesigning the core drive system.\r\nOverall, it improves current security standards by combining continuous, fatigue-free monitoring with real-time remote visibility, reducing dependency on constant human presence in high-risk or hard-to-monitor areas, and giving public-safety and private-security teams a scalable, affordable surveillance tool.\r\n(Based on Arduino Uno, HC-SR04 sensor, L298N motor driver, 4WD chassis + motors, servo, ESP32-CAM, LEDs, buzzer, and rechargeable battery.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "HIGHLIGHT WHY THIS IS WORTH SEEING:\r\nThe Smart Police Patrol Robot stands out for solving a real, everyday security gap — continuous patrol coverage — with a genuinely low-cost, accessible build. Unlike commercial security robots that cost lakhs, this prototype achieves autonomous obstacle-aware navigation, live remote video monitoring, and instant local alerting for a fraction of the price, making it practical for campuses, warehouses, and small organizations that can't afford expensive alternatives.\r\nIts most impressive aspect is the integration of multiple subsystems — ultrasonic obstacle sensing, 4WD motor control, pan/tilt live video via ESP32-CAM, and dual-mode alerting (visual + audible) — into a single compact, coordinated unit driven by just an Arduino Uno. This shows efficient hardware-software coordination on minimal, affordable components.\r\nThe design is also built for growth: its modular architecture allows future upgrades like GPS route logging and intelligent video analytics to be added without touching the core drive system. That means judges are looking at a foundation for a genuinely deployable product, not just a one-off demo.\r\nIn short, it combines affordability, functional autonomy, and real security value — a practical prototype that directly benefits public-safety teams, campus security, and warehouse operators looking for low-cost remote patrol support.", "safetyHazards": ["water_near_electrical_equipment", "high_temperature", "moving_rotating_machinery", "fire_combustion", "chemicals", "sharp_mechanical_components"], "safetyPrecautions": "Safety Precautions Taken:\r\nThe Smart Police Petrol Robot has been designed with safety as a priority. The robot operates at a controlled speed to reduce the risk of collisions and accidents. Sensors are used to detect obstacles and avoid collisions with people or objects. The motors and electronic components are securely mounted to prevent loose connections during movement. The battery and power supply are properly insulated to reduce the risk of short circuits and overheating. A suitable protective enclosure is provided for sensitive electronic components such as the microcontroller, motor driver and wiring. The robot can be stopped immediately using a manual power switch in case of an emergency. All exposed wires and terminals are properly covered to prevent accidental contact. The prototype is tested at low speed in a controlled area before demonstration. During testing, the robot is kept away from water, fire and other hazardous materials. These precautions help ensure safe operation for the users, surroundings and the prototype itself.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-26T14:34:26.15Z", "updatedAt": "2026-10-11T17:31:47.057Z", "abstract": { "originalName": "smart_patrol_robot_compact.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790433264/aura-registrations/abstract-docs/smart_patrol_robot_compact.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Robotics & Things/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Robotics & Things/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790433265/aura-registrations/id-cards/ym42oxxjywwl0a2zkuhq.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Robotics & Things/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790433265/aura-registrations/id-cards/xtb36ajyx42umcxbtcbh.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Robotics & Things/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790433265/aura-registrations/id-cards/idty9ejfqx2g1xoq3gpq.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Robotics & Things/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790433264/aura-registrations/id-cards/pdk5ncegqstavdiqwrs7.jpg", "exists": true }] }, { "index": 8, "id": "6ab8c1e39bb2d35d4baadb67", "registrationId": "AURA2K26-767ZFY", "rawTeamName": "team Electron", "folderName": "team Electron", "folderRelPath": "assets/Teams/team Electron", "projectTitle": "wearable medical heart monitor devices", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Meherab Chowdhury", "teamLeaderEmail": "rakeshchowdhuryy07@gmail.com", "teamLeaderPhone": "8972439990", "teamMemberDetails": "1st: Mobinul Hoque ,dept:ECE, 3rd year,ph:9832918574\r\n2nd:Tuhina Mallick,dept:ECE, 3rd year,ph:98002 79614\r\n3ed:Mir Sania,dept:ECE, 3rd year,ph:9382725442", "hardwareProjectCategories": ["Biomedical / Healthcare Devices", "Environmental Technology"], "prototypeType": "Wearable Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Design and Development of a High-Precision Multiparameter Wearable Heart Health Monitor with Adaptive Noise Cancellation and BLE Telemetry\r\n\r\nThe system uses a Raspberry Pi Pico 2W with an external 16-bit ADS1115 ADC to overcome microcontroller quantization limits and capture microvolt-level ECG signals. It applies IIR/FIR filters for baseline wander and high-frequency noise, plus an NLMS adaptive filter with IMU reference to cancel motion artifacts. Automatic Gain Control compensates for skin pigmentation, while ambient light cancellation and thermal drift compensation improve PPG/SpO₂ accuracy. A BLE GATT architecture with an interrupt-driven deep sleep state machine enables multi-day, low-power continuous monitoring.", "solutionDescription": "Design and Development of a High-Precision Multiparameter Wearable Heart Health Monitor with Adaptive Noise Cancellation and BLE Telemetry\r\n\r\nThe system uses a Raspberry Pi Pico 2W with an external 16-bit ADS1115 ADC to overcome microcontroller quantization limits and capture microvolt-level ECG signals. It applies IIR/FIR filters for baseline wander and high-frequency noise, plus an NLMS adaptive filter with IMU reference to cancel motion artifacts. Automatic Gain Control compensates for skin pigmentation, while ambient light cancellation and thermal drift compensation improve PPG/SpO₂ accuracy. A BLE GATT architecture with an interrupt-driven deep sleep state machine enables multi-day, low-power continuous monitoring.", "innovationDescription": "Design and Development of a High-Precision Multiparameter Wearable Heart Health Monitor with Adaptive Noise Cancellation and BLE Telemetry\r\n\r\nThe system uses a Raspberry Pi Pico 2W with an external 16-bit ADS1115 ADC to overcome microcontroller quantization limits and capture microvolt-level ECG signals. It applies IIR/FIR filters for baseline wander and high-frequency noise, plus an NLMS adaptive filter with IMU reference to cancel motion artifacts. Automatic Gain Control compensates for skin pigmentation, while ambient light cancellation and thermal drift compensation improve PPG/SpO₂ accuracy. A BLE GATT architecture with an interrupt-driven deep sleep state machine enables multi-day, low-power continuous monitoring.", "workingPrinciple": "**Working Principle**\r\n\r\nThe wearable heart health monitor operates by continuously acquiring physiological signals, conditioning them, removing noise, and transmitting clinically relevant parameters over BLE. The Raspberry Pi Pico 2W acts as the central controller. The MAX30102 measures PPG using red and IR LEDs and a photodiode to derive heart rate and SpO₂. The AD8232 captures ECG biopotential, which is digitized by an external 16-bit ADS1115 via I2C, improving resolution to approximately 0.05 mV so delicate P and T waves are preserved. The MAX30205 measures skin temperature for thermal compensation, while the LSM6DSOX provides a 3-axis accelerometer and gyroscope motion reference. Core 0 polls sensors and runs DSP; Core 1 manages BLE.\r\n\r\nRaw signals undergo IIR high-pass filtering to remove baseline wander below 0.5 Hz, FIR moving average filtering to suppress high-frequency noise, and 50 Hz ambient light cancellation. For motion artifacts, an NLMS adaptive filter uses the IMU reference vector to estimate and subtract movement noise overlapping the cardiac band. AGC adjusts LED drive current based on the DC baseline to compensate for melanin attenuation. Thermal drift correction adjusts SpO₂ calibration using temperature. Processed parameters are packaged into GATT services, including Heart Rate (0x180D) and Health Thermometer (0x1809), and advertised via BLE. An interrupt-driven deep sleep state machine wakes every 5 minutes, acquires 10 seconds of data, processes it, broadcasts for 3 seconds, and hibernates at ~1.5 mA, enabling multi-day monitoring.", "majorHardwareComponents": ["Raspberry Pi Pico 2W (RP2350)", "MAX30102", "AD8232", "ADS1115", "MAX30205", "LSM6DSOX", "TP4056 + LDO", "500 mAh LiPo Battery", "ECG Electrodes", "Passive Components", "PCB / Breadboard", "BLE Client (Smartphone/App)"], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Healthcare"], "potentialImpact": "**Potential Real-World Impact**\r\n\r\nCardiovascular diseases remain the leading cause of death globally, and continuous monitoring outside hospitals is critical for early detection and management. This wearable heart health monitor has the potential to transform ambulatory cardiac care by delivering clinical-grade ECG, PPG, SpO₂, and temperature data in real-world conditions. By overcoming the ADC resolution bottleneck with an external 16-bit ADS1115, it captures subtle cardiac features like P and T waves, enabling more accurate arrhythmia detection. The NLMS adaptive filter cancels motion artifacts, allowing reliable monitoring during walking or exercise, while AGC eliminates skin pigmentation bias, ensuring equitable performance across all Fitzpatrick skin types. The low-power BLE GATT architecture and deep sleep state machine enable multi-day operation, making continuous monitoring practical for chronic conditions.\r\n\r\nReal-world impact includes remote patient monitoring to reduce hospital readmissions, early detection of atrial fibrillation and heart failure, improved management of hypertension and sleep apnea, and enhanced telemedicine. In rural and resource-limited settings, this low-cost device can extend cardiology expertise where it is scarce. Athletes and fitness enthusiasts can benefit from precise cardiac and recovery metrics. Ultimately, this technology democratizes access to high-fidelity cardiac monitoring, shifting healthcare from reactive to preventive, reducing costs, and saving lives. By addressing demographic and environmental biases, it ensures that the benefits of wearable health technology are available to all, not just a privileged few. This work lays the foundation for next-generation medical wearables that are accurate, equitable, and ubiquitous.", "productPotential": "yes", "prototypeDevelopmentCost": 3500, "auraDemoHighlight": "Clinical-grade ECG on low-cost hardware — The external 16-bit ADS1115 bypasses the Pico’s 12-bit ADC limit, revealing P and T waves, not just the QRS complex.\r\n\r\nReal-time motion cancellation — The NLMS adaptive filter uses IMU data to mathematically subtract walking/jogging artifacts that overlap the cardiac band.\r\n\r\nDemographic equity in sensing — Automatic Gain Control compensates for melanin attenuation, ensuring accurate PPG/SpO₂ across all Fitzpatrick skin types.\r\n\r\nMulti-day continuous monitoring — The interrupt-driven deep sleep state machine draws ~1.5 mA and wakes every 5 minutes, making 24/7 operation practical on a 500 mAh LiPo.\r\n\r\nDual-core RTOS-style architecture — Core 0 handles deterministic DSP; Core 1 handles BLE, so wireless transmission never interrupts sensor polling.\r\n\r\nExtremely low cost — The prototype component cost is around ₹3,759, making advanced cardiac monitoring accessible.\r\n\r\nReal-world impact — Enables remote patient monitoring, early arrhythmia detection, rural telemedicine, and preventive cardiology.", "safetyHazards": ["none"], "safetyPrecautions": "no", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-27T07:12:35.161Z", "updatedAt": "2026-10-11T17:31:52.563Z", "abstract": { "originalName": "AURA_Red_Rangers.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1790493154/aura-registrations/abstract-docs/AURA_Red_Rangers", "filename": "Abstract.docx", "relPath": "assets/Teams/team Electron/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "Complete Technical Thesis\n\nDesign, Architecture, and Error Mitigation of a High-Precision Multiparameter Wearable Health MonitorIntegrating Raspberry Pi Pico 2W, High-Resolution External ADCs, Adaptive Noise Cancellation, and BLE RTOS\n\nMaster Engineering BlueprintPrepared byTeam Red RangersMeherab Chowdhury Mir Sania Mobinul Hoque Tuhina Mallick\n\nMentorSunirnay ChatterjeeSeptember 2026\n\nAbstract\n\nThe transition of physiological monitoring from controlled clinical environments to ambulatory wearable form factors introduces severe engineering challenges. This comprehensive thesis details the end-to-end design of a multiparameter medical device utilizing the Raspberry Pi Pico 2W. The foundational hardware architecture integrates photoplethysmography (MAX30102), electrocardiography (AD8232), clinical-grade tissue thermometry (MAX30205), and tri-axial inertial tracking (LSM6DSOX). To overcome the quantization bottlenecks of standard microcontrollers, the design employs a 16-bit Sigma-Delta external Analog-to-Digital Converter (ADS1115), dramatically increasing the Signal-to-Noise Ratio (SNR) for microvolt ECG signals.\n\nCrucially, this complete report details rigorous error eradication strategies for both physiological and environmental noise. It models countermeasures for (1) Skin Pigmentation Disparities via dynamic Automatic Gain Control (AGC); (2) Motion Artifacts via Normalized Least Mean Squares (NLMS) Adaptive Noise Cancellation; (3) 50Hz Ambient Light Interference (ALI); and (4) LED Thermal Drift. Standard IIR/FIR filters for baseline wander are derived mathematically alongside the adaptive algorithms. Finally, the system utilizes a Bluetooth Low Energy (BLE) Generic Attribute Profile (GATT) architecture with an interrupt-driven deep sleep state machine, ensuring multi-day 24/7 continuous monitoring capability.\n\nChapter 1: Introduction & System Objectives\n\n1.1 The Paradigm Shift in Continuous Monitoring\n\nIn clinical environments, physiological parameters are monitored using tethered machinery under heavily controlled conditions. The shift towards ambulatory, continuous monitoring devices offers unparalleled advantages for preventative cardiology. However, a wearable device must operate accurately on a person who is jogging, sweating, under indoor fluorescent lights, and possessing varying levels of epidermal melanin.\n\n1.2 System Specifications\n\nThis project aims to engineer a master architecture that achieves:\n\nHigh-Fidelity Data Acquisition: Utilizing external 16-bit ADCs to bypass standard 12-bit microcontroller limitations, revealing the full cardiac QRS complex.\n\nDemographic Equity in Sensing: Implementing dynamic LED drive controls to equalize SNR across all Fitzpatrick skin types.\n\nAlgorithmic Resilience to Motion: Implementation of real-time Adaptive Noise Cancellation (ANC) utilizing multi-axis IMU data.\n\nMicro-power Telemetry: Utilization of GATT over BLE for multi-day operation.\n\nChapter 2: Hardware Architecture and Circuit Design\n\n2.1 Core Processing: Raspberry Pi Pico 2W\n\nThe RP2350-based Pico 2W is selected due to its dual-core architecture. Core 0 is dedicated to real-time hardware interrupts and intensive DSP filtering (IIR, FIR, LMS), while Core 1 autonomously manages the BLE radio stack, ensuring wireless transmission does not interrupt rigid sensor polling intervals.\n\n2.2 Overcoming the ADC Bottleneck\n\nMicrocontrollers inherently suffer from internal ground bounce and digital noise coupling into their built-in ADCs. The Pico 2W's internal ADC yields a resolution of ≈ 0.8mV. By routing the AD8232 analog output to an external ADS1115 (16-bit Sigma-Delta ADC) via I2C, the resolution increases to 65536 levels (a quantization step of ≈ 0.05mV), revealing the delicate P and T waves.\n\n2.3 Hardware Interface Mapping\n\nModule\n\nFunction\n\nInterface Bus\n\nMAX30102\n\nPPG (SpO2, Heart Rate)\n\nI2C0 (SDA: GP4, SCL: GP5)\n\nMAX30205\n\nSkin Temperature Calibration\n\nI2C0 (SDA: GP4, SCL: GP5)\n\nLSM6DSOX\n\nMotion Reference Vector\n\nI2C1 (SDA: GP14, SCL: GP15)\n\nADS1115\n\n16-bit ADC for ECG\n\nI2C1 (SDA: GP14, SCL: GP15)\n\nAD8232\n\nCardiac Biopotential AFE\n\nAnalog → external ADC\n\n Figure 2.1: Complete System Architecture and Data Bus Routing Strategy\n\nFigure 2.2: This flowchart visually breaks down the 6-step deep sleep cycle that the RTOS uses to manage power\n\nChapter 3: Error Modeling and Hardware Mitigation\n\n3.1 Skin Pigmentation Disparities (The Melanin Problem)\n\nEpidermal melanin acts as a broadband optical attenuator. The Modified Beer-Lambert Law is:\n\nI(t) = I_0 * e^[-(μ_dc * d_dc + μ_ac * d_ac(t))]\n\nHigher melanin increases the static coefficient μ_dc. To eliminate this demographic bias, the firmware utilizes an Automatic Gain Control (AGC) feedback loop. If the DC baseline falls below a threshold, the Pico dynamically increases the LED drive current via I2C registers:\n\nI_LED[n+1] = I_LED[n] + K_p * (DC_target - DC_current)\n\n3.2 Environmental Noise Mitigations\n\n3.2.1 Ambient Light Interference (ALI)\n\nIndoor lighting (AC mains) flickers at exactly 50Hz. The MAX30102 utilizes active Ambient Light Cancellation (ALC) by measuring photodiode dark current while LEDs are off, mathematically subtracting this 50Hz interference.\n\n3.2.2 Thermal Drift Compensation\n\nLED emission wavelengths shift relative to junction temperature (≈ 0.1 nm / °C). The MAX30205 Clinical Thermometer continually feeds data to dynamically offset the SpO2 calibration matrices:\n\nλ_actual = λ_nominal + ΔT * τ_drift\n\nChapter 4: Digital Signal Processing (DSP) and Adaptive Filters\n\nHardware filters alone cannot isolate the cardiac band (0.5Hz - 4.0Hz).\n\n4.1 Standard Filtering: Baseline Wander and High-Frequency Noise\n\nTo remove the baseline wander (<0.5Hz) from breathing, a discrete-time IIR high-pass filter is implemented:\n\ny[n] = x[n] - x[n-1] + α * y[n-1]\n\nFor high-frequency noise (50Hz), a Moving Average (FIR) filter is applied:\n\ny_smooth[n] = (1/W) * Σ y[n-k]\n\nFigure 4.1: Simulated PPG Pipeline: Removal of low-frequency baseline wander using the IIR high-pass filter.\n\nFigure 4.2: Simulated ECG Pipeline: 16-bit quantization and 50Hz notch rejection revealing the QRS complex.\n\n4.2 Motion Artifact Elimination via Adaptive Noise Cancellation (ANC)\n\nBecause walking step frequencies (1.0Hz - 3.0Hz) overlap the cardiac band, standard filters fail. This architecture uses the LSM6DSOX IMU to generate a reference vector v[n]. A Normalized Least Mean Squares (NLMS) algorithm estimates and subtracts the motion artifact. The recovered clean cardiac signal e[n] is:\n\ne[n] = d[n] - Σ (w_k[n] * v[n-k])\n\nThe filter weights update iteratively to track movement patterns:\n\nw_k[n+1] = w_k[n] + (μ / (||v[n]||² + ε)) * e[n] * v[n-k]\n\nFigure 4.3: Elimination of Motion Artifacts: The IMU accelerometer vector is used by the LMS adaptive filter to mathematically subtract the walking/jogging artifact from the corrupted PPG signal.\n\nChapter 5: Firmware and RTOS Implementation\n\n5.1 Bluetooth Low Energy (BLE) GATT Architecture\n\nThe Pico 2W operates as a GATT Server to conserve power. Data is structured into Standard UUIDs:\n\nHeart Rate Service: 0x180D\n\nHealth Thermometer Service: 0x1809\n\n5.2 Deep Sleep State Machine\n\nTo achieve multi-day operation on a 500mAh LiPo battery:\n\nHIBERNATE: Pico in deep sleep (Draw: ≈ 1.5mA).\n\nWAKEUP: Hardware timer triggers every 5 minutes.\n\nACQUIRE: Sensors power up. Data arrays filled for 10 seconds.\n\nPROCESS: Core 0 executes IIR, FIR, and LMS DSP algorithms.\n\nBROADCAST: Core 1 BLE radio advertises characteristic payload for 3 seconds.\n\nSHUTDOWN: Return to HIBERNATE.\n\nChapter 6: Conclusion\n\nThis thesis culminates in a fully realized blueprint for an ambulatory, clinical-grade medical monitor. By merging precision analog external components (ADS1115), robust sensor arrays (PPG, ECG, IMU, Temp), and advanced mathematically proven adaptive filters (NLMS, AGC), this architecture definitively solves the quantization, melanin bias, and motion artifact bottlenecks that cripple standard hobbyist microcontrollers.\n\nAppendix: pseudocode\n\nA.1 DSP Pipeline (IIR and FIR Filters)\n\n// ========================================================\n\n// INITIALIZATION AND CONSTANT DEFINITIONS\n\n// ========================================================\n\nCONST WAKEUP_INTERVAL_SEC = 300       // Wakes up every 5 minutes\n\nCONST ACQUISITION_TIME_SEC = 10       // Polling duration\n\nCONST SAMPLE_RATE_HZ = 50             // Sensor sampling frequency\n\nCONST SAMPLES_NEEDED = ACQUISITION_TIME_SEC * SAMPLE_RATE_HZ\n\nCONST DC_THRESHOLD_MIN = 10000        // AGC minimum baseline\n\nCONST LED_CURRENT_LOW = 10            // 10mA Default\n\nCONST LED_CURRENT_HIGH = 30           // 30mA Boost for dark skin\n\n// Filter Variables\n\nGLOBAL iir_prev_x = 0.0, iir_prev_y = 0.0\n\nGLOBAL fir_buffer = ARRAY of size 8\n\nGLOBAL fir_idx = 0\n\nGLOBAL lms_weights = ARRAY of size 16 initialized to 0.0\n\nGLOBAL lms_buffer = ARRAY of size 16 initialized to 0.0\n\n// ========================================================\n\n// CORE HARDWARE INTERRUPT LOOP\n\n// ========================================================\n\nFUNCTION MainLoop()\n\n    WHILE True DO\n\n        // 1. Wake from Deep Sleep\n\n        PowerOnPeripherals()\n\n        Set_LED_Current(LED_CURRENT_LOW)\n\n        \n\n        ARRAY raw_ppg_buffer = []\n\n        ARRAY clean_ppg_buffer = []\n\n        \n\n        // 2. Acquisition Cycle\n\n        FOR count = 1 TO SAMPLES_NEEDED DO\n\n            // Read Sensors via I2C\n\n            raw_red = Read_MAX30102_Red()\n\n            accel_x, accel_y, accel_z = Read_LSM6DSOX()\n\n            temp_c = Read_MAX30205()\n\n            \n\n            // Calculate Motion Vector Magnitude\n\n            accel_mag = SQRT(accel_x^2 + accel_y^2 + accel_z^2)\n\n            \n\n            Append raw_red TO raw_ppg_buffer\n\n            \n\n            // Run DSP Pipeline instantly on the sample\n\n            clean_sample = ExecuteDSP(raw_red, accel_mag)\n\n            Append clean_sample TO clean_ppg_buffer\n\n            \n\n            Wait(1 / SAMPLE_RATE_HZ)\n\n        END FOR\n\n        // 3. Automatic Gain Control (AGC) Validation\n\n        dc_baseline = CalculateAverage(raw_ppg_buffer)\n\n        IF dc_baseline < DC_THRESHOLD_MIN THEN\n\n            // Melanin absorption too high or poor perfusion\n\n            Set_LED_Current(LED_CURRENT_HIGH)\n\n            CONTINUE // Abort this loop and acquire 10s of data again with higher power\n\n        END IF\n\n        // 4. Feature Extraction (Physiological Calculation)\n\n        heart_rate = ExtractBPM(clean_ppg_buffer)\n\n        spo2_raw = CalculateSpO2(raw_ppg_buffer)\n\n        spo2_compensated = ApplyThermalDriftCorrection(spo2_raw, temp_c)\n\n        // 5. Telemetry / Transmission\n\n        IF heart_rate > 30 AND heart_rate < 240 THEN\n\n            UpdateBLE_GATT_Characteristics(heart_rate, spo2_compensated, temp_c)\n\n            TurnOnBLERadio()\n\n            AdvertiseBLE(duration = 3 seconds)\n\n            TurnOffBLERadio()\n\n        END IF\n\n        // 6. Hibernate\n\n        PowerDownPeripherals()\n\n        DeepSleep(WAKEUP_INTERVAL_SEC)\n\n    END WHILE\n\nEND FUNCTION\n\n// ========================================================\n\n// SIGNAL PROCESSING PIPELINE\n\n// ========================================================\n\nFUNCTION ExecuteDSP(raw_val, noise_reference)\n\n    \n\n    // A. IIR High-Pass Filter (Removes Baseline Wander)\n\n    ALPHA = 0.95\n\n    y_hp = raw_val - iir_prev_x + (ALPHA * iir_prev_y)\n\n    \n\n    iir_prev_x = raw_val\n\n    iir_prev_y = y_hp\n\n    // B. FIR Low-Pass Filter (Moving Average for 50Hz/Fuzz)\n\n    fir_buffer[fir_idx] = y_hp\n\n    fir_idx = (fir_idx + 1) MODULO 8\n\n    \n\n    y_smooth = Sum(fir_buffer) / 8\n\n    // C. LMS Adaptive Noise Cancellation (Removes Motion)\n\n    Insert noise_reference at beginning of lms_buffer\n\n    Remove last element of lms_buffer\n\n    \n\n    // Estimate motion artifact\n\n    y_est = 0.0\n\n    FOR i = 0 TO 15 DO\n\n        y_est = y_est + (lms_weights[i] * lms_buffer[i])\n\n    END FOR\n\n    \n\n    // Calculate the error (which is our target clean cardiac signal)\n\n    clean_cardiac = y_smooth - y_est\n\n    \n\n    // Update Filter Weights (Normalized LMS)\n\n    LMS_MU = 0.01\n\n    norm = SumOfSquares(lms_buffer) + 0.000001\n\n    \n\n    FOR i = 0 TO 15 DO\n\n        lms_weights[i] = lms_weights[i] + (LMS_MU / norm) * clean_cardiac * lms_buffer[i]\n\n    END FOR\n\n    RETURN clean_cardiac\n\nEND FUNCTION\n\n// ========================================================\n\n// FEATURE EXTRACTION (BPM)\n\n// ========================================================\n\nFUNCTION ExtractBPM(clean_array)\n\n    // Dynamic Thresholding\n\n    sorted_array = Sort(clean_array)\n\n    top_10_percent = ExtractTop10Percent(sorted_array)\n\n    dynamic_threshold = CalculateAverage(top_10_percent) * 0.75\n\n    \n\n    ARRAY peaks = []\n\n    \n\n    FOR i = 1 TO length(clean_array) - 2 DO\n\n        current = clean_array[i]\n\n        prev = clean_array[i-1]\n\n        next = clean_array[i+1]\n\n        \n\n        // Find local maxima above threshold\n\n        IF current > dynamic_threshold AND current > prev AND current > next THEN\n\n            Append i TO peaks\n\n        END IF\n\n    END FOR\n\n    \n\n    IF length(peaks) < 2 THEN\n\n        RETURN 0 // Error: Not enough data\n\n    END IF\n\n    \n\n    // Calculate BPM\n\n    avg_interval_samples = CalculateAverageDistanceBetweenPeaks(peaks)\n\n    bpm = (60.0 * SAMPLE_RATE_HZ) / avg_interval_samples\n\n    \n\n    RETURN bpm\n\nEND FUNCTION" }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/team Electron/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790493153/aura-registrations/id-cards/tzz7vzwbqo7oscpnuizt.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/team Electron/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790493153/aura-registrations/id-cards/vjre1vhbg1gu03zpumdn.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/team Electron/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790493153/aura-registrations/id-cards/ybggiltq5edid3qpqwkr.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/team Electron/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790493153/aura-registrations/id-cards/nclwz3jw43kz0rqknrx9.jpg", "exists": true }] }, { "index": 9, "id": "6ab943e4487ebf4abc5ed157", "registrationId": "AURA2K26-U5T7AH", "rawTeamName": "SAOANA", "folderName": "SAOANA", "folderRelPath": "assets/Teams/SAOANA", "projectTitle": "SAOANA- Smart Autonomous Obstacle Avoidance & Navigation Robot", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "Md Arif BIllah Laskar", "teamLeaderEmail": "mdheremdarif@gmail.com", "teamLeaderPhone": "9332325739", "teamMemberDetails": "Saif Parvez ,Electical Engineering student in Aliah university", "hardwareProjectCategories": ["Robotics", "Drone / Autonomous Systems", "Automation & Control"], "prototypeType": "Robotic System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "1. Problem Statement\r\nNowadays, robots are being used in many areas to reduce human effort and to perform tasks automatically. One common problem in mobile robots is how they can move safely without hitting obstacles. Many simple obstacle-avoiding robots are programmed with a fixed rule, such as turning left or right whenever an obstacle comes in front of them. This method may not always be effective because the selected direction can also be blocked or may not be the better path. The robot can also get stuck in narrow spaces or dead ends. Therefore, there is a need for a simple and low-cost robot that can detect obstacles, check the available space around it and make a suitable movement decision automatically.\r\n2. Solution Details\r\nTo solve this problem, we are developing SAOANA – Smart Autonomous Obstacle Avoidance & Navigation Robot. The main controller of the robot is an Arduino UNO. An ultrasonic sensor is used to measure the distance between the robot and an obstacle. The sensor is mounted on a servo motor so that it can look towards different directions. When the path in front of the robot is clear, the robot moves forward. If an obstacle is detected within a fixed safe distance, the robot stops and checks the left and right sides. The Arduino compares the measured distances and decides which side has more free space. The robot then moves in that direction using its four DC gear motors and motor driver. If both sides are blocked, the robot moves backward and changes its direction to find another path.\r\n3. Innovation Details\r\nThe main innovation of our project is that the robot does not simply turn in one fixed direction whenever it finds an obstacle. Instead, it first checks different directions and then chooses a path according to the available space. This makes the movement more logical and useful in different situations. Another feature is the dead-end recovery system, where the robot can reverse and try another direction if it finds that both sides are blocked. The project is designed using affordable and easily available components such as Arduino UNO, ultrasonic sensor, servo motor, L293D motor driver and DC gear motors. Our aim is to make a simple, low-cost and practical autonomous robot that demonstrates how sensors, programming and mechanical movement can work together to solve a real-world navigation problem.\r\n                                                                    it's works any sector", "solutionDescription": "1. Problem Statement\r\nNowadays, robots are being used in many areas to reduce human effort and to perform tasks automatically. One common problem in mobile robots is how they can move safely without hitting obstacles. Many simple obstacle-avoiding robots are programmed with a fixed rule, such as turning left or right whenever an obstacle comes in front of them. This method may not always be effective because the selected direction can also be blocked or may not be the better path. The robot can also get stuck in narrow spaces or dead ends. Therefore, there is a need for a simple and low-cost robot that can detect obstacles, check the available space around it and make a suitable movement decision automatically.\r\n2. Solution Details\r\nTo solve this problem, we are developing SAOANA – Smart Autonomous Obstacle Avoidance & Navigation Robot. The main controller of the robot is an Arduino UNO. An ultrasonic sensor is used to measure the distance between the robot and an obstacle. The sensor is mounted on a servo motor so that it can look towards different directions. When the path in front of the robot is clear, the robot moves forward. If an obstacle is detected within a fixed safe distance, the robot stops and checks the left and right sides. The Arduino compares the measured distances and decides which side has more free space. The robot then moves in that direction using its four DC gear motors and motor driver. If both sides are blocked, the robot moves backward and changes its direction to find another path.\r\n3. Innovation Details\r\nThe main innovation of our project is that the robot does not simply turn in one fixed direction whenever it finds an obstacle. Instead, it first checks different directions and then chooses a path according to the available space. This makes the movement more logical and useful in different situations. Another feature is the dead-end recovery system, where the robot can reverse and try another direction if it finds that both sides are blocked. The project is designed using affordable and easily available components such as Arduino UNO, ultrasonic sensor, servo motor, L293D motor driver and DC gear motors. Our aim is to make a simple, low-cost and practical autonomous robot that demonstrates how sensors, programming and mechanical movement can work together to solve a real-world navigation problem.\r\n                                                                    it's works any sector", "innovationDescription": "1. Problem Statement\r\nNowadays, robots are being used in many areas to reduce human effort and to perform tasks automatically. One common problem in mobile robots is how they can move safely without hitting obstacles. Many simple obstacle-avoiding robots are programmed with a fixed rule, such as turning left or right whenever an obstacle comes in front of them. This method may not always be effective because the selected direction can also be blocked or may not be the better path. The robot can also get stuck in narrow spaces or dead ends. Therefore, there is a need for a simple and low-cost robot that can detect obstacles, check the available space around it and make a suitable movement decision automatically.\r\n2. Solution Details\r\nTo solve this problem, we are developing SAOANA – Smart Autonomous Obstacle Avoidance & Navigation Robot. The main controller of the robot is an Arduino UNO. An ultrasonic sensor is used to measure the distance between the robot and an obstacle. The sensor is mounted on a servo motor so that it can look towards different directions. When the path in front of the robot is clear, the robot moves forward. If an obstacle is detected within a fixed safe distance, the robot stops and checks the left and right sides. The Arduino compares the measured distances and decides which side has more free space. The robot then moves in that direction using its four DC gear motors and motor driver. If both sides are blocked, the robot moves backward and changes its direction to find another path.\r\n3. Innovation Details\r\nThe main innovation of our project is that the robot does not simply turn in one fixed direction whenever it finds an obstacle. Instead, it first checks different directions and then chooses a path according to the available space. This makes the movement more logical and useful in different situations. Another feature is the dead-end recovery system, where the robot can reverse and try another direction if it finds that both sides are blocked. The project is designed using affordable and easily available components such as Arduino UNO, ultrasonic sensor, servo motor, L293D motor driver and DC gear motors. Our aim is to make a simple, low-cost and practical autonomous robot that demonstrates how sensors, programming and mechanical movement can work together to solve a real-world navigation problem.\r\n                                                                    it's works any sector", "workingPrinciple": "Our project SAOANA (Smart Autonomous Obstacle Avoidance & Navigation Robot) works by detecting obstacles and automatically choosing a suitable direction. An Arduino UNO is used as the main controller of the robot. An HC-SR04 ultrasonic sensor is used to detect obstacles and measure their distance from the robot.\r\nWhen the robot starts moving, the ultrasonic sensor continuously checks the path in front of it. If there is no obstacle within the safe distance, the Arduino gives signals to the L293D motor driver, and the four motors move the robot forward.\r\nIf an obstacle is detected in front of the robot, the robot stops. The ultrasonic sensor is attached to an SG90 servo motor, so the sensor can turn towards the left and right sides. The robot checks the distance on both sides and sends the information to the Arduino.\r\nThe Arduino compares the left and right distances. If the left side has more free space, the robot turns left. If the right side has more free space, it turns right. If both sides are blocked, the robot moves backward for a short time and then changes its direction.\r\nIn this way, SAOANA can detect obstacles, make its own direction decision and move without continuous human control. The main aim of our project is to demonstrate a simple and low-cost method of autonomous robot navigation.", "majorHardwareComponents": ["1. Arduino UNO – Main controller of the robot\n2. HC-SR04 Ultrasonic Sensor – Detects obstacles and measures distance\n3. SG90 Servo Motor – Rotates the ultrasonic sensor left and right\n4. L293D Motor Driver – Controls the DC motors\n5 .4 DC Gear Motors – Moves the robot\n6. 4 Wheels + Robot Chassis – Mechanical structure\n7. 2 × Li-ion Batteries + Battery Holder – Power supply\n8. Jumper Wires & Breadboard – For electrical connections\n9. Push Button – For ON/OFF or starting the robot"], "useAi": true, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Industry", "Transportation", "Government / Public Services", "Persons with Disabilities", "Education", "Healthcare", "Agriculture"], "potentialImpact": "SAOANA can have useful applications in different real-world situations where robots need to move safely without continuous human control. The basic idea can be used in delivery robots, warehouse robots, indoor service robots, and smart vehicles to detect obstacles and choose a suitable direction. It can help reduce collisions and make robotic movement more automatic.\r\n\r\nSince our prototype uses low-cost and easily available components, it can also be useful for students and beginners who want to learn about robotics and autonomous navigation. The project can be further developed by adding more sensors, wheel encoders, cameras, GPS, or IoT features. In the future, a more advanced version could be used for applications such as automatic material transportation in factories and obstacle-aware assistance robots.\r\n\r\nOverall, SAOANA demonstrates a simple and affordable approach to autonomous obstacle detection and navigation.", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "SAOANA is worth seeing because it demonstrates autonomous decision-making in a simple and practical way. The robot does not just move forward and turn at fixed angles; it detects obstacles, scans the surroundings, compares the available space, and chooses a suitable direction on its own. The live movement makes the working principle easy to understand and interesting to observe. It is also built using low-cost and easily available components, making the project affordable and suitable for students.", "safetyHazards": ["none", "moving_rotating_machinery"], "safetyPrecautions": "All electrical connections are properly insulated and checked before use.\r\nThe battery voltage is kept within the safe operating range.\r\nThe robot is tested at low speed in an open area to avoid collisions.\r\nThe power supply is switched off before changing .", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-27T16:27:16.91Z", "updatedAt": "2026-10-11T17:31:56.987Z", "abstract": { "originalName": "DOC-20260926-WA0039.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790526436/aura-registrations/abstract-docs/DOC-20260926-WA0039.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/SAOANA/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/SAOANA/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790526435/aura-registrations/id-cards/irx6fzqrf9dtduahadhi.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/SAOANA/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790526435/aura-registrations/id-cards/u66i8mn4ly3jh4i5ysgb.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/SAOANA/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/SAOANA/4.jpg", "url": null, "exists": false }] }, { "index": 10, "id": "6ab9eeb67b6ef896b8f78257", "registrationId": "AURA2K26-CYHF2B", "rawTeamName": "Optix", "folderName": "Optix", "folderRelPath": "assets/Teams/Optix", "projectTitle": "NightPulse", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Md Tahseen alam", "teamLeaderEmail": "alamtahseen.dev@gmail.com", "teamLeaderPhone": "6200568732", "teamMemberDetails": "Warish imam / aliah university/mechanical engineering department/MEN244069\r\nSK MD ferdosh/aliah university/computer science and engineering/CSE253003\r\nMD Afzal hussain/ aliah university/mechanical engineering department/MEN244029", "hardwareProjectCategories": ["Electronics & Communication", "IoT & Smart Devices"], "prototypeType": "Wearable Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Problem Statement\r\nProfessional night vision systems are prohibitively expensive for civilian, academic, or low-resource emergency use. Traditional goggles rely on costly analog image intensifier tubes or expensive microbolometers, creating a massive financial barrier to entry for accessible zero-light navigation and monitoring.\r\n\r\n​Hardware Solution\r\nNightPulse bridges this gap by repurposing off-the-shelf consumer electronics into a cohesive wearable device. By modifying standard digital CMOS cameras to remove their factory IR-cut filters, the sensors become highly sensitive to near-infrared light. The environment is actively illuminated using a 940nm invisible infrared LED array, capturing a high-resolution video feed in total darkness. This feed is routed to an integrated smartphone, where software renders the image into a stereoscopic side-by-side (SBS) display. Housed within a standard VR headset shell, it provides the user with an immersive, hands-free night vision experience.\r\n\r\n​Innovation Details\r\nThe core innovation is achieving functional, stereoscopic depth perception at a fraction of the cost of commercial equivalents. NightPulse democratizes active-IR technology by fusing repurposed camera hardware with accessible smartphone VR capabilities. This modular approach transforms everyday electronics into a specialized smart device, proving that effective, real-time spatial navigation in zero-light conditions does not require military-grade budgets.", "solutionDescription": "Problem Statement\r\nProfessional night vision systems are prohibitively expensive for civilian, academic, or low-resource emergency use. Traditional goggles rely on costly analog image intensifier tubes or expensive microbolometers, creating a massive financial barrier to entry for accessible zero-light navigation and monitoring.\r\n\r\n​Hardware Solution\r\nNightPulse bridges this gap by repurposing off-the-shelf consumer electronics into a cohesive wearable device. By modifying standard digital CMOS cameras to remove their factory IR-cut filters, the sensors become highly sensitive to near-infrared light. The environment is actively illuminated using a 940nm invisible infrared LED array, capturing a high-resolution video feed in total darkness. This feed is routed to an integrated smartphone, where software renders the image into a stereoscopic side-by-side (SBS) display. Housed within a standard VR headset shell, it provides the user with an immersive, hands-free night vision experience.\r\n\r\n​Innovation Details\r\nThe core innovation is achieving functional, stereoscopic depth perception at a fraction of the cost of commercial equivalents. NightPulse democratizes active-IR technology by fusing repurposed camera hardware with accessible smartphone VR capabilities. This modular approach transforms everyday electronics into a specialized smart device, proving that effective, real-time spatial navigation in zero-light conditions does not require military-grade budgets.", "innovationDescription": "Problem Statement\r\nProfessional night vision systems are prohibitively expensive for civilian, academic, or low-resource emergency use. Traditional goggles rely on costly analog image intensifier tubes or expensive microbolometers, creating a massive financial barrier to entry for accessible zero-light navigation and monitoring.\r\n\r\n​Hardware Solution\r\nNightPulse bridges this gap by repurposing off-the-shelf consumer electronics into a cohesive wearable device. By modifying standard digital CMOS cameras to remove their factory IR-cut filters, the sensors become highly sensitive to near-infrared light. The environment is actively illuminated using a 940nm invisible infrared LED array, capturing a high-resolution video feed in total darkness. This feed is routed to an integrated smartphone, where software renders the image into a stereoscopic side-by-side (SBS) display. Housed within a standard VR headset shell, it provides the user with an immersive, hands-free night vision experience.\r\n\r\n​Innovation Details\r\nThe core innovation is achieving functional, stereoscopic depth perception at a fraction of the cost of commercial equivalents. NightPulse democratizes active-IR technology by fusing repurposed camera hardware with accessible smartphone VR capabilities. This modular approach transforms everyday electronics into a specialized smart device, proving that effective, real-time spatial navigation in zero-light conditions does not require military-grade budgets.", "workingPrinciple": "NightPulse operates on the principle of active infrared (IR) digital imaging. Standard CMOS camera sensors are inherently sensitive to near-infrared light but are typically blocked by factory-installed IR-cut filters. By removing this filter, the camera can capture IR wavelengths. The workflow begins with an active illuminator—a 940nm IR LED ring—flooding the dark environment with infrared light, which remains completely invisible to the human eye. The modified UVC USB camera captures the IR light reflected off the surroundings. This continuous video stream is transmitted via a USB-OTG connection to an integrated Android smartphone. Custom software on the smartphone processes the raw UVC data and splits the feed into a stereoscopic Side-by-Side (SBS) display. Finally, the smartphone is mounted inside a plastic VR headset shell. The lenses in the VR shell bend the SBS display to accommodate the user's focal length, rendering a unified, immersive image with restored depth perception in total darkness.", "majorHardwareComponents": ["​1. Vision Sensor: 1080p UVC USB Camera Module (modified via the manual removal of the IR-cut filter) equipped with an M12 wide-angle lens.\n​2. Active Illuminator: 940nm Infrared (IR) LED Ring", "providing invisible low-light illumination.\n​3. Power Delivery: A portable 7.4V Lithium-ion Battery Pack (e.g.", "2x 18650 cells).\n4. ​Voltage Regulation: MT3608 DC-DC Step-Up Boost Converter (to step the 7.4V up to 12V DC for the LED ring).\n​5. Data Transmission: High-speed USB-OTG (On-The-Go) adapter for UVC protocol streaming.\n​6. Computing & Display: Android Smartphone capable of running SBS (Side-by-Side) VR camera applications and acting as the stereoscopic screen.\n​7. Mechanical Housing: Plastic VR Headset Shell to mount the smartphone", "focus the lenses", "and secure the external hardware."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Other", "General Public"], "potentialImpact": "The primary beneficiaries of NightPulse are low-resource emergency responders, night-shift security personnel, wildlife observers, and amateur explorers. Currently, functional zero-light navigation requires military-grade analog image intensifier tubes or high-resolution thermal microbolometers, both of which cost thousands of dollars. NightPulse dramatically improves upon these current financial and accessibility standards by democratizing night vision technology. By leveraging off-the-shelf, low-cost consumer electronics and repurposing the immense processing power and display capabilities of everyday smartphones, this prototype achieves stereoscopic active-IR vision at a fraction of the traditional cost. Furthermore, it eliminates the single-eye fatigue common in cheap monocular night vision scopes by utilizing a dual-lens VR approach, preserving user depth perception and reducing motion sickness during physical navigation. This makes hands-free, zero-light mobility accessible to civilian sectors, rural watch groups, and academic researchers who were previously priced out of the market.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "NightPulse stands out because it solves a high-cost hardware problem using accessible, everyday consumer electronics. While traditional night vision goggles cost thousands of dollars and remain restricted to military or high-end commercial sectors, NightPulse achieves effective active-infrared capability for under ₹5,000.\r\n​The most impressive aspect of this prototype is its clever integration of existing technologies. By taking an inexpensive UVC camera, stripping its IR-cut filter, and pairing it with the processing power and high-resolution display of a standard smartphone, it completely bypasses the need for expensive analog image intensifier tubes. Furthermore, it leverages basic VR headset housings to provide a stereoscopic Side-by-Side (SBS) display. This restores the user's natural depth perception—a critical feature for physical navigation that is entirely missing from budget monocular night vision scopes.\r\nJudges should pay attention to NightPulse because it is a prime example of frugal innovation. It proves that hands-free spatial navigation in total darkness does not require military-grade budgets. It is a highly practical, ready-to-use wearable device that successfully democratizes zero-light navigation for civilians, low-resource emergency responders, and academic researchers.", "safetyHazards": ["none"], "safetyPrecautions": "The NightPulse prototype incorporates multiple safety measures to ensure safe wearable operation during live demonstrations:\r\n​1. Electrical & Battery Safeguards: The 18650 Lithium-ion power source is equipped with a Battery Management System (BMS) protection circuit to guard against overcharging, over-discharging, and short-circuits. All internal wiring between the step-up boost converter and the IR LED array is fully heat-shrink insulated.\r\n2. ​Thermal Management: Operating strictly under low-voltage DC (12V max), the system poses no electrical shock hazard. Passive heat-dissipating mounts isolate the warm IR LED ring from direct contact with the user or the VR shell.\r\n3. ​Ergonomic Safety: All hardware components are securely mounted to the exterior housing using non-conductive materials. The user's face remains fully cushioned by the headset's factory foam padding, completely isolating skin from electrical components and preventing optical strain.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-28T04:36:06.797Z", "updatedAt": "2026-10-11T17:32:01.752Z", "abstract": { "originalName": "DOC-20260927-WA0018 (1).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790570165/aura-registrations/abstract-docs/DOC-20260927-WA0018%20%281%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Optix/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Optix/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790570166/aura-registrations/id-cards/axmyiyibnboc8vsbckxu.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Optix/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790570165/aura-registrations/id-cards/z9sogwzaehzh1fykrtix.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Optix/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790570165/aura-registrations/id-cards/jbwxvnzi5ubaltjw9zxp.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Optix/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790570166/aura-registrations/id-cards/pvvycwborjzeifyd21az.jpg", "exists": true }] }, { "index": 11, "id": "6aba784a872cf26c69fc2ba9", "registrationId": "AURA2K26-849TM6", "rawTeamName": "\"TECHWALK\"", "folderName": "TECHWALK", "folderRelPath": "assets/Teams/TECHWALK", "projectTitle": "SMART BLIND STICK", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "MD SABAB ALAM", "teamLeaderEmail": "mdsababalam9427@gmail.com", "teamLeaderPhone": "9883229209", "teamMemberDetails": "1) UMME RUMAN KHATUN , 7003157040\r\n2) MD ZUNED SHAREYAR , 8391899464", "hardwareProjectCategories": ["Embedded Systems", "Electronics & Communication", "IoT & Smart Devices", "Safety & Security Systems"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "PROBLEM STATEMENT :-\r\n\r\nVisually impaired people often face difficulties while walking independently, especially in crowded streets, unfamiliar areas, and places with unexpected obstacles. Traditional white canes mainly help users detect obstacles through physical contact, but they may not provide sufficient warning about obstacles located at different heights or about hazards such as water on the walking path. This can increase the risk of collisions, falls, and accidents. There is therefore a need for an affordable, lightweight, and easy-to-use assistive device that can provide early warnings about common hazards while allowing the user to move more independently.\r\n\r\nSOLUTION :-\r\n\r\nThe proposed Smart Blind Stick is an electronic assistive device designed to improve the safety and awareness of visually impaired users. An Arduino Nano acts as the main controller and processes information from different sensors.\r\n\r\nAn ultrasonic sensor continuously detects obstacles in front of the user by transmitting ultrasonic waves and measuring the time taken for the reflected waves to return. The Arduino converts this time into distance. According to the detected distance, the system generates different warning patterns using a buzzer and vibration motor. For example, a distant obstacle can produce slower alerts, while a nearby obstacle can produce faster alerts, allowing the user to understand the approximate distance without looking at the device.\r\n\r\nA water detection sensor can identify water on the ground and generate a separate warning. This helps the user recognize potentially slippery or flooded areas. The system can be powered using a rechargeable battery, making the stick portable and practical for everyday use.\r\n\r\nINNOVATION :-\r\n\r\nThe key innovation of the project is the combination of distance-based obstacle detection, vibration/audio feedback, and water detection in a compact and low-cost device. Instead of providing only a simple obstacle warning, the Smart Blind Stick communicates the approximate danger level through changing beep and vibration patterns.\r\n\r\nThe system is designed using easily available and inexpensive electronic components, making it suitable for student-level development and potentially accessible to users with limited financial resources. The modular design also allows future upgrades such as GPS-based location tracking, emergency alerts, GSM communication, and IoT connectivity.\r\n\r\nThe project demonstrates how embedded electronics can be applied to solve a real-world accessibility problem and provide visually impaired users with additional environmental awareness and safer mobility.", "solutionDescription": "PROBLEM STATEMENT :-\r\n\r\nVisually impaired people often face difficulties while walking independently, especially in crowded streets, unfamiliar areas, and places with unexpected obstacles. Traditional white canes mainly help users detect obstacles through physical contact, but they may not provide sufficient warning about obstacles located at different heights or about hazards such as water on the walking path. This can increase the risk of collisions, falls, and accidents. There is therefore a need for an affordable, lightweight, and easy-to-use assistive device that can provide early warnings about common hazards while allowing the user to move more independently.\r\n\r\nSOLUTION :-\r\n\r\nThe proposed Smart Blind Stick is an electronic assistive device designed to improve the safety and awareness of visually impaired users. An Arduino Nano acts as the main controller and processes information from different sensors.\r\n\r\nAn ultrasonic sensor continuously detects obstacles in front of the user by transmitting ultrasonic waves and measuring the time taken for the reflected waves to return. The Arduino converts this time into distance. According to the detected distance, the system generates different warning patterns using a buzzer and vibration motor. For example, a distant obstacle can produce slower alerts, while a nearby obstacle can produce faster alerts, allowing the user to understand the approximate distance without looking at the device.\r\n\r\nA water detection sensor can identify water on the ground and generate a separate warning. This helps the user recognize potentially slippery or flooded areas. The system can be powered using a rechargeable battery, making the stick portable and practical for everyday use.\r\n\r\nINNOVATION :-\r\n\r\nThe key innovation of the project is the combination of distance-based obstacle detection, vibration/audio feedback, and water detection in a compact and low-cost device. Instead of providing only a simple obstacle warning, the Smart Blind Stick communicates the approximate danger level through changing beep and vibration patterns.\r\n\r\nThe system is designed using easily available and inexpensive electronic components, making it suitable for student-level development and potentially accessible to users with limited financial resources. The modular design also allows future upgrades such as GPS-based location tracking, emergency alerts, GSM communication, and IoT connectivity.\r\n\r\nThe project demonstrates how embedded electronics can be applied to solve a real-world accessibility problem and provide visually impaired users with additional environmental awareness and safer mobility.", "innovationDescription": "PROBLEM STATEMENT :-\r\n\r\nVisually impaired people often face difficulties while walking independently, especially in crowded streets, unfamiliar areas, and places with unexpected obstacles. Traditional white canes mainly help users detect obstacles through physical contact, but they may not provide sufficient warning about obstacles located at different heights or about hazards such as water on the walking path. This can increase the risk of collisions, falls, and accidents. There is therefore a need for an affordable, lightweight, and easy-to-use assistive device that can provide early warnings about common hazards while allowing the user to move more independently.\r\n\r\nSOLUTION :-\r\n\r\nThe proposed Smart Blind Stick is an electronic assistive device designed to improve the safety and awareness of visually impaired users. An Arduino Nano acts as the main controller and processes information from different sensors.\r\n\r\nAn ultrasonic sensor continuously detects obstacles in front of the user by transmitting ultrasonic waves and measuring the time taken for the reflected waves to return. The Arduino converts this time into distance. According to the detected distance, the system generates different warning patterns using a buzzer and vibration motor. For example, a distant obstacle can produce slower alerts, while a nearby obstacle can produce faster alerts, allowing the user to understand the approximate distance without looking at the device.\r\n\r\nA water detection sensor can identify water on the ground and generate a separate warning. This helps the user recognize potentially slippery or flooded areas. The system can be powered using a rechargeable battery, making the stick portable and practical for everyday use.\r\n\r\nINNOVATION :-\r\n\r\nThe key innovation of the project is the combination of distance-based obstacle detection, vibration/audio feedback, and water detection in a compact and low-cost device. Instead of providing only a simple obstacle warning, the Smart Blind Stick communicates the approximate danger level through changing beep and vibration patterns.\r\n\r\nThe system is designed using easily available and inexpensive electronic components, making it suitable for student-level development and potentially accessible to users with limited financial resources. The modular design also allows future upgrades such as GPS-based location tracking, emergency alerts, GSM communication, and IoT connectivity.\r\n\r\nThe project demonstrates how embedded electronics can be applied to solve a real-world accessibility problem and provide visually impaired users with additional environmental awareness and safer mobility.", "workingPrinciple": "WORKING PRINCIPLE :-\r\n\r\nThe SMARTGUARD Smart Stick works by continuously detecting obstacles and water hazards in the user’s surroundings. The system is controlled by an ESP32 microcontroller, which receives information from different sensors and converts it into simple warning signals.\r\n\r\nA front ultrasonic/ToF distance sensor continuously measures the distance between the stick and objects ahead. When an obstacle is detected within a predefined range, the ESP32 processes the sensor data and activates a vibration motor and buzzer/speaker to warn the user. The vibration provides a tactile alert, allowing the user to understand that an obstacle is present without depending only on sound.\r\n\r\nA water sensor is positioned near the lower part of the stick to detect water or puddles on the walking path. When water is detected, the sensor sends a signal to the ESP32. The controller identifies it as a water hazard and produces a different vibration pattern and/or audio alert so that the user can distinguish it from a normal obstacle.\r\n\r\nThe system therefore uses hazard-specific feedback: one alert pattern for obstacles and another for water. This makes the information easier to understand while walking.\r\n\r\nThe ESP32 continuously repeats this sensing–processing–alert cycle in real time. The project is designed as a low-cost assistive system that improves environmental awareness and helps visually impaired users identify common walking hazards more safely and independently.", "majorHardwareComponents": ["MAJOR HARDWARE COMPONENTS :-\n\nThe SMARTGUARD Smart Stick uses a combination of sensors", "a microcontroller", "and alert devices to detect obstacles and water hazards.\n\n1. ARDUINO NANO : The Arduino Nano is the main control unit of the system. It receives signals from the sensors", "processes the data", "identifies hazards", "and activates the appropriate warning devices.\n\n\n2. FRONT DISTANCE SENSOR : An ultrasonic or ToF sensor is placed at the front of the stick to measure the distance between the user and obstacles. When an object comes within a predefined range", "the Arduino Nano triggers an alert.\n\n\n3. WATER SENSOR : A water detection sensor is positioned near the bottom of the stick. It detects water or puddles on the walking path and sends a signal to the Arduino Nano.\n\n\n4. VIBRATION MOTOR : The vibration motor provides tactile feedback. Different vibration patterns can be used to distinguish between an obstacle and water.\n\n\n5. BUZZER / SPEAKER : The buzzer or speaker provides an audio warning whenever a hazard is detected. Different sound patterns can represent different hazards.\n\n\n6. RECHARGEBLE BATTERY : A Li-ion battery supplies power to the Arduino Nano", "sensors", "and alert devices.\n\n\n7. TP4056 CHARGING MODULE : This module is used to recharge the Li-ion battery safely.\n\n\n8. WIRE", "SWITCH", "ENCLOSURE: These provide electrical connections", "power control", "and physical protection for the electronics.\n\n\n\nTogether", "these components form a compact", "low-cost", "real-time hazard detection system that helps visually impaired users identify obstacles and water hazards while walking."], "useAi": true, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Persons with Disabilities"], "potentialImpact": "POTENTIAL REAL WORLD IMPACT :-\r\n\r\nThe Smart Blind Stick can significantly improve the safety, mobility, and independence of visually impaired people. The system uses an Arduino Nano, ultrasonic sensors, and a water-detection sensor to identify common hazards that may be difficult to detect using a conventional white cane.\r\n\r\nObstacle detection: Detects objects in the user’s path and provides different buzzer patterns according to the approximate distance of the obstacle.\r\n\r\nWater hazard detection: Identifies water on the walking surface and alerts the user, helping prevent slips and falls.\r\n\r\nImproved independence: Allows visually impaired users to navigate familiar and unfamiliar surroundings with greater confidence.\r\n\r\nLow-cost solution: Uses affordable and easily available electronic components, making the technology more accessible.\r\n\r\nUseful in daily environments: Can assist on roads, footpaths, corridors, campuses, and other public areas.\r\n\r\nScope for future development: GPS, emergency-alert systems, vibration feedback, and IoT connectivity can be added to make the stick more intelligent.\r\n\r\n\r\nOverall, the project aims to transform a conventional walking stick into an affordable electronic assistive device that provides real-time hazard warnings and supports safer mobility.", "productPotential": "potentially", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "THE PROJECT WORTH :-\r\n\r\nThe Smart Blind Stick is worth seeing because it converts a simple traditional walking stick into an intelligent safety device using affordable electronics.\r\n\r\n🚶 Solves a real problem: Helps visually impaired people detect hazards while walking.\r\n\r\n📡 Real-time detection: Ultrasonic sensors detect obstacles and provide immediate alerts.\r\n\r\n💧 Detects water hazards: The water sensor can warn the user about water on the walking path.\r\n\r\n🔊 Easy-to-understand alerts: Different buzzer patterns can indicate how close an obstacle is.\r\n\r\n💰 Low-cost and practical: The prototype can be built at around ₹1,500, making it suitable for affordable assistive technology.\r\n\r\n⚙️ ECE-focused innovation: Combines sensors, Arduino Nano, signal processing, and alert systems in one compact device.\r\n\r\n🚀 Future-ready: GPS, emergency alerts, vibration feedback, and IoT features can be added later.", "safetyHazards": ["none"], "safetyPrecautions": "SAFETY PRECAUTIONS TAKEN :-\r\n\r\nLow-voltage components are used to reduce electrical hazards.\r\n\r\nAll electronic connections are properly insulated to prevent short circuits.\r\n\r\nThe Arduino Nano and sensors are securely mounted on the stick to prevent loose connections.\r\n\r\nWires are properly routed and fixed so they do not interfere with walking.\r\n\r\nThe water sensor is positioned to detect water while keeping the main electronic circuit protected from moisture.\r\n\r\nA battery with suitable voltage is used to power the circuit safely.\r\n\r\nThe buzzer provides immediate audible alerts without requiring the user to look at the device.\r\n\r\nThe stick is tested at different obstacle distances before demonstration.\r\n\r\nThe system is designed as an assistive prototype and should not replace normal safety awareness or other mobility assistance.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-28T14:23:06.924Z", "updatedAt": "2026-10-11T17:32:06.537Z", "abstract": { "originalName": "1000113722.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790605385/aura-registrations/abstract-docs/1000113722.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/TECHWALK/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/TECHWALK/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790605385/aura-registrations/id-cards/hy0llaoouyl2crsafpha.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/TECHWALK/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790605385/aura-registrations/id-cards/fqoqcfomux2n3p1q1soa.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/TECHWALK/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790605385/aura-registrations/id-cards/ak5tiytnysaris7td7sd.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/TECHWALK/4.jpg", "url": null, "exists": false }] }, { "index": 12, "id": "6abaa49f6b098e7ecbd28055", "registrationId": "AURA2K26-4VZWNU", "rawTeamName": "HydroFix", "folderName": "HydroFix", "folderRelPath": "assets/Teams/HydroFix", "projectTitle": "Autonomous Robotic arm", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "Md Ali", "teamLeaderEmail": "zaynakash777@gmail.com", "teamLeaderPhone": "8001342389", "teamMemberDetails": "Mir Soleman Ali,", "hardwareProjectCategories": ["Robotics", "Embedded Systems", "AI-Enabled Hardware"], "prototypeType": "Robotic System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem:\r\nAffordable autonomous robotic systems for small-scale object handling are not easily accessible to students, educational institutions, and small-scale applications.\r\n\r\nSolution:\r\nPickBot is a low-cost autonomous robotic arm that uses computer vision and servo-controlled mechanisms to detect objects and perform pick-and-place tasks with minimal human intervention.", "solutionDescription": "Problem:\r\nAffordable autonomous robotic systems for small-scale object handling are not easily accessible to students, educational institutions, and small-scale applications.\r\n\r\nSolution:\r\nPickBot is a low-cost autonomous robotic arm that uses computer vision and servo-controlled mechanisms to detect objects and perform pick-and-place tasks with minimal human intervention.", "innovationDescription": "Problem:\r\nAffordable autonomous robotic systems for small-scale object handling are not easily accessible to students, educational institutions, and small-scale applications.\r\n\r\nSolution:\r\nPickBot is a low-cost autonomous robotic arm that uses computer vision and servo-controlled mechanisms to detect objects and perform pick-and-place tasks with minimal human intervention.", "workingPrinciple": "System Specifications & Technical Details:\r\nESP32-based 5-DOF robotic arm with servo motors and a gripper, equipped with a camera for computer-vision-based object detection, wireless communication, and autonomous pick-and-place control using embedded software and intelligent motion planning.", "majorHardwareComponents": ["ESP32 microcontroller", "5 servo motors", "robotic arm mechanism", "gripper", "camera module", "motor power supply", "and mechanical frame/body."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "Transportation", "Agriculture"], "potentialImpact": "Potential Real-World Impact:\r\nEnables affordable autonomous automation for small-scale industries, warehouses, laboratories, and educational institutions by reducing repetitive manual work and making robotic technology more accessible.", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "PickBot demonstrates how low-cost hardware, computer vision, and autonomous control can be combined to transform a simple robotic arm into an intelligent system capable of perceiving and interacting with real-world objects.", "safetyHazards": ["none"], "safetyPrecautions": "Nothing", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-28T17:32:15.482Z", "updatedAt": "2026-10-11T17:32:10.893Z", "abstract": { "originalName": "PickBot_Hackathon_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790616734/aura-registrations/abstract-docs/PickBot_Hackathon_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/HydroFix/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/HydroFix/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790616734/aura-registrations/id-cards/cywxmodao3if2nnwoczf.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/HydroFix/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790616734/aura-registrations/id-cards/qntze1vnqf93gwgdzlgs.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/HydroFix/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/HydroFix/4.jpg", "url": null, "exists": false }] }, { "index": 13, "id": "6abaa9c3d21450140ef800e2", "registrationId": "AURA2K26-HMW249", "rawTeamName": "Cache Me If You Can", "folderName": "Cache Me If You Can", "folderRelPath": "assets/Teams/Cache Me If You Can", "projectTitle": "KRISHIDRISHTI", "teamSize": 4, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 4, "teamLeaderName": "Mayukh Dey Dhara", "teamLeaderEmail": "mayukhdeydhara17@gmail.com", "teamLeaderPhone": "9330290195", "teamMemberDetails": "Shreejib Das | TECHNO MAIN SALT LAKE | CSE(DS) | 1st yr,2026-2030 | 9051877529\r\nAnushka Singh | TECHNO MAIN SALT LAKE | CSE(DS) | 1st yr,2026-2030 | 9836805847\r\nNeevv Khillan | TECHNO MAIN SALT LAKE | CSE(AIML) | 1st yr,2026-2030 | 8535941159", "hardwareProjectCategories": ["IoT & Smart Devices", "Electronics & Communication", "Embedded Systems", "Electrical Systems", "Automation & Control", "AI-Enabled Hardware", "Assistive Technology", "Smart Agriculture", "Environmental Technology"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Agriculture remains the backbone of many economies, yet farmers continue to face challenges such as irregular irrigation, crop diseases, unpredictable weather conditions, and inefficient resource utilization. Traditional farming methods often rely on manual observation and experience, which can lead to delayed decisions, water wastage, reduced crop yields, and financial losses. Small and medium-scale farmers are especially affected due to limited access to advanced agricultural technologies and expert guidance.\r\n\r\nKRISHIDRISHTI addresses these challenges through an intelligent agriculture decision-support system that leverages the power of IoT, Artificial Intelligence, and data analytics. The system continuously collects real-time field data using sensors that monitor soil moisture, temperature, humidity, rainfall, and light intensity. This data is transmitted through an ESP32-based communication layer to a cloud-enabled backend where it is securely stored and analyzed.\r\n\r\nThe core innovation of KRISHIDRISHTI lies in transforming raw environmental data into actionable farming recommendations. Instead of simply displaying sensor readings, the platform provides irrigation suggestions, crop-health insights, pest and disease detection, and yield estimation support. Farmers can upload crop images, which are processed by AI models to identify potential diseases and pests. The integrated AI assistant, KrishiSaathi, explains recommendations in a simple and understandable manner, enabling farmers to make informed decisions.\r\n\r\nAnother innovative aspect is the platform's focus on explainable intelligence. Every recommendation is accompanied by a reason, helping farmers understand why a specific action is suggested. This increases trust and encourages technology adoption among rural communities.\r\n\r\nThe solution also incorporates farm economics analysis by estimating operational costs, expected revenue, and profit margins. This feature helps farmers optimize not only crop productivity but also financial planning.\r\n\r\nKRISHIDRISHTI is designed to be scalable, affordable, and accessible. By combining IoT hardware, AI-powered analytics, multilingual support, and a farmer-friendly interface, it creates a complete ecosystem for precision agriculture. The system reduces water consumption, improves crop health management, minimizes losses caused by diseases, and supports sustainable farming practices. Through intelligent automation and data-driven insights, KRISHIDRISHTI empowers farmers to achieve higher productivity while conserving valuable agricultural resources.", "solutionDescription": "Agriculture remains the backbone of many economies, yet farmers continue to face challenges such as irregular irrigation, crop diseases, unpredictable weather conditions, and inefficient resource utilization. Traditional farming methods often rely on manual observation and experience, which can lead to delayed decisions, water wastage, reduced crop yields, and financial losses. Small and medium-scale farmers are especially affected due to limited access to advanced agricultural technologies and expert guidance.\r\n\r\nKRISHIDRISHTI addresses these challenges through an intelligent agriculture decision-support system that leverages the power of IoT, Artificial Intelligence, and data analytics. The system continuously collects real-time field data using sensors that monitor soil moisture, temperature, humidity, rainfall, and light intensity. This data is transmitted through an ESP32-based communication layer to a cloud-enabled backend where it is securely stored and analyzed.\r\n\r\nThe core innovation of KRISHIDRISHTI lies in transforming raw environmental data into actionable farming recommendations. Instead of simply displaying sensor readings, the platform provides irrigation suggestions, crop-health insights, pest and disease detection, and yield estimation support. Farmers can upload crop images, which are processed by AI models to identify potential diseases and pests. The integrated AI assistant, KrishiSaathi, explains recommendations in a simple and understandable manner, enabling farmers to make informed decisions.\r\n\r\nAnother innovative aspect is the platform's focus on explainable intelligence. Every recommendation is accompanied by a reason, helping farmers understand why a specific action is suggested. This increases trust and encourages technology adoption among rural communities.\r\n\r\nThe solution also incorporates farm economics analysis by estimating operational costs, expected revenue, and profit margins. This feature helps farmers optimize not only crop productivity but also financial planning.\r\n\r\nKRISHIDRISHTI is designed to be scalable, affordable, and accessible. By combining IoT hardware, AI-powered analytics, multilingual support, and a farmer-friendly interface, it creates a complete ecosystem for precision agriculture. The system reduces water consumption, improves crop health management, minimizes losses caused by diseases, and supports sustainable farming practices. Through intelligent automation and data-driven insights, KRISHIDRISHTI empowers farmers to achieve higher productivity while conserving valuable agricultural resources.", "innovationDescription": "Agriculture remains the backbone of many economies, yet farmers continue to face challenges such as irregular irrigation, crop diseases, unpredictable weather conditions, and inefficient resource utilization. Traditional farming methods often rely on manual observation and experience, which can lead to delayed decisions, water wastage, reduced crop yields, and financial losses. Small and medium-scale farmers are especially affected due to limited access to advanced agricultural technologies and expert guidance.\r\n\r\nKRISHIDRISHTI addresses these challenges through an intelligent agriculture decision-support system that leverages the power of IoT, Artificial Intelligence, and data analytics. The system continuously collects real-time field data using sensors that monitor soil moisture, temperature, humidity, rainfall, and light intensity. This data is transmitted through an ESP32-based communication layer to a cloud-enabled backend where it is securely stored and analyzed.\r\n\r\nThe core innovation of KRISHIDRISHTI lies in transforming raw environmental data into actionable farming recommendations. Instead of simply displaying sensor readings, the platform provides irrigation suggestions, crop-health insights, pest and disease detection, and yield estimation support. Farmers can upload crop images, which are processed by AI models to identify potential diseases and pests. The integrated AI assistant, KrishiSaathi, explains recommendations in a simple and understandable manner, enabling farmers to make informed decisions.\r\n\r\nAnother innovative aspect is the platform's focus on explainable intelligence. Every recommendation is accompanied by a reason, helping farmers understand why a specific action is suggested. This increases trust and encourages technology adoption among rural communities.\r\n\r\nThe solution also incorporates farm economics analysis by estimating operational costs, expected revenue, and profit margins. This feature helps farmers optimize not only crop productivity but also financial planning.\r\n\r\nKRISHIDRISHTI is designed to be scalable, affordable, and accessible. By combining IoT hardware, AI-powered analytics, multilingual support, and a farmer-friendly interface, it creates a complete ecosystem for precision agriculture. The system reduces water consumption, improves crop health management, minimizes losses caused by diseases, and supports sustainable farming practices. Through intelligent automation and data-driven insights, KRISHIDRISHTI empowers farmers to achieve higher productivity while conserving valuable agricultural resources.", "workingPrinciple": "KRISHIDRISHTI operates through a systematic pipeline that converts field observations into intelligent farming decisions. The workflow follows the sequence: Sense → Transmit → Store → Analyze → Explain → Act.\r\n\r\nThe process begins with IoT sensors deployed in agricultural fields. These sensors continuously monitor important environmental parameters such as soil moisture, temperature, humidity, rainfall, and sunlight exposure. The collected readings are processed by an ESP32 microcontroller, which acts as the central data acquisition unit.\r\n\r\nThe ESP32 transmits the collected information to a backend server through a communication network. Once received, the data is stored in a structured SQL database for historical tracking and future analysis. A Flask-based application processes incoming information and performs trend analysis, threshold monitoring, and predictive assessment.\r\n\r\nThe analytics engine evaluates environmental conditions to determine irrigation requirements, detect crop stress, and identify potential risks. AI algorithms compare sensor patterns with agricultural datasets to generate recommendations. Farmers can additionally upload crop images, which are analyzed using machine learning models for pest and disease identification.\r\n\r\nThe system then converts analytical results into simple recommendations through the KrishiSaathi advisory platform. Notifications, alerts, and suggestions are generated in a user-friendly format and delivered through the farmer dashboard. Each recommendation includes a clear explanation, ensuring transparency and trust.\r\n\r\nThe farmer can then take corrective actions such as adjusting irrigation schedules, applying treatments, or implementing preventive measures. This closed-loop process enables continuous monitoring and improvement, allowing data-driven decision-making throughout the farming cycle.", "majorHardwareComponents": ["KRISHIDRISHTI utilizes a set of carefully selected hardware components that work together to collect accurate agricultural data and facilitate intelligent decision-making.\n\nThe primary component is the ESP32 microcontroller", "which serves as the central processing and communication unit. It receives data from various sensors", "performs preliminary processing", "and transmits information to the backend server through wireless connectivity.\n\nThe soil moisture sensor measures the water content present in the soil. This sensor is critical for determining irrigation requirements and preventing overwatering or underwatering conditions.\n\nA temperature sensor monitors ambient environmental temperature", "which directly influences crop growth", "evaporation rates", "and disease development. Alongside it", "a humidity sensor measures atmospheric moisture levels", "helping assess plant health and weather-related risks.\n\nThe system also incorporates a rainfall sensor that detects precipitation events and assists in adjusting irrigation recommendations accordingly. This prevents unnecessary water usage during rainy periods and contributes to water conservation.\n\nA light intensity sensor measures sunlight exposure received by crops. Light data helps evaluate growing conditions and identify environmental factors affecting crop productivity.\n\nSupporting hardware includes a regulated power supply", "communication modules integrated within the ESP32", "connecting wires", "protective sensor housings", "and field deployment accessories. A smartphone or computer acts as the user interface for accessing recommendations and monitoring field conditions.\n\nTogether", "these components create a low-cost", "scalable", "and reliable monitoring network capable of collecting real-time agricultural data. The hardware architecture ensures accurate sensing", "efficient communication", "and seamless integration with the AI-powered analytics platform."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Agriculture", "Rural Communities", "General Public", "Government / Public Services"], "potentialImpact": "KRISHIDRISHTI has the potential to significantly transform modern agricultural practices by enabling data-driven farming decisions. One of its most important impacts is efficient water management. By providing precise irrigation recommendations based on soil and weather conditions, the system reduces water wastage and promotes sustainable resource utilization.\r\n\r\nThe platform also contributes to improved crop health. Early detection of pests, diseases, and environmental stress enables timely intervention, reducing crop losses and improving productivity. Farmers can take preventive measures before problems become severe, resulting in healthier crops and better yields.\r\n\r\nAnother major impact is economic empowerment. Through yield estimation and farm economics analysis, farmers gain valuable insights into costs, expected revenues, and profitability. These insights support better planning and resource allocation, ultimately increasing financial stability.\r\n\r\nKRISHIDRISHTI can also bridge the knowledge gap in rural communities. The multilingual KrishiSaathi assistant makes advanced agricultural intelligence accessible to farmers regardless of technical expertise. Explainable recommendations increase trust and encourage technology adoption.\r\n\r\nAt a larger scale, widespread deployment can contribute to food security by improving agricultural efficiency and crop production. Reduced water consumption and optimized input usage also support environmental sustainability. Governments, agricultural agencies, and cooperatives can leverage the platform for regional agricultural monitoring and planning.\r\n\r\nBy integrating IoT, AI, and accessible advisory services, KRISHIDRISHTI has the potential to improve livelihoods, strengthen agricultural resilience, and promote sustainable farming practices across diverse farming ecosystems.", "productPotential": "yes", "prototypeDevelopmentCost": 4500, "auraDemoHighlight": "KRISHIDRISHTI stands out because it combines multiple cutting-edge technologies into a single practical solution that addresses real-world agricultural challenges. Unlike conventional monitoring systems that only display sensor readings, KRISHIDRISHTI interprets data and provides meaningful recommendations that farmers can immediately act upon.\r\n\r\nThe project demonstrates the effective integration of IoT hardware, cloud-based data management, artificial intelligence, image-based disease detection, and explainable decision support. This multidisciplinary approach showcases innovation across electronics, software engineering, machine learning, and agriculture.\r\n\r\nVisitors will find the real-time sensor monitoring particularly engaging. Live field data can be visualized instantly, demonstrating how environmental conditions influence agricultural decisions. The AI-powered KrishiSaathi assistant adds an interactive element by explaining recommendations in a simple and understandable manner.\r\n\r\nThe disease detection feature further enhances the project's appeal. By uploading crop images, users can experience how artificial intelligence assists in identifying agricultural threats and recommending corrective measures. This creates a compelling demonstration of practical AI implementation.\r\n\r\nBeyond technical sophistication, the project addresses a socially important problem. Agriculture affects millions of livelihoods, and solutions that improve productivity while conserving resources have significant societal value. The project's affordability and scalability make it suitable for real-world deployment rather than remaining a laboratory prototype.\r\n\r\nKRISHIDRISHTI is worth seeing because it transforms complex technologies into an accessible tool that empowers farmers, supports sustainability, and demonstrates how innovation can create meaningful impact in one of the world's most critical sectors.", "safetyHazards": ["none"], "safetyPrecautions": "Safety has been a key consideration in the design and implementation of KRISHIDRISHTI. All electronic components are operated within their specified voltage and current limits to prevent overheating, short circuits, and hardware damage. Proper voltage regulation is employed to ensure stable operation of the ESP32 microcontroller and connected sensors.\r\n\r\nSensor modules deployed in outdoor agricultural environments are enclosed within protective casings to shield them from rain, dust, mud, and excessive moisture. Waterproofing measures help maintain sensor accuracy while protecting electronic circuitry from environmental damage.\r\n\r\nElectrical connections are properly insulated to minimize the risk of accidental short circuits and ensure safe operation in wet farming conditions. Cables are organized and secured to prevent physical damage and accidental disconnections during field activities.\r\n\r\nData safety is also considered. Sensor readings and farmer information are stored securely in the backend database with controlled access mechanisms. This helps protect sensitive agricultural data and ensures system reliability.\r\n\r\nThe AI recommendation engine is designed as a decision-support tool rather than an autonomous controller. Final decisions remain under farmer supervision, reducing risks associated with fully automated actions. Recommendations are accompanied by explanations so that users can verify and understand suggested actions before implementation.\r\n\r\nRegular calibration and testing of sensors are performed to maintain measurement accuracy. Backup mechanisms and validation checks help detect abnormal readings and prevent incorrect recommendations.\r\n\r\nThese safety measures ensure reliable operation, user trust, data security, and long-term sustainability while enabling the system to function effectively in challenging agricultural environments.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-28T17:54:11.407Z", "updatedAt": "2026-10-11T17:32:15.27Z", "abstract": { "originalName": "FINAL.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1790618050/aura-registrations/abstract-docs/FINAL", "filename": "Abstract.docx", "relPath": "assets/Teams/Cache Me If You Can/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "KRISHIDRISHTI KRISHIDRISHTI is a smart agriculture decision-support system that helps farmers optimize irrigation, crop health, and farm productivity using real-time field data. The solution combines IoT sensors, AI-assisted analytics, and a farmer-friendly advisory platform to transform raw measurements into actionable recommendations.The proposed implementation uses an ESP32 microcontroller connected to soil moisture, temperature, humidity, rainfall, and light sensors. Sensor readings are transmitted to a backend server and stored in an SQL database. A Flask-based application processes the data, analyzes trends, and generates recommendations. Farmers can also upload crop images for AI-based pest and disease detection.Methodology:Sense → Transmit → Store → Analyze → Explain → ActField data is continuously collected and transmitted to the backend. Rule-based analysis and trend monitoring identify irrigation needs, crop stress, and environmental risks. AI models assist in pest and disease recognition, while explainable alerts provide the reasoning behind every recommendation. We have KrishiSaathi as our AI model which is proficient enough to help the farmers.Desired Outputs:• Smart irrigation recommendations based on soil and weather conditions.• Water-stress and crop-health alerts.• Pest and disease identification with suggested actions.• Harvest and yield estimation support.• Farm economics insights including cost, revenue, and profit estimation.• Multilingual advisory support through the KrishiSaathi interface.Block Diagram:  Sensors (Moisture, Temperature, Humidity, Rainfall, Light)            ↓  ESP32 Controller            ↓ Communication Layer            ↓ Flask Backend + SQL Database            ↓ Analytics & AI Engine            ↓ Recommendation & Alert System            ↓ Farmer Dashboard / KrishiSaathiKRISHIDRISHTI promotes precision agriculture by enabling data-driven decisions, reducing water wastage, improving crop management, and supporting sustainable farming practices through a scalable and low-cost technology framework." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Cache Me If You Can/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790618050/aura-registrations/id-cards/yyxrbokvu20n4duzprsi.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Cache Me If You Can/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790618050/aura-registrations/id-cards/n6pnnwgyyhmnkmbnaryw.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Cache Me If You Can/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790618050/aura-registrations/id-cards/uieufwlisw5d2seqppb9.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Cache Me If You Can/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790618050/aura-registrations/id-cards/gqlvi08uiirvls0wsqt8.jpg", "exists": true }] }, { "index": 14, "id": "6abb9ba8f7271ea45edd6643", "registrationId": "AURA2K26-SHK8W5", "rawTeamName": "Nexora", "folderName": "Nexora", "folderRelPath": "assets/Teams/Nexora", "projectTitle": "IoT-Enabled Embedded LPG Safety & Emergency Response System", "teamSize": 4, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 4, "teamLeaderName": "Prachi Sinha", "teamLeaderEmail": "prachisinha323606@gmail.com", "teamLeaderPhone": "7277989204", "teamMemberDetails": "Member 1\r\n Anurag Singh \r\nHooghly Engineering and Technology College \r\nDept ECE \r\n4th yr \r\n9073705905\r\nEmail anuragsinghthakur2005@gmail.com\r\nMember-2 \r\nSwagata Mukherjee \r\nHooghly Engineering and Technology College \r\nDept ECE \r\n4th yr \r\n8017068773\r\nEmail swagatamukherjee572@gmail.com\r\nMember 3\r\nSayan Bhattacharya \r\nHooghly Engineering and Technology College \r\nDept ECE \r\n4th yr \r\n 98308 89864\r\nsayanbhattacharya133@gmail.com", "hardwareProjectCategories": ["Embedded Systems", "IoT & Smart Devices", "Safety & Security Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "LPG leakage is a major safety concern in homes, kitchens, and small establishments, as undetected gas leakage can lead to fire, explosion, health hazards, and property damage. Conventional systems often provide only a basic alarm and may not offer continuous remote monitoring or automated emergency response. In many situations, the user may also be away from the premises and unable to respond immediately. Therefore, there is a need for a smart, low-cost system that can continuously monitor LPG leakage and related environmental conditions, provide instant alerts, and initiate appropriate emergency actions automatically.\r\nOur project addresses this problem by developing an IoT-enabled embedded LPG safety and emergency response system using ESP32, gas and environmental sensors, local warning devices, automatic response mechanisms, and Blynk-based remote monitoring and control.", "solutionDescription": "LPG leakage is a major safety concern in homes, kitchens, and small establishments, as undetected gas leakage can lead to fire, explosion, health hazards, and property damage. Conventional systems often provide only a basic alarm and may not offer continuous remote monitoring or automated emergency response. In many situations, the user may also be away from the premises and unable to respond immediately. Therefore, there is a need for a smart, low-cost system that can continuously monitor LPG leakage and related environmental conditions, provide instant alerts, and initiate appropriate emergency actions automatically.\r\nOur project addresses this problem by developing an IoT-enabled embedded LPG safety and emergency response system using ESP32, gas and environmental sensors, local warning devices, automatic response mechanisms, and Blynk-based remote monitoring and control.", "innovationDescription": "LPG leakage is a major safety concern in homes, kitchens, and small establishments, as undetected gas leakage can lead to fire, explosion, health hazards, and property damage. Conventional systems often provide only a basic alarm and may not offer continuous remote monitoring or automated emergency response. In many situations, the user may also be away from the premises and unable to respond immediately. Therefore, there is a need for a smart, low-cost system that can continuously monitor LPG leakage and related environmental conditions, provide instant alerts, and initiate appropriate emergency actions automatically.\r\nOur project addresses this problem by developing an IoT-enabled embedded LPG safety and emergency response system using ESP32, gas and environmental sensors, local warning devices, automatic response mechanisms, and Blynk-based remote monitoring and control.", "workingPrinciple": "The system uses an ESP32 microcontroller to continuously monitor LPG leakage and environmental conditions. An MQ-6 sensor detects LPG concentration, while the DHT11 monitors temperature and humidity and an IR flame sensor detects the presence of flame. The ESP32 processes the sensor readings and determines whether the environment is normal or hazardous. During a detected LPG leakage or fire condition, the system activates a buzzer and LED indicators and automatically operates the exhaust fan and servo-based safety demonstration mechanism. An OLED display provides local system status. The ESP32 is connected to the Blynk IoT platform through Wi-Fi, enabling remote monitoring, control and notifications through a smartphone. The system therefore combines real-time sensing, embedded decision-making, local emergency response and IoT-based remote supervision. The prototype is designed as a safe educational demonstration and is not connected to or used to modify a real LPG cylinder or regulator.", "majorHardwareComponents": ["ESP32 DevKit – main controller; MQ-6 LPG gas sensor – leakage detection; DHT11 – temperature and humidity monitoring; IR flame sensor – flame detection; 0.96-inch I2C OLED – real-time status display; relay module – switching control; 5V DC exhaust fan – ventilation during hazardous conditions; MG90S servo motor – safety mechanism demonstration; active buzzer – audible alarm; RGB LEDs – visual status indication; resistors", "breadboard and jumper wires – circuit interfacing and prototyping; DC power supply – system power source. Blynk IoT is used for remote monitoring and control through Wi-Fi."], "useAi": false, "useIot": true, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["General Public", "Industry"], "potentialImpact": "The system can benefit households, small kitchens, hostels, shops and other LPG-using environments by providing continuous monitoring and faster response to gas leakage and fire-related hazards. Unlike a basic alarm-only system, the proposed solution combines sensing, local warning, automatic response and IoT-based remote monitoring. Blynk connectivity allows users to check system status and receive alerts remotely. The concept can help demonstrate how affordable embedded and IoT technologies can improve awareness and reduce response time during hazardous situations. The prototype can also serve as an educational platform for developing future certified LPG safety products with improved sensing, reliability and safety mechanisms.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "This project is worth seeing because it goes beyond simple LPG leakage detection by combining real-time sensing, automatic emergency response and IoT-based remote monitoring in a single embedded system. The ESP32 acts as the central decision-making unit, while the MQ-6, DHT11 and flame sensor continuously monitor hazardous conditions. When an abnormal condition is detected, the system provides immediate local alerts and activates response mechanisms such as the exhaust fan and servo-based safety demonstration. Blynk further allows the user to monitor and control the system remotely through a smartphone. The prototype demonstrates a practical combination of embedded systems, IoT and safety automation in a compact, low-cost educational model.", "safetyHazards": ["moving_rotating_machinery", "high_temperature"], "safetyPrecautions": "The prototype uses a low-voltage DC power supply and is designed as a safe educational demonstration model. The system is not connected to or used to modify a real LPG cylinder or regulator. The LPG detection function is demonstrated using an MQ-6 sensor in a controlled setup. Moving components such as the exhaust fan and servo mechanism are positioned to minimize accidental contact. Electrical connections are properly insulated and secured to reduce the risk of short circuits. The prototype is operated on a stable surface, and the demonstration area is kept clear of unnecessary combustible materials. The system is tested under controlled conditions before demonstration, and the emergency response mechanism is implemented as a safe model demonstration.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T11:06:16.889Z", "updatedAt": "2026-10-11T17:32:19.627Z", "abstract": { "originalName": "LPGAbstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790679975/aura-registrations/abstract-docs/LPGAbstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Nexora/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Nexora/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790679976/aura-registrations/id-cards/whaboq4cunwhfcovfjy8.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Nexora/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790679975/aura-registrations/id-cards/ddc1zc3apjosvanggeh6.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Nexora/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790679975/aura-registrations/id-cards/z2dn1eeicq0uwqoje1sp.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Nexora/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790679975/aura-registrations/id-cards/arrrvwgwnkepcwbn3bj3.jpg", "exists": true }] }, { "index": 15, "id": "6abba3e479d425f326b5b8e4", "registrationId": "AURA2K26-YN5YAK", "rawTeamName": "TechTrio", "folderName": "TechTrio", "folderRelPath": "assets/Teams/TechTrio", "projectTitle": "Smart Driver Safety System", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "RABIA PARVEEN", "teamLeaderEmail": "rabiaparveen888@gmail.com", "teamLeaderPhone": "6289142291", "teamMemberDetails": "Dilshad Fatma - Aliah University - ECE(28) - ph: 78120 39652\r\n\r\nAdiba Naushad - Aliah University - CSE(28)\r\n\r\nAribah Tahseen Btech(CSE) | CSE244039", "hardwareProjectCategories": ["Safety & Security Systems"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement: Road accidents can happen when drivers fall asleep while driving or drive after drinking alcohol. A sleepy driver may not notice the road properly, and an alcohol-influenced driver may lose control. Therefore, a simple and low-cost safety system is needed to warn the driver and stop the vehicle when alcohol is detected.\r\n\r\nSolution: Our project is a smart driver safety system that detects both sleepiness and alcohol. An eye-blink sensor checks the driver's eyes. If the driver's eyes stay closed for about 3 seconds, the system turns on a buzzer to wake and alert the driver.\r\nAn MQ-3 alcohol sensor checks for alcohol. If alcohol is detected, the Arduino Nano sends a signal to the control circuit, which stops the BO motor. The motor represents the vehicle engine in our prototype. Therefore, the vehicle cannot operate when alcohol is detected.\r\n\r\nInnovation Details: The main innovation of this project is that it combines two safety features in one system:\r\n1.Anti-sleep alarm for detecting driver drowsiness.\r\n2.Alcohol detection with engine lock for preventing drunk driving.\r\nThe system uses simple and low-cost components such as an Arduino Nano, eye-blink sensor, MQ-3 alcohol sensor, buzzer, LED, transistor, and motor. It is easy to build and can be used as a basic model for a real vehicle safety system in the future.", "solutionDescription": "Problem Statement: Road accidents can happen when drivers fall asleep while driving or drive after drinking alcohol. A sleepy driver may not notice the road properly, and an alcohol-influenced driver may lose control. Therefore, a simple and low-cost safety system is needed to warn the driver and stop the vehicle when alcohol is detected.\r\n\r\nSolution: Our project is a smart driver safety system that detects both sleepiness and alcohol. An eye-blink sensor checks the driver's eyes. If the driver's eyes stay closed for about 3 seconds, the system turns on a buzzer to wake and alert the driver.\r\nAn MQ-3 alcohol sensor checks for alcohol. If alcohol is detected, the Arduino Nano sends a signal to the control circuit, which stops the BO motor. The motor represents the vehicle engine in our prototype. Therefore, the vehicle cannot operate when alcohol is detected.\r\n\r\nInnovation Details: The main innovation of this project is that it combines two safety features in one system:\r\n1.Anti-sleep alarm for detecting driver drowsiness.\r\n2.Alcohol detection with engine lock for preventing drunk driving.\r\nThe system uses simple and low-cost components such as an Arduino Nano, eye-blink sensor, MQ-3 alcohol sensor, buzzer, LED, transistor, and motor. It is easy to build and can be used as a basic model for a real vehicle safety system in the future.", "innovationDescription": "Problem Statement: Road accidents can happen when drivers fall asleep while driving or drive after drinking alcohol. A sleepy driver may not notice the road properly, and an alcohol-influenced driver may lose control. Therefore, a simple and low-cost safety system is needed to warn the driver and stop the vehicle when alcohol is detected.\r\n\r\nSolution: Our project is a smart driver safety system that detects both sleepiness and alcohol. An eye-blink sensor checks the driver's eyes. If the driver's eyes stay closed for about 3 seconds, the system turns on a buzzer to wake and alert the driver.\r\nAn MQ-3 alcohol sensor checks for alcohol. If alcohol is detected, the Arduino Nano sends a signal to the control circuit, which stops the BO motor. The motor represents the vehicle engine in our prototype. Therefore, the vehicle cannot operate when alcohol is detected.\r\n\r\nInnovation Details: The main innovation of this project is that it combines two safety features in one system:\r\n1.Anti-sleep alarm for detecting driver drowsiness.\r\n2.Alcohol detection with engine lock for preventing drunk driving.\r\nThe system uses simple and low-cost components such as an Arduino Nano, eye-blink sensor, MQ-3 alcohol sensor, buzzer, LED, transistor, and motor. It is easy to build and can be used as a basic model for a real vehicle safety system in the future.", "workingPrinciple": "The system works using an Arduino Nano, an eye-blink sensor, and an MQ-3 alcohol sensor. When the system is switched ON, the eye-blink sensor continuously checks the driver’s eyes. If the driver’s eyes remain closed for about 3 seconds, the Arduino detects drowsiness and turns ON the 5V buzzer. The buzzer gives a warning to the driver to wake up.\r\nAt the same time, the MQ-3 alcohol sensor checks for alcohol. If alcohol is detected above the set limit, the sensor sends a signal to the Arduino. The Arduino then controls the BD139 transistor, which stops the BO motor. The motor represents the vehicle engine in our prototype. Therefore, the vehicle cannot start or operate when alcohol is detected.\r\nAn LED gives a visual indication of the system status.The TP4056 Type-C module is used to provide power to the project from an adapter. A switch is used to turn the system ON and OFF.", "majorHardwareComponents": ["Arduino Nano\nEye Blink Sensor\nMQ-3 Alcohol Sensor\n5V Buzzer\nBO Motor\nBD139 Transistor\nLED\nTP4056 Type-C Module\nBreadboard\nSwitch\n220Ω & 1kΩ Resistors"], "useAi": false, "useIot": false, "powerSource": "usb", "intendedBeneficiaries": ["Transportation"], "potentialImpact": "This project can help improve road safety by detecting two common causes of accidents: driver drowsiness and alcohol consumption. When the driver’s eyes remain closed for about 3 seconds, the system gives a buzzer alert to make the driver aware and awake. If alcohol is detected, the system locks the engine and prevents the motor from operating.\r\nThe project is low-cost, simple, and easy to use, making it suitable for further development. It can be improved and used in cars, buses, trucks, and other vehicles. The system can also help reduce the risk of accidents and protect the driver, passengers, and other people on the road.\r\nIn the future, the project can be connected with GPS, mobile alerts, or IoT features to provide emergency information. Overall, this system can be developed into a useful vehicle safety device for safer transportation.", "productPotential": "potentially", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "This project is worth seeing because it focuses on real road safety problems using a simple and low-cost solution.\r\n\r\n1. Prevents accidents: Detects driver drowsiness and alcohol use.\r\n2. Detects sleepiness: If the driver's eyes stay closed for about 3 seconds, the buzzer gives an alert.\r\n3.Detects alcohol: The MQ-3 sensor checks for alcohol before vehicle operation.\r\n4. Engine lock: When alcohol is detected, the system stops the motor, representing an engine lock.\r\n5. Low cost: Uses easily available and affordable components.\r\n6. Simple technology: Arduino Nano controls the complete system.\r\n7. Easy power supply: The prototype can be powered through a Type-C adapter.\r\n8.Real-world potential: The idea can be further developed for cars, buses, and other vehicles.\r\n\r\nThe key point is that our project does not only detect danger but it also gives an immediate warning or safety action. This makes it a practical concept for building safer transportation systems.", "safetyHazards": ["none"], "safetyPrecautions": "The project is powered through a USB/Type-C power supply. All wires and connections are checked properly before switching ON the system. Proper resistors are used with the LED and buzzer. The circuit is kept away from water and moisture. The BO motor is handled carefully while running. The prototype is operated under supervision during the demo. The USB power supply is disconnected before changing or checking any circuit connection. These precautions help ensure safe operation during testing and demonstration.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T11:41:24.676Z", "updatedAt": "2026-10-11T17:32:23.935Z", "abstract": { "originalName": "Smart Driver Safety System(abstract).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790682083/aura-registrations/abstract-docs/Smart%20Driver%20Safety%20System%28abstract%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/TechTrio/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/TechTrio/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790682083/aura-registrations/id-cards/n2q0j9c9yc2nivsr2ws6.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/TechTrio/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790682083/aura-registrations/id-cards/tgsvo8bxodtowef5atnc.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/TechTrio/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790682083/aura-registrations/id-cards/grpwrgdpobkz6hraduhm.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/TechTrio/4.jpg", "url": "to_be_added_manually", "exists": true }] }, { "index": 16, "id": "6abbb95af363ac3592fda4e1", "registrationId": "AURA2K26-UWV4S8", "rawTeamName": "BHUKAVACH", "folderName": "BHUKAVACH", "folderRelPath": "assets/Teams/BHUKAVACH", "projectTitle": "BHUKAVACH: AI-ASSISTED UNDERGROUND MINE SAFETY, MONITORING AND RESCUE ROVER", "teamSize": 3, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 3, "teamLeaderName": "SAHANOWAZ HOSSAIN MOLLA", "teamLeaderEmail": "sahanowazhossainmolla@gmail.com", "teamLeaderPhone": "7699771913", "teamMemberDetails": "KISHOR HALDER | SWAMI VIVEKANANDA INSTITUTE OF SCIENCE & TECHNOLOGY | MECHANICAL ENGINEERING | 3RD YEAR | 8293457614\r\nSANDIP BHANDARI | SWAMI VIVEKANANDA INSTITUTE OF SCIENCE & TECHNOLOGY | MECHANICAL ENGINEERING | 3RD YEAR | 8597429042", "hardwareProjectCategories": ["Robotics", "Mechanical Systems", "Mechatronics", "Safety & Security Systems", "Other", "Industrial / Manufacturing Technology"], "prototypeType": "Robotic System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Underground mines are challenging and hazardous environments where rescue and inspection teams may face poor visibility, harmful gases, high temperature, unstable terrain, flooding and other unknown conditions. During an emergency, entering an affected area without sufficient information can increase the risk to rescue personnel. There is a need for a system that can remotely inspect such areas and provide useful information before human entry.\r\nBHUKAVACH is a remotely controlled tracked rover designed to support underground mine safety, inspection and rescue operations. Instead of sending a person directly into an unknown area, the rover can be operated remotely to collect information about the surrounding environment. It uses an HD camera with illumination for visual monitoring, thermal sensing for identifying heat sources, gas sensors for monitoring O₂, CH₄ and CO₂, environmental sensors for temperature, humidity and pressure, and LiDAR for distance measurement and spatial awareness.\r\nThe collected information is transmitted to a surface control station where the operator can monitor the rover and its surroundings. AI-assisted analysis is used to support the identification of possible visual or thermal hazards and changes in gas conditions. The system follows a human-in-the-loop approach, meaning that the operator remains responsible for controlling the rover and making operational decisions.\r\nThe innovation of BHUKAVACH lies in combining remote robotic inspection, multi-sensor environmental monitoring and AI-assisted analysis into a single platform for underground safety support. It follows an “Information First, Human Entry Later” approach, allowing rescue teams to gather useful information before entering a potentially hazardous area. Mission data can also be recorded and organised into a post-mission report, helping preserve information collected during the inspection.", "solutionDescription": "Underground mines are challenging and hazardous environments where rescue and inspection teams may face poor visibility, harmful gases, high temperature, unstable terrain, flooding and other unknown conditions. During an emergency, entering an affected area without sufficient information can increase the risk to rescue personnel. There is a need for a system that can remotely inspect such areas and provide useful information before human entry.\r\nBHUKAVACH is a remotely controlled tracked rover designed to support underground mine safety, inspection and rescue operations. Instead of sending a person directly into an unknown area, the rover can be operated remotely to collect information about the surrounding environment. It uses an HD camera with illumination for visual monitoring, thermal sensing for identifying heat sources, gas sensors for monitoring O₂, CH₄ and CO₂, environmental sensors for temperature, humidity and pressure, and LiDAR for distance measurement and spatial awareness.\r\nThe collected information is transmitted to a surface control station where the operator can monitor the rover and its surroundings. AI-assisted analysis is used to support the identification of possible visual or thermal hazards and changes in gas conditions. The system follows a human-in-the-loop approach, meaning that the operator remains responsible for controlling the rover and making operational decisions.\r\nThe innovation of BHUKAVACH lies in combining remote robotic inspection, multi-sensor environmental monitoring and AI-assisted analysis into a single platform for underground safety support. It follows an “Information First, Human Entry Later” approach, allowing rescue teams to gather useful information before entering a potentially hazardous area. Mission data can also be recorded and organised into a post-mission report, helping preserve information collected during the inspection.", "innovationDescription": "Underground mines are challenging and hazardous environments where rescue and inspection teams may face poor visibility, harmful gases, high temperature, unstable terrain, flooding and other unknown conditions. During an emergency, entering an affected area without sufficient information can increase the risk to rescue personnel. There is a need for a system that can remotely inspect such areas and provide useful information before human entry.\r\nBHUKAVACH is a remotely controlled tracked rover designed to support underground mine safety, inspection and rescue operations. Instead of sending a person directly into an unknown area, the rover can be operated remotely to collect information about the surrounding environment. It uses an HD camera with illumination for visual monitoring, thermal sensing for identifying heat sources, gas sensors for monitoring O₂, CH₄ and CO₂, environmental sensors for temperature, humidity and pressure, and LiDAR for distance measurement and spatial awareness.\r\nThe collected information is transmitted to a surface control station where the operator can monitor the rover and its surroundings. AI-assisted analysis is used to support the identification of possible visual or thermal hazards and changes in gas conditions. The system follows a human-in-the-loop approach, meaning that the operator remains responsible for controlling the rover and making operational decisions.\r\nThe innovation of BHUKAVACH lies in combining remote robotic inspection, multi-sensor environmental monitoring and AI-assisted analysis into a single platform for underground safety support. It follows an “Information First, Human Entry Later” approach, allowing rescue teams to gather useful information before entering a potentially hazardous area. Mission data can also be recorded and organised into a post-mission report, helping preserve information collected during the inspection.", "workingPrinciple": "BHUKAVACH works as a remotely operated underground inspection and monitoring system. The tracked rover is controlled by an operator from a surface control station. Its tracked mechanism helps it move over uneven underground surfaces while maintaining stability.\r\nDuring operation, the HD camera provides a live view of the surroundings with the help of onboard illumination. The thermal sensor provides heat-related information, while gas sensors monitor O₂, CH₄ and CO₂ levels. Environmental sensors collect temperature, humidity and pressure data. LiDAR provides distance measurements and information about nearby objects and the surrounding area.\r\nAn onboard ESP32-based electronics system collects the sensor information and manages communication between the rover and the control station. The collected data is transmitted to the operator for real-time monitoring.\r\nAI-assisted analysis can then be used to support the identification of possible hazards from visual and thermal information and to observe changes in gas conditions. The operator remains in control of rover movement and operational decisions.\r\nDuring and after a mission, important sensor readings, observations and recorded evidence can be stored and used to prepare a structured mission report. This allows the system to provide both real-time information and a record of the inspection.", "majorHardwareComponents": ["The major hardware components of BHUKAVACH include:\n1. Tracked Rover Platform:\nProvides mobility and better traction on uneven underground surfaces.\n2. ESP32-Based Electronics:\nUsed for sensor data acquisition", "onboard control and communication-related functions.\n3. HD Camera:\nProvides live visual monitoring and records the underground environment.\n4. LED Illumination:\nProvides additional lighting for visibility in dark underground areas.\n5. Thermal Sensor:\nProvides thermal information for identifying possible heat sources and supporting situational awareness.\n6. Gas Sensors:\nUsed for planned monitoring of O₂", "CH₄ and CO₂ levels to help identify potentially unsafe atmospheric conditions.\n7. Environmental Sensors:\nMeasure parameters such as temperature", "humidity and air pressure.\n8. LiDAR:\nProvides distance measurements and spatial information about the surrounding area.\n9. Wireless Communication System:\nTransfers live video", "sensor readings and rover status to the surface control station.\n10. Battery and Power System:\nProvides power to the rover", "sensors and onboard electronics.\nTogether", "these components allow BHUKAVACH to combine mobility", "visual monitoring", "environmental sensing and remote operation in a single platform."], "useAi": true, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["Other", "Industry"], "potentialImpact": "BHUKAVACH has potential applications in underground mine safety, inspection and emergency response. Its main purpose is to provide information about hazardous areas before rescue or safety personnel enter them.\r\nBy allowing a rover to enter an unknown area first, the system can help reduce unnecessary human exposure during initial inspection. Live camera, thermal and environmental information can give operators a better understanding of conditions underground. Gas monitoring can provide additional information about the atmosphere, while LiDAR can support awareness of nearby obstacles and the surrounding space.\r\nThe system can also record mission information and organise collected data into a post-mission report. This can help preserve observations from an inspection instead of relying only on manual reporting.\r\nBeyond mining, the same approach could potentially be adapted for other environments where remote inspection is useful, such as tunnels, industrial facilities, confined spaces and disaster-affected areas. However, application in actual mines would require further testing, appropriate sensor validation, communication testing, environmental ruggedisation and compliance with applicable safety and regulatory requirements.\r\nOverall, BHUKAVACH aims to support a safer approach to hazardous-area inspection by helping teams gather information remotely before making decisions about human entry.", "productPotential": "yes", "prototypeDevelopmentCost": 250000, "auraDemoHighlight": "BHUKAVACH is worth seeing because it demonstrates how robotics, sensing and AI-assisted analysis can be combined to address a real industrial safety challenge.\r\nThe system is not designed to replace mine rescue personnel. Instead, it works as a remote information-gathering platform that can enter a potentially hazardous area while the operator remains outside. This makes the project different from a simple remote-controlled rover.\r\nVisitors can see multiple types of information being collected from the same platform, including live camera footage, thermal information, gas readings, environmental measurements and LiDAR-based distance information. The system also demonstrates how these different data sources can be brought together at a surface control station.\r\nAnother important aspect is the human-in-the-loop approach. AI is used to assist with analysing collected information and identifying possible hazards, while the operator remains responsible for controlling the rover and making decisions.\r\nBHUKAVACH therefore demonstrates a practical engineering concept based on “Information First, Human Entry Later”—using a robotic system to help people understand a hazardous environment before entering it. This combination of hardware, sensing, remote operation and AI-assisted analysis makes it relevant to real-world industrial safety challenges.", "safetyHazards": ["none", "moving_rotating_machinery"], "safetyPrecautions": "BHUKAVACH is designed with a remote-operation approach so that the operator can control the rover from a safer location rather than directly entering the area being inspected. This reduces the need for immediate human exposure during initial remote assessment.\r\nThe system follows a human-in-the-loop approach. The rover does not independently make rescue decisions or replace trained personnel. Movement and operational decisions remain under the control of the human operator.\r\nDuring testing and demonstration, the rover is operated in controlled conditions and its movement, communication and sensor readings are monitored. The battery-powered electrical system and onboard electronics are handled carefully during operation and testing.\r\nThe gas, thermal and environmental sensors are intended to provide monitoring information and support hazard awareness. Their readings are treated as information for the operator rather than as a substitute for certified mine-safety instruments.\r\nBHUKAVACH is currently intended as a technology demonstration and requires further validation before operation in actual underground mines. Future development will include more extensive testing of communication reliability, sensor accuracy, battery performance, environmental protection and other mine-specific safety requirements.\r\nThe system therefore prioritises remote operation, human oversight and controlled testing while avoiding unsupported claims of mine-safety certification or field deployment.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T13:12:58.534Z", "updatedAt": "2026-10-11T17:32:29.511Z", "abstract": { "originalName": "BHUKAVACH.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790687578/aura-registrations/abstract-docs/BHUKAVACH.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/BHUKAVACH/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/BHUKAVACH/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790687577/aura-registrations/id-cards/smhgwotjmtjloesfpiak.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/BHUKAVACH/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790687577/aura-registrations/id-cards/gzlq1bqukdtrj3x6i2y1.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/BHUKAVACH/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790687577/aura-registrations/id-cards/fionhbeccz9vkaf9q4pi.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/BHUKAVACH/4.jpg", "url": null, "exists": false }] }, { "index": 17, "id": "6abbc41373bce36ff66c525d", "registrationId": "AURA2K26-W2UVHA", "rawTeamName": "CNCraze", "folderName": "CNCraze", "folderRelPath": "assets/Teams/CNCraze", "projectTitle": "Hybrid Multitool CNC Engraving Machine", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Saugata Samanta", "teamLeaderEmail": "saugatasamanta2005@gmail.com", "teamLeaderPhone": "7074230847", "teamMemberDetails": "Najmul Islam Molla | Swami Vivekananda Institenute Of Science & Technology | EEE | 4th yr | 9433670755", "hardwareProjectCategories": ["Automation & Control"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement\r\n\r\nSmall-scale artisans, craftsmen, carpenters and rural entrepreneurs often depend on manual methods for producing customized wooden products, decorative designs, nameplates, keyrings and similar items. This limits production speed, repeatability and design flexibility. Conventional CNC and engraving systems can also be difficult to adopt for small workshops because of their size, cost, fixed configurations and dependence on external servicing. For users in rural and semi-urban areas, equipment downtime and maintenance support can further affect productivity. There is therefore a need for a compact, adaptable and accessible digital manufacturing solution that can support different types of customized production within limited workspace.\r\n\r\nProposed Solution\r\n\r\nNeoCNC-X is a compact hybrid digital manufacturing platform designed to combine CNC-based machining and laser engraving capabilities within a single machine platform. It is intended to provide a practical solution for prototyping, customization, engraving and small-scale manufacturing. The platform is designed around a scalable machine concept, allowing different working sizes to be developed according to customer requirements rather than forcing every user into a single standard configuration. Its digital workflow enables designs to be converted into machine-executable instructions, reducing dependence on conventional manual production and supporting more consistent output. The approach is particularly suited to small workshops, artisans and emerging manufacturing users seeking a compact digital fabrication solution.\r\n\r\nInnovation\r\n\r\nThe innovation of NeoCNC-X is not presented as a single isolated component, but as an integrated manufacturing architecture that brings multiple capabilities into one adaptable platform. The concept focuses on creating a common operational foundation through which different manufacturing functions can be incorporated without requiring completely separate machines. The architecture is designed with modularity, scalability and future expandability in mind, allowing the platform to evolve according to application and customer requirements.", "solutionDescription": "Problem Statement\r\n\r\nSmall-scale artisans, craftsmen, carpenters and rural entrepreneurs often depend on manual methods for producing customized wooden products, decorative designs, nameplates, keyrings and similar items. This limits production speed, repeatability and design flexibility. Conventional CNC and engraving systems can also be difficult to adopt for small workshops because of their size, cost, fixed configurations and dependence on external servicing. For users in rural and semi-urban areas, equipment downtime and maintenance support can further affect productivity. There is therefore a need for a compact, adaptable and accessible digital manufacturing solution that can support different types of customized production within limited workspace.\r\n\r\nProposed Solution\r\n\r\nNeoCNC-X is a compact hybrid digital manufacturing platform designed to combine CNC-based machining and laser engraving capabilities within a single machine platform. It is intended to provide a practical solution for prototyping, customization, engraving and small-scale manufacturing. The platform is designed around a scalable machine concept, allowing different working sizes to be developed according to customer requirements rather than forcing every user into a single standard configuration. Its digital workflow enables designs to be converted into machine-executable instructions, reducing dependence on conventional manual production and supporting more consistent output. The approach is particularly suited to small workshops, artisans and emerging manufacturing users seeking a compact digital fabrication solution.\r\n\r\nInnovation\r\n\r\nThe innovation of NeoCNC-X is not presented as a single isolated component, but as an integrated manufacturing architecture that brings multiple capabilities into one adaptable platform. The concept focuses on creating a common operational foundation through which different manufacturing functions can be incorporated without requiring completely separate machines. The architecture is designed with modularity, scalability and future expandability in mind, allowing the platform to evolve according to application and customer requirements.", "innovationDescription": "Problem Statement\r\n\r\nSmall-scale artisans, craftsmen, carpenters and rural entrepreneurs often depend on manual methods for producing customized wooden products, decorative designs, nameplates, keyrings and similar items. This limits production speed, repeatability and design flexibility. Conventional CNC and engraving systems can also be difficult to adopt for small workshops because of their size, cost, fixed configurations and dependence on external servicing. For users in rural and semi-urban areas, equipment downtime and maintenance support can further affect productivity. There is therefore a need for a compact, adaptable and accessible digital manufacturing solution that can support different types of customized production within limited workspace.\r\n\r\nProposed Solution\r\n\r\nNeoCNC-X is a compact hybrid digital manufacturing platform designed to combine CNC-based machining and laser engraving capabilities within a single machine platform. It is intended to provide a practical solution for prototyping, customization, engraving and small-scale manufacturing. The platform is designed around a scalable machine concept, allowing different working sizes to be developed according to customer requirements rather than forcing every user into a single standard configuration. Its digital workflow enables designs to be converted into machine-executable instructions, reducing dependence on conventional manual production and supporting more consistent output. The approach is particularly suited to small workshops, artisans and emerging manufacturing users seeking a compact digital fabrication solution.\r\n\r\nInnovation\r\n\r\nThe innovation of NeoCNC-X is not presented as a single isolated component, but as an integrated manufacturing architecture that brings multiple capabilities into one adaptable platform. The concept focuses on creating a common operational foundation through which different manufacturing functions can be incorporated without requiring completely separate machines. The architecture is designed with modularity, scalability and future expandability in mind, allowing the platform to evolve according to application and customer requirements.", "workingPrinciple": "NeoCNC-X operates on the principle of computer-controlled digital manufacturing, where a digital design is converted into coordinated machine movements and tool operations to produce the required physical output. The process begins with the preparation of a digital design using appropriate CAD/CAM or engraving software. The design is then translated into G-code, containing the required coordinates, movement paths and operational commands.\r\n\r\nThe generated G-code is processed by the GRBL-based control system, which interprets the commands and generates control signals for the machine’s motion system. These signals drive the respective X, Y and Z axes, providing controlled and coordinated positioning of the selected manufacturing tool.\r\n\r\nBased on the required application, the machine operates through either CNC spindle machining or laser engraving. In spindle mode, the rotating cutting tool removes material according to the programmed tool path. In laser mode, controlled laser energy produces the required engraving or marking pattern on the workpiece. Both operations utilize the machine’s coordinated motion architecture to reproduce the programmed design accurately.\r\n\r\nThe overall workflow is therefore:\r\n\r\nDigital Design → G-code Generation → GRBL Control → X-Y-Z Motion → Tool Operation → Material Processing → Final Output\r\n\r\nThis principle enables NeoCNC-X to convert digital designs into physical products through a controlled, repeatable and adaptable manufacturing process.", "majorHardwareComponents": ["The major electronic and hardware components of NeoCNC-X include an Arduino Uno microcontroller with GRBL firmware", "CNC Shield V3", "stepper motor drivers", "and stepper motors for precise X-Y-Z axis movement. The machine incorporates a  DC spindle motor for CNC machining and a laser module for engraving. A DC power supply provides the required electrical power", "while relay modules and an MOSFET are used for controlled switching of the spindle and laser. An boost converter supports voltage regulation", "and cooling fans/cooling modules provide thermal management for reliable operation. Other essential hardware includes the CNC frame", "lead screws", "couplings", "linear guides", "work bed", "and modular tool-head assembly."], "useAi": true, "useIot": false, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["Industry", "Education", "Rural Communities", "Persons with Disabilities"], "potentialImpact": "NeoCNC-X is primarily designed to benefit rural artisans, craftsmen, carpenters, small-scale manufacturers, handicraft producers, and customization businesses that require affordable and flexible digital manufacturing capabilities. In many rural and semi-urban areas, small products such as wooden toys, nameplates, key rings, decorative items, customized gifts, and craft components are still produced manually, requiring significant time and skilled labour. Existing CNC and laser systems can be costly, have fixed machine dimensions, and may create difficulties in maintenance and servicing when technical support is located far from the user. NeoCNC-X addresses these limitations through a compact, modular, and customizable machine architecture that combines CNC spindle machining and laser engraving on a common X-Y-Z motion platform. The system improves current working standards by shifting selected manufacturing operations from predominantly manual processes toward computer-controlled, repeatable, and digitally driven production. Its Arduino-based GRBL control system, modular tool-head arrangement, and offline G-code execution reduce dependence on continuous computer operation and provide greater flexibility during production. The use of commonly available electronic components such as Arduino Uno, CNC Shield, stepper motors, and motor drivers can also support easier local maintenance and component replacement. Integrated power management, controlled switching, and dedicated cooling contribute to safer and more stable operation. The customizable machine size allows users to select a suitable working envelope according to their workspace and production requirements. Consequently, NeoCNC-X can help reduce production time, improve repeatability and design flexibility, support small-batch customization, and make digital manufacturing technology more accessible to users who may not be able to adopt", "productPotential": "yes", "prototypeDevelopmentCost": 35000, "auraDemoHighlight": "NeoCNC-X deserves attention because it is not simply another CNC machine—it is a compact, modular digital manufacturing platform built around practical accessibility. By combining CNC spindle machining and laser engraving on a shared X-Y-Z platform, it brings multiple manufacturing capabilities into a single system while remaining adaptable to different workspace and production requirements. Its use of readily available components, offline G-code operation, modular tool heads, controlled power management, and integrated cooling focuses on real-world usability, maintainability, and affordability. More importantly, NeoCNC-X connects digital manufacturing technology with rural artisans, craftsmen, carpenters, and small-scale producers, helping bridge the gap between traditional craftsmanship and modern automated production.", "safetyHazards": ["water_near_electrical_equipment", "fire_combustion", "laser_intense_light", "high_current"], "safetyPrecautions": "NeoCNC-X incorporates multiple safety measures for reliable operation, including controlled power switching, relay-based isolation, MOSFET-controlled laser activation, dedicated cooling, and electrical separation of high-current loads. For laser operation, the system is designed with a controlled laser ON/OFF mechanism and enclosed/guarded working area, along with appropriate laser safety eyewear and operating precautions to minimize accidental exposure.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": true, "previousExhibitionDetails": "NeoCNC-X has been exhibited and demonstrated across multiple innovation and technology platforms, including Techathon 3.0 organized by the Patent Information Centre (PIC), West Bengal State Council of Science & Technology, where the project secured Runner-Up in the Best Solution category. The project was also showcased at Heritage Institute of Technology Techfest, NITTTR, and the Global Entrepreneurship Summit (GES 2026) at IIT Kharagpur, providing opportunities to demonstrate its working prototype, technical approach, and potential applications to judges, innovators, academicians, and technology-focused audiences. These exhibitions have helped provide practical exposure and external validation of NeoCNC-X as a compact hybrid CNC and laser-based digital manufacturing platform.", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T13:58:43.013Z", "updatedAt": "2026-10-11T17:32:35.135Z", "abstract": { "originalName": "Aura_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790690322/aura-registrations/abstract-docs/Aura_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/CNCraze/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/CNCraze/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790690322/aura-registrations/id-cards/gpyyv4io4hfjewdu5swe.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/CNCraze/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790690322/aura-registrations/id-cards/hlr5djemxpknjlesnfpw.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/CNCraze/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/CNCraze/4.jpg", "url": null, "exists": false }] }, { "index": 18, "id": "6abbefe40eb8993e6aff30fd", "registrationId": "AURA2K26-LRXP8E", "rawTeamName": "SLYTHERINS", "folderName": "SLYTHERINS", "folderRelPath": "assets/Teams/SLYTHERINS", "projectTitle": "DUAL AXIS SOLAR TRACKING PANEL WITH DIGITAL DASHBOARD AND CONTROL PANEL", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "AZLFAH MAQSOOD", "teamLeaderEmail": "maqazzie@gmail.com", "teamLeaderPhone": "9433575487", "teamMemberDetails": "MD TAHFEEMUL HODA | ALIAH UNIERSITY | ECE | 2ND YEAR | 9046924854\r\nFAUZIA ANWAR | ALIAH UNIVERSITY | EEN | 2ND YEAR | 8910769300", "hardwareProjectCategories": ["Embedded Systems", "Environmental Technology"], "prototypeType": "Smart Product", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement\r\nConventional fixed solar panels cannot continuously face the Sun throughout the day. As the Sun changes its position, the angle of sunlight falling on the panel changes, reducing the effective solar energy captured. Manual adjustment is inefficient, requires human intervention, and cannot respond continuously to changing sunlight conditions. Additionally, basic solar tracking systems often lack real-time monitoring, making it difficult to observe panel performance, diagnose issues, or optimize operation.\r\n\r\nSolution\r\nWe propose a Dual-Axis Automatic Solar Tracking System with a Digital Dashboard. The system uses multiple LDR sensors to detect the direction of maximum sunlight and two servo motors to adjust the panel along both horizontal and vertical axes. An Arduino continuously compares the light intensity from the sensors and moves the panel toward the direction receiving the strongest sunlight.\r\nA digital dashboard connected through Bluetooth (HC-05) provides real-time information such as voltage, current, power output, panel inclination, and compass direction. The system also supports different operating modes, including automatic sunlight tracking, preset positioning, and manual control through the dashboard.\r\n\r\nInnovation Details\r\n*Dual-Axis Tracking: Automatically adjusts both horizontal and vertical angles to maintain better alignment with the Sun.\r\n*Closed-Loop Light Detection: Uses multiple LDRs to continuously compare sunlight intensity and correct the panel position.\r\n*Real-Time Digital Dashboard: Displays important electrical and positional parameters in a single interface.\r\n*Multi-Mode Operation: Allows automatic tracking, scheduled/preset positioning, and manual touch control.\r\n*Wireless Monitoring & Control: HC-05 Bluetooth enables communication between the Arduino system and a smartphone without requiring Wi-Fi or a router.\r\n*Performance Monitoring: Voltage and current measurements can be used to calculate real-time power and evaluate the effectiveness of solar tracking.\r\n*Expandable Architecture: The system can later be upgraded with IoT connectivity, cloud data logging, weather sensors, predictive tracking, or energy-efficiency analytics.", "solutionDescription": "Problem Statement\r\nConventional fixed solar panels cannot continuously face the Sun throughout the day. As the Sun changes its position, the angle of sunlight falling on the panel changes, reducing the effective solar energy captured. Manual adjustment is inefficient, requires human intervention, and cannot respond continuously to changing sunlight conditions. Additionally, basic solar tracking systems often lack real-time monitoring, making it difficult to observe panel performance, diagnose issues, or optimize operation.\r\n\r\nSolution\r\nWe propose a Dual-Axis Automatic Solar Tracking System with a Digital Dashboard. The system uses multiple LDR sensors to detect the direction of maximum sunlight and two servo motors to adjust the panel along both horizontal and vertical axes. An Arduino continuously compares the light intensity from the sensors and moves the panel toward the direction receiving the strongest sunlight.\r\nA digital dashboard connected through Bluetooth (HC-05) provides real-time information such as voltage, current, power output, panel inclination, and compass direction. The system also supports different operating modes, including automatic sunlight tracking, preset positioning, and manual control through the dashboard.\r\n\r\nInnovation Details\r\n*Dual-Axis Tracking: Automatically adjusts both horizontal and vertical angles to maintain better alignment with the Sun.\r\n*Closed-Loop Light Detection: Uses multiple LDRs to continuously compare sunlight intensity and correct the panel position.\r\n*Real-Time Digital Dashboard: Displays important electrical and positional parameters in a single interface.\r\n*Multi-Mode Operation: Allows automatic tracking, scheduled/preset positioning, and manual touch control.\r\n*Wireless Monitoring & Control: HC-05 Bluetooth enables communication between the Arduino system and a smartphone without requiring Wi-Fi or a router.\r\n*Performance Monitoring: Voltage and current measurements can be used to calculate real-time power and evaluate the effectiveness of solar tracking.\r\n*Expandable Architecture: The system can later be upgraded with IoT connectivity, cloud data logging, weather sensors, predictive tracking, or energy-efficiency analytics.", "innovationDescription": "Problem Statement\r\nConventional fixed solar panels cannot continuously face the Sun throughout the day. As the Sun changes its position, the angle of sunlight falling on the panel changes, reducing the effective solar energy captured. Manual adjustment is inefficient, requires human intervention, and cannot respond continuously to changing sunlight conditions. Additionally, basic solar tracking systems often lack real-time monitoring, making it difficult to observe panel performance, diagnose issues, or optimize operation.\r\n\r\nSolution\r\nWe propose a Dual-Axis Automatic Solar Tracking System with a Digital Dashboard. The system uses multiple LDR sensors to detect the direction of maximum sunlight and two servo motors to adjust the panel along both horizontal and vertical axes. An Arduino continuously compares the light intensity from the sensors and moves the panel toward the direction receiving the strongest sunlight.\r\nA digital dashboard connected through Bluetooth (HC-05) provides real-time information such as voltage, current, power output, panel inclination, and compass direction. The system also supports different operating modes, including automatic sunlight tracking, preset positioning, and manual control through the dashboard.\r\n\r\nInnovation Details\r\n*Dual-Axis Tracking: Automatically adjusts both horizontal and vertical angles to maintain better alignment with the Sun.\r\n*Closed-Loop Light Detection: Uses multiple LDRs to continuously compare sunlight intensity and correct the panel position.\r\n*Real-Time Digital Dashboard: Displays important electrical and positional parameters in a single interface.\r\n*Multi-Mode Operation: Allows automatic tracking, scheduled/preset positioning, and manual touch control.\r\n*Wireless Monitoring & Control: HC-05 Bluetooth enables communication between the Arduino system and a smartphone without requiring Wi-Fi or a router.\r\n*Performance Monitoring: Voltage and current measurements can be used to calculate real-time power and evaluate the effectiveness of solar tracking.\r\n*Expandable Architecture: The system can later be upgraded with IoT connectivity, cloud data logging, weather sensors, predictive tracking, or energy-efficiency analytics.", "workingPrinciple": "Working Principle\r\nThe Dual-Axis Solar Tracking System works by continuously detecting the direction of maximum sunlight and adjusting the solar panel accordingly.\r\nFour LDR (Light Dependent Resistor) sensors are placed around the panel to measure light intensity from different directions. The Arduino reads these sensor values and compares the light levels. If one side receives more sunlight, the controller drives the corresponding servo motor to rotate the panel toward that direction.\r\nTwo servo motors provide dual-axis movement: one controls the horizontal (azimuth) angle, while the other controls the vertical (elevation) angle. This allows the panel to follow the Sun throughout the day.\r\nVoltage and current sensors measure the panel's electrical output, allowing the Arduino to calculate real-time power. The panel's position and other operating parameters can also be monitored.\r\nAn HC-05 Bluetooth module wirelessly sends this data to a smartphone digital dashboard, where users can monitor power generation, panel angles, and operating modes. The dashboard can also provide manual control and preset positioning when required.", "majorHardwareComponents": ["ARDUINO UNO REV 3\nHC-05\nLDRs\nACS712\n5V SOLAR PANEL\nSG90 SERVO MOTORS"], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "Agriculture", "General Public"], "potentialImpact": "Potential Real-World Impact\r\nThe proposed Dual-Axis Solar Tracking System with Digital Dashboard can improve the practical utilization of solar energy by keeping the panel better aligned with the Sun throughout the day. This can help increase energy collection compared with a fixed panel under suitable conditions.\r\nKey Impacts:\r\n*Higher Solar Energy Utilization: Continuous tracking can improve sunlight exposure and potentially increase daily energy generation.\r\n*Reduced Manual Intervention: Automatic movement eliminates the need for users to repeatedly adjust the panel.\r\n*Real-Time Monitoring: The digital dashboard allows users to monitor voltage, current, power, panel angle, and operating status remotely.\r\n*Better Maintenance: Continuous performance data can help identify abnormal output and potential system problems.\r\n*Educational & Research Applications: The system provides a practical platform for learning solar energy, embedded systems, sensors, motor control, and wireless communication.\r\n*Scalability: The concept can be adapted for rooftop systems, small-scale solar installations, agricultural applications, and standalone power systems.\r\n*Sustainable Energy Adoption: By improving the utilization of available sunlight, the system can contribute to more efficient use of renewable energy and support the transition toward cleaner power generation.", "productPotential": "yes", "prototypeDevelopmentCost": 1200, "auraDemoHighlight": "Why Our Project Is Worth Seeing...\r\nOur project is worth seeing because it combines renewable energy, automation, embedded systems, and digital monitoring into one practical solution. Unlike a conventional fixed solar panel, our dual-axis tracker actively follows the direction of maximum sunlight, demonstrating how intelligent control can improve solar-energy utilization.\r\nWhat makes the project particularly engaging is its interactive digital dashboard. Users can see real-time voltage, current, power, panel angle, and operating status, while also switching between automatic, preset, and manual control modes.\r\nThe project is also designed as a working prototype rather than just a theoretical concept. Visitors can observe the panel physically responding to changes in light and interact with the system through the dashboard.\r\nIts modular design provides opportunities for future upgrades such as IoT connectivity, cloud data logging, weather-based control, energy analytics, and predictive solar tracking.\r\nOverall, the project demonstrates how smart automation can make renewable-energy systems more efficient, measurable, and user-friendly, making it relevant for both educational demonstrations and future real-world applications.", "safetyHazards": ["none", "water_near_electrical_equipment"], "safetyPrecautions": "Safety Precautions\r\n*Electrical Safety: Proper insulation and secure connections were maintained to prevent short circuits, overheating, and accidental contact with exposed wires.\r\n*Motor & Mechanical Safety: The panel and servo motors were securely mounted, with movement limits considered to prevent excessive rotation or mechanical damage.\r\n*Power Supply Safety: The system was operated within the rated voltage and current limits of the Arduino, sensors, and motors, with an appropriate external power supply used where required.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T17:05:40.49Z", "updatedAt": "2026-10-11T17:32:39.948Z", "abstract": { "originalName": "Aura2k26.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790701539/aura-registrations/abstract-docs/Aura2k26.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/SLYTHERINS/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/SLYTHERINS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790701539/aura-registrations/id-cards/oyd2bjez0b8rdbhoysll.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/SLYTHERINS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790701539/aura-registrations/id-cards/acjh9rb7fhs9j57acvnq.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/SLYTHERINS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790701539/aura-registrations/id-cards/ysaqcbek0k9bpvx0cpoi.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/SLYTHERINS/4.jpg", "url": null, "exists": false }] }, { "index": 19, "id": "6abbfb9c1041785b648de982", "registrationId": "AURA2K26-CK3YMN", "rawTeamName": "INDROVE", "folderName": "INDROVE", "folderRelPath": "assets/Teams/INDROVE", "projectTitle": "INDROVE: A New Version of India's Pipeline Health", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Arijit Naskar", "teamLeaderEmail": "arijitnaskar4521@gmail.com", "teamLeaderPhone": "7686940559", "teamMemberDetails": "Mou Rani Hutait | Swami Vivekananda Institute of Science & Technology | Mechanical Engineering | 2nd Year | 7601823733", "hardwareProjectCategories": ["Robotics", "Embedded Systems", "Mechanical Systems", "IoT & Smart Devices"], "prototypeType": "Robotic System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Pipeline blockages in drainage and utility networks are commonly difficult to locate and remove because the affected section is inside a confined pipeline. Conventional maintenance often depends on access through manholes, manual intervention, or surface-level removal of accumulated waste. These approaches can be time-consuming, labour-intensive and difficult to perform safely, particularly when the blockage is located deep inside a horizontal pipeline.\r\nINDROVE is an in-pipe robotic rover developed to address this problem by enabling direct access inside horizontal cylindrical pipelines. The project aims to provide a remotely operated platform capable of moving inside the pipe, reaching the blockage location and supporting inspection and future blockage-removal operations without requiring human entry into the pipeline.\r\nA key innovation of INDROVE is its sprocket-chain mechanised wheel system, developed specifically for controlled movement and improved traction inside the pipeline. The rover also incorporates a three-arm expandable support mechanism that provides multi-point contact with the pipe wall and helps maintain stability while travelling through the pipeline. The arms can be expanded or retracted according to the pipe diameter.\r\nThe current prototype is externally controlled through a wired system and operates using a 220 V power supply. A camera-based live visual system enables the operator to observe the internal environment during operation.\r\nThe project is designed with a modular architecture so that additional functions can be incorporated later. A dedicated mechanical blockage-removal mechanism is proposed as the next operational module. Additional sensing and automated inspection capabilities are also planned for future development.\r\nThus, INDROVE combines in-pipe mobility, mechanical stability and remote operation into a single robotic platform aimed at making pipeline inspection and maintenance more accessible and safer.", "solutionDescription": "Pipeline blockages in drainage and utility networks are commonly difficult to locate and remove because the affected section is inside a confined pipeline. Conventional maintenance often depends on access through manholes, manual intervention, or surface-level removal of accumulated waste. These approaches can be time-consuming, labour-intensive and difficult to perform safely, particularly when the blockage is located deep inside a horizontal pipeline.\r\nINDROVE is an in-pipe robotic rover developed to address this problem by enabling direct access inside horizontal cylindrical pipelines. The project aims to provide a remotely operated platform capable of moving inside the pipe, reaching the blockage location and supporting inspection and future blockage-removal operations without requiring human entry into the pipeline.\r\nA key innovation of INDROVE is its sprocket-chain mechanised wheel system, developed specifically for controlled movement and improved traction inside the pipeline. The rover also incorporates a three-arm expandable support mechanism that provides multi-point contact with the pipe wall and helps maintain stability while travelling through the pipeline. The arms can be expanded or retracted according to the pipe diameter.\r\nThe current prototype is externally controlled through a wired system and operates using a 220 V power supply. A camera-based live visual system enables the operator to observe the internal environment during operation.\r\nThe project is designed with a modular architecture so that additional functions can be incorporated later. A dedicated mechanical blockage-removal mechanism is proposed as the next operational module. Additional sensing and automated inspection capabilities are also planned for future development.\r\nThus, INDROVE combines in-pipe mobility, mechanical stability and remote operation into a single robotic platform aimed at making pipeline inspection and maintenance more accessible and safer.", "innovationDescription": "Pipeline blockages in drainage and utility networks are commonly difficult to locate and remove because the affected section is inside a confined pipeline. Conventional maintenance often depends on access through manholes, manual intervention, or surface-level removal of accumulated waste. These approaches can be time-consuming, labour-intensive and difficult to perform safely, particularly when the blockage is located deep inside a horizontal pipeline.\r\nINDROVE is an in-pipe robotic rover developed to address this problem by enabling direct access inside horizontal cylindrical pipelines. The project aims to provide a remotely operated platform capable of moving inside the pipe, reaching the blockage location and supporting inspection and future blockage-removal operations without requiring human entry into the pipeline.\r\nA key innovation of INDROVE is its sprocket-chain mechanised wheel system, developed specifically for controlled movement and improved traction inside the pipeline. The rover also incorporates a three-arm expandable support mechanism that provides multi-point contact with the pipe wall and helps maintain stability while travelling through the pipeline. The arms can be expanded or retracted according to the pipe diameter.\r\nThe current prototype is externally controlled through a wired system and operates using a 220 V power supply. A camera-based live visual system enables the operator to observe the internal environment during operation.\r\nThe project is designed with a modular architecture so that additional functions can be incorporated later. A dedicated mechanical blockage-removal mechanism is proposed as the next operational module. Additional sensing and automated inspection capabilities are also planned for future development.\r\nThus, INDROVE combines in-pipe mobility, mechanical stability and remote operation into a single robotic platform aimed at making pipeline inspection and maintenance more accessible and safer.", "workingPrinciple": "INDROVE works as a remotely operated robotic rover inside a horizontal cylindrical pipeline. The system receives power through a 220 V supply and is operated externally using a wired control arrangement.\r\nMovement is generated through the sprocket-chain mechanised wheel system developed for INDROVE. The mechanism provides traction against the pipeline surface and enables the rover to travel forward and backward inside the pipe.\r\nA three-arm expandable support mechanism maintains contact with the internal pipe wall. The arms can be expanded or retracted to accommodate variations in pipeline diameter and provide stability during movement.\r\nDuring operation, the rover is guided by the external operator towards the required location. A camera provides live visual feedback, allowing the operator to observe the internal pipeline environment and identify the approximate location of an obstruction.\r\nThe current project primarily demonstrates in-pipe movement, stability and visual observation. A mechanical blockage-removal mechanism is proposed as a future operational module. Once developed, it will allow the rover to approach and mechanically act upon a blockage from inside the pipeline.\r\nThe modular design allows further inspection and maintenance functions to be added without fundamentally changing the rover's core mobility system.", "majorHardwareComponents": ["The major hardware components of the INDROVE project include:\n•\tSprocket-chain mechanised wheel system: Developed by the team to provide traction and controlled movement inside cylindrical pipelines.\n•\tThree-arm expandable support mechanism: Provides multi-point contact with the internal pipe wall and helps maintain rover stability.\n•\tDrive mechanism: Transfers mechanical power to the sprocket-chain wheel system for forward and reverse movement.\n•\tMain control system: Receives operator commands and controls the rover's movement.\n•\tWired control unit: Allows the operator to control the rover externally without entering the pipeline.\n•\tCamera system: Provides live visual feedback of the internal pipeline environment during operation.\n•\t220 V power supply: Provides the electrical power required by the current prototype.\n•\tMechanical frame and structural components: Provide the required support for the drive", "wheel and expandable-arm mechanisms.\nThe current prototype is primarily focused on mobility", "stability and visual inspection. An independent mechanical blockage-removal mechanism is proposed for the next development stage and is therefore not considered a currently integrated hardware component.\nSimilarly", "advanced sensors and IR-camera integration are not included in the present prototype."], "useAi": true, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["General Public", "Industry", "Government / Public Services", "Urban Communities"], "potentialImpact": "INDROVE has the potential to improve the way horizontal pipeline blockages are inspected and maintained. Instead of requiring a person to enter a confined pipeline, the robotic platform can be remotely operated from outside, allowing inspection and intervention to be performed from a safer position.\r\nThe rover's in-pipe mobility can help operators reach locations that are difficult to access directly from the surface. Its live visual feedback can assist in identifying the location and nature of an obstruction before maintenance action is planned.\r\nThe proposed blockage-removal module could further enable targeted mechanical intervention directly at the blockage location, reducing dependence on repeated surface-level access through manholes.\r\nThe project's modular architecture also provides scope for future integration of additional sensors and inspection capabilities. This could support applications in building drainage systems, institutional facilities, municipal drainage networks and other cylindrical pipeline environments, subject to further testing and adaptation.\r\nBy combining remote operation with direct in-pipe access, INDROVE aims to contribute towards safer, more targeted and efficient pipeline maintenance.\r\nAt its current stage, the project is a developing prototype, and further engineering validation, environmental testing and field trials are required before large-scale real-world deployment.", "productPotential": "yes", "prototypeDevelopmentCost": 1000000, "auraDemoHighlight": "INDROVE is worth seeing because it demonstrates a practical attempt to put a robotic system inside a real-world pipeline maintenance problem rather than limiting robotics to conventional open environments.\r\nThe most distinctive part of the prototype is its sprocket-chain mechanised wheel system, developed by the team for movement inside a cylindrical pipeline. The rover also uses a three-arm expandable support mechanism, allowing it to maintain multi-point contact with the pipe wall while moving.\r\nVisitors can observe the actual mechanical principles behind the system, including in-pipe movement, traction, expandable support and remote operation. The live camera system also demonstrates how an operator can obtain visual information from inside the pipeline while remaining outside it.\r\nAnother important aspect is the project's modular development approach. The current prototype establishes the mobility and inspection platform, while a dedicated mechanical blockage-removal mechanism is being developed as the next stage.\r\nINDROVE therefore offers a combination of mechanical design, robotics, control and practical infrastructure application in one physical prototype.\r\nSeeing the project in operation provides a clearer understanding of how a compact robotic system can enter a confined cylindrical environment and perform controlled movement where conventional inspection and maintenance can be challenging.", "safetyHazards": ["sharp_mechanical_components"], "safetyPrecautions": "Safety is considered in the operation and testing of the INDROVE prototype by keeping the operator outside the pipeline during robotic movement and inspection. The rover is controlled externally through a wired control system, allowing the operator to remain at a safe distance from the confined operating environment.\r\nThe prototype is tested in a controlled setup rather than being immediately deployed in live public infrastructure. This allows the movement, mechanical mechanisms and control system to be observed and evaluated before considering field applications.\r\nThe current prototype uses a 220 V power supply, so electrical operation is restricted to controlled testing conditions and requires appropriate handling of the power connection and electrical components.\r\nThe mechanical system is also operated under controlled conditions so that the movement of the sprocket-chain mechanism and expandable support arms can be monitored during testing.\r\nAt the present development stage, INDROVE is a prototype and does not claim complete environmental protection or field-safety certification. Waterproofing protection, additional electrical protection and other safety enhancements will require further engineering development and validation before operation in actual drainage or utility pipelines.\r\nThe project therefore follows a controlled-test-first approach, with further safety validation planned alongside future field deployment.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": true, "previousExhibitionDetails": "TA 2.0 Symposium Kolkata 2026 (Know Your TA), Dhono Dhanyo Auditorium\r\n33rd West Bengal State Science & Technology, Biswa Bangla Convention Centre\r\nCII ICT East (CII Eastern Region Hackathon 2026), ITC Sonar", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-29T17:55:40.644Z", "updatedAt": "2026-10-11T17:32:44.411Z", "abstract": { "originalName": "INDROVE abstruct.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790704539/aura-registrations/abstract-docs/INDROVE%20abstruct.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/INDROVE/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/INDROVE/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790704539/aura-registrations/id-cards/japzac8vessd3gqkcebt.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/INDROVE/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790704539/aura-registrations/id-cards/kpivcaurhiibu3akmvdk.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/INDROVE/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/INDROVE/4.jpg", "url": null, "exists": false }] }, { "index": 20, "id": "6abc8d2087ebbaa70b081851", "registrationId": "AURA2K26-4D8PRS", "rawTeamName": "TARAKSHA", "folderName": "TARAKSHA", "folderRelPath": "assets/Teams/TARAKSHA", "projectTitle": "TARAKSA – Smart Flood Rescue & Relief Delivery Boat", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "SNEHA DUTTA", "teamLeaderEmail": "snehadutta1011@gmail.com", "teamLeaderPhone": "9476419594", "teamMemberDetails": "SUBHAM SAMUI | SWAMI VIVEKANANDA INSTITUTE SCIENCE & TECHNOLOGY | ELECTRONICS & COMMUNICATION ENGINEERING | 3RD YEAR | 6297 218 712\r\nSHUVA PRADHAN | SWAMI VIVEKANANDA INSTITUTE SCIENCE & TECHNOLOGY | MECHANICAL ENGINEERING | 3RD YEAR | 9732722325\r\nSUBHAM SAHA | SWAMI VIVEKANANDA INSTITUTE SCIENCE & TECHNOLOGY | MECHANICAL ENGINEERING | 3RD YEAR | 8972786106", "hardwareProjectCategories": ["Robotics", "IoT & Smart Devices", "Electronics & Communication", "Industrial / Manufacturing Technology", "Safety & Security Systems"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Floods can isolate communities, make roads unusable and create dangerous conditions for rescue personnel. In many situations, affected people may require rapid visual assessment, drinking water, food or first-aid supplies before a full rescue team can safely reach them.\r\n\r\nTARAKSA is a compact, remotely operated flood-rescue and relief boat designed to support these situations. An ESP32-based control system manages propulsion and onboard sensors, while a 4G router provides long-range internet connectivity where cellular coverage is available. A 360° camera provides live situational awareness, and GPS, compass and IMU data help the operator understand the boat’s position and movement. Ultrasonic sensing assists with nearby obstacle detection.\r\n\r\nThe boat also carries a waterproof emergency-storage compartment for small relief supplies. A remote-release mechanism can deliver supplies without requiring a person to approach the flooded location. An independent RC transmitter/receiver is included as a backup control link.\r\n\r\nThe innovation lies in combining remote operation, live visual monitoring, location awareness, environmental sensing, obstacle awareness and relief delivery in a relatively low-cost platform. TARAKSA is intended as a support tool for trained rescue personnel, helping them assess flooded areas and deliver essential supplies while reducing unnecessary exposure to hazardous conditions.", "solutionDescription": "Floods can isolate communities, make roads unusable and create dangerous conditions for rescue personnel. In many situations, affected people may require rapid visual assessment, drinking water, food or first-aid supplies before a full rescue team can safely reach them.\r\n\r\nTARAKSA is a compact, remotely operated flood-rescue and relief boat designed to support these situations. An ESP32-based control system manages propulsion and onboard sensors, while a 4G router provides long-range internet connectivity where cellular coverage is available. A 360° camera provides live situational awareness, and GPS, compass and IMU data help the operator understand the boat’s position and movement. Ultrasonic sensing assists with nearby obstacle detection.\r\n\r\nThe boat also carries a waterproof emergency-storage compartment for small relief supplies. A remote-release mechanism can deliver supplies without requiring a person to approach the flooded location. An independent RC transmitter/receiver is included as a backup control link.\r\n\r\nThe innovation lies in combining remote operation, live visual monitoring, location awareness, environmental sensing, obstacle awareness and relief delivery in a relatively low-cost platform. TARAKSA is intended as a support tool for trained rescue personnel, helping them assess flooded areas and deliver essential supplies while reducing unnecessary exposure to hazardous conditions.", "innovationDescription": "Floods can isolate communities, make roads unusable and create dangerous conditions for rescue personnel. In many situations, affected people may require rapid visual assessment, drinking water, food or first-aid supplies before a full rescue team can safely reach them.\r\n\r\nTARAKSA is a compact, remotely operated flood-rescue and relief boat designed to support these situations. An ESP32-based control system manages propulsion and onboard sensors, while a 4G router provides long-range internet connectivity where cellular coverage is available. A 360° camera provides live situational awareness, and GPS, compass and IMU data help the operator understand the boat’s position and movement. Ultrasonic sensing assists with nearby obstacle detection.\r\n\r\nThe boat also carries a waterproof emergency-storage compartment for small relief supplies. A remote-release mechanism can deliver supplies without requiring a person to approach the flooded location. An independent RC transmitter/receiver is included as a backup control link.\r\n\r\nThe innovation lies in combining remote operation, live visual monitoring, location awareness, environmental sensing, obstacle awareness and relief delivery in a relatively low-cost platform. TARAKSA is intended as a support tool for trained rescue personnel, helping them assess flooded areas and deliver essential supplies while reducing unnecessary exposure to hazardous conditions.", "workingPrinciple": "TARAKSA operates as a remotely controlled surface vehicle. The operator sends navigation commands through the primary communication link using a 4G router and SIM-based internet connection, subject to cellular network availability. The ESP32 receives the control information and generates commands for the propulsion system through the motor controllers/ESCs.\r\n\r\nAt the same time, onboard sensors continuously provide operational information. GPS supplies geographical position, while the compass and IMU provide heading and motion-related data. Ultrasonic sensors assist with identifying nearby obstacles. The camera supplies live visual information so the operator can observe the surrounding flood environment. A battery-monitoring circuit helps track the power condition, and a water-leak sensor provides an early warning of water entering the electronics enclosure.\r\n\r\nFor emergency relief, the boat carries a waterproof payload compartment. When the boat reaches the intended location, the operator can activate the release mechanism to deliver a limited quantity of supplies. If the primary internet-based link becomes unavailable, the independent RC system can be used as a backup, within its operating range.\r\n\r\nThe system is designed as a supervised rescue-support platform rather than an autonomous replacement for trained rescue personnel.", "majorHardwareComponents": ["• ESP32 development board – main control and communication interface\n• 4G router with SIM – primary long-range internet connectivity\n• 360° Wi-Fi camera with microphone – live visual monitoring\n• GPS module – position tracking\n• Digital compass and IMU – heading and motion sensing\n• Ultrasonic sensors – nearby obstacle detection\n• BME280 – environmental sensing\n• Water-leak sensor – electronics enclosure protection\n• Battery voltage/level indicator and BMS – power monitoring and battery protection\n• Motor controllers/ESCs and propulsion motors – boat movement\n• RC transmitter and receiver – independent backup control\n• Solar panel and charging interface – auxiliary charging support\n• SD card/storage – local data/video support where applicable\n• Waterproof electronics enclosure and wiring\n• Waterproof relief-supply compartment with remote-release mechanism\n• Switches", "connectors", "fuses/protection and mounting hardware"], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "Other"], "potentialImpact": "TARAKSA is intended to support disaster-response teams during flood situations by providing a remotely operated platform for visual assessment, location-based monitoring and delivery of small emergency supplies. It can help responders inspect areas that may be difficult or temporarily unsafe to access directly.\r\n\r\nThe system combines live video, GPS location, basic obstacle awareness, environmental and water-leak monitoring, and battery-status information in one platform. This can provide the operator with useful situational information before deciding how and where to deploy human rescuers.\r\n\r\nThe relief compartment can carry limited quantities of drinking water, dry food, first-aid materials or other essential items. This makes the platform useful not only for reconnaissance but also for short-distance relief delivery.\r\n\r\nThe design is modular, allowing future upgrades such as night-vision or thermal cameras, improved navigation, stronger communication links, higher-capacity payloads and additional safety systems. The project therefore has potential as a low-cost experimental platform for flood-response technology and engineering education.", "productPotential": "yes", "prototypeDevelopmentCost": 80000, "auraDemoHighlight": "The most notable aspect of TARAKSA is that it combines several practical rescue functions in a single compact surface platform. Instead of being limited to simple RC movement, the prototype integrates remote control, 4G connectivity, live camera monitoring, GPS, motion sensing, obstacle detection, battery monitoring and emergency-supply delivery.\r\n\r\nThe project is also designed with redundancy in mind: the 4G-based control path is supported by an independent RC link. This makes the communication architecture more practical for a prototype intended for unpredictable flood environments, although all operation remains dependent on network and radio conditions.\r\n\r\nAnother important feature is the relief-delivery mechanism. A small payload can be transported to an isolated location and released remotely, reducing the need for a person to immediately enter the water.\r\n\r\nTARAKSA demonstrates how affordable embedded electronics and communication technologies can be integrated into a physical rescue-support system. The prototype provides a clear foundation for future development toward improved autonomy, navigation, sensing and disaster-response applications.", "safetyHazards": ["none"], "safetyPrecautions": "The electronics are housed inside a sealed/water-resistant enclosure to reduce the risk of water reaching electrical components. Battery wiring is arranged with appropriate insulation and protection, and a battery-management/protection system is used with the rechargeable battery pack.\r\n\r\nPropulsion components are mechanically secured and should be operated only when the boat is in a suitable test area. Moving propellers/motors are kept away from people during testing, and the system should be powered down before mechanical servicing.\r\n\r\nThe prototype is intended for controlled and supervised demonstrations. Operators should maintain a safe distance from the boat, use appropriate personal safety precautions near water, and avoid operation during unsafe weather or water conditions.\r\n\r\nThe payload release mechanism is designed to operate remotely, reducing the need for direct contact with the moving boat. A manual power cutoff should be available to stop the system in an emergency.\r\n\r\nThe prototype is a rescue-support device and is not certified life-saving equipment. Field deployment should be performed only by trained personnel after appropriate testing, risk assessment and local authorization.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-30T04:16:32.358Z", "updatedAt": "2026-10-11T17:32:49.839Z", "abstract": { "originalName": "TARAKSHA_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790741791/aura-registrations/abstract-docs/TARAKSHA_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/TARAKSHA/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/TARAKSHA/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790741791/aura-registrations/id-cards/g3dckifvzpky5zzvqrdn.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/TARAKSHA/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790741791/aura-registrations/id-cards/ly5nvhwbwb3ll3bxpme6.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/TARAKSHA/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790741791/aura-registrations/id-cards/czwiem6zyo37kthdn0js.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/TARAKSHA/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790741791/aura-registrations/id-cards/vd3kt3zegsarfpcax1n0.jpg", "exists": true }] }, { "index": 21, "id": "6abcefb71e01160fb6dfffca", "registrationId": "AURA2K26-CDGP69", "rawTeamName": "SASHTHAM INDRIYA", "folderName": "SASHTHAM INDRIYA", "folderRelPath": "assets/Teams/SASHTHAM INDRIYA", "projectTitle": "SASHTHAM INDRIYA: AI POWERED BREATH-BASED NARCOTICS DETECTION DEVICE", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "KUSHAL MAKAR", "teamLeaderEmail": "kushal.m2580@gmail.com", "teamLeaderPhone": "8910858500", "teamMemberDetails": "SUNITA DAS | SWAMI VIVEKANANDA INSTITUTE OF SCIENCE & TECHNOLOGY | ECE | 3rd | 9007361753", "hardwareProjectCategories": ["Biomedical / Healthcare Devices", "Safety & Security Systems", "Embedded Systems", "IoT & Smart Devices"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "SASHTHAM INDRIYA: AI-Powered Breath Analysis for Immediate Narcotics Screening\r\nThe Challenge:\r\nCurrent law enforcement protocols for field drug detection rely on invasive, time-consuming (24-48 Hrs) blood and urine tests. There is a critical absence of a rapid, portable, and non-invasive screening tool capable of providing real-time intelligence at checkpoints and borders.\r\nThe Solution:\r\nSASHTHAM INDRIYA is a fully functional, indigenous handheld prototype that translates the simplicity of an alcohol breathalyzer to narcotics detection. Utilizing multi-sensor fusion (Bosch BME688 AI Gas Sensors and MQ series) combined with Edge AI, the device captures and fingerprints the Volatile Organic Compounds (VOCs) and biomarkers present in human breath after narcotic consumption.\r\nThe Innovation of Project: We did not just design a concept; we built a deployable reality. SASHTHAM INDRIYA is an accessible, working hardware prototype capable of immediate breath-sample analysis.\r\nNear Real-Time Results: The device provides rapid feedback directly at the point of testing. From the moment a subject exhales into the device, it captures, processes, and outputs the result in under 15 seconds.\r\nwe are proving that India does not need to rely on vastly expensive (₹50,000+), imported forensic laboratory kits to secure its communities.\r\nOur device directly supports the National Action Plan for Drug Demand Reduction (NAPDDR). By equipping our police forces, border security, and de-addiction centers with a handheld, cost-effective (under ₹3,000), and highly accurate indigenous tool, we are enabling proactive deterrence and rapid intervention. SASHTHAM INDRIYA is not just a hackathon submission; it is a scalable, self-reliant leap forward in safeguarding the health, safety, and future of our nation.", "solutionDescription": "SASHTHAM INDRIYA: AI-Powered Breath Analysis for Immediate Narcotics Screening\r\nThe Challenge:\r\nCurrent law enforcement protocols for field drug detection rely on invasive, time-consuming (24-48 Hrs) blood and urine tests. There is a critical absence of a rapid, portable, and non-invasive screening tool capable of providing real-time intelligence at checkpoints and borders.\r\nThe Solution:\r\nSASHTHAM INDRIYA is a fully functional, indigenous handheld prototype that translates the simplicity of an alcohol breathalyzer to narcotics detection. Utilizing multi-sensor fusion (Bosch BME688 AI Gas Sensors and MQ series) combined with Edge AI, the device captures and fingerprints the Volatile Organic Compounds (VOCs) and biomarkers present in human breath after narcotic consumption.\r\nThe Innovation of Project: We did not just design a concept; we built a deployable reality. SASHTHAM INDRIYA is an accessible, working hardware prototype capable of immediate breath-sample analysis.\r\nNear Real-Time Results: The device provides rapid feedback directly at the point of testing. From the moment a subject exhales into the device, it captures, processes, and outputs the result in under 15 seconds.\r\nwe are proving that India does not need to rely on vastly expensive (₹50,000+), imported forensic laboratory kits to secure its communities.\r\nOur device directly supports the National Action Plan for Drug Demand Reduction (NAPDDR). By equipping our police forces, border security, and de-addiction centers with a handheld, cost-effective (under ₹3,000), and highly accurate indigenous tool, we are enabling proactive deterrence and rapid intervention. SASHTHAM INDRIYA is not just a hackathon submission; it is a scalable, self-reliant leap forward in safeguarding the health, safety, and future of our nation.", "innovationDescription": "SASHTHAM INDRIYA: AI-Powered Breath Analysis for Immediate Narcotics Screening\r\nThe Challenge:\r\nCurrent law enforcement protocols for field drug detection rely on invasive, time-consuming (24-48 Hrs) blood and urine tests. There is a critical absence of a rapid, portable, and non-invasive screening tool capable of providing real-time intelligence at checkpoints and borders.\r\nThe Solution:\r\nSASHTHAM INDRIYA is a fully functional, indigenous handheld prototype that translates the simplicity of an alcohol breathalyzer to narcotics detection. Utilizing multi-sensor fusion (Bosch BME688 AI Gas Sensors and MQ series) combined with Edge AI, the device captures and fingerprints the Volatile Organic Compounds (VOCs) and biomarkers present in human breath after narcotic consumption.\r\nThe Innovation of Project: We did not just design a concept; we built a deployable reality. SASHTHAM INDRIYA is an accessible, working hardware prototype capable of immediate breath-sample analysis.\r\nNear Real-Time Results: The device provides rapid feedback directly at the point of testing. From the moment a subject exhales into the device, it captures, processes, and outputs the result in under 15 seconds.\r\nwe are proving that India does not need to rely on vastly expensive (₹50,000+), imported forensic laboratory kits to secure its communities.\r\nOur device directly supports the National Action Plan for Drug Demand Reduction (NAPDDR). By equipping our police forces, border security, and de-addiction centers with a handheld, cost-effective (under ₹3,000), and highly accurate indigenous tool, we are enabling proactive deterrence and rapid intervention. SASHTHAM INDRIYA is not just a hackathon submission; it is a scalable, self-reliant leap forward in safeguarding the health, safety, and future of our nation.", "workingPrinciple": "SASHTHAM INDRIYA operates on a streamlined, five-step electrochemical and AI-driven workflow: Warmup, Exhale, VOC Capture, AI Classify, and Display.  \r\nThe process begins when a subject exhales into the device, releasing a complex mixture of breath trace elements. The breath passes over a multi-sensor fusion array—anchored by the Bosch BME688 AI Gas Sensor and MQ-series chemiresistive sensors. These sensors capture the unique Volatile Organic Compounds (VOCs) and chemical biomarkers indicative of recent narcotic consumption, such as opioids.  \r\nThe raw analog data is instantly sampled by the core ESP32 microcontroller. Instead of sending data to the cloud, the ESP32 utilizes the embedded Bosch BSEC2 AI Library to perform on-device edge classification. The AI model, pre-trained using BME AI-Studio to recognize specific biomarker fingerprints, analyzes the gas resistance patterns in near real-time.  \r\nFinally, the microcontroller outputs the classification. It hosts its own offline Wi-Fi hotspot and WebServer, pushing a definitive Positive, Negative, or Inconclusive result to a secure mobile dashboard in under 15 seconds. Visual and auditory indicators (LEDs and a buzzer) provide immediate physical feedback. This creates a rapid, non-invasive, and fully offline detection loop.", "majorHardwareComponents": ["The SASHTHAM INDRIYA prototype is engineered using accessible", "commercially viable hardware to ensure low cost (under ₹3", "000) and high scalability:  \nESP32 Microcontroller: The core processing unit. It handles real-time analog-to-digital (ADC) sensor sampling", "runs the embedded C/C++ firmware", "executes the on-device AI classification", "and hosts the standalone Wi-Fi WebServer for the offline dashboard.  \nBosch BME688 AI Gas Sensor: An industry-grade", "highly sensitive environmental and gas sensor capable of detecting Volatile Organic Compounds (VOCs). It is the primary hardware responsible for capturing the distinct chemical \"fingerprints\" of exhaled breath.  \nChemiresistive Sensor Array (MQ Series): Supplementary gas sensors working in tandem with the BME688 to detect volatile solvents", "hydrocarbon inhalants", "and specific chemical biomarkers", "creating a robust multi-sensor fusion setup.  \nVisual & Auditory Indicators: Integrated LEDs (Green for clean", "Red for detected) and a buzzer provide immediate", "unambiguous physical alerts to the field officer the moment a substance is classified.  \nPower & Portability Architecture: Housed in a compact", "handheld form factor designed for USB or battery operation", "making it entirely independent of specialized medical infrastructure and ready for field deployment."], "useAi": true, "useIot": true, "powerSource": "usb", "intendedBeneficiaries": ["Healthcare", "Government / Public Services", "Industry"], "potentialImpact": "SASHTHAM INDRIYA fundamentally transforms how authorities conduct preliminary narcotics screening, offering massive improvements over existing blood or urine tests that are invasive, expensive (₹50,000+ per lab kit), and take 24–72 hours for results. Our device provides a non-invasive, accurate readout in under 15 seconds at a fraction of the cost (<₹3,000).  \r\nWho Benefits?\r\nLaw Enforcement: Enables rapid roadside screening at traffic stops and checkpoints, directly acting as a proactive deterrence tool.  \r\nDe-addiction Centers & Rehabilitation: Allows for non-invasive patient compliance monitoring and quick relapse detection.  \r\nWorkplaces & Educational Institutions: Facilitates pre-shift safety screenings in high-risk sectors (transport, construction) and deterrence programs in campus hostels.  \r\nImproving Standards:\r\nBy eliminating the need for specialized medical personnel and laboratory infrastructure for initial screening, it democratizes drug detection. It directly champions the Atmanirbhar Bharat initiative by replacing imported forensic kits with an indigenous solution. Furthermore, it actively supports India’s National Action Plan for Drug Demand Reduction (NAPDDR) by equipping frontline workers with a highly accessible, rapid-response tool to secure communities and enforce safety protocols instantaneously.", "productPotential": "yes", "prototypeDevelopmentCost": 3000, "auraDemoHighlight": "What sets SASHTHAM INDRIYA apart is that it is not a theoretical whitepaper—it is a fully functional, tangible prototype that has already proven its field viability. Evaluators should pay attention for three critical reasons:\r\nOfficial Stakeholder Validation: We didn't just build this in a lab; we took it directly to the end-users. The prototype has been successfully demonstrated to the West Bengal Police, who validated its extreme operational necessity and 15-second response time. We have documented this endorsement and our live testing on video via a single QR code.  \r\nIngenious, Legal Validation Methodology: To prove our electrochemical VOC detection works for opioids without handling illegal narcotics, we successfully tested the device using \"Opium 200CH\" (a legal homeopathic medicine containing active Opium). This innovative approach achieved a 50–75% accuracy baseline on our self-generated test set, proving technical feasibility perfectly within hackathon constraints.\r\nTrue Edge-AI: Unlike many IoT devices that rely on cloud APIs, our ESP32 and BSEC2 AI library execute complex biomarker classification entirely offline. It hosts its own Wi-Fi dashboard, meaning a police officer can use this device in the most remote, internet-deprived checkpoint in India with zero lag.", "safetyHazards": ["none"], "safetyPrecautions": "Building a MedTech/HealthTech device requires rigorous safety and operational safeguards. We have integrated several key precautions into SASHTHAM INDRIYA:\r\nLegal & Safe Development: To ensure absolute safety and regulatory compliance during development, we strictly utilized legal medicinal drug analogues (like Opium 200CH) for AI model training and testing. No illegal or dangerous narcotics were handled.  \r\nCross-Sensitivity Mitigation: A major risk in breath analysis is false positives from everyday items (food, perfumes, mouthwash). We safeguard against this using multi-sensor fusion and AI-filtering algorithms that are specifically trained to distinguish targeted narcotic VOC fingerprints from common environmental anomalies.  \r\nEnvironmental Stability Safeguards: Sensor accuracy can drift due to external temperature or humidity changes. The firmware includes automated auto-calibration routines and baseline tracking to ensure the sensors remain accurate regardless of the operating environment.  \r\nHygienic, Non-Invasive Design: By relying entirely on exhaled breath, the device completely eliminates the biohazard risks associated with handling bodily fluids like blood or urine.  \r\nDefined Operational Scope: The device is explicitly safeguarded by its intended use case: it is a preliminary screening tool. The dashboard and documentation clearly state that positive readings provide probable cause and require standard laboratory confirmation before any legal or punitive action is taken, protecting both the user and the subject.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-30T11:17:11.819Z", "updatedAt": "2026-10-11T17:32:54.158Z", "abstract": { "originalName": "SASHTHAM_INDRIYA_Writeup.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790767031/aura-registrations/abstract-docs/SASHTHAM_INDRIYA_Writeup.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/SASHTHAM INDRIYA/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/SASHTHAM INDRIYA/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790767030/aura-registrations/id-cards/dkcnpn3atmmolhpsvni4.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/SASHTHAM INDRIYA/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790767030/aura-registrations/id-cards/ey97uumxfnjaamysmvb8.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/SASHTHAM INDRIYA/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/SASHTHAM INDRIYA/4.jpg", "url": null, "exists": false }] }, { "index": 22, "id": "6abd4aa65fda01fbe7a9c54d", "registrationId": "AURA2K26-GE52CY", "rawTeamName": "ABBOY", "folderName": "ABBOY", "folderRelPath": "assets/Teams/ABBOY", "projectTitle": "Forever FitBand", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Smarajit Datta", "teamLeaderEmail": "smarajitdatta6@gmail.com", "teamLeaderPhone": "6291655258", "teamMemberDetails": "Ankit Gupta | Hooghly Engineering & Technology College | Computer Science and Engineering | 3rd | 7003345530", "hardwareProjectCategories": ["IoT & Smart Devices", "Biomedical / Healthcare Devices"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "PROBLEM\r\nDuring heat waves, floods, pollution events and earthquakes, people receive generic alerts but no warning that conditions are dangerous for them personally. Elderly and at-risk people living alone can fall and go unnoticed, and most health wearables depend on the cloud, so they stop helping exactly when networks fail.\r\n\r\nSOLUTION\r\nForever FitBand is an ESP32-S3 wrist wearable paired with a mobile app. The band measures heart rate and SpO2 (MAX30102), body temperature (DS18B20), motion (MPU6050) and ambient temperature, humidity and pressure (BME280), shows them on an OLED watch face, and streams them over Bluetooth Low Energy. The app detects falls, flags abnormal vitals, and warns of local heat, air-quality, flood, cyclone and earthquake risk. A fall or SOS starts a 10-second cancel window, then escalates to an emergency call, a caregiver and SMS with the user's vitals and location.\r\n\r\nINNOVATION\r\n- Fully on-device AI: fall-detection and activity CNNs (92% precision and recall on unseen test subjects) and an offline LLM health assistant. No cloud, and health data never leaves the phone.\r\n- Works without internet: offline hazard maps and cached risk data keep alerts running when networks fail.\r\n- Personal risk, not generic alerts: vitals are fused with heat index, air quality and hazard data.\r\n- Trustworthy readings: the band shows HR and SpO2 only after the signal settles and passes quality checks, and reports nothing when not worn.\r\n- Low cost: about ₹2,200 in parts.", "solutionDescription": "PROBLEM\r\nDuring heat waves, floods, pollution events and earthquakes, people receive generic alerts but no warning that conditions are dangerous for them personally. Elderly and at-risk people living alone can fall and go unnoticed, and most health wearables depend on the cloud, so they stop helping exactly when networks fail.\r\n\r\nSOLUTION\r\nForever FitBand is an ESP32-S3 wrist wearable paired with a mobile app. The band measures heart rate and SpO2 (MAX30102), body temperature (DS18B20), motion (MPU6050) and ambient temperature, humidity and pressure (BME280), shows them on an OLED watch face, and streams them over Bluetooth Low Energy. The app detects falls, flags abnormal vitals, and warns of local heat, air-quality, flood, cyclone and earthquake risk. A fall or SOS starts a 10-second cancel window, then escalates to an emergency call, a caregiver and SMS with the user's vitals and location.\r\n\r\nINNOVATION\r\n- Fully on-device AI: fall-detection and activity CNNs (92% precision and recall on unseen test subjects) and an offline LLM health assistant. No cloud, and health data never leaves the phone.\r\n- Works without internet: offline hazard maps and cached risk data keep alerts running when networks fail.\r\n- Personal risk, not generic alerts: vitals are fused with heat index, air quality and hazard data.\r\n- Trustworthy readings: the band shows HR and SpO2 only after the signal settles and passes quality checks, and reports nothing when not worn.\r\n- Low cost: about ₹2,200 in parts.", "innovationDescription": "PROBLEM\r\nDuring heat waves, floods, pollution events and earthquakes, people receive generic alerts but no warning that conditions are dangerous for them personally. Elderly and at-risk people living alone can fall and go unnoticed, and most health wearables depend on the cloud, so they stop helping exactly when networks fail.\r\n\r\nSOLUTION\r\nForever FitBand is an ESP32-S3 wrist wearable paired with a mobile app. The band measures heart rate and SpO2 (MAX30102), body temperature (DS18B20), motion (MPU6050) and ambient temperature, humidity and pressure (BME280), shows them on an OLED watch face, and streams them over Bluetooth Low Energy. The app detects falls, flags abnormal vitals, and warns of local heat, air-quality, flood, cyclone and earthquake risk. A fall or SOS starts a 10-second cancel window, then escalates to an emergency call, a caregiver and SMS with the user's vitals and location.\r\n\r\nINNOVATION\r\n- Fully on-device AI: fall-detection and activity CNNs (92% precision and recall on unseen test subjects) and an offline LLM health assistant. No cloud, and health data never leaves the phone.\r\n- Works without internet: offline hazard maps and cached risk data keep alerts running when networks fail.\r\n- Personal risk, not generic alerts: vitals are fused with heat index, air quality and hazard data.\r\n- Trustworthy readings: the band shows HR and SpO2 only after the signal settles and passes quality checks, and reports nothing when not worn.\r\n- Low cost: about ₹2,200 in parts.", "workingPrinciple": "Forever FitBand is a wrist wearable built on an ESP32-S3 microcontroller that works with a companion mobile app.\r\n\r\n1. Sensing: a MAX30102 optical sensor measures heart rate and SpO2 using photoplethysmography (PPG) at 100 Hz. A DS18B20 measures body temperature, an MPU6050 measures motion, and a BME280 measures ambient temperature, humidity and pressure.\r\n2. Signal quality: the firmware filters the PPG signal, waits 2 seconds for it to settle, rejects irregular beats, and reports HR and SpO2 only after 4 clean beats. Skin-contact detection stops readings when the band is not worn.\r\n3. Communication: the band streams vitals, environment and motion data to the phone over Bluetooth Low Energy (BLE) and shows the time and readings on an OLED watch face.\r\n4. On-device intelligence: the phone runs small neural networks (1D-CNNs) for fall detection and activity recognition, compares vitals to the user's 7-day personal baseline, and fuses them with heat index, air quality and local disaster-hazard data (cached for offline use).\r\n5. Response: abnormal vitals trigger alerts, imminent disasters trigger a full-screen warning with a siren, and a detected fall or SOS starts a 10-second cancel countdown before escalating to an emergency call, a caregiver and SMS.\r\n\r\nAll processing happens on the phone, so no internet or cloud server is needed.", "majorHardwareComponents": ["- ESP32-S3 N16R8 microcontroller (dual-core", "BLE", "16 MB flash", "8 MB PSRAM)\n- MAX30102 pulse oximeter and heart-rate sensor (PPG)\n- DS18B20 digital body-temperature sensor\n- MPU6050 accelerometer and gyroscope (motion", "fall detection)\n- BME280 ambient temperature", "humidity and pressure sensor\n- 0.96\" SSD1306 OLED display (watch face)\n- 500 mAh Li-ion battery with a 3.3 V regulator\n- Breadboard prototype with jumper wiring and a wrist strap\n- Android smartphone running the companion app (on-device AI processing)"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Healthcare"], "potentialImpact": "Beneficiaries: elderly people and those living alone, people with chronic heart or respiratory conditions, outdoor workers exposed to heat, caregivers, and communities in disaster-prone areas.\r\n\r\nHow it improves current standards:\r\n- Personal, not generic, warnings: instead of broadcast weather alerts, it tells users when local heat, air quality, flood, cyclone or earthquake risk is dangerous for their own current vitals.\r\n- Faster help after falls: automatic fall detection with escalation to emergency services and caregivers, even if the person can't reach their phone.\r\n- Works when networks fail: all analysis, hazard data and the AI assistant run offline, which is exactly when cloud-based wearables stop helping.\r\n- Privacy by design: health data stays on the user's phone, unlike most commercial fitness trackers.\r\n- Affordable: built from about ₹2,200 of parts, far cheaper than commercial smartwatches with similar sensors, making it practical for low-income and rural users.", "productPotential": "yes", "prototypeDevelopmentCost": 2200, "auraDemoHighlight": "It is a complete working system, not a concept: real hardware on the wrist, real data on the phone, and real AI running without internet.\r\n\r\nVisitors can see:\r\n- Live heart rate and SpO2 from their own finger, with the band honestly showing \"measuring\" until the reading is stable instead of a fake number.\r\n- Fall detection triggering an alert with a 10-second \"I'm OK\" countdown and a simulated emergency call.\r\n- A disaster-risk map and a full-screen imminent-disaster warning with safety steps.\r\n- An AI health assistant answering questions with the phone in airplane mode.\r\n\r\nOur fall-detection model scores 92% precision and 92% recall on test subjects it never saw during training, and its threshold was chosen from data and real drop tests. Everything runs on-device, so no health data leaves the phone.", "safetyHazards": ["none"], "safetyPrecautions": "- Low-voltage system: the whole device runs at 3.3 V from a small 500 mAh Li-ion cell through a regulator; there is no mains power.\r\n- The battery is kept away from sharp edges and heat, is not charged unattended, and is disconnected when not in use.\r\n- Wiring is checked for short circuits before powering on.\r\n- The optical sensor uses a low-power LED, safe for skin contact.\r\n- Emergency features run in test mode during demos, so no real calls or SMS are sent.\r\n- The disaster-alert siren is played at reduced volume in public demos.\r\n- The device is not a medical instrument; readings are shown as estimates, not diagnoses.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-30T17:45:10.477Z", "updatedAt": "2026-10-14T18:48:04.99Z", "abstract": { "originalName": "ForeverFitBand_Abstract_AURA26.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790790308/aura-registrations/abstract-docs/ForeverFitBand_Abstract_AURA26.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/ABBOY/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/ABBOY/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790790309/aura-registrations/id-cards/a4jth77rrld0xzfmlcjn.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/ABBOY/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790790309/aura-registrations/id-cards/qjz5gxlmwydauely1ccm.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/ABBOY/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/ABBOY/4.jpg", "url": null, "exists": false }] }, { "index": 23, "id": "6abd52a93d1543685c70bbfc", "registrationId": "AURA2K26-Y2AV77", "rawTeamName": "Aegis Innovators", "folderName": "Aegis Innovators", "folderRelPath": "assets/Teams/Aegis Innovators", "projectTitle": "Shield Band: A Sustainable Forensic-Grade Personal Safety Wearable", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "Astana Parvin", "teamLeaderEmail": "astanaparvin9434231722@gmail.com", "teamLeaderPhone": "8597379637", "teamMemberDetails": "Member Name - Manine Khatun \r\nInstitution - Aliah University \r\nDepartment - Mathematics and Statistics \r\nYear - 3rd Year\r\nPhone - 9593597174\r\n\r\nMember Name - Sarfaraj Siddiqui \r\nInstitution - Aliah University \r\nDepartment - Mathematics and Statistics \r\nYear - 3rd Year\r\nPhone - 9083356465", "hardwareProjectCategories": ["Safety & Security Systems", "IoT & Smart Devices"], "prototypeType": "Wearable Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Shield Band addresses the gap between an emergency situation and timely assistance, especially when a user cannot access or unlock a smartphone. It is a low-cost, smartphone-independent personal safety wearable designed for students, women, children, night-shift workers and other vulnerable users.\r\nThe proposed hardware integrates an ESP32-CAM microcontroller, GPS module, microphone, OLED display and a tactile SOS push-button. The device follows a privacy-first approach: the camera and microphone remain inactive during normal operation and activate only after the user deliberately presses the SOS button. Upon activation, the GPS acquires the user's location while the camera and microphone capture time-linked audio-visual evidence. A GSM/LTE module sends an automated SMS containing a Google Maps location link to pre-configured emergency contacts. Where internet connectivity is available, emergency metadata and captured evidence can be securely transmitted to a cloud platform for authorized response personnel.\r\nThe innovation lies in combining smartphone-independent emergency activation, location-aware alerts, event-triggered evidence capture and secure cloud storage in a compact wearable. Sustainability is incorporated through proposed biodegradable or bio-reinforced housing, low-power operation and supplementary solar charging. The target prototype cost is below approximately ₹2,500, supporting accessibility and scalability.", "solutionDescription": "Shield Band addresses the gap between an emergency situation and timely assistance, especially when a user cannot access or unlock a smartphone. It is a low-cost, smartphone-independent personal safety wearable designed for students, women, children, night-shift workers and other vulnerable users.\r\nThe proposed hardware integrates an ESP32-CAM microcontroller, GPS module, microphone, OLED display and a tactile SOS push-button. The device follows a privacy-first approach: the camera and microphone remain inactive during normal operation and activate only after the user deliberately presses the SOS button. Upon activation, the GPS acquires the user's location while the camera and microphone capture time-linked audio-visual evidence. A GSM/LTE module sends an automated SMS containing a Google Maps location link to pre-configured emergency contacts. Where internet connectivity is available, emergency metadata and captured evidence can be securely transmitted to a cloud platform for authorized response personnel.\r\nThe innovation lies in combining smartphone-independent emergency activation, location-aware alerts, event-triggered evidence capture and secure cloud storage in a compact wearable. Sustainability is incorporated through proposed biodegradable or bio-reinforced housing, low-power operation and supplementary solar charging. The target prototype cost is below approximately ₹2,500, supporting accessibility and scalability.", "innovationDescription": "Shield Band addresses the gap between an emergency situation and timely assistance, especially when a user cannot access or unlock a smartphone. It is a low-cost, smartphone-independent personal safety wearable designed for students, women, children, night-shift workers and other vulnerable users.\r\nThe proposed hardware integrates an ESP32-CAM microcontroller, GPS module, microphone, OLED display and a tactile SOS push-button. The device follows a privacy-first approach: the camera and microphone remain inactive during normal operation and activate only after the user deliberately presses the SOS button. Upon activation, the GPS acquires the user's location while the camera and microphone capture time-linked audio-visual evidence. A GSM/LTE module sends an automated SMS containing a Google Maps location link to pre-configured emergency contacts. Where internet connectivity is available, emergency metadata and captured evidence can be securely transmitted to a cloud platform for authorized response personnel.\r\nThe innovation lies in combining smartphone-independent emergency activation, location-aware alerts, event-triggered evidence capture and secure cloud storage in a compact wearable. Sustainability is incorporated through proposed biodegradable or bio-reinforced housing, low-power operation and supplementary solar charging. The target prototype cost is below approximately ₹2,500, supporting accessibility and scalability.", "workingPrinciple": "Shield Band operates as a privacy-first, event-triggered personal safety wearable. During normal operation, the camera and microphone remain inactive and the system stays in a low-power standby state. When the user deliberately presses the physical SOS button, the ESP32-CAM exits the low-power state and initiates the emergency workflow. The GPS module acquires the user's current geographical coordinates, while the camera and microphone activate to capture time-linked audio-visual evidence.\r\nA GSM/LTE communication module provides cellular connectivity and sends an automated SMS alert containing a Google Maps location link to pre-configured emergency contacts. Where Internet connectivity is available, emergency metadata and captured evidence are transmitted through an encrypted connection to a secure cloud platform. Authorized campus safety or response personnel can access the location information and cloud-stored evidence through a dashboard.\r\nThe OLED display provides local feedback regarding system readiness, alert status and recording state. The system therefore separates the immediate cellular alert pathway from the Internet-based evidence and dashboard pathway, while maintaining privacy by activating audio-visual recording only after an SOS trigger.", "majorHardwareComponents": ["ESP32-CAM: Main microcontroller and camera unit responsible for controlling the emergency workflow and capturing visual evidence.\nGPS Module: Acquires the user's geographical coordinates for location-aware emergency alerts.\nMicrophone: Captures audio evidence after the SOS trigger.\nTactile SOS Push-Button: Provides deliberate physical activation of the emergency workflow.\nGSM/LTE Communication Module: Enables cellular communication and sends an automated SMS containing a Google Maps location link to pre-configured emergency contacts.\nOLED Display: Provides local feedback such as system readiness", "alert status and recording state.\nRechargeable Power System"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public"], "potentialImpact": "Shield Band is designed to benefit students, women, children, night-shift workers and other users who may require a rapidly accessible emergency mechanism. It addresses situations where a person may not be able to unlock a smartphone or depend on a mobile application during an emergency. The physical SOS button enables immediate activation of an emergency workflow, while GPS provides location information for responders.\r\n\r\nThe system can improve current personal safety approaches by combining smartphone-independent emergency activation, location-aware alerts and event-triggered audio-visual evidence capture in one wearable. The camera and microphone remain inactive during normal operation and activate only after an SOS trigger, supporting a privacy-first approach. Where Internet connectivity is available, emergency metadata and captured evidence can be securely transmitted to a cloud platform for authorized access.\r\n\r\nThe proposed low-cost design, targeted at approximately ₹2,500, also supports accessibility and scalability. Sustainable housing, low-power operation and supplementary solar harvesting further support resource-conscious product development.", "productPotential": "yes", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "Shield Band combines multiple emergency functions into a compact wearable while maintaining a privacy-first operating principle. Its most distinctive feature is that the camera and microphone are not continuously active; they are triggered only when the user deliberately presses the SOS button. This allows the system to capture time-linked audio-visual evidence during an emergency while reducing unnecessary routine surveillance.\r\n\r\nThe device also separates the emergency communication pathway from the evidence pathway. GSM/LTE can send an immediate SMS containing the user's location to pre-configured emergency contacts, while Internet connectivity can be used to transmit emergency metadata and captured evidence to a secure cloud platform.\r\n\r\nThe project further incorporates sustainability through proposed biodegradable or bio-reinforced housing, low-power operation and supplementary solar harvesting. With a proposed prototype cost of approximately ₹2,500, Shield Band explores an accessible and scalable approach to personal safety technology.", "safetyHazards": ["none"], "safetyPrecautions": "Shield Band is designed as a low-power wearable safety system. The electronics operate in a low-power standby state, reducing unnecessary energy consumption. The camera and microphone remain inactive during normal operation and are activated only after a deliberate SOS trigger, supporting privacy and controlled operation. The system uses a physical SOS button for intentional emergency activation and an OLED display to provide local feedback on system readiness, alert status and recording state. The proposed enclosure uses biodegradable or bio-reinforced materials, while supplementary solar harvesting is considered as part of the sustainable power design. During prototype development and testing, the electronic and power components should be handled according to their component specifications and manufacturer safety requirements.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "external_assistance", "previouslyExhibited": true, "previousExhibitionDetails": "Udaan 2.0, on 26th August 2026", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-30T18:19:21.093Z", "updatedAt": "2026-10-14T18:48:10.356Z", "abstract": { "originalName": "Shield_Band_AURA_2K26_Final.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790792360/aura-registrations/abstract-docs/Shield_Band_AURA_2K26_Final.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Aegis Innovators/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Aegis Innovators/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790792359/aura-registrations/id-cards/mmsazf3wg3e90dq2ebuq.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Aegis Innovators/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790792359/aura-registrations/id-cards/xixv15cqzzyweimsex0g.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Aegis Innovators/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790792359/aura-registrations/id-cards/abyeqqjjpx65ho4ba9fg.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Aegis Innovators/4.jpg", "url": null, "exists": false }] }, { "index": 24, "id": "6abd587074ea1518a42952a4", "registrationId": "AURA2K26-6MCNE2", "rawTeamName": "GEONEX", "folderName": "GEONEX", "folderRelPath": "assets/Teams/GEONEX", "projectTitle": "DRAIN-X", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Rahnuma Naaz", "teamLeaderEmail": "rahnuma11100@gmail.com", "teamLeaderPhone": "9064561623", "teamMemberDetails": "Farhin Sardar, Aliah University, Geography, 2nd, 8274077701\r\nWasi Ahmed, Aliah University, Geography, 2nd, 7074211956\r\nAbdul Mannan Saheb, Aliah University, Geography, 2nd, 7364070118", "hardwareProjectCategories": ["Embedded Systems", "Automation & Control", "Mechatronics", "Mechanical Systems", "Environmental Technology"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Urban waterlogging is often caused not only by heavy rainfall but also by blocked inlets, accumulated plastic and organic waste, sediment deposition, restricted flow, and downstream backwater. Conventional drains generally depend on periodic manual inspection and cleaning, making it difficult to identify the actual cause of poor drainage during rainfall. This can delay intervention, increase maintenance effort, and cause further accumulation.\r\n\r\nDRAIN-X is a proposed intelligent stormwater drainage prototype that monitors drainage conditions using rainfall, water-level, and flow sensors. A microcontroller analyses the sensor data to identify abnormal hydraulic conditions and determine the likely cause. Based on the diagnosis, the system can activate an appropriate response. Leaves and plastic will be intercepted into a solid-waste chamber, while sand and silt will be separated into a sediment chamber. Conditions such as downstream backwater or rainfall exceeding drainage capacity will generate an alert instead of triggering unnecessary cleaning. After intervention, the system will recheck the hydraulic conditions to verify whether flow has improved.\r\n\r\nThe main innovation of DRAIN-X is its closed-loop approach: Sense, Diagnose, Decide, Act, and Verify. Unlike a basic smart drain that only detects water level or blockage, DRAIN-X aims to distinguish between different causes of drainage failure and respond selectively. Its separate handling of solid waste and sediment, combined with post-intervention verification, is designed to reduce unnecessary maintenance and improve drainage efficiency. The prototype will provide a platform for testing adaptive stormwater management under controlled conditions and support efficient urban drainage maintenance in future.", "solutionDescription": "Urban waterlogging is often caused not only by heavy rainfall but also by blocked inlets, accumulated plastic and organic waste, sediment deposition, restricted flow, and downstream backwater. Conventional drains generally depend on periodic manual inspection and cleaning, making it difficult to identify the actual cause of poor drainage during rainfall. This can delay intervention, increase maintenance effort, and cause further accumulation.\r\n\r\nDRAIN-X is a proposed intelligent stormwater drainage prototype that monitors drainage conditions using rainfall, water-level, and flow sensors. A microcontroller analyses the sensor data to identify abnormal hydraulic conditions and determine the likely cause. Based on the diagnosis, the system can activate an appropriate response. Leaves and plastic will be intercepted into a solid-waste chamber, while sand and silt will be separated into a sediment chamber. Conditions such as downstream backwater or rainfall exceeding drainage capacity will generate an alert instead of triggering unnecessary cleaning. After intervention, the system will recheck the hydraulic conditions to verify whether flow has improved.\r\n\r\nThe main innovation of DRAIN-X is its closed-loop approach: Sense, Diagnose, Decide, Act, and Verify. Unlike a basic smart drain that only detects water level or blockage, DRAIN-X aims to distinguish between different causes of drainage failure and respond selectively. Its separate handling of solid waste and sediment, combined with post-intervention verification, is designed to reduce unnecessary maintenance and improve drainage efficiency. The prototype will provide a platform for testing adaptive stormwater management under controlled conditions and support efficient urban drainage maintenance in future.", "innovationDescription": "Urban waterlogging is often caused not only by heavy rainfall but also by blocked inlets, accumulated plastic and organic waste, sediment deposition, restricted flow, and downstream backwater. Conventional drains generally depend on periodic manual inspection and cleaning, making it difficult to identify the actual cause of poor drainage during rainfall. This can delay intervention, increase maintenance effort, and cause further accumulation.\r\n\r\nDRAIN-X is a proposed intelligent stormwater drainage prototype that monitors drainage conditions using rainfall, water-level, and flow sensors. A microcontroller analyses the sensor data to identify abnormal hydraulic conditions and determine the likely cause. Based on the diagnosis, the system can activate an appropriate response. Leaves and plastic will be intercepted into a solid-waste chamber, while sand and silt will be separated into a sediment chamber. Conditions such as downstream backwater or rainfall exceeding drainage capacity will generate an alert instead of triggering unnecessary cleaning. After intervention, the system will recheck the hydraulic conditions to verify whether flow has improved.\r\n\r\nThe main innovation of DRAIN-X is its closed-loop approach: Sense, Diagnose, Decide, Act, and Verify. Unlike a basic smart drain that only detects water level or blockage, DRAIN-X aims to distinguish between different causes of drainage failure and respond selectively. Its separate handling of solid waste and sediment, combined with post-intervention verification, is designed to reduce unnecessary maintenance and improve drainage efficiency. The prototype will provide a platform for testing adaptive stormwater management under controlled conditions and support efficient urban drainage maintenance in future.", "workingPrinciple": "DRAIN-X is an adaptive stormwater drainage prototype designed to detect, diagnose and respond to different causes of urban drainage failure. Controlled rainfall is introduced into a miniature urban drainage network containing an inlet, underground conduit and outlet. Rainfall intensity, water level and flow are continuously monitored using multiple sensors positioned at critical points. The sensor data are processed by a microcontroller using predefined hydraulic thresholds and decision logic to identify conditions such as solid-waste blockage, sediment accumulation, internal flow restriction, downstream backwater and rainfall exceeding drainage capacity. Based on the diagnosed condition, the control unit activates an appropriate response. Coarse debris such as leaves and plastic is mechanically intercepted and transferred to a separate solid-waste chamber, while sand and silt are directed towards a dedicated sediment-collection chamber through controlled flushing. When flooding is associated with downstream backwater or excessive rainfall rather than blockage, the system generates an alert without unnecessary cleaning. After intervention, water level and flow are measured again to verify whether drainage performance has recovered. Thus, DRAIN-X follows a closed-loop Sense → Diagnose → Decide → Act → Verify methodology for selective and resource-efficient stormwater management.", "majorHardwareComponents": ["ESP32/Arduino-based microcontroller", "rainfall sensor", "ultrasonic water-level sensors", "water-flow sensor", "debris/obstruction detection sensor", "servo/stepper motor", "motor driver", "miniature water pump", "solenoid valve", "mechanical screening/raking mechanism", "sediment flushing mechanism", "drainage pipes and channels", "solid-waste collection chamber", "sediment-collection chamber", "water reservoir", "LED/LCD display", "connecting wires", "tubing", "structural frame and power-supply unit."], "useAi": false, "useIot": false, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["General Public", "Government / Public Services", "Urban Communities"], "potentialImpact": "DRAIN-X is intended to support urban drainage authorities and infrastructure managers in reducing waterlogging caused by identifiable drainage failures. Unlike conventional maintenance approaches that often depend on periodic manual inspection, the proposed system continuously monitors hydraulic conditions and distinguishes between solid-waste blockage, sediment accumulation, internal restriction, downstream backwater and rainfall exceeding drainage capacity. Its selective response can reduce unnecessary cleaning, improve maintenance efficiency and minimise the mixing of solid waste with sediment. Separate collection chambers may also facilitate subsequent waste handling and sediment management. The system is particularly relevant to flood-prone urban roads, institutional campuses, industrial areas, parking facilities and other critical drainage locations. At larger scales, the sensing and diagnostic framework could be adapted for integration with municipal stormwater infrastructure. The prototype will provide experimental data on diagnostic accuracy, response time and restoration of flow, creating a basis for further engineering development and field validation. Its low-cost architecture is intended to make intelligent drainage monitoring more accessible to resource-constrained urban environments.", "productPotential": "yes", "prototypeDevelopmentCost": 8000, "auraDemoHighlight": "DRAIN-X is worth seeing because it takes a problem we see around us almost every monsoon—waterlogging—and asks a simple but important question: what is actually causing the drain to fail?\r\nA flooded road does not always mean that the drain is blocked. Sometimes leaves and plastic block the inlet, sometimes sand and silt build up inside, while in other situations the real problem may be excessive rainfall or water backing up from downstream. DRAIN-X is designed to identify these different situations and respond accordingly, rather than treating every problem in the same way.\r\nVisitors can actually watch this process happen in a working miniature urban drainage system. Controlled rainfall is introduced, sensors monitor the changing water and flow conditions, and the system decides what action is required. Solid waste is separated into one collection chamber, while sediment is handled separately. In situations where cleaning is unnecessary, the system simply generates an alert.\r\nThe most interesting part is that DRAIN-X checks whether its intervention actually worked by monitoring the drainage conditions again.\r\nIn short, DRAIN-X is not just a model of a drain. It is an attempt to make drainage more aware, selective and responsive—while using a problem that is familiar to almost every urban resident as the starting point for a practical engineering solution.", "safetyHazards": ["none"], "safetyPrecautions": "Safety will be given priority during the development and testing of the DRAIN-X prototype. Since the project combines water, electrical components, sensors, and moving mechanical parts, suitable precautions will be followed throughout the work.\r\nThe system will use a low-voltage power supply to reduce electrical hazards. All electrical connections will be properly insulated, and electronic components such as the microcontroller and sensors will be protected from direct contact with water. The power supply will always be switched off before changing wiring, repairing components, or carrying out maintenance.\r\nThe mechanical waste-removal mechanism will be designed with controlled movement and limited operating speed. Moving parts will be covered or positioned safely to prevent accidental contact during operation. Sharp edges and unnecessary exposed mechanical components will be avoided.\r\nDuring rainfall simulation, controlled quantities of water will be used to prevent sudden overflow. The prototype will be placed on a stable, level surface, and a designated collection area will be provided for discharged water. Any spilled water will be removed immediately to prevent slipping and protect electrical equipment.\r\nSolid waste such as leaves and plastic, along with collected sediment, will be handled carefully using separate collection chambers. Appropriate precautions will be followed during their removal and disposal.\r\nBefore every experimental trial, the drainage pathway, sensors, wiring, collection chambers, and mechanical components will be checked. Testing will be conducted in a controlled environment under continuous supervision to ensure the safe operation and reliable evaluation of DRAIN-X throughout all stages of testing.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-09-30T18:44:00.614Z", "updatedAt": "2026-10-14T18:48:16.264Z", "abstract": { "originalName": "ABSTRACT.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1790793839/aura-registrations/abstract-docs/ABSTRACT", "filename": "Abstract.docx", "relPath": "assets/Teams/GEONEX/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "Title:\n\nIoT-Based Dynamic Health Monitoring and Distress Prediction System for Victims of Atrocities\n\nMethodology:\n\nThe proposed system integrates Internet of things (IoT) - based physiological monitoring, standardized psychological questionnaires, and an Android application for preliminary distress screening among victims of atrocities.\n\nHardware Development: A microcontroller is interfaced with a heart rate sensor, body temperature sensor, and Galvanic Skin Response (GSR) sensor to collect physiological parameters. An HC-05 Bluetooth module enables wireless communication between the hardware and the Android application.\n\nData Acquisition and Transmission: The microcontroller collects sensor measurements and transmits the data to the Android application, where the physiological parameters are displayed for real-time or periodic monitoring.\n\nAndroid Application Development: The application incorporates two standardized questionnaires: the Patient Health Questionnaire-9 (PHQ-9) for assessing depressive symptoms and the WHO-5 Well-Being Index for evaluating psychological well-being. Users respond to the questionnaire items through the mobile interface.\n\nScoring and Assessment: The application calculates questionnaire scores according to the respective scoring guidelines. Physiological measurements are evaluated alongside questionnaire results using a predefined assessment framework to support preliminary distress screening.\n\nRisk Classification and Recommendations: Based on the defined assessment criteria, the system categorizes screening results into low, borderline, moderate, and high-concern levels. Appropriate guidance is displayed, including self-care suggestions, recommendations for professional consultation, and relevant mental health service contact information.\n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring SystemFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring SystemBlock Diagram: \n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring System\n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring System\n\nProposed Outcome:\n\nThe proposed system is expected to provide a functional IoT-based platform for physiological health monitoring and preliminary psychological distress screening among victims of atrocities. This system will enable the collection and visualization of physiological data alongside standardized psychological assessments using the PHQ-9 and WHO-5 questionnaires. The application will evaluate questionnaire scores and relevant physiological measurements using a predefined assessment framework to identify potential levels of distress and generate appropriate recommendations. Depending on the screening results, the system will provide guidance ranging from general well-being suggestions to recommendations for professional mental health consultation and referral. The proposed platform aims to improve accessibility to preliminary screening and facilitate timely identification of individuals who may require further psychological assessment. In future development, artificial intelligence and machine learning techniques may be incorporated to identify patterns in physiological and questionnaire data and improve screening performance." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/GEONEX/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790793839/aura-registrations/id-cards/kfxbxzz57ab7rwswf0ak.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/GEONEX/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790793839/aura-registrations/id-cards/w8jq27zozlqc7svmaekq.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/GEONEX/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790793839/aura-registrations/id-cards/qr6mz6lgisoi4ytwsyr5.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/GEONEX/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790793839/aura-registrations/id-cards/nhymtxgugwed9hceicrj.jpg", "exists": true }] }, { "index": 25, "id": "6abe01c1ed528cc7a12871d9", "registrationId": "AURA2K26-5FF8P8", "rawTeamName": "Team Boltz", "folderName": "Team Boltz", "folderRelPath": "assets/Teams/Team Boltz", "projectTitle": "WASTE HEAT TO ELECTRICAL ENERGY CONVERSION USING THERMOELECTRIC GENERATOR", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Mir Farid Ahmad", "teamLeaderEmail": "mir.ee.au25@gmail.com", "teamLeaderPhone": "9907698930", "teamMemberDetails": "1. Megha Ahmed | Aliah University | Electronics And Communication Engineering | 4th Year | 9330436360\r\n2. Zeba Ahmed | Aliah University | Electronics And Communication Engineering | 3rd Year | 7980218400\r\n3. Minhaz Ul Islam | Aliah University | Electronics And Communication Engineering | 3rd Year | 9641699500", "hardwareProjectCategories": ["IoT & Smart Devices", "Renewable Energy / Clean Technology"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement: A large amount of energy is lost as waste heat from vehicle exhausts, industrial machinery, generators, and cooking systems. This heat is rarely recovered, which wastes energy, raises costs, and harms the environment. Remote sensors and off-grid areas also lack simple, maintenance-free power sources.\r\nSolution: A thermoelectric generator (TEG) is placed between hot surface and cooled heatsink. The temperature difference produces a low DC voltage through the Seebeck effect. An MT3608 boost converter raises it, and an LM7805 regulates it to 5 V to power a load and charge a Li-ion battery through a TP4056 module.\r\nInnovation: The design combines heat recovery with smart power management. Sensors (DS18B20, INA219) and an Arduino/ESP32 display temperature, ΔT, voltage, current, power, and efficiency in real time on an LCD. It is compact, has no moving parts in the generator, needs little maintenance, and works wherever a temperature gradient exists.", "solutionDescription": "Problem Statement: A large amount of energy is lost as waste heat from vehicle exhausts, industrial machinery, generators, and cooking systems. This heat is rarely recovered, which wastes energy, raises costs, and harms the environment. Remote sensors and off-grid areas also lack simple, maintenance-free power sources.\r\nSolution: A thermoelectric generator (TEG) is placed between hot surface and cooled heatsink. The temperature difference produces a low DC voltage through the Seebeck effect. An MT3608 boost converter raises it, and an LM7805 regulates it to 5 V to power a load and charge a Li-ion battery through a TP4056 module.\r\nInnovation: The design combines heat recovery with smart power management. Sensors (DS18B20, INA219) and an Arduino/ESP32 display temperature, ΔT, voltage, current, power, and efficiency in real time on an LCD. It is compact, has no moving parts in the generator, needs little maintenance, and works wherever a temperature gradient exists.", "innovationDescription": "Problem Statement: A large amount of energy is lost as waste heat from vehicle exhausts, industrial machinery, generators, and cooking systems. This heat is rarely recovered, which wastes energy, raises costs, and harms the environment. Remote sensors and off-grid areas also lack simple, maintenance-free power sources.\r\nSolution: A thermoelectric generator (TEG) is placed between hot surface and cooled heatsink. The temperature difference produces a low DC voltage through the Seebeck effect. An MT3608 boost converter raises it, and an LM7805 regulates it to 5 V to power a load and charge a Li-ion battery through a TP4056 module.\r\nInnovation: The design combines heat recovery with smart power management. Sensors (DS18B20, INA219) and an Arduino/ESP32 display temperature, ΔT, voltage, current, power, and efficiency in real time on an LCD. It is compact, has no moving parts in the generator, needs little maintenance, and works wherever a temperature gradient exists.", "workingPrinciple": "A thermoelectric generator (TEG) sits between a hot plate and a cooled heatsink. The temperature difference (∆T) produces a DC voltage via the Seebeck effect (V ≈ S × ∆T). A boost converter raises this low voltage, a regulator stabilizes it to 5V, and it powers a load or charges a battery.", "majorHardwareComponents": ["TEG module", "Esp-32", "Heatsink and fan", "Boost converter", "Voltage Regulator", "Charging Module", "Temperature sensors", "Current sensor", "LCD display", "DC load"], "useAi": false, "useIot": true, "powerSource": "other", "intendedBeneficiaries": ["General Public", "Industry", "Transportation"], "potentialImpact": "This project could make waste heat a useful energy source. Recovering even a small fraction of heat lost from vehicle exhausts, industrial machinery, generators, and stoves would improve overall energy efficiency and reduce fuel consumption and carbon emissions. Because TEGs have no moving parts and need little maintenance, they can power remote sensors, IoT devices, and industrial monitoring systems without frequent battery replacement. In off-grid and rural areas, the same approach could provide basic electricity for lighting or phone charging from cooking fires. At scale, it supports sustainable energy recovery, lowers operating costs, and encourages cleaner, more resource-efficient technology across many sectors.", "productPotential": "potentially", "prototypeDevelopmentCost": 2800, "auraDemoHighlight": "This project is worth seeing because it turns energy that's normally thrown away into usable electricity, with no moving parts and almost no maintenance. It combines several skills in one build: thermoelectrics, power electronics (boost converter, regulator, battery charging), and sensor-based monitoring with a live LCD display of temperature, voltage, current, and power.It's also practical. The same idea applies to car exhausts, industrial machines, stoves, and remote IoT sensors, including off-grid areas. You can watch heat become electricity in real time, making it a clear, hands-on demonstration of sustainable energy recovery.", "safetyHazards": ["none"], "safetyPrecautions": "Keep the heatsink and fan running, since overheating can damage the TEG, and check its maximum rated temperature. Use a protected TP4056 module for the Li-ion battery, and never short it or charge it unattended. Verify polarity and connections before powering on, and insulate all exposed wires. Finally, place the setup on a stable, non-flammable surface with good ventilation, and keep a fire extinguisher nearby.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-01T06:46:25.123Z", "updatedAt": "2026-10-14T18:48:21.805Z", "abstract": { "originalName": "Team-Boltz Project.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790837184/aura-registrations/abstract-docs/Team-Boltz%20Project.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Team Boltz/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Team Boltz/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790837183/aura-registrations/id-cards/xso2b3f6lb1yvltghrne.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Team Boltz/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790837183/aura-registrations/id-cards/splu7avfplkvzpqdvjhy.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Team Boltz/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790837183/aura-registrations/id-cards/gygqyqqwedapjveclrym.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Team Boltz/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790837183/aura-registrations/id-cards/cvnzjetkzf8ndmtieler.png", "exists": true }] }, { "index": 26, "id": "6abe692761a4b5868457515d", "registrationId": "AURA2K26-M3GTU5", "rawTeamName": "AeroX", "folderName": "AeroX", "folderRelPath": "assets/Teams/AeroX", "projectTitle": "Fertilizer-Spraying Drone", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Shershah", "teamLeaderEmail": "shershah78600@gmail.com", "teamLeaderPhone": "9546872911", "teamMemberDetails": "SANIA PARVEEN \\ ALIAH UNIVERSITY \\ EEN \\ 2ND YEAR \\ 7584091556\r\nSUBHRODEEP PAL \\ ALIAH UNIVERSITY \\ ECE \\ 2ND YEAR \\ 8478989369\r\nESHAL EHSAN  \\ ALIAH UNIVERSITY \\ ECE \\ 2ND YEAR \\ 8981327584", "hardwareProjectCategories": ["Drone / Autonomous Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "no_prototype", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Statement\r\n\r\nManual fertilizer application exposes farmers to hazardous chemicals and often causes uneven and excessive distribution, leading to health risks, fertilizer wastage, and increased costs. Although commercial agricultural spraying drones address these issues, their high cost and dependence on specialized remote controllers and pilot training make them difficult for small-scale farmers to adopt.\r\n\r\nProposed Solution\r\n\r\nWe propose a  low-cost, IoT-enabled smart spraying payload that can be retrofitted onto standard drone frames. Instead of depending on an expensive flight controller, our system operates as an independent spraying module. An ESP32 microcontroller creates a localized Wi-Fi network, allowing the operator to control the spraying mechanism through an intuitive smartphone interface. This enables convenient and safer control of fertilizer application during flight.\r\n\r\n Innovation & Technical Details\r\n\r\nThe system replaces complex proprietary controllers with a smartphone-based interface, reducing the learning curve for operators. From an ECE perspective, the project applies C programming, PWM, embedded systems, and wireless communication. A smartphone slider controls PWM output from the ESP32, dynamically regulating the speed of a 5V DC pump and enabling variable-rate fertilizer application according to crop requirements.\r\n\r\nThe modular hardware architecture separates the spraying mechanism from the drone's flight system, reducing cost and allowing the same payload to be adapted to drones or ground-based agricultural rovers. The Wi-Fi-enabled ESP32 framework also provides a scalable foundation for future integration of soil-moisture, crop-density, and environmental sensors, enabling automated and data-driven precision agriculture.", "solutionDescription": "Problem Statement\r\n\r\nManual fertilizer application exposes farmers to hazardous chemicals and often causes uneven and excessive distribution, leading to health risks, fertilizer wastage, and increased costs. Although commercial agricultural spraying drones address these issues, their high cost and dependence on specialized remote controllers and pilot training make them difficult for small-scale farmers to adopt.\r\n\r\nProposed Solution\r\n\r\nWe propose a  low-cost, IoT-enabled smart spraying payload that can be retrofitted onto standard drone frames. Instead of depending on an expensive flight controller, our system operates as an independent spraying module. An ESP32 microcontroller creates a localized Wi-Fi network, allowing the operator to control the spraying mechanism through an intuitive smartphone interface. This enables convenient and safer control of fertilizer application during flight.\r\n\r\n Innovation & Technical Details\r\n\r\nThe system replaces complex proprietary controllers with a smartphone-based interface, reducing the learning curve for operators. From an ECE perspective, the project applies C programming, PWM, embedded systems, and wireless communication. A smartphone slider controls PWM output from the ESP32, dynamically regulating the speed of a 5V DC pump and enabling variable-rate fertilizer application according to crop requirements.\r\n\r\nThe modular hardware architecture separates the spraying mechanism from the drone's flight system, reducing cost and allowing the same payload to be adapted to drones or ground-based agricultural rovers. The Wi-Fi-enabled ESP32 framework also provides a scalable foundation for future integration of soil-moisture, crop-density, and environmental sensors, enabling automated and data-driven precision agriculture.", "innovationDescription": "Problem Statement\r\n\r\nManual fertilizer application exposes farmers to hazardous chemicals and often causes uneven and excessive distribution, leading to health risks, fertilizer wastage, and increased costs. Although commercial agricultural spraying drones address these issues, their high cost and dependence on specialized remote controllers and pilot training make them difficult for small-scale farmers to adopt.\r\n\r\nProposed Solution\r\n\r\nWe propose a  low-cost, IoT-enabled smart spraying payload that can be retrofitted onto standard drone frames. Instead of depending on an expensive flight controller, our system operates as an independent spraying module. An ESP32 microcontroller creates a localized Wi-Fi network, allowing the operator to control the spraying mechanism through an intuitive smartphone interface. This enables convenient and safer control of fertilizer application during flight.\r\n\r\n Innovation & Technical Details\r\n\r\nThe system replaces complex proprietary controllers with a smartphone-based interface, reducing the learning curve for operators. From an ECE perspective, the project applies C programming, PWM, embedded systems, and wireless communication. A smartphone slider controls PWM output from the ESP32, dynamically regulating the speed of a 5V DC pump and enabling variable-rate fertilizer application according to crop requirements.\r\n\r\nThe modular hardware architecture separates the spraying mechanism from the drone's flight system, reducing cost and allowing the same payload to be adapted to drones or ground-based agricultural rovers. The Wi-Fi-enabled ESP32 framework also provides a scalable foundation for future integration of soil-moisture, crop-density, and environmental sensors, enabling automated and data-driven precision agriculture.", "workingPrinciple": "The system operates on an IoT-based master-slave architecture, completely decoupling the spraying payload from the drone’s main flight controller. The workflow follows three distinct stages: Communication, Processing, and Actuation.\r\n\r\n1. Communication & Interface\r\nThe workflow begins on a smartphone application serving as the operator interface. The app connects to an ESP32 microcontroller via a localized Wi-Fi hotspot, transmitting user commands—such as spray activation and flow rate intensity—as continuous wireless data packets.\r\n\r\n2. Processing & Control Logic\r\nThe ESP32 acts as the core processing unit, executing embedded C programming control flow logic. Upon receiving a data packet, the microcontroller interprets the command. For variable rate spraying, the C code generates a Pulse Width Modulation (PWM) signal. The operator’s slider input on the app dynamically adjusts the PWM duty cycle, enabling precise software-based control over the output rather than a simple binary on/off state.\r\n\r\n3. Actuation & Fluid Delivery\r\nBecause the ESP32’s 3.3V logic pins cannot safely drive high-current hardware, the PWM signal is routed to a motor driver circuit (or a relay module for basic switching). This driver regulates power from an isolated battery pack to a 5V/12V DC machine (the water pump). By altering the DC pump's motor speed via PWM, the system precisely dictates the volume of liquid pushed through the tubing and out the misting nozzle, achieving dynamic, targeted agricultural spraying.", "majorHardwareComponents": ["Microcontroller: ESP32 or NodeMCU (ESP8266)\n\nMotor Control: L298N Motor Driver or Relay Module\n\nPump: 5V or 12V DC Mini Water Pump\n\nPower Source: LiPo Battery or 5V Power Bank\n\nPlumbing: Fluid Reservoir (Tank)", "Silicone Tubing", "and Misting Nozzle\n\nStructure: Mounting Chassis or Dummy Drone Frame"], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Agriculture"], "potentialImpact": "Primary Beneficiaries\r\nSmall-to-medium scale farmers and agricultural workers are the primary beneficiaries. Currently, these groups rely on hazardous manual labor or cannot afford expensive third-party drone services. By making precision technology modular, local farming cooperatives and agricultural entrepreneurs also benefit, allowing them to deploy low-cost spraying operations without requiring specialized RC pilot training.\r\n\r\nImproving Current Standards\r\nThis system disrupts existing agricultural standards in three critical ways:\r\n\r\nHealth and Safety: It replaces the current standard of manual backpack spraying. By controlling the payload remotely via Wi-Fi, it physically removes farmers from the hazardous mist of toxic chemicals, preventing severe respiratory and dermatological diseases.\r\n\r\nCost and Accessibility: Commercial spraying drones are prohibitively expensive and tightly integrate payload control with proprietary flight controllers. Our IoT payload improves this standard by decoupling the hardware. It easily retrofits onto cheap, generic frames and shifts control to a familiar smartphone app, drastically lowering both the financial barrier and the operational learning curve.\r\n\r\nResource Efficiency: Manual application leads to uneven chemical distribution. By utilizing Pulse Width Modulation (PWM) via the microcontroller, our system introduces Variable Rate Application (VRA) to budget-friendly setups. Operators can dynamically adjust the DC pump's speed mid-flight, ensuring exact fluid distribution. This prevents expensive fertilizer waste, minimizes environmental runoff, and improves overall crop yields compared to traditional blanket spraying.", "productPotential": "yes", "prototypeDevelopmentCost": 8000, "auraDemoHighlight": "Judges should pay attention to this project because it democratizes precision agriculture for small-scale farmers through an ultra-low-cost, IoT-driven architecture.\r\n\r\nThe most impressive aspect of our prototype is its decoupled, modular payload system paired with extreme cost efficiency. Commercial spraying drones cost lakhs of rupees and lock their mechanisms behind complex, proprietary flight controllers that require specialized pilot training. We shatter this barrier.\r\n\r\nBy isolating the spraying mechanism into an independent IoT module using an ESP32 microcontroller, we bypass the main flight controller entirely. This allows our smart payload to be retrofitted onto a basic, custom-built drone for a total system cost of just ₹8,000—a fraction of commercial prices.\r\n\r\nFurthermore, we replaced the steep learning curve of an RC transmitter with a familiar smartphone interface. Using fundamental C programming and Pulse Width Modulation (PWM) over a localized Wi-Fi network, operators can dynamically adjust the DC pump's motor speed mid-flight via a simple app slider. This achieves true Variable Rate Application (VRA)—applying precise fertilizer volumes based on crop density, minimizing toxic chemical exposure, and preventing expensive fertilizer waste.\r\n\r\nUltimately, we took a highly exclusive technology and distilled it into an accessible ECE framework. Delivering a complete, smartphone-controlled precision spraying drone for just ₹8,000 proves that advanced agricultural automation can be affordable, highly modular, and directly scalable for the farmers who need it most.", "safetyHazards": ["drone_flying_equipment"], "safetyPrecautions": "To ensure operational reliability and user safety, our prototype incorporates three layers of hardware and software safeguards:\r\n\r\n1. Electrical Isolation & Circuit Protection\r\nThe ESP32’s delicate 3.3V logic pins are physically isolated from the high-current DC pump. By utilizing an L298N motor driver or an opto-isolated relay, we protect the microcontroller from dangerous voltage spikes and back-EMF generated by the pump motor. We also use separated power domains—driving the microcontroller logic independently from the heavy-load DC motors—which prevents sudden voltage drops from causing unwanted system resets mid-flight.\r\n\r\n2. Software Fail-Safes (Signal Loss Protocol)\r\nBecause agricultural fields often lack internet, our ESP32 hosts its own localized Wi-Fi hotspot. Crucially, the C control logic includes a continuous heartbeat check. If the Wi-Fi connection between the smartphone and the ESP32 drops or lags, the code automatically sets the PWM duty cycle to zero. This immediately shuts off the pump, preventing accidental chemical dumping or motor burnout if the drone flies out of range.\r\n\r\n3. Operator Health Safeguards\r\nThe primary hazard in agriculture is toxic chemical exposure. By shifting control to a smartphone with a 50-100 meter Wi-Fi range, the system fundamentally acts as a physical safeguard. It completely removes the farmer from the chemical drift zone, eliminating the respiratory and dermatological risks associated with traditional manual backpack sprayers.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-01T14:07:35.994Z", "updatedAt": "2026-10-14T18:48:29.267Z", "abstract": { "originalName": "aerox Methodology.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790863655/aura-registrations/abstract-docs/aerox%20Methodology.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/AeroX/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/AeroX/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790863655/aura-registrations/id-cards/if9eruxn0vf9z3lyzrmz.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/AeroX/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790863655/aura-registrations/id-cards/flttm6lqqajgfrzpu2sl.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/AeroX/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790863655/aura-registrations/id-cards/mdbhqvzx91kodcpqdrfj.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/AeroX/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790863655/aura-registrations/id-cards/diyjlyt4mq3pkkt3pelj.jpg", "exists": true }] }, { "index": 27, "id": "6abe8e37a6daff02386ec5be", "registrationId": "AURA2K26-D2EWRE", "rawTeamName": "VoltVision", "folderName": "VoltVision", "folderRelPath": "assets/Teams/VoltVision", "projectTitle": "IoT-Enabled Distribution Transformer Health Monitoring and Online IEEE C57.91 Thermal Insulation Degradation Estimation System", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "ARIJ HUSSAIN", "teamLeaderEmail": "arijhussain8@gmail.com", "teamLeaderPhone": "7364829329", "teamMemberDetails": "SOUVICK HALDER | ALIAH UNIVERSITY | ELECTRICAL ENGINEERING | 3RD YEAR | 8145447548\r\nTAOSIF AHASAN | ALIAH UNIVERSITY | ELECTRICAL ENGINEERING | 3RD YEAR | 7811087200\r\nENAMUL HAQUE | ALIAH UNIVERSITY | ELECTRICAL ENGINEERING | 3RD YEAR | 9430880942", "hardwareProjectCategories": ["IoT & Smart Devices", "Electrical Systems", "Safety & Security Systems", "Electronics & Communication", "Embedded Systems"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Statement\r\n\r\nDistribution transformers are critical components of electrical distribution networks and operate continuously under varying electrical and thermal stresses. Conventional transformer protection systems primarily respond to immediate faults such as overcurrent, short circuits, and excessive temperature. However, they generally do not provide continuous estimation of \"long-term thermal insulation degradation\" or the remaining useful life of the transformer.\r\n\r\nLow-cost IoT monitoring systems can measure parameters such as voltage, current, and temperature, but many systems simply transmit sensor readings or generate basic threshold-based alarms. They lack the ability to correlate multiple operating parameters, identify the probable cause of abnormal conditions, and quantify the cumulative effect of thermal stress on transformer insulation. This creates a gap between simple monitoring and predictive transformer health assessment.\r\n\r\n Proposed Solution\r\n\r\nThe proposed system is an \"IoT-Enabled Distribution Transformer Health Monitoring and Online IEEE C57.91 Thermal Insulation Degradation Estimation System\" designed as a low-cost prototype using a 12 V test transformer and an ESP32 microcontroller.\r\n\r\nThe system continuously measures \"AC voltage, load current, top-oil temperature, and oil-level condition\" using appropriate sensors. The ESP32 processes these measurements locally and calculates the transformer hot-spot temperature using an IEEE C57.91-based thermal model. From the estimated hot-spot temperature, the \"Aging Acceleration Factor (FAA)\" is calculated to estimate cumulative thermal aging, dynamic Loss of Life (LOL), and Remaining Useful Life (RUL).\r\n\r\nThe processed parameters are displayed locally on a 16×2 LCD and transmitted to the \"Blynk IoT platform\" for remote monitoring. A cooling fan and buzzer are automatically controlled when predefined abnormal conditions are detected.\r\n\r\nInnovation Details\r\n\r\nThe key innovation is the combination of 'IoT monitoring, edge-based anomaly classification, and online thermal aging estimation' in a single low-cost system.\r\n\r\nInstead of only reporting sensor values, the system analyzes combinations of electrical and thermal parameters to distinguish between:\r\n\r\n- Severe Overload: High current + high temperature\r\n- Downstream Fault/Spike: High current + normal temperature\r\n- Cooling System Failure: Normal current + high temperature\r\n- Oil Hazard: Abnormal oil-level condition\r\n\r\nFurthermore, the system converts real-time thermal stress into a quantitative \"insulation aging indicator using the IEEE C57.91 methodology\", providing an early indication of cumulative transformer degradation rather than responding only after a major failure occurs.\r\n\r\nThe proposed prototype therefore demonstrates how an affordable ESP32-based platform can combine \"condition monitoring, predictive thermal assessment, automated protection, and IoT-based visualization\" for smarter transformer maintenance.", "solutionDescription": "Problem Statement\r\n\r\nDistribution transformers are critical components of electrical distribution networks and operate continuously under varying electrical and thermal stresses. Conventional transformer protection systems primarily respond to immediate faults such as overcurrent, short circuits, and excessive temperature. However, they generally do not provide continuous estimation of \"long-term thermal insulation degradation\" or the remaining useful life of the transformer.\r\n\r\nLow-cost IoT monitoring systems can measure parameters such as voltage, current, and temperature, but many systems simply transmit sensor readings or generate basic threshold-based alarms. They lack the ability to correlate multiple operating parameters, identify the probable cause of abnormal conditions, and quantify the cumulative effect of thermal stress on transformer insulation. This creates a gap between simple monitoring and predictive transformer health assessment.\r\n\r\n Proposed Solution\r\n\r\nThe proposed system is an \"IoT-Enabled Distribution Transformer Health Monitoring and Online IEEE C57.91 Thermal Insulation Degradation Estimation System\" designed as a low-cost prototype using a 12 V test transformer and an ESP32 microcontroller.\r\n\r\nThe system continuously measures \"AC voltage, load current, top-oil temperature, and oil-level condition\" using appropriate sensors. The ESP32 processes these measurements locally and calculates the transformer hot-spot temperature using an IEEE C57.91-based thermal model. From the estimated hot-spot temperature, the \"Aging Acceleration Factor (FAA)\" is calculated to estimate cumulative thermal aging, dynamic Loss of Life (LOL), and Remaining Useful Life (RUL).\r\n\r\nThe processed parameters are displayed locally on a 16×2 LCD and transmitted to the \"Blynk IoT platform\" for remote monitoring. A cooling fan and buzzer are automatically controlled when predefined abnormal conditions are detected.\r\n\r\nInnovation Details\r\n\r\nThe key innovation is the combination of 'IoT monitoring, edge-based anomaly classification, and online thermal aging estimation' in a single low-cost system.\r\n\r\nInstead of only reporting sensor values, the system analyzes combinations of electrical and thermal parameters to distinguish between:\r\n\r\n- Severe Overload: High current + high temperature\r\n- Downstream Fault/Spike: High current + normal temperature\r\n- Cooling System Failure: Normal current + high temperature\r\n- Oil Hazard: Abnormal oil-level condition\r\n\r\nFurthermore, the system converts real-time thermal stress into a quantitative \"insulation aging indicator using the IEEE C57.91 methodology\", providing an early indication of cumulative transformer degradation rather than responding only after a major failure occurs.\r\n\r\nThe proposed prototype therefore demonstrates how an affordable ESP32-based platform can combine \"condition monitoring, predictive thermal assessment, automated protection, and IoT-based visualization\" for smarter transformer maintenance.", "innovationDescription": "Problem Statement\r\n\r\nDistribution transformers are critical components of electrical distribution networks and operate continuously under varying electrical and thermal stresses. Conventional transformer protection systems primarily respond to immediate faults such as overcurrent, short circuits, and excessive temperature. However, they generally do not provide continuous estimation of \"long-term thermal insulation degradation\" or the remaining useful life of the transformer.\r\n\r\nLow-cost IoT monitoring systems can measure parameters such as voltage, current, and temperature, but many systems simply transmit sensor readings or generate basic threshold-based alarms. They lack the ability to correlate multiple operating parameters, identify the probable cause of abnormal conditions, and quantify the cumulative effect of thermal stress on transformer insulation. This creates a gap between simple monitoring and predictive transformer health assessment.\r\n\r\n Proposed Solution\r\n\r\nThe proposed system is an \"IoT-Enabled Distribution Transformer Health Monitoring and Online IEEE C57.91 Thermal Insulation Degradation Estimation System\" designed as a low-cost prototype using a 12 V test transformer and an ESP32 microcontroller.\r\n\r\nThe system continuously measures \"AC voltage, load current, top-oil temperature, and oil-level condition\" using appropriate sensors. The ESP32 processes these measurements locally and calculates the transformer hot-spot temperature using an IEEE C57.91-based thermal model. From the estimated hot-spot temperature, the \"Aging Acceleration Factor (FAA)\" is calculated to estimate cumulative thermal aging, dynamic Loss of Life (LOL), and Remaining Useful Life (RUL).\r\n\r\nThe processed parameters are displayed locally on a 16×2 LCD and transmitted to the \"Blynk IoT platform\" for remote monitoring. A cooling fan and buzzer are automatically controlled when predefined abnormal conditions are detected.\r\n\r\nInnovation Details\r\n\r\nThe key innovation is the combination of 'IoT monitoring, edge-based anomaly classification, and online thermal aging estimation' in a single low-cost system.\r\n\r\nInstead of only reporting sensor values, the system analyzes combinations of electrical and thermal parameters to distinguish between:\r\n\r\n- Severe Overload: High current + high temperature\r\n- Downstream Fault/Spike: High current + normal temperature\r\n- Cooling System Failure: Normal current + high temperature\r\n- Oil Hazard: Abnormal oil-level condition\r\n\r\nFurthermore, the system converts real-time thermal stress into a quantitative \"insulation aging indicator using the IEEE C57.91 methodology\", providing an early indication of cumulative transformer degradation rather than responding only after a major failure occurs.\r\n\r\nThe proposed prototype therefore demonstrates how an affordable ESP32-based platform can combine \"condition monitoring, predictive thermal assessment, automated protection, and IoT-based visualization\" for smarter transformer maintenance.", "workingPrinciple": "Working Principle\r\nThe proposed system works by continuously monitoring the electrical, thermal, and oil-level conditions of a distribution transformer and using the measured data to estimate its health and insulation aging.\r\nThe ZMPT101B voltage sensor measures the transformer’s AC voltage, while the ACS712 current sensor measures the load current. The DS18B20 temperature sensor measures the top-oil temperature, and the HC-SR04 ultrasonic sensor monitors the oil-level condition. All sensor outputs are processed by the ESP32 microcontroller.\r\n\r\n\r\nThe calculated hot-spot temperature is then used to determine the Aging Acceleration Factor (FAA). By continuously accumulating the aging effect, the system estimates the transformer’s Loss of Life (LOL) and Remaining Useful Life (RUL).\r\nThe ESP32 also performs edge-based anomaly classification by correlating current, temperature, and oil-level measurements. It can identify conditions such as severe overload, downstream current spikes, cooling-system failure, and low-oil hazards.\r\nWhen abnormal conditions occur, the system can activate a cooling fan through the relay and generate an alarm using the buzzer. The measured and calculated parameters are displayed on the 16×2 LCD and transmitted to the Blynk IoT platform for remote monitoring.\r\nThus, the system follows:\r\nSensing → Data Processing → Thermal Estimation → Aging Calculation → Fault Diagnosis → Protection → IoT Monitoring.", "majorHardwareComponents": ["ESP32 Dev Board  \n12 V Test/Distribution Transformer  \nZMPT101B AC Voltage Sensor  \nACS712 5A Current Sensor  \nDS18B20 Waterproof Temperature Sensor  \nHC-SR04 Ultrasonic Sensor  \n16×2 I2C LCD Display  \n5 V Relay Module  \nDC Cooling Fan  \nPiezo Buzzer  \n4.7 kΩ Resistor  \n1 kΩ Resistor  \n2 kΩ Resistor  \nBreadboard/PCB  \nJumper Wires  \nDC Power Supply / Adapter"], "useAi": false, "useIot": true, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["Industry", "Government / Public Services", "Rural Communities"], "potentialImpact": "The proposed system can improve distribution transformer monitoring, maintenance, and reliability by moving from conventional reactive protection toward condition-based and predictive monitoring.\r\nIn practical distribution networks, transformers operate continuously under varying loads and temperatures. The proposed system continuously monitors voltage, current, temperature, and oil-level conditions, allowing abnormal operating conditions to be detected at an early stage. By applying an IEEE C57.91-based thermal aging model, the system can also estimate the effect of thermal stress on transformer insulation life, providing information beyond simple threshold-based alarms.\r\nThe edge-based diagnostic system can help distinguish between different abnormal conditions, such as severe overload, abnormal current spikes, cooling-system failure, and low-oil conditions. This can help maintenance personnel understand the possible cause of an abnormal condition and take appropriate action before serious damage occurs.\r\nThe IoT functionality allows transformer parameters and health indicators to be monitored remotely through a Blynk-based dashboard, reducing the need for continuous physical inspection. Automatic cooling and alarm functions can provide an additional layer of protection during abnormal conditions.\r\nBecause the prototype uses low-cost sensors and an ESP32, the concept can potentially be adapted for affordable monitoring of small distribution transformers, rural substations, educational laboratories, and other low-voltage transformer applications.\r\nOverall, the project demonstrates a pathway toward low-cost, data-driven transformer condition monitoring, potentially helping reduce unexpected failures, improve maintenance planning, and increase transformer operational reliability.", "productPotential": "potentially", "prototypeDevelopmentCost": 1500, "auraDemoHighlight": "This project is worth seeing because it shows how a simple, low-cost setup can be used to monitor the health of a transformer in a smarter way. Instead of only showing voltage, current, or temperature, the system also tries to understand what those values mean for the transformer.\r\n- Real-time monitoring: Voltage, current, temperature, and oil level are continuously monitored.\r\n- Early warning: The system can identify abnormal conditions before they develop into serious problems.\r\n- Transformer aging estimation: It uses the IEEE C57.91 thermal model to estimate hot-spot temperature and the effect of heat on insulation aging.\r\n- Loss of Life and RUL: The system estimates how much useful life has been consumed and the remaining useful life of the transformer.\r\n- Different fault conditions: It can distinguish between conditions such as overload, sudden current increase, cooling failure, and low oil level.\r\n- Automatic action: A cooling fan can be switched on automatically when the temperature rises, while a buzzer provides an alarm during critical conditions.\r\n- IoT-based monitoring: Important readings and transformer health information can be viewed remotely through the Blynk dashboard.\r\n- Low-cost prototype: The project is designed using easily available components and costs around ₹1,500, making it affordable for an academic prototype", "safetyHazards": ["none"], "safetyPrecautions": "The project uses a 12 V test transformer instead of directly experimenting with high-voltage distribution equipment.\r\nThe ESP32 and its sensors are operated at their recommended voltage levels to prevent damage to the controller and other components.\r\nThe ZMPT101B and ACS712 are used to electrically isolate or safely measure the transformer voltage and current.\r\nA 1 kΩ/2 kΩ voltage divider is used on the HC-SR04 Echo line so that the voltage reaching the ESP32 GPIO remains within a safe range.\r\nA 4.7 kΩ pull-up resistor is provided for reliable operation of the DS18B20 temperature sensor.\r\nAll connections are checked carefully before switching on the power supply to avoid short circuits or incorrect connections.\r\nExposed wires and terminals are properly insulated to reduce the risk of accidental contact.\r\nThe relay and cooling fan are operated within their rated voltage and current limits.\r\nThe transformer is not operated continuously under excessive load, and abnormal temperature rise is avoided during testing.\r\nThe prototype is kept on a dry and stable surface, away from water and conductive materials.\r\nPower is disconnected before changing wiring, replacing components, or troubleshooting the circuit.\r\nA suitable fuse/current-limiting protection should be used in the transformer supply during practical testing.\r\nThe system's automatic fan and buzzer functions provide an additional warning when abnormal operating conditions are detected.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-01T16:45:43.903Z", "updatedAt": "2026-10-14T18:48:34.951Z", "abstract": { "originalName": "Aura Project.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790873143/aura-registrations/abstract-docs/Aura%20Project.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/VoltVision/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/VoltVision/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790873142/aura-registrations/id-cards/va9t8bnewqkqgbk5k75f.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/VoltVision/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790873142/aura-registrations/id-cards/xjimwqflscw6ipqncmn7.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/VoltVision/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790873142/aura-registrations/id-cards/qibkokbo6ikugzf9ja1p.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/VoltVision/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1790873143/aura-registrations/id-cards/uaaufz3xaxgcunixz9yg.jpg", "exists": true }] }, { "index": 28, "id": "6ac28d02566021388a34a564", "registrationId": "AURA2K26-HWCZCM", "rawTeamName": "ELECTRORANGERS", "folderName": "ELECTRORANGERS", "folderRelPath": "assets/Teams/ELECTRORANGERS", "projectTitle": "Protecting People's Lives from Electrocution Caused by Electrical Equipment on Waterlogged Streets", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Md Mazharul Haque", "teamLeaderEmail": "haquemazharul201@gmail.com", "teamLeaderPhone": "8420417023", "teamMemberDetails": "Md Gulam Sarwar, Animesh Nandy, Noor Saba", "hardwareProjectCategories": ["Electrical Systems", "IoT & Smart Devices"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "The Problem:\r\nDuring heavy monsoon rain, many city streets stay waterlogged for hours. Street lights, electrical poles, junction boxes and feeder pillars stand in or beside this water. If insulation fails or a live wire snaps and falls, electric current can leak into the water.\r\nThe danger is invisible. The water looks like any other puddle, there is no sound and no warning, and people only find out when they touch it or step in. Pedestrians, hand-rickshaw pullers, cyclists and two-wheeler riders are the most exposed. The electricity utility often learns about the fault only after someone has already been hurt.\r\n Our idea in one line:\r\n Place a low-cost sensing unit on every high-risk pole. It checks the water for electric leakage, warns people on the spot with a siren and flashing light, and instantly alerts the substation so the dangerous line can be switched off.\r\nProposed Outcome of the Project :\r\nLives saved On-the-spot warning and a quick power cut greatly reduce the chance of electric shock in flooded streets.\r\nLive wire detection Broken or fallen live wires and leaking equipment are detected automatically and located by pole ID.\r\nFaster response The utility gets alerts in seconds instead of waiting for public complaints, so repair crews reach faults sooner.\r\nSafe route information Alarm status helps people and traffic authorities avoid dangerous streets, reducing delays for bikes, hand rickshaws, scooters and pedestrians.\r\nLow cost and scalable Built from simple, low-cost parts, so every high-risk pole in a city can be covered.\r\nData for planning Alarm records show which areas are most flood-prone and fault-prone, helping maintenance planning.", "solutionDescription": "The Problem:\r\nDuring heavy monsoon rain, many city streets stay waterlogged for hours. Street lights, electrical poles, junction boxes and feeder pillars stand in or beside this water. If insulation fails or a live wire snaps and falls, electric current can leak into the water.\r\nThe danger is invisible. The water looks like any other puddle, there is no sound and no warning, and people only find out when they touch it or step in. Pedestrians, hand-rickshaw pullers, cyclists and two-wheeler riders are the most exposed. The electricity utility often learns about the fault only after someone has already been hurt.\r\n Our idea in one line:\r\n Place a low-cost sensing unit on every high-risk pole. It checks the water for electric leakage, warns people on the spot with a siren and flashing light, and instantly alerts the substation so the dangerous line can be switched off.\r\nProposed Outcome of the Project :\r\nLives saved On-the-spot warning and a quick power cut greatly reduce the chance of electric shock in flooded streets.\r\nLive wire detection Broken or fallen live wires and leaking equipment are detected automatically and located by pole ID.\r\nFaster response The utility gets alerts in seconds instead of waiting for public complaints, so repair crews reach faults sooner.\r\nSafe route information Alarm status helps people and traffic authorities avoid dangerous streets, reducing delays for bikes, hand rickshaws, scooters and pedestrians.\r\nLow cost and scalable Built from simple, low-cost parts, so every high-risk pole in a city can be covered.\r\nData for planning Alarm records show which areas are most flood-prone and fault-prone, helping maintenance planning.", "innovationDescription": "The Problem:\r\nDuring heavy monsoon rain, many city streets stay waterlogged for hours. Street lights, electrical poles, junction boxes and feeder pillars stand in or beside this water. If insulation fails or a live wire snaps and falls, electric current can leak into the water.\r\nThe danger is invisible. The water looks like any other puddle, there is no sound and no warning, and people only find out when they touch it or step in. Pedestrians, hand-rickshaw pullers, cyclists and two-wheeler riders are the most exposed. The electricity utility often learns about the fault only after someone has already been hurt.\r\n Our idea in one line:\r\n Place a low-cost sensing unit on every high-risk pole. It checks the water for electric leakage, warns people on the spot with a siren and flashing light, and instantly alerts the substation so the dangerous line can be switched off.\r\nProposed Outcome of the Project :\r\nLives saved On-the-spot warning and a quick power cut greatly reduce the chance of electric shock in flooded streets.\r\nLive wire detection Broken or fallen live wires and leaking equipment are detected automatically and located by pole ID.\r\nFaster response The utility gets alerts in seconds instead of waiting for public complaints, so repair crews reach faults sooner.\r\nSafe route information Alarm status helps people and traffic authorities avoid dangerous streets, reducing delays for bikes, hand rickshaws, scooters and pedestrians.\r\nLow cost and scalable Built from simple, low-cost parts, so every high-risk pole in a city can be covered.\r\nData for planning Alarm records show which areas are most flood-prone and fault-prone, helping maintenance planning.", "workingPrinciple": "Methodology:\r\nThe system works in seven stages, from detecting the hazard to cutting the power. Every stage is built from simple, low-cost hardware that can be assembled and tested as a student prototype.\r\n 1. Sense A stainless steel electrode measures the small voltage that appears in the water when current is leaking. A water-level (float) sensor confirms that the street is really waterlogged.\r\n2. Isolate and condition An optocoupler and op-amp circuit separates the sensor from the microcontroller and scales the tiny signal into a safe range. The electronics stay protected even if the water is live.\r\n3. Decide An ESP32 microcontroller raises the alarm only when two checks pass: water is present AND voltage is present.\r\n4. Warn locally A buzzer, a flashing LED and a STOP signal (toll-gate style barrier) switch on immediately, so people nearby are warned without waiting for any remote action.\r\n5. Travellers stopped Seeing the STOP signal, travellers will not pass through the electrified street, which keeps them out of danger.\r\n6. Communicate A GSM or LoRa module sends the pole ID, voltage reading, water level and time to the substation. A regular \"heartbeat\" message proves the unit is still working.\r\n7. Respond The substation dashboard shows the alarming pole on a map. After operator confirmation (or an automatic trip at a high threshold), a relay opens the breaker and cuts power to that feeder section, covering the whole affected area. A repair crew is sent to the location.", "majorHardwareComponents": ["ESP32", "OPTOCOUPLER", "BUZZER", "BATTERY", "FLOAT SENSOR", "GPS MODULE", "etc."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Urban Communities"], "potentialImpact": "Lives saved\r\nOn-the-spot warning and a quick power cut greatly reduce the chance of electric shock in flooded streets.\t\tLive wire detection\r\nBroken or fallen live wires and leaking equipment are detected automatically and located by pole ID.\r\n\t\t\r\nFaster response\r\nThe utility gets alerts in seconds instead of waiting for public complaints, so repair crews reach faults sooner.\t\tSafe route information\r\nAlarm status helps people and traffic authorities avoid dangerous streets, reducing delays for bikes, hand rickshaws, scooters and pedestrians.\r\n\t\t\r\nLow cost and scalable\r\nBuilt from simple, low-cost parts, so every high-risk pole in a city can be covered.\t\tData for planning\r\nAlarm records show which areas are most flood-prone and fault-prone, helping maintenance planning.", "productPotential": "yes", "prototypeDevelopmentCost": 3000, "auraDemoHighlight": "This project is based on real life problem electrocution death which occurs on September , 2025 in Kolkata.", "safetyHazards": ["none", "water_near_electrical_equipment"], "safetyPrecautions": "Battery is taken as a 12v source, with low Ah rating .", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-04T17:29:38.225Z", "updatedAt": "2026-10-14T18:48:41.666Z", "abstract": { "originalName": "ELECTRO RANGERS_AURA2026_Project_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791134976/aura-registrations/abstract-docs/ELECTRO%20RANGERS_AURA2026_Project_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/ELECTRORANGERS/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/ELECTRORANGERS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791134976/aura-registrations/id-cards/nedehqxyizlejs5vxiqx.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/ELECTRORANGERS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791134977/aura-registrations/id-cards/tafywpsdk2kweivqjvx8.png", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/ELECTRORANGERS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791134976/aura-registrations/id-cards/mrpydyekrb62hj5egmdk.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/ELECTRORANGERS/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791134977/aura-registrations/id-cards/ahtdnpd9suos1ucqj6s2.png", "exists": true }] }, { "index": 29, "id": "6ac3d34a44616724030e6942", "registrationId": "AURA2K26-N9K8P8", "rawTeamName": "MindZed", "folderName": "MindZed", "folderRelPath": "assets/Teams/MindZed", "projectTitle": "BioArc v2", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Md Noor Hasan Ansari", "teamLeaderEmail": "mdnoorhasan1720@gmail.com", "teamLeaderPhone": "9662925898", "teamMemberDetails": "Md Abdul Kadir Jillani | Aliah university | CSE | 4 | 9830509865\r\nMd Shahabuddin | Aliah University | CSE | 4 | 8910297699\r\nArsalan Ahmed | Aliah University | CEN | 1 | 9875584694", "hardwareProjectCategories": ["IoT & Smart Devices", "Automation & Control", "AI-Enabled Hardware", "Renewable Energy / Clean Technology", "Environmental Technology"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement\r\nRising atmospheric CO₂ emissions, increasing wastewater volumes, and the limitations of conventional green infrastructure create a need for compact, resource-efficient biological systems. Traditional approaches often require large land areas, continuous manual supervision, and separate systems for environmental treatment and resource recovery. At the same time, high-density microalgae cultivation is sensitive to changes in temperature, lighting, aeration, liquid level, and growth conditions, making stable operation difficult.\r\n\r\nSolution\r\nBioArc is a compact, automated microalgae photobioreactor designed to combine carbon capture, oxygen generation, wastewater nutrient utilization, and biomass recovery in a single system. Microalgae use CO₂ during photosynthesis while growing in a controlled reactor. The system is designed to use treated municipal wastewater as a nutrient-rich cultivation medium, helping recycle wastewater while supporting algal growth. The resulting biomass can be further utilized as a feedstock for products such as biofuels, biopolymers, fertilizers, and other bio-products.\r\n\r\nInnovation Details\r\nBioArc combines biological processing with autonomous hardware and intelligent software control. An ESP32-based edge controller integrates optical, temperature, environmental, and liquid-level sensing with automated pumps, valves, lighting, and agitation. A low-cost RGB sensor is used with our Green Excess Index (GEI) method to estimate algal biomass without relying on expensive laboratory optical instruments. The controller also uses an autonomous finite-state workflow to manage cultivation, monitoring, dosing, and harvesting.\r\n\r\nThe software layer adds real-time MQTT/WebSocket telemetry, remote monitoring, offline control, historical analytics, and an AI copilot capable of interacting with the reactor through controlled actuator commands. This makes BioArc more than an algae-growing device: it is a compact, intelligent biological resource-recovery system designed to turn environmental inputs into useful outputs.", "solutionDescription": "Problem Statement\r\nRising atmospheric CO₂ emissions, increasing wastewater volumes, and the limitations of conventional green infrastructure create a need for compact, resource-efficient biological systems. Traditional approaches often require large land areas, continuous manual supervision, and separate systems for environmental treatment and resource recovery. At the same time, high-density microalgae cultivation is sensitive to changes in temperature, lighting, aeration, liquid level, and growth conditions, making stable operation difficult.\r\n\r\nSolution\r\nBioArc is a compact, automated microalgae photobioreactor designed to combine carbon capture, oxygen generation, wastewater nutrient utilization, and biomass recovery in a single system. Microalgae use CO₂ during photosynthesis while growing in a controlled reactor. The system is designed to use treated municipal wastewater as a nutrient-rich cultivation medium, helping recycle wastewater while supporting algal growth. The resulting biomass can be further utilized as a feedstock for products such as biofuels, biopolymers, fertilizers, and other bio-products.\r\n\r\nInnovation Details\r\nBioArc combines biological processing with autonomous hardware and intelligent software control. An ESP32-based edge controller integrates optical, temperature, environmental, and liquid-level sensing with automated pumps, valves, lighting, and agitation. A low-cost RGB sensor is used with our Green Excess Index (GEI) method to estimate algal biomass without relying on expensive laboratory optical instruments. The controller also uses an autonomous finite-state workflow to manage cultivation, monitoring, dosing, and harvesting.\r\n\r\nThe software layer adds real-time MQTT/WebSocket telemetry, remote monitoring, offline control, historical analytics, and an AI copilot capable of interacting with the reactor through controlled actuator commands. This makes BioArc more than an algae-growing device: it is a compact, intelligent biological resource-recovery system designed to turn environmental inputs into useful outputs.", "innovationDescription": "Problem Statement\r\nRising atmospheric CO₂ emissions, increasing wastewater volumes, and the limitations of conventional green infrastructure create a need for compact, resource-efficient biological systems. Traditional approaches often require large land areas, continuous manual supervision, and separate systems for environmental treatment and resource recovery. At the same time, high-density microalgae cultivation is sensitive to changes in temperature, lighting, aeration, liquid level, and growth conditions, making stable operation difficult.\r\n\r\nSolution\r\nBioArc is a compact, automated microalgae photobioreactor designed to combine carbon capture, oxygen generation, wastewater nutrient utilization, and biomass recovery in a single system. Microalgae use CO₂ during photosynthesis while growing in a controlled reactor. The system is designed to use treated municipal wastewater as a nutrient-rich cultivation medium, helping recycle wastewater while supporting algal growth. The resulting biomass can be further utilized as a feedstock for products such as biofuels, biopolymers, fertilizers, and other bio-products.\r\n\r\nInnovation Details\r\nBioArc combines biological processing with autonomous hardware and intelligent software control. An ESP32-based edge controller integrates optical, temperature, environmental, and liquid-level sensing with automated pumps, valves, lighting, and agitation. A low-cost RGB sensor is used with our Green Excess Index (GEI) method to estimate algal biomass without relying on expensive laboratory optical instruments. The controller also uses an autonomous finite-state workflow to manage cultivation, monitoring, dosing, and harvesting.\r\n\r\nThe software layer adds real-time MQTT/WebSocket telemetry, remote monitoring, offline control, historical analytics, and an AI copilot capable of interacting with the reactor through controlled actuator commands. This makes BioArc more than an algae-growing device: it is a compact, intelligent biological resource-recovery system designed to turn environmental inputs into useful outputs.", "workingPrinciple": "BioArc uses a controlled microalgae cultivation cycle to convert environmental inputs into useful outputs.\r\nFirst, the reactor receives a nutrient-rich cultivation medium, with CO₂ supplied for algal growth. Microalgae grow under controlled lighting, temperature, aeration, and mixing conditions. During cultivation, sensors continuously monitor key parameters such as temperature, liquid level, and algal growth density.\r\nAn onboard ESP32 controller processes sensor data and manages the reactor’s pumps, valves, lights, and agitator through an autonomous control workflow. Optical measurements are used to estimate biomass growth, allowing the system to determine when the culture reaches the required density. \r\nAt sufficient biomass density, BioArc initiates the harvesting cycle, removes the algal biomass, and resets the reactor for the next cultivation cycle. The process therefore creates a continuous loop of cultivation → monitoring → growth assessment → harvesting → regeneration.", "majorHardwareComponents": ["Major Hardware Components\n- ESP32 Microcontroller\n- TCS34725 RGB Color Sensor\n- DS18B20 Temperature Sensor\n- BME280 Environmental Sensor\n- Aeration / CO₂ Pump\n- Grow Light Array\n- Agitator Motor"], "useAi": true, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["Government / Public Services", "General Public"], "potentialImpact": "Potential Real-World Impact\r\nBioArc aims to:\r\n- Capture CO₂ and generate oxygen through microalgae cultivation.\r\n- Reuse nutrient-rich municipal wastewater for algal growth and water recovery.\r\n- Convert algal biomass into useful products such as biofuel, biogas, and biopolymers.\r\n- Provide a compact, deployable environmental solution for urban and industrial settings.", "productPotential": "yes", "prototypeDevelopmentCost": 9000, "auraDemoHighlight": "One compact system, multiple environmental outputs:\r\nCO₂ capture + O₂ generation + wastewater utilization + valuable algal biomass.\r\nIt combines real hardware, biological processing, and autonomous control into a single working prototype rather than treating each problem separately.", "safetyHazards": ["water_near_electrical_equipment"], "safetyPrecautions": "Safety Precautions Taken\r\n- Automated monitoring of temperature, liquid level, and culture conditions.\r\n- Controlled operation of pumps, lights, valves, and agitator through the ESP32.\r\n- Offline fallback control to maintain safe operation during network failure.\r\n- Automated process states prevent unsafe simultaneous actuator operation.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": true, "previousExhibitionDetails": "HexaFalls 2.0", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-05T16:41:46.294Z", "updatedAt": "2026-10-14T18:48:46.237Z", "abstract": { "originalName": "BioArc_Reactor_2.0.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791218505/aura-registrations/abstract-docs/BioArc_Reactor_2.0.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/MindZed/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/MindZed/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791218505/aura-registrations/id-cards/v1hgfdsmicmhptssfnkc.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/MindZed/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791218505/aura-registrations/id-cards/onoyvbg2zltva99uzqgg.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/MindZed/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791218505/aura-registrations/id-cards/yuf8etyemki1pddi9w8w.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/MindZed/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791218505/aura-registrations/id-cards/hrlbsuc9feu3y52szrwq.jpg", "exists": true }] }, { "index": 30, "id": "6ac62d92d0d49fb80b735147", "registrationId": "AURA2K26-HYKYME", "rawTeamName": "Zentrix", "folderName": "Zentrix", "folderRelPath": "assets/Teams/Zentrix", "projectTitle": "Smart Water Monitoring System for Drain Overflow & Pipeline Leakage Detection", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Aalia Irshad", "teamLeaderEmail": "aaliairshad842@gmail.com", "teamLeaderPhone": "7439912565", "teamMemberDetails": "Abdullahil Kafi ,Aliah university ,9339158498\r\nMd Miraj Ali ,Aliah university, 9735587576\r\nMd Kamal Akhtar,aliah university,9062138135", "hardwareProjectCategories": ["Other", "Embedded Systems", "IoT & Smart Devices", "Electronics & Communication"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Urban areas face two major water-related problems: drain overflow and underground pipeline leakage. During heavy rainfall, overflowing drains can cause waterlogging, traffic disruption and road damage. Pipeline leaks can also waste large amounts of water and may remain undetected because they occur underground. Our Smart Water Monitoring System provides an early-warning solution using sensors and a microcontroller. An ultrasonic water-level sensor continuously monitors the water level inside a drain. When the water rises above a predefined critical level, the system activates an alert. For underground pipelines, flow and pressure sensors monitor the normal water conditions. An unusual pressure drop or unexpected flow change can indicate a possible leakage. The sensor data is processed by an Arduino, which compares the readings with preset safe values and activates a buzzer, LED or display when an abnormal condition is detected. The system helps reduce water wastage, flooding, road damage and unnecessary inspection work. Its main innovation is combining drain-overflow and pipeline-leakage monitoring into one compact, low-cost hardware system for early detection and faster response.", "solutionDescription": "Urban areas face two major water-related problems: drain overflow and underground pipeline leakage. During heavy rainfall, overflowing drains can cause waterlogging, traffic disruption and road damage. Pipeline leaks can also waste large amounts of water and may remain undetected because they occur underground. Our Smart Water Monitoring System provides an early-warning solution using sensors and a microcontroller. An ultrasonic water-level sensor continuously monitors the water level inside a drain. When the water rises above a predefined critical level, the system activates an alert. For underground pipelines, flow and pressure sensors monitor the normal water conditions. An unusual pressure drop or unexpected flow change can indicate a possible leakage. The sensor data is processed by an Arduino, which compares the readings with preset safe values and activates a buzzer, LED or display when an abnormal condition is detected. The system helps reduce water wastage, flooding, road damage and unnecessary inspection work. Its main innovation is combining drain-overflow and pipeline-leakage monitoring into one compact, low-cost hardware system for early detection and faster response.", "innovationDescription": "Urban areas face two major water-related problems: drain overflow and underground pipeline leakage. During heavy rainfall, overflowing drains can cause waterlogging, traffic disruption and road damage. Pipeline leaks can also waste large amounts of water and may remain undetected because they occur underground. Our Smart Water Monitoring System provides an early-warning solution using sensors and a microcontroller. An ultrasonic water-level sensor continuously monitors the water level inside a drain. When the water rises above a predefined critical level, the system activates an alert. For underground pipelines, flow and pressure sensors monitor the normal water conditions. An unusual pressure drop or unexpected flow change can indicate a possible leakage. The sensor data is processed by an Arduino, which compares the readings with preset safe values and activates a buzzer, LED or display when an abnormal condition is detected. The system helps reduce water wastage, flooding, road damage and unnecessary inspection work. Its main innovation is combining drain-overflow and pipeline-leakage monitoring into one compact, low-cost hardware system for early detection and faster response.", "workingPrinciple": "The system uses sensors and a microcontroller to continuously monitor drain water levels and underground pipeline conditions. An ultrasonic water-level sensor measures the distance between the sensor and the water surface. As the water level rises, the measured distance decreases. When the water reaches a predefined critical level, the microcontroller detects the condition and activates a buzzer/LED alert. For pipeline monitoring, flow and pressure sensors measure the normal water flow and pressure inside the pipe. A sudden pressure drop or an unexpected change in flow can indicate a possible leakage. The sensor readings are processed by an Arduino/ESP32, which compares them with preset safe limits. If an abnormal condition is detected, the system generates an immediate warning. This enables early detection of drain overflow and pipeline leakage, helping reduce water wastage, flooding and damage.", "majorHardwareComponents": ["Arduino/ESP32 microcontroller – processes sensor readings and controls the system.\n• Ultrasonic water-level sensor – measures the water level in the drain.\n• Flow sensor – monitors the flow of water through the pipeline.\n• Pressure sensor – detects unusual pressure changes that may indicate leakage.\n• Buzzer – provides an audible warning when an abnormal condition is detected.\n• LED indicators – show normal and warning conditions.\n• LCD/OLED display – can display water level and sensor status.\n• Mini water pump – circulates water in the prototype model.\n• Pipes and connectors – represent the underground pipeline system.\n• Breadboard", "jumper wires and power supply – connect and power the electronic components."], "useAi": true, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["Government / Public Services", "Other"], "potentialImpact": "The system can benefit households, municipalities, water-supply authorities and urban infrastructure managers. It provides early warnings for drain overflow and possible underground pipeline leakage, allowing problems to be addressed before they become severe. Drain monitoring can help reduce waterlogging, road damage and disruption during heavy rainfall. Pipeline monitoring can help identify possible leaks early, reducing unnecessary water wastage and helping maintenance teams locate problem areas more efficiently. The system can also reduce the need for frequent manual inspection of difficult-to-access pipelines and drains. Because the prototype uses commonly available sensors and a microcontroller, it has the potential to be developed into a low-cost monitoring solution for homes, buildings and urban infrastructure. In the future, IoT connectivity could be added to send alerts remotely to maintenance teams or authorities.", "productPotential": "yes", "prototypeDevelopmentCost": 4000, "auraDemoHighlight": "This project is worth seeing because it combines two important water-management problems in one smart system: drain overflow and underground pipeline leakage. The system uses sensors to continuously monitor water conditions and provides an early warning when abnormal conditions are detected. Its main advantage is early detection, which can help reduce water wastage, flooding, road damage and unnecessary manual inspection. The prototype is compact, practical and can be developed using affordable, easily available electronic components. It also has scope for future improvement through IoT-based remote monitoring and mobile alerts. The project demonstrates how simple sensor technology can be applied to solve real-world urban water-management problems.", "safetyHazards": ["none", "fire_combustion"], "safetyPrecautions": "The prototype uses low-voltage electrical components and is designed for safe demonstration. Electrical connections are properly insulated and secured to prevent accidental short circuits. The electronic components are kept away from unnecessary water exposure. The water flow is limited to the small demonstration model, and the pump and moving parts are handled carefully. The system is operated under supervision during demonstrations. Proper wiring, secure connections and a suitable power supply are used to reduce electrical and mechanical risks.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-07T11:31:30.172Z", "updatedAt": "2026-10-14T18:48:51.853Z", "abstract": { "originalName": "Smart_Water_Monitoring_AURA2K26_Submission-1.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791372689/aura-registrations/abstract-docs/Smart_Water_Monitoring_AURA2K26_Submission-1.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Zentrix/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Zentrix/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791372689/aura-registrations/id-cards/l89zzexxgfh4no6jflje.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Zentrix/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791372689/aura-registrations/id-cards/cbqrwmcikjhq4u5hv80u.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Zentrix/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791372689/aura-registrations/id-cards/zbwjzpjteqvouousfdk1.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Zentrix/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791372689/aura-registrations/id-cards/xjcwwvklc3tso8lsntjr.png", "exists": true }] }, { "index": 31, "id": "6ac663a2cdbef90437c943ad", "registrationId": "AURA2K26-CQGEH2", "rawTeamName": "VISION ROAD", "folderName": "VISION ROAD", "folderRelPath": "assets/Teams/VISION ROAD", "projectTitle": "Driver Monitoring Device", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "HASAN IMAM", "teamLeaderEmail": "uddinzaid23@gmail.com", "teamLeaderPhone": "7980614249", "teamMemberDetails": "Zaiduddin/ Aliah University/ EEN/ Second Year/ 62905 43966\r\n\r\nMd. Shaqib/ Aliah University/ EEN/ Second Year/ 82769 57426\r\n\r\nArsalan Akhter/ Aliah University/ ECE/ Second Year/ 93303 25041", "hardwareProjectCategories": ["IoT & Smart Devices", "Automation & Control", "Assistive Technology", "Smart Mobility / Transportation", "Safety & Security Systems", "Embedded Systems"], "prototypeType": "IoT Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Driver fatigue and drowsiness are leading causes of severe road accidents globally. When a driver falls asleep behind the wheel, their reaction time drops to zero, making high-speed collisions almost inevitable. Most conventional vehicles lack active safety systems that can intervene in real time to detect driver impairment, stop the vehicle safely, and notify help before a tragedy occurs.\r\nHardware Solution\r\nThe proposed system uses an embedded monitoring architecture directly integrated into the vehicle's ignition and communication systems:\r\n Monitoring Sensor/Camera Module: A driver-facing visual or infrared sensor continuously tracks eye closure duration and facial cues to detect micro-sleep.\r\n Microcontroller (Processing Unit): An onboard processor (such as an ESP32 or Arduino) processes the sensor input in real time to detect drowsiness.\r\n Buzzer Alert: A high-decibel piezobuzzer triggers immediately upon sleep detection to startle and awaken the driver.\r\n Engine Immobilizer Relay: An inline relay module wired into the ignition circuit safely cuts engine power to stop the moving vehicle.\r\n GPS & GSM/LTE Module: A location tracking and cellular unit fetches precise coordinates and transmits an automated emergency SMS with live location links to predefined emergency contacts or fleet managers.\r\nKey Innovations\r\n1 Active Intervention Over Passive Warning: Most existing systems only sound an alarm. This solution actively mitigates risk by controlling the vehicle's ignition to prevent high-speed collisions if the driver fails to respond.\r\n2 Integrated Multi-Layered Safety Chain: It unifies real-time detection, instant auditory awakening, active vehicle stopping, and emergency notification into one automated response loop.\r\n3 Automated Incident Localization: Transmitting live GPS coordinates immediately ensures family or emergency responders can locate the vehicle quickly, even on isolated highways.\r\n4 Universal & Low-Cost Retrofitting: Built with accessible, affordable hardware components, making it viable for both commercial fleet management and retrofitting older consumer vehicles.", "solutionDescription": "Driver fatigue and drowsiness are leading causes of severe road accidents globally. When a driver falls asleep behind the wheel, their reaction time drops to zero, making high-speed collisions almost inevitable. Most conventional vehicles lack active safety systems that can intervene in real time to detect driver impairment, stop the vehicle safely, and notify help before a tragedy occurs.\r\nHardware Solution\r\nThe proposed system uses an embedded monitoring architecture directly integrated into the vehicle's ignition and communication systems:\r\n Monitoring Sensor/Camera Module: A driver-facing visual or infrared sensor continuously tracks eye closure duration and facial cues to detect micro-sleep.\r\n Microcontroller (Processing Unit): An onboard processor (such as an ESP32 or Arduino) processes the sensor input in real time to detect drowsiness.\r\n Buzzer Alert: A high-decibel piezobuzzer triggers immediately upon sleep detection to startle and awaken the driver.\r\n Engine Immobilizer Relay: An inline relay module wired into the ignition circuit safely cuts engine power to stop the moving vehicle.\r\n GPS & GSM/LTE Module: A location tracking and cellular unit fetches precise coordinates and transmits an automated emergency SMS with live location links to predefined emergency contacts or fleet managers.\r\nKey Innovations\r\n1 Active Intervention Over Passive Warning: Most existing systems only sound an alarm. This solution actively mitigates risk by controlling the vehicle's ignition to prevent high-speed collisions if the driver fails to respond.\r\n2 Integrated Multi-Layered Safety Chain: It unifies real-time detection, instant auditory awakening, active vehicle stopping, and emergency notification into one automated response loop.\r\n3 Automated Incident Localization: Transmitting live GPS coordinates immediately ensures family or emergency responders can locate the vehicle quickly, even on isolated highways.\r\n4 Universal & Low-Cost Retrofitting: Built with accessible, affordable hardware components, making it viable for both commercial fleet management and retrofitting older consumer vehicles.", "innovationDescription": "Driver fatigue and drowsiness are leading causes of severe road accidents globally. When a driver falls asleep behind the wheel, their reaction time drops to zero, making high-speed collisions almost inevitable. Most conventional vehicles lack active safety systems that can intervene in real time to detect driver impairment, stop the vehicle safely, and notify help before a tragedy occurs.\r\nHardware Solution\r\nThe proposed system uses an embedded monitoring architecture directly integrated into the vehicle's ignition and communication systems:\r\n Monitoring Sensor/Camera Module: A driver-facing visual or infrared sensor continuously tracks eye closure duration and facial cues to detect micro-sleep.\r\n Microcontroller (Processing Unit): An onboard processor (such as an ESP32 or Arduino) processes the sensor input in real time to detect drowsiness.\r\n Buzzer Alert: A high-decibel piezobuzzer triggers immediately upon sleep detection to startle and awaken the driver.\r\n Engine Immobilizer Relay: An inline relay module wired into the ignition circuit safely cuts engine power to stop the moving vehicle.\r\n GPS & GSM/LTE Module: A location tracking and cellular unit fetches precise coordinates and transmits an automated emergency SMS with live location links to predefined emergency contacts or fleet managers.\r\nKey Innovations\r\n1 Active Intervention Over Passive Warning: Most existing systems only sound an alarm. This solution actively mitigates risk by controlling the vehicle's ignition to prevent high-speed collisions if the driver fails to respond.\r\n2 Integrated Multi-Layered Safety Chain: It unifies real-time detection, instant auditory awakening, active vehicle stopping, and emergency notification into one automated response loop.\r\n3 Automated Incident Localization: Transmitting live GPS coordinates immediately ensures family or emergency responders can locate the vehicle quickly, even on isolated highways.\r\n4 Universal & Low-Cost Retrofitting: Built with accessible, affordable hardware components, making it viable for both commercial fleet management and retrofitting older consumer vehicles.", "workingPrinciple": "> System starts\r\nWhen the vehicle is started, the ESP32 turns ON the complete monitoring system.\r\n> Driver's eyes are monitored\r\nThe eye sensor continuously checks whether the driver's eyes are open or closed.\r\n> Drowsiness is detected\r\nIf the driver's eyes remain closed for a predefined time, the ESP32 considers that the driver may be falling asleep.\r\n> Warning alarm\r\nThe ESP32 immediately activates the buzzer.\r\nThe buzzer gives an alarm to wake the driver.\r\n> Driver gets a chance to respond\r\nIf the driver opens their eyes after the alarm, the system returns to normal monitoring.\r\n> Vehicle is stopped if there is no response\r\nIf the driver does not respond and the eyes remain closed, the ESP32 activates the relay module.\r\nThe relay disconnects the vehicle's ignition/control circuit, causing the vehicle to stop safely.\r\n> Location is obtained\r\nThe GPS module continuously provides the vehicle's location.\r\n> Data is sent to the mobile app\r\nThe ESP32 sends information through GSM/Wi-Fi, such as:\r\n- Driver awake/drowsy status\r\n- Alarm status\r\n- Vehicle status\r\n- GPS location\r\nAlert appears in the app\r\nThe mobile app shows an alert such as \"Driver Drowsiness Detected\" and can display the vehicle's current location.", "majorHardwareComponents": ["ESP32 Development Board\nIR Eye Blink Sensor\nBuzzer\nRelay Module\nGPS Module (NEO-6M)\nGSM Module (SIM800L)\nMPU6050\nOLED Display\nLEDs\nPush Button\nBreadboard\nJumper Wires\nResistors\nPower Supply\nBattery"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "General Public", "Transportation", "Government / Public Services"], "potentialImpact": "A Driver Monitoring Device can be used in many real-world situations where driver safety is important. The main purpose of this system is to detect driver drowsiness and provide an early warning before an accident occurs.\r\n1. Trucks and Buses:\r\nLong-distance truck and bus drivers often drive for many hours continuously. The device can monitor the driver's eyes and detect signs of sleep. If drowsiness is detected, an alarm can warn the driver.\r\n2. Public Transport:\r\nThe system can be installed in buses and other public transport vehicles to improve passenger safety. The driver's condition can also be monitored by the transport management team.\r\n3. Taxi and Cab Services:\r\nTaxi and cab drivers may work for long hours, especially during night shifts. The device can provide alerts when the driver becomes drowsy.\r\n4. Fleet Management:\r\nLogistics and delivery companies can use the system to monitor multiple vehicles. The mobile application can show driver status, alerts, and vehicle location.\r\n5. Night-Time Driving:\r\nThe device is particularly useful during night journeys when the risk of driver fatigue is higher.\r\n6. Accident Prevention:\r\nThe biggest application is accident prevention. By detecting drowsiness early and providing warnings, the system can help reduce accidents caused by drivers falling asleep while driving.", "productPotential": "yes", "prototypeDevelopmentCost": 3500, "auraDemoHighlight": "The Driver Monitoring Device is worth seeing because it combines safety, automation, and real-time monitoring in one system. It can detect when a driver becomes drowsy and immediately provide an alarm to alert the driver. If the driver does not respond, the system can demonstrate an automatic vehicle-stop function in a safe prototype setup.\r\nThe project is also interesting because it connects hardware with a mobile application. The user can see the driver's status, warning alerts, and vehicle location on the app. This makes the system useful not only for the driver but also for fleet owners and transport companies.", "safetyHazards": ["water_near_electrical_equipment", "moving_rotating_machinery"], "safetyPrecautions": "Keep away from water.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-07T15:22:10.463Z", "updatedAt": "2026-10-14T18:48:56.464Z", "abstract": { "originalName": "driver_monitoring_device_7pages.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791386528/aura-registrations/abstract-docs/driver_monitoring_device_7pages.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/VISION ROAD/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/VISION ROAD/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791386529/aura-registrations/id-cards/xuiymxh8w9zykcurzdsf.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/VISION ROAD/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791386529/aura-registrations/id-cards/qoupxrhsgugig2in4fge.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/VISION ROAD/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791386529/aura-registrations/id-cards/ty1byft0gsljxwxe3bsz.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/VISION ROAD/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791386529/aura-registrations/id-cards/r4olclcrjcqszv8iejkb.jpg", "exists": true }] }, { "index": 32, "id": "6ac7b8ef071f16c04dc808f1", "registrationId": "AURA2K26-VR79LS", "rawTeamName": "NEXUS", "folderName": "NEXUS", "folderRelPath": "assets/Teams/NEXUS", "projectTitle": "D.I.S.H.A. – Driver Information Safety Via Hillroad Automation", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "HUSAIN RAIHAN LASKAR", "teamLeaderEmail": "husain00819819@gmail.com", "teamLeaderPhone": "9339195701", "teamMemberDetails": "1. ARMAN ANSARY | ALIAH UNIVERSITY | EEN | 2025-2029 | 9907374595\r\n2. SOUMA JIT DAS | ALIAH UNIVERSITY | EEN | 2025-2029 | 7811035056\r\n3. SHAKIL PARVEZ MOLLA | EEN | 2025-2029 | 9242207985", "hardwareProjectCategories": ["Safety & Security Systems"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem staement:- Lack of real-time visibility and collision warning systems on blind mountain curves leads to severe head-on accidents due to driver's inability to detect oncoming traffic beyond static signage.\r\n\r\nSolution:- D.I.S.H.A. (Driver Information Safety Via Hillroad Automation) is a microcontroller-free, hardware-based collision prevention system designed for blind hill-road U-turns.IR sensors detect approaching vehicles from opposite sides of the curve. The sensor signals are processed through transistor-based analog switching circuits. Based on vehicle detection, the system automatically activates red and green LED traffic indicators to inform drivers which side has an approaching vehicle and help regulate right-of-way.\r\n\r\nInnovation:- The system uses simple, low-cost and easily available electronic components without Arduino, software, internet connectivity or complex programming. Its analog switching architecture provides immediate response with low maintenance requirements, making it suitable for remote hill roads where reliable infrastructure and technical support may be limited. The system can potentially be powered using a small DC source, battery or solar-powered setup.", "solutionDescription": "Problem staement:- Lack of real-time visibility and collision warning systems on blind mountain curves leads to severe head-on accidents due to driver's inability to detect oncoming traffic beyond static signage.\r\n\r\nSolution:- D.I.S.H.A. (Driver Information Safety Via Hillroad Automation) is a microcontroller-free, hardware-based collision prevention system designed for blind hill-road U-turns.IR sensors detect approaching vehicles from opposite sides of the curve. The sensor signals are processed through transistor-based analog switching circuits. Based on vehicle detection, the system automatically activates red and green LED traffic indicators to inform drivers which side has an approaching vehicle and help regulate right-of-way.\r\n\r\nInnovation:- The system uses simple, low-cost and easily available electronic components without Arduino, software, internet connectivity or complex programming. Its analog switching architecture provides immediate response with low maintenance requirements, making it suitable for remote hill roads where reliable infrastructure and technical support may be limited. The system can potentially be powered using a small DC source, battery or solar-powered setup.", "innovationDescription": "Problem staement:- Lack of real-time visibility and collision warning systems on blind mountain curves leads to severe head-on accidents due to driver's inability to detect oncoming traffic beyond static signage.\r\n\r\nSolution:- D.I.S.H.A. (Driver Information Safety Via Hillroad Automation) is a microcontroller-free, hardware-based collision prevention system designed for blind hill-road U-turns.IR sensors detect approaching vehicles from opposite sides of the curve. The sensor signals are processed through transistor-based analog switching circuits. Based on vehicle detection, the system automatically activates red and green LED traffic indicators to inform drivers which side has an approaching vehicle and help regulate right-of-way.\r\n\r\nInnovation:- The system uses simple, low-cost and easily available electronic components without Arduino, software, internet connectivity or complex programming. Its analog switching architecture provides immediate response with low maintenance requirements, making it suitable for remote hill roads where reliable infrastructure and technical support may be limited. The system can potentially be powered using a small DC source, battery or solar-powered setup.", "workingPrinciple": "Working Principle:-\r\nIR sensors detect vehicles approaching the blind turn from either side. The sensor signals drive a BC547 NPN and BC557 PNP transistor-based switching circuit, which automatically activates the corresponding LED warning indicators to alert approaching drivers and reduce the risk of head-on collisions.", "majorHardwareComponents": ["Major Hardware Components:-\nIR sensors", "BC547 (NPN) and BC557 (PNP) transistors", "Red/Yellow LEDs", "1kΩ", "10kΩ and 220Ω resistors", "battery", "switches", "connecting wires and breadboard."], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Transportation"], "potentialImpact": "D.I.S.H.A. can improve safety on narrow and blind hill-road turns by providing automatic visual warnings when an approaching vehicle is detected. It can benefit drivers, particularly in areas with limited visibility, by providing timely information about traffic approaching from the opposite direction. The low-cost, standalone design can potentially be adapted for remote roads where complex infrastructure may not be practical.", "productPotential": "potentially", "prototypeDevelopmentCost": 1500, "auraDemoHighlight": "D.I.S.H.A. demonstrates a simple yet practical approach to hill-road safety using low-cost electronic components. Its microcontroller-free design uses IR sensing and transistor-based switching to provide automatic visual warnings with minimal complexity. The prototype shows how a small hardware system can address a real-world road-safety problem without relying on internet connectivity or sophisticated software.", "safetyHazards": ["none"], "safetyPrecautions": "The prototype operates from a low-voltage battery supply. Proper resistor values are used to limit LED and circuit currents, and all connections are insulated and checked before operation. The circuit is mounted securely to prevent accidental short circuits or loose connections. The prototype is handled and demonstrated under safe operating conditions away from water and excessive heat.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-08T15:38:23.393Z", "updatedAt": "2026-10-14T18:49:02.01Z", "abstract": { "originalName": "D.I.S.H.A. â Driver Information Safety Via Hillroad Automation.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791473902/aura-registrations/abstract-docs/D.I.S.H.A.%20%C3%A2%C2%80%C2%93%20Driver%20Information%20Safety%20Via%20Hillroad%20Automation.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/NEXUS/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/NEXUS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791473902/aura-registrations/id-cards/a9d2hkgrvc0jgfxu5gn7.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/NEXUS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791473902/aura-registrations/id-cards/lwqishrbllfnb8gjhlh9.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/NEXUS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791473902/aura-registrations/id-cards/sd6gmdrf1eucw4hk8hiy.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/NEXUS/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791473902/aura-registrations/id-cards/poe1yu0hfwj2tvahelez.jpg", "exists": true }] }, { "index": 33, "id": "6ac8af37214102ba1613bbca", "registrationId": "AURA2K26-2HBT5D", "rawTeamName": "Circuit breakers", "folderName": "Circuit breakers", "folderRelPath": "assets/Teams/Circuit breakers", "projectTitle": "Ultrasonic glasses", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "Md Reyaz Mosharraf", "teamLeaderEmail": "mosharrafmdreyaz@gmail.com", "teamLeaderPhone": "8789322323", "teamMemberDetails": "Syed Md Bader Uddin | Aliah University | ECE | 2nd year | 7634870997\r\nRahmtullah siddique | Aliah University | ECE | 2nd year | 9835707094", "hardwareProjectCategories": ["Safety & Security Systems"], "prototypeType": "Wearable Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Problem Statement: Visually impaired people face difficulty detecting obstacles and knowing their direction and distance while walking. Conventional mobility aids may not provide immediate directional feedback.\r\nHardware Solution: Wearable ultrasonic glasses use two ultrasonic sensors to detect obstacles in front-left and front-right regions. An Arduino Nano calculates real-time distance and controls two buzzers, producing side-specific and distance-based sound alerts. The system is powered by a 9V battery and designed to be lightweight and hands-free.\r\nInnovation: The system combines real-time sensing, directional warning, synchronized central alerts, and distance-based beep patterns in a low-cost wearable device, enabling safer and intuitive navigation for users.", "solutionDescription": "Problem Statement: Visually impaired people face difficulty detecting obstacles and knowing their direction and distance while walking. Conventional mobility aids may not provide immediate directional feedback.\r\nHardware Solution: Wearable ultrasonic glasses use two ultrasonic sensors to detect obstacles in front-left and front-right regions. An Arduino Nano calculates real-time distance and controls two buzzers, producing side-specific and distance-based sound alerts. The system is powered by a 9V battery and designed to be lightweight and hands-free.\r\nInnovation: The system combines real-time sensing, directional warning, synchronized central alerts, and distance-based beep patterns in a low-cost wearable device, enabling safer and intuitive navigation for users.", "innovationDescription": "Problem Statement: Visually impaired people face difficulty detecting obstacles and knowing their direction and distance while walking. Conventional mobility aids may not provide immediate directional feedback.\r\nHardware Solution: Wearable ultrasonic glasses use two ultrasonic sensors to detect obstacles in front-left and front-right regions. An Arduino Nano calculates real-time distance and controls two buzzers, producing side-specific and distance-based sound alerts. The system is powered by a 9V battery and designed to be lightweight and hands-free.\r\nInnovation: The system combines real-time sensing, directional warning, synchronized central alerts, and distance-based beep patterns in a low-cost wearable device, enabling safer and intuitive navigation for users.", "workingPrinciple": "The Ultrasonic Glasses work on the principle of ultrasonic distance measurement.", "majorHardwareComponents": ["Ultrasonic sensors", "Arduino nano", "Buzzer"], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["Persons with Disabilities"], "potentialImpact": "THE BLIND PEOPLES GET BENIFITS FROM THIS. IT WILL HELP THEM BY VOICE ALERT", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "IT WILL HELP SOME DISABLE PEOPLE AND SAVE THEM FROM ACCIDENTS", "safetyHazards": ["none"], "safetyPrecautions": "USING ORIGNAL COMPONENTS", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-09T09:09:11.442Z", "updatedAt": "2026-10-14T18:49:06.219Z", "abstract": { "originalName": "project idea.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791536950/aura-registrations/abstract-docs/project%20idea.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Circuit breakers/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Circuit breakers/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791536950/aura-registrations/id-cards/tzw7bhinhcuhxcnml3e3.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Circuit breakers/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791536949/aura-registrations/id-cards/c55xbeg1jwuoorkn4z9l.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Circuit breakers/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791536949/aura-registrations/id-cards/fneobx1ukb9vjwmvon3w.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Circuit breakers/4.jpg", "url": null, "exists": false }] }, { "index": 34, "id": "6ac911b94c648a17fb697395", "registrationId": "AURA2K26-AKFQB6", "rawTeamName": "Qbit Dynamics", "folderName": "Qbit Dynamics", "folderRelPath": "assets/Teams/Qbit Dynamics", "projectTitle": "QDA-2, Autonomous Drone and GCS for Search and Mapping", "teamSize": 3, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 3, "teamLeaderName": "Sarthak Sharan", "teamLeaderEmail": "sarthaksharan006@gmail.com", "teamLeaderPhone": "8910518530", "teamMemberDetails": "Saaraswata Roy, Heritage Institute of Technology, Applied Electronics and Instrumentation, 2nd, 9903589661\r\nSoumyadip Das, Heritage Institute of Technology, CSE - Data Science, 3rd, 8159982595", "hardwareProjectCategories": ["AI-Enabled Hardware", "Robotics", "Drone / Autonomous Systems", "Safety & Security Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Problem Statement\r\n\r\nLarge, remote, hazardous, and difficult-to-access areas require continuous surveillance, systematic inspection, and rapid information gathering. Applications such as border monitoring, anti-poaching operations, disaster response, missing-person searches, and infrastructure security often face limited manpower, challenging terrain, unreliable GPS signals, and restricted communication infrastructure. Conventional aerial surveillance relies heavily on manual piloting and human analysis of video footage, making operations resource-intensive and vulnerable to fatigue, coverage gaps, and delayed detection. An affordable autonomous system is needed to survey large areas systematically, identify objects or persons of interest, and provide location-linked information while reducing human exposure to dangerous environments.\r\n\r\n2. Proposed Hardware Solution\r\n\r\nQDA-2, developed by Qbit Dynamics, is an autonomous aerial surveillance, search, and mapping platform designed for operation in GPS-denied environments. The hardware integrates a quadrotor UAV, Raspberry Pi 5 companion computer, STM32H7-based flight controller, visual-inertial navigation sensors, perception cameras, and an autonomous docking and charging station.\r\n\r\nOnce a mission area is defined, the UAV can autonomously take off, follow a systematic survey pattern, capture imagery, and use onboard computer vision to identify relevant targets. Visual-inertial odometry, optical flow, and laser ranging enable navigation without dependence on GPS. The ground station provides telemetry, detection records, coverage information, and processed aerial maps. Upon completing a sortie or reaching its battery threshold, the UAV returns, lands on a self-aligning docking station, recharges through electrical contacts, and can resume the mission. The whole process runs autonomously.\r\n\r\nThe platform can support different mission-specific detection models and workflows for border surveillance, wildlife monitoring and anti-poaching, disaster assessment, missing-person searches, perimeter security, and remote-area inspection.\r\n\r\n3. Innovation Details\r\n\r\nGPS-independent autonomy: Visual-inertial localisation enables systematic aerial operations where satellite positioning is unavailable or unreliable.\r\n\r\nEnd-to-end autonomous operation: Mission execution, area coverage, target detection, precision landing, passive docking, and recharging are integrated into a single reusable system capable of repeated sorties.\r\n\r\nOnboard intelligence: Local processing enables target detection without mandatory cloud connectivity, while a separate flight controller maintains flight-critical control and failsafes.\r\n\r\nModular, cost-conscious architecture: Commercially available hardware, open-source software, and 3D-printed components support affordability, maintainability, and potential fleet deployment. Mission-specific perception models allow the same core platform to serve multiple surveillance and search applications.\r\n\r\nBy combining autonomous navigation, intelligent perception, systematic coverage, and self-recharging capability, QDA-2 aims to make persistent aerial monitoring and search operations more accessible, efficient, and adaptable across civilian and public-safety applications.", "solutionDescription": "1. Problem Statement\r\n\r\nLarge, remote, hazardous, and difficult-to-access areas require continuous surveillance, systematic inspection, and rapid information gathering. Applications such as border monitoring, anti-poaching operations, disaster response, missing-person searches, and infrastructure security often face limited manpower, challenging terrain, unreliable GPS signals, and restricted communication infrastructure. Conventional aerial surveillance relies heavily on manual piloting and human analysis of video footage, making operations resource-intensive and vulnerable to fatigue, coverage gaps, and delayed detection. An affordable autonomous system is needed to survey large areas systematically, identify objects or persons of interest, and provide location-linked information while reducing human exposure to dangerous environments.\r\n\r\n2. Proposed Hardware Solution\r\n\r\nQDA-2, developed by Qbit Dynamics, is an autonomous aerial surveillance, search, and mapping platform designed for operation in GPS-denied environments. The hardware integrates a quadrotor UAV, Raspberry Pi 5 companion computer, STM32H7-based flight controller, visual-inertial navigation sensors, perception cameras, and an autonomous docking and charging station.\r\n\r\nOnce a mission area is defined, the UAV can autonomously take off, follow a systematic survey pattern, capture imagery, and use onboard computer vision to identify relevant targets. Visual-inertial odometry, optical flow, and laser ranging enable navigation without dependence on GPS. The ground station provides telemetry, detection records, coverage information, and processed aerial maps. Upon completing a sortie or reaching its battery threshold, the UAV returns, lands on a self-aligning docking station, recharges through electrical contacts, and can resume the mission. The whole process runs autonomously.\r\n\r\nThe platform can support different mission-specific detection models and workflows for border surveillance, wildlife monitoring and anti-poaching, disaster assessment, missing-person searches, perimeter security, and remote-area inspection.\r\n\r\n3. Innovation Details\r\n\r\nGPS-independent autonomy: Visual-inertial localisation enables systematic aerial operations where satellite positioning is unavailable or unreliable.\r\n\r\nEnd-to-end autonomous operation: Mission execution, area coverage, target detection, precision landing, passive docking, and recharging are integrated into a single reusable system capable of repeated sorties.\r\n\r\nOnboard intelligence: Local processing enables target detection without mandatory cloud connectivity, while a separate flight controller maintains flight-critical control and failsafes.\r\n\r\nModular, cost-conscious architecture: Commercially available hardware, open-source software, and 3D-printed components support affordability, maintainability, and potential fleet deployment. Mission-specific perception models allow the same core platform to serve multiple surveillance and search applications.\r\n\r\nBy combining autonomous navigation, intelligent perception, systematic coverage, and self-recharging capability, QDA-2 aims to make persistent aerial monitoring and search operations more accessible, efficient, and adaptable across civilian and public-safety applications.", "innovationDescription": "1. Problem Statement\r\n\r\nLarge, remote, hazardous, and difficult-to-access areas require continuous surveillance, systematic inspection, and rapid information gathering. Applications such as border monitoring, anti-poaching operations, disaster response, missing-person searches, and infrastructure security often face limited manpower, challenging terrain, unreliable GPS signals, and restricted communication infrastructure. Conventional aerial surveillance relies heavily on manual piloting and human analysis of video footage, making operations resource-intensive and vulnerable to fatigue, coverage gaps, and delayed detection. An affordable autonomous system is needed to survey large areas systematically, identify objects or persons of interest, and provide location-linked information while reducing human exposure to dangerous environments.\r\n\r\n2. Proposed Hardware Solution\r\n\r\nQDA-2, developed by Qbit Dynamics, is an autonomous aerial surveillance, search, and mapping platform designed for operation in GPS-denied environments. The hardware integrates a quadrotor UAV, Raspberry Pi 5 companion computer, STM32H7-based flight controller, visual-inertial navigation sensors, perception cameras, and an autonomous docking and charging station.\r\n\r\nOnce a mission area is defined, the UAV can autonomously take off, follow a systematic survey pattern, capture imagery, and use onboard computer vision to identify relevant targets. Visual-inertial odometry, optical flow, and laser ranging enable navigation without dependence on GPS. The ground station provides telemetry, detection records, coverage information, and processed aerial maps. Upon completing a sortie or reaching its battery threshold, the UAV returns, lands on a self-aligning docking station, recharges through electrical contacts, and can resume the mission. The whole process runs autonomously.\r\n\r\nThe platform can support different mission-specific detection models and workflows for border surveillance, wildlife monitoring and anti-poaching, disaster assessment, missing-person searches, perimeter security, and remote-area inspection.\r\n\r\n3. Innovation Details\r\n\r\nGPS-independent autonomy: Visual-inertial localisation enables systematic aerial operations where satellite positioning is unavailable or unreliable.\r\n\r\nEnd-to-end autonomous operation: Mission execution, area coverage, target detection, precision landing, passive docking, and recharging are integrated into a single reusable system capable of repeated sorties.\r\n\r\nOnboard intelligence: Local processing enables target detection without mandatory cloud connectivity, while a separate flight controller maintains flight-critical control and failsafes.\r\n\r\nModular, cost-conscious architecture: Commercially available hardware, open-source software, and 3D-printed components support affordability, maintainability, and potential fleet deployment. Mission-specific perception models allow the same core platform to serve multiple surveillance and search applications.\r\n\r\nBy combining autonomous navigation, intelligent perception, systematic coverage, and self-recharging capability, QDA-2 aims to make persistent aerial monitoring and search operations more accessible, efficient, and adaptable across civilian and public-safety applications.", "workingPrinciple": "1. Mission Planning and Take-off: The operator defines a search boundary through the ground station. The UAV autonomously takes off and generates a systematic lawnmower flight path to survey the designated area with minimal gaps and unnecessary backtracking.\r\n\r\n2. GPS-Denied Navigation: A global-shutter monochrome camera captures environmental features, while a dedicated inertial measurement unit (IMU) measures angular velocity and acceleration. Visual-Inertial Odometry (VIO) fuses these measurements to estimate the UAV's position and motion. This enables navigation without dependence on GPS.\r\n\r\n3. Autonomous Flight Control: A Raspberry Pi 5 processes localisation data, mission logic, and perception. An independent STM32H7-based flight controller executes real-time stabilisation, motor control, and safety functions. This separation allows flight-critical control to continue if the companion computer fails, subject to predefined failsafe behaviour.\r\n\r\n4. AI-Based Perception and Mapping: A dedicated colour camera captures survey imagery. Onboard computer vision identifies potentially relevant people, objects, or features according to the deployed detection models. The system tracks surveyed regions and associates observations with estimated locations. After landing, the ground station processes imagery into stitched, georeferenced maps for analysis.\r\n\r\n5. Autonomous Recovery and Recharging: After completing the mission or reaching a battery threshold, the UAV returns to its docking station. Vision-guided landing and passive mechanical funnels help align the landing gear with charging contacts. The battery recharges, enabling subsequent sorties.\r\n\r\n6. Operational Output: Responders receive telemetry, coverage information, detected-target locations, and mapped imagery to support surveillance, search, and decision-making.", "majorHardwareComponents": ["1. F450-class quadrotor airframe\n2. Four BLDC motors", "ESCs and propellers\n3. Raspberry Pi 5 companion computer\n4. TBS Lucid H7 (STM32H7) flight controller\n5. Arducam OV9281 monochrome global-shutter navigation camera\n6. Innomaker IMX296 colour global-shutter perception camera\n7. ICM-42688-P IMUs (three units)\n8. MicoAir MTF-02P laser altimeter and optical-flow module\n9. DPS310 barometer\n10. 4S 5000 mAh Li-ion battery\n11. Power distribution and regulated power supply system\n12. Wireless communication module\n13. Independent RC receiver and emergency override link\n14. Autonomous docking station with passive alignment funnels and charging contacts\n15. Ground station computer for mission monitoring and map processing\n16. 26 TOPS AI HAT"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Government / Public Services", "Other", "Industry"], "potentialImpact": "QDA-2 can benefit border security teams, forest and wildlife departments, disaster-response agencies, search-and-rescue teams, and infrastructure monitoring personnel by providing an affordable autonomous aerial surveillance and mapping solution. It reduces dependence on continuous manual piloting and enables systematic coverage of large, remote, or hazardous areas.\r\n\r\nUsing visual-inertial navigation, onboard AI-based object detection, and aerial image mapping, the drone can help identify objects of interest, record their locations, and generate useful visual information for ground operators. Its GPS-denied navigation capability is designed to support missions in environments where GPS availability is limited or unreliable. The autonomous return, precision landing, and docking system aims to reduce operator workload and support repeated missions with less manual intervention.\r\n\r\nCompared with conventional manually operated drones, QDA-2 integrates navigation, perception, mapping, and autonomous recovery into a single platform. Its modular, cost-conscious design also aims to make autonomous aerial technology more accessible to institutions with limited resources. Overall, the project has the potential to improve surveillance coverage, reduce human exposure to risky environments, and help teams make faster, better-informed decisions. Its effectiveness in specific applications will depend on field testing and mission-specific validation.", "productPotential": "yes", "prototypeDevelopmentCost": 60000, "auraDemoHighlight": "QDA-2 stands out for combining GPS-denied autonomous navigation, onboard AI, and a complete autonomous mission cycle in one cost-conscious UAV platform. Unlike conventional drones that often depend on continuous GPS availability and operator control, QDA-2 is designed to navigate using visual-inertial odometry, enabling operation in environments where GPS is unavailable or unreliable.\r\n\r\nIts most distinctive feature is the ability to operate without continuous reliance on a ground control station (GCS) link for onboard navigation and mission execution. The drone combines autonomous flight, AI-based object detection, aerial mapping, and mission management, reducing the need for constant human intervention.\r\n\r\nQDA-2 also aims to solve a major practical challenge: what happens after the mission? It is designed to return autonomously, perform precision landing, align with a docking station, and recharge through contact-based charging. This creates a pathway toward repeated missions with reduced manual handling and turnaround effort.\r\n\r\nBy integrating navigation, perception, recovery, and recharging, QDA-2 goes beyond a drone that simply flies a programmed route. It demonstrates a step toward a self-operating aerial system that can survey large or hazardous areas, identify objects of interest, and prepare for subsequent missions. Its modular architecture and use of accessible hardware make this approach promising for scalable autonomous surveillance, search, and mapping applications.", "safetyHazards": ["drone_flying_equipment"], "safetyPrecautions": "QDA-2 incorporates multiple safety measures to maintain controlled and reliable operation. A fully manual RC override allows the operator to take control whenever required, independently of the autonomous system or ground control station software. A dedicated emergency kill switch enables immediate motor shutdown in critical situations.\r\n\r\nThe drone incorporates a multi-point pre-arm safety interlock: **physical movement is inhibited until three independent safety checks, verified through separate sources, have all passed.** This layered validation helps prevent unintended activation due to a single sensor, subsystem, or software check reporting an incorrect safe state.\r\n\r\nThe flight controller operates independently from the companion computer, separating low-level flight stabilisation and safety functions from AI processing and mission planning. This architecture helps isolate flight-control execution from companion-computer failures or excessive processing loads.\r\n\r\nAn independent manual-control link allows operator intervention if autonomous operation behaves unexpectedly. Visual-inertial odometry, optical flow, and laser-altitude measurements support navigation when GPS is unavailable or unreliable.\r\n\r\nFurther precautions include pre-flight inspections of the airframe, propellers, battery, sensors, and control links; battery and flight-status monitoring; and progressive testing of autonomous navigation, return, landing, and docking in controlled environments. Autonomous landing and contact charging are designed to support recovery with minimal manual handling.\r\n\r\nThese safeguards combine independent checks, fault isolation, and direct human intervention to reduce operational risks while retaining operator authority over the aircraft.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": true, "previousExhibitionDetails": "ISRO Robotics Challenge(IROC-U), Final Round, URSC, Bangalore, July 2026\r\nUDAAN 2.0, Heritage Institute of Technology, September 2026\r\nCII Eastern Region ICT, September 2026", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-09T16:09:29.937Z", "updatedAt": "2026-10-14T18:49:10.472Z", "abstract": { "originalName": "QDA-2, Qbit Dynamics.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791562169/aura-registrations/abstract-docs/QDA-2%2C%20Qbit%20Dynamics.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Qbit Dynamics/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Qbit Dynamics/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791562168/aura-registrations/id-cards/vsjgfkta5yzfiwiz7nw4.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Qbit Dynamics/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791562168/aura-registrations/id-cards/efcpf1prplqpu1p1nvyi.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Qbit Dynamics/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791562168/aura-registrations/id-cards/vybrxmp7uqxwsewvufom.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Qbit Dynamics/4.jpg", "url": null, "exists": false }] }, { "index": 35, "id": "6ac9ed272799adf946c2f0b2", "registrationId": "AURA2K26-3GKLD6", "rawTeamName": "Jeevan Dhara", "folderName": "Jeevan Dhara", "folderRelPath": "assets/Teams/Jeevan Dhara", "projectTitle": "Jeevan Drop", "teamSize": 3, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 3, "teamLeaderName": "Sharukh Khan", "teamLeaderEmail": "41.o.sharukhkhan@gmail.com", "teamLeaderPhone": "7477750144", "teamMemberDetails": "Abhirup Chakraborty | Institute of Engineering & Management, Kolkata | Mechanical Engineering | 4th | 9831148603\r\nSiddharth | Insttitute of Engineering & Management, Kolkata | Mechanical Engineering | 4th | 7033177666", "hardwareProjectCategories": ["Mechanical Systems"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "The present problem statement focuses on the destruction of the infrastructure that provides clean drinking water along with the health problem which occurs due to the same in flood plains prone to flooding. These areas, where moving rivers loaded with a lot of sediment coming from the mountains pass through, experience destruction every year because of the extreme weather conditions prevailing upstream. The main problem arises in its very beginning when the water starts flooding into the region and causes problems for millions of people living there, making it impossible for them to cope with the situation. The five key issues are the following: Total Infrastructure Flooding: There is total destruction of the primary water infrastructure. The existing water sources like hand pumps, wells, and ponds are all totally flooded, structurally damaged, or clogged with thick silt. Hence, there is no source of safe drinking water for the displaced population who often have to drink contaminated water for survival. Extreme Biological Contamination: The biological contamination of the available surface water becomes extremely toxic. Flooded open defecation sites and sewage systems result in high pathogen load in the standing pools of water. Since the desperate populations are using this water for drinking and sanitation purposes, there is rampant spread of deadly waterborne diseases like cholera, typhoid, acute diarrhea, and hepatitis. Turbidity Challenges: The specific nature of these flood waters makes it impossible to purify the water through the traditional methods. Since the flood waters come from mountainous rivers, there is heavy sediment and silt load which results in extremely high turbidity. Grid Dependent Paralysis: Due to infrastructure dependency, there is absolute systemic paralysis. In every instance of disasters, there are power blackouts which will stop the working of all piped water systems and the municipal mechanical pumps. All water purification and distribution systems which use electricity grid become paralyzed. Relief and Economic Constraints: Economic constraints and stretched logistics in disaster relief result in the population being stranded. In every emergency relief camp, there is no enough amount of clean water. Moreover, the technology of water purification which can filter water for drinking purposes is expensive. Thus, there is a dire need for developing a cheap and highly durable method of water purification system that does not require any electricity but at the same time is effective in purifying highly turbid water and removing deadly biological pathogens.", "solutionDescription": "The present problem statement focuses on the destruction of the infrastructure that provides clean drinking water along with the health problem which occurs due to the same in flood plains prone to flooding. These areas, where moving rivers loaded with a lot of sediment coming from the mountains pass through, experience destruction every year because of the extreme weather conditions prevailing upstream. The main problem arises in its very beginning when the water starts flooding into the region and causes problems for millions of people living there, making it impossible for them to cope with the situation. The five key issues are the following: Total Infrastructure Flooding: There is total destruction of the primary water infrastructure. The existing water sources like hand pumps, wells, and ponds are all totally flooded, structurally damaged, or clogged with thick silt. Hence, there is no source of safe drinking water for the displaced population who often have to drink contaminated water for survival. Extreme Biological Contamination: The biological contamination of the available surface water becomes extremely toxic. Flooded open defecation sites and sewage systems result in high pathogen load in the standing pools of water. Since the desperate populations are using this water for drinking and sanitation purposes, there is rampant spread of deadly waterborne diseases like cholera, typhoid, acute diarrhea, and hepatitis. Turbidity Challenges: The specific nature of these flood waters makes it impossible to purify the water through the traditional methods. Since the flood waters come from mountainous rivers, there is heavy sediment and silt load which results in extremely high turbidity. Grid Dependent Paralysis: Due to infrastructure dependency, there is absolute systemic paralysis. In every instance of disasters, there are power blackouts which will stop the working of all piped water systems and the municipal mechanical pumps. All water purification and distribution systems which use electricity grid become paralyzed. Relief and Economic Constraints: Economic constraints and stretched logistics in disaster relief result in the population being stranded. In every emergency relief camp, there is no enough amount of clean water. Moreover, the technology of water purification which can filter water for drinking purposes is expensive. Thus, there is a dire need for developing a cheap and highly durable method of water purification system that does not require any electricity but at the same time is effective in purifying highly turbid water and removing deadly biological pathogens.", "innovationDescription": "The present problem statement focuses on the destruction of the infrastructure that provides clean drinking water along with the health problem which occurs due to the same in flood plains prone to flooding. These areas, where moving rivers loaded with a lot of sediment coming from the mountains pass through, experience destruction every year because of the extreme weather conditions prevailing upstream. The main problem arises in its very beginning when the water starts flooding into the region and causes problems for millions of people living there, making it impossible for them to cope with the situation. The five key issues are the following: Total Infrastructure Flooding: There is total destruction of the primary water infrastructure. The existing water sources like hand pumps, wells, and ponds are all totally flooded, structurally damaged, or clogged with thick silt. Hence, there is no source of safe drinking water for the displaced population who often have to drink contaminated water for survival. Extreme Biological Contamination: The biological contamination of the available surface water becomes extremely toxic. Flooded open defecation sites and sewage systems result in high pathogen load in the standing pools of water. Since the desperate populations are using this water for drinking and sanitation purposes, there is rampant spread of deadly waterborne diseases like cholera, typhoid, acute diarrhea, and hepatitis. Turbidity Challenges: The specific nature of these flood waters makes it impossible to purify the water through the traditional methods. Since the flood waters come from mountainous rivers, there is heavy sediment and silt load which results in extremely high turbidity. Grid Dependent Paralysis: Due to infrastructure dependency, there is absolute systemic paralysis. In every instance of disasters, there are power blackouts which will stop the working of all piped water systems and the municipal mechanical pumps. All water purification and distribution systems which use electricity grid become paralyzed. Relief and Economic Constraints: Economic constraints and stretched logistics in disaster relief result in the population being stranded. In every emergency relief camp, there is no enough amount of clean water. Moreover, the technology of water purification which can filter water for drinking purposes is expensive. Thus, there is a dire need for developing a cheap and highly durable method of water purification system that does not require any electricity but at the same time is effective in purifying highly turbid water and removing deadly biological pathogens.", "workingPrinciple": "There’s nothing complicated happening inside JEEVAN-DROP, just gravity doing all the work. You fit the rubber-grip connector onto a tap or a raised dispenser, and from there, water simply flows downward through three stacked filtration layers, no electricity or pumps needed. First, it passes through a polypropylene mesh that catches the mud, silt, and sand, the kind of thick sediment you’d expect in floodwater. This step matters more than it sounds, because without it, the finer layers below would clog almost instantly. Next, the water moves through activated carbon, which doesn’t strain out particles so much as pull contaminants onto its surface: chlorine, pesticides, and the smells and off-tastes that make murky water hard to drink. The real heart of the system, though, is the last stage: a 0.2-micron ceramic disc paired with maifan mineral balls. The ceramic’s pores are so fine that bacteria and parasites simply can’t fit through; they’re blocked by size alone, not killed with chemicals. And while that’s happening, the mineral balls are quietly doing something different, releasing small amounts of calcium, magnesium, and potassium into the water, which brings the pH into a healthy range and makes the water taste like water again, not like a filter. By the time it reaches the spout, the water has been cleaned three separate ways, physically, chemically, and biologically, without the person using it having to do anything at all.", "majorHardwareComponents": ["Rubber-Grip Connector – Fits onto a tap or raised dispenser; creates a leak-free", "gravity-fed inlet without needing electricity or tools.\nPP Mesh Pre-filter – A woven polypropylene mesh that mechanically strains out mud", "silt", "sand", "and suspended solids before water reaches the finer stages.\nActivated Carbon Filter – Works through adsorption; removes chlorine", "pesticides", "volatile organic compounds", "and odour-causing substances that affect taste and smell.\nCeramic Disc (0.2-micron) – The core microbial barrier; its fine pore structure physically blocks bacteria and parasites through size-exclusion", "without using any chemicals.\nMaifan Mineral Balls – Placed alongside the ceramic disc; slowly release trace calcium", "magnesium", "and potassium to naturally stabilize pH (7.0–8.5) and improve taste.\n3D-Printed Housing – The outer cartridge body", "printed in food-safe PLA/PETG; holds all three filtration stages in a compact", "stacked", "field-replaceable structure.\nTogether", "these components form a self-contained", "modular filtration unit: each part is either a purchasable", "market-sourced media (mesh", "carbon", "ceramic", "minerals) or a 3D-printed structural piece", "making the design both low-cost and easy to repair or upgrade in the field."], "useAi": false, "useIot": false, "powerSource": "other", "intendedBeneficiaries": ["Rural Communities", "Government / Public Services", "General Public"], "potentialImpact": "If this actually reaches the field, the difference it could make isn’t abstract, it’s immediate. Picture a family in North Bihar during the monsoon, their hand pump underwater, their only option a stretch of muddy floodwater outside their door, where the choices are grim: drink it anyway and risk cholera or typhoid, wait for a relief truck that might not come in time, or try to boil water with firewood that’s already soaked through. JEEVAN-DROP changes that equation, since clipping it onto whatever tap or water point is still standing turns that same contaminated water into something safe to give a child within seconds. What makes this matter isn’t just the filtration, it’s the price: at around ₹120 a unit, this isn’t a device for the few who can afford imported filters costing ten times as much, but one built for mass distribution, the kind relief agencies could actually hand out by the hundreds, not the dozens, needing no electricity, no spare parts, and no training manual, just gravity and three honest layers of filtration doing their job. Beyond the immediate relief, there’s a longer-term shift worth imagining too, fewer diarrheal deaths, fewer overwhelmed health camps, fewer families forced to choose between thirst and sickness. It’s a small, inexpensive object, but in the middle of a flood, when every other system has failed, something this simple might be exactly what people need most.", "productPotential": "yes", "prototypeDevelopmentCost": 120, "auraDemoHighlight": "This prototype is unique on it's own, because it is made for community service and at a very low and affordable cost. Moreover, this filter is a gravity based filteration system, which means it doesn't require any type of fuel or energy to work, fetch your water pass it through the filter and you have your clean water, it can attach to any tap opening, with a help of a rubber grip, helping in filteration directly through water barels and dispensers.", "safetyHazards": ["none"], "safetyPrecautions": "We kept things careful at every step of putting this together. Once a part came off the printer, it got washed properly before any filter media went in, just to make sure no dust or leftover bits of plastic ended up somewhere they shouldn’t. We ran our hands over every edge and joint, especially around the interlocking lip, since that’s the bit people will actually be touching and twisting each time they swap a cartridge, and nobody should have to deal with a rough or sharp edge there. The seals between the three layers got extra attention too, because if one of those seals is even slightly loose, water starts sneaking past the filters instead of going through them, which kind of defeats the whole point of building this in the first place. We also made sure everything slides apart and locks back together smoothly, so a person using this in the middle of a flood doesn’t need a tool or any real strength to open it up. That said, we’re not pretending this is a finished, certified product yet. Right now it’s a working prototype built to prove the idea holds up. Getting it properly lab-tested and certified is the next real step before anyone should trust it for everyday drinking water.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T07:45:43.178Z", "updatedAt": "2026-10-14T18:49:14.853Z", "abstract": { "originalName": "JEEVAN DHARA.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791618342/aura-registrations/abstract-docs/JEEVAN%20DHARA.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Jeevan Dhara/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Jeevan Dhara/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791618342/aura-registrations/id-cards/juddcsxx6wstjfxc30he.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Jeevan Dhara/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791618342/aura-registrations/id-cards/tvyiklzeb1frzhvez8ah.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Jeevan Dhara/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791618342/aura-registrations/id-cards/io6a0cq1zklgpmqjgzhe.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Jeevan Dhara/4.jpg", "url": null, "exists": false }] }, { "index": 36, "id": "6aca21730db23efcd0d9febf", "registrationId": "AURA2K26-R5NSSP", "rawTeamName": "MECHARON", "folderName": "MECHARON", "folderRelPath": "assets/Teams/MECHARON", "projectTitle": "Intravascular Micro-Sieve System for Localized Drug Delivery and Target Particle Capture (IMS-LDD-TPC)", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Mir Md Minhaajuddin", "teamLeaderEmail": "mirmdminhaajuddin20@gmail.com", "teamLeaderPhone": "7431916507", "teamMemberDetails": "Jiaul Haque | Aliah University | Dept of MEN | PhD | +91 98001 11975\r\nMahabub Alam | Aliah University | Dept of MEN | UG 4th Year | +91 94751 83884\r\nSafiur Rahman | Aliah University | Dept of MEN | UG 4th Year | +91 7645 897 396", "hardwareProjectCategories": ["Biomedical / Healthcare Devices"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "In modern medical science to treat Cancer, conventional systemic drug administration distributes therapeutic agents throughout the body, potentially exposing healthy tissues to undesirable side effects. Localized drug delivery aims to concentrate therapeutic action near the intended target. Additionally, selective capture of target particles while maintaining continuous fluid flow presents an engineering challenge.\r\n\r\nThe proposed Intravascular Micro-Sieve System for Localized Drug Delivery and Target Particle Capture (IMS-LDD-TPC) is a laboratory-scale hardware concept integrating localized model-drug release and selective particle retention within a compact, retrievable intravascular device. The system comprises an Intravascular Micro-Cage (IMC), a drug-carrier capsule, an external ultrasonic transducer, and a controlled-flow experimental setup using transparent IV tubing to simulate a vessel. Acoustic excitation is proposed to induce capsule vibration and release a model agent, such as coloured water, near the target region. A mesh-covered cage with proposed one-way capture valves is designed to retain suitably sized target particles while permitting fluid passage.\r\n\r\nThe key innovation is integrating acoustic-actuated localized release, physical particle capture, continuous flow, and device retrievability into a single conceptual engineering platform. The prototype will be experimentally evaluated for release behaviour, particle retention, flow continuity, and retrieval feasibility. The project aims to establish the engineering feasibility and identify design limitations for future optimization and research.", "solutionDescription": "In modern medical science to treat Cancer, conventional systemic drug administration distributes therapeutic agents throughout the body, potentially exposing healthy tissues to undesirable side effects. Localized drug delivery aims to concentrate therapeutic action near the intended target. Additionally, selective capture of target particles while maintaining continuous fluid flow presents an engineering challenge.\r\n\r\nThe proposed Intravascular Micro-Sieve System for Localized Drug Delivery and Target Particle Capture (IMS-LDD-TPC) is a laboratory-scale hardware concept integrating localized model-drug release and selective particle retention within a compact, retrievable intravascular device. The system comprises an Intravascular Micro-Cage (IMC), a drug-carrier capsule, an external ultrasonic transducer, and a controlled-flow experimental setup using transparent IV tubing to simulate a vessel. Acoustic excitation is proposed to induce capsule vibration and release a model agent, such as coloured water, near the target region. A mesh-covered cage with proposed one-way capture valves is designed to retain suitably sized target particles while permitting fluid passage.\r\n\r\nThe key innovation is integrating acoustic-actuated localized release, physical particle capture, continuous flow, and device retrievability into a single conceptual engineering platform. The prototype will be experimentally evaluated for release behaviour, particle retention, flow continuity, and retrieval feasibility. The project aims to establish the engineering feasibility and identify design limitations for future optimization and research.", "innovationDescription": "In modern medical science to treat Cancer, conventional systemic drug administration distributes therapeutic agents throughout the body, potentially exposing healthy tissues to undesirable side effects. Localized drug delivery aims to concentrate therapeutic action near the intended target. Additionally, selective capture of target particles while maintaining continuous fluid flow presents an engineering challenge.\r\n\r\nThe proposed Intravascular Micro-Sieve System for Localized Drug Delivery and Target Particle Capture (IMS-LDD-TPC) is a laboratory-scale hardware concept integrating localized model-drug release and selective particle retention within a compact, retrievable intravascular device. The system comprises an Intravascular Micro-Cage (IMC), a drug-carrier capsule, an external ultrasonic transducer, and a controlled-flow experimental setup using transparent IV tubing to simulate a vessel. Acoustic excitation is proposed to induce capsule vibration and release a model agent, such as coloured water, near the target region. A mesh-covered cage with proposed one-way capture valves is designed to retain suitably sized target particles while permitting fluid passage.\r\n\r\nThe key innovation is integrating acoustic-actuated localized release, physical particle capture, continuous flow, and device retrievability into a single conceptual engineering platform. The prototype will be experimentally evaluated for release behaviour, particle retention, flow continuity, and retrieval feasibility. The project aims to establish the engineering feasibility and identify design limitations for future optimization and research.", "workingPrinciple": "The system uses a controlled-flow experimental setup to simulate an intravascular environment. A pump circulates water or saline through transparent IV tubing containing a retrievable Intravascular Micro-Cage (IMC). The cage houses a drug-carrier capsule and incorporates fine mesh surfaces with proposed inward-facing one-way capture valves. An external ultrasonic transducer applies acoustic excitation to induce capsule vibration and investigate localized release of a model agent, such as coloured water. During flow, suitably sized model target particles are intended to enter and remain within the cage, while the working fluid and smaller particles pass through.", "majorHardwareComponents": ["1. Transparent IV tubing to simulate a blood vessel.\n2. Miniature pump and reservoir for controlled continuous flow.\n3. Intravascular Micro-Cage (IMC) with fine-mesh surfaces and proposed one-way capture valves (Will be made by our team).\n4. Drug-carrier capsule containing a model agent", "such as coloured water.\n5. External ultrasonic transducer and its driving circuit.\n6. Model target particles of selected sizes.\n7. Connecting rods", "cage supports", "and retrieval mechanism.\n8. Suitable tubing connectors", "seals", "and mounting components."], "useAi": false, "useIot": false, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["Healthcare"], "potentialImpact": "The proposed system explores an engineering approach to localized drug delivery and selective particle retention. If successfully developed and validated, the concept could inform future research into devices that combine localized therapeutic release with physical capture of selected particles. The laboratory prototype will help assess the feasibility and limitations of integrating acoustic actuation, porous structures, controlled fluid flow, and retrieval in a compact system. Its immediate value lies in experimental learning and proof-of-concept development, rather than direct clinical application. Further research, biocompatibility testing, and safety validation would be essential before any medical use.", "productPotential": "potentially", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "IMS-LDD-TPC combines several mechanical and biomedical engineering principles in one compact, retrievable hardware concept. Its distinctive feature is the proposed integration of acoustic-actuated model-drug release, a mesh-covered micro-cage with one-way particle-capture valves, and continuous fluid passage. The prototype offers a tangible demonstration of how advanced microfabrication, acoustics, fluid mechanics, and device design can work together to address a complex engineering challenge. Rather than relying solely on simulation, the project aims to evaluate the concept through a physical laboratory-scale setup and identify practical design limitations for future improvement.", "safetyHazards": ["moving_rotating_machinery", "water_near_electrical_equipment"], "safetyPrecautions": "The prototype is intended for laboratory demonstration only and will use water or saline as the working fluid, along with non-hazardous model particles and a coloured-water surrogate instead of actual drugs or biological samples. The fluid circuit will be checked for leakage and connections secured before operation. Electrical components, including the pump and ultrasonic driver, will be kept away from liquid and operated using appropriate power ratings and insulation. Acoustic actuation will be performed at controlled settings, avoiding direct contact with the transducer during operation. The prototype will be tested on a stable work surface. The device is not intended for use inside a human or animal body.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T11:28:51.142Z", "updatedAt": "2026-10-14T18:49:19.408Z", "abstract": { "originalName": "IMS-LDD-TPC.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791631729/aura-registrations/abstract-docs/IMS-LDD-TPC.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/MECHARON/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/MECHARON/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791631729/aura-registrations/id-cards/avyfpcm1ehtm0ljkeckw.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/MECHARON/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791631729/aura-registrations/id-cards/lrlespcbppwvvksinkpd.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/MECHARON/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791631730/aura-registrations/id-cards/l2v6kfr1mblipk7pwg7f.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/MECHARON/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791631729/aura-registrations/id-cards/jqiwey32i5yyxm4tdqs8.jpg", "exists": true }] }, { "index": 37, "id": "6aca410375e4e48d9cf8569a", "registrationId": "AURA2K26-TA83X9", "rawTeamName": "Team Guardian", "folderName": "Team Guardian", "folderRelPath": "assets/Teams/Team Guardian", "projectTitle": "Classroom Energy guardian-Detect empty classrooms and automatically manages light/fan", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Afreen Kainat", "teamLeaderEmail": "akainat723@gmail.com", "teamLeaderPhone": "8902584073", "teamMemberDetails": "MD MINHAJ HUSSAIN\r\nAliah university \r\nElectronic and communication department \r\n1st year \r\n9007066165\r\nSk Avan Aktar\r\nAliah University \r\nElectrical department \r\n1st year\r\n8918094707\r\nSWEETY PATRA \r\nAliah University \r\nElectrical department \r\n1st year \r\n6295298095", "hardwareProjectCategories": ["Electrical Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "*The Problem* \r\nSchools waste a massive amount of electricity every day. Students and teachers frequently forget to turn off lights, fans,  when they leave for lunch, recess, or at the end of the day. While smart building systems can fix this, they usually require complex computer programming, stable Wi-Fi networks, and constant software updates. For many schools, these high-tech systems are simply too expensive, difficult to install, and hard to maintain.\r\n *The Solution* \r\nThe Classroom Energy Guardian fixes this problem using a *100% offline* ,  and *zero-Wi-Fi* approach. Instead of using smart computers or apps, it relies on rugged, standalone motion sensors installed directly into the classroom ceiling. These sensors act like automated light switches. When they detect people moving, they keep the power on. When the room is empty, they automatically cut the power. To protect  from damage caused by sudden shutting off and on, a heavy-duty electrical switch (called a contactor) is used alongside a built-in time delay.\r\n *The Innovation* \r\nThe true innovation of this project is its low-tech, plug-and-play simplicity. It achieves the exact same energy savings as a high-tech smart school without needing a single line of code or an internet connection. Adjustments are made easily using small, physical dials right on the sensor. It even features a built-in daylight sensor, meaning the lights will stay off if the sun is already keeping the room bright, saving even more power. By removing the need for Wi-Fi and programming, this system creates an affordable, fail-safe solution that any local electrician can install. It instantly *cuts school electricity bills by up to 40%* with absolutely zero software maintenance.", "solutionDescription": "*The Problem* \r\nSchools waste a massive amount of electricity every day. Students and teachers frequently forget to turn off lights, fans,  when they leave for lunch, recess, or at the end of the day. While smart building systems can fix this, they usually require complex computer programming, stable Wi-Fi networks, and constant software updates. For many schools, these high-tech systems are simply too expensive, difficult to install, and hard to maintain.\r\n *The Solution* \r\nThe Classroom Energy Guardian fixes this problem using a *100% offline* ,  and *zero-Wi-Fi* approach. Instead of using smart computers or apps, it relies on rugged, standalone motion sensors installed directly into the classroom ceiling. These sensors act like automated light switches. When they detect people moving, they keep the power on. When the room is empty, they automatically cut the power. To protect  from damage caused by sudden shutting off and on, a heavy-duty electrical switch (called a contactor) is used alongside a built-in time delay.\r\n *The Innovation* \r\nThe true innovation of this project is its low-tech, plug-and-play simplicity. It achieves the exact same energy savings as a high-tech smart school without needing a single line of code or an internet connection. Adjustments are made easily using small, physical dials right on the sensor. It even features a built-in daylight sensor, meaning the lights will stay off if the sun is already keeping the room bright, saving even more power. By removing the need for Wi-Fi and programming, this system creates an affordable, fail-safe solution that any local electrician can install. It instantly *cuts school electricity bills by up to 40%* with absolutely zero software maintenance.", "innovationDescription": "*The Problem* \r\nSchools waste a massive amount of electricity every day. Students and teachers frequently forget to turn off lights, fans,  when they leave for lunch, recess, or at the end of the day. While smart building systems can fix this, they usually require complex computer programming, stable Wi-Fi networks, and constant software updates. For many schools, these high-tech systems are simply too expensive, difficult to install, and hard to maintain.\r\n *The Solution* \r\nThe Classroom Energy Guardian fixes this problem using a *100% offline* ,  and *zero-Wi-Fi* approach. Instead of using smart computers or apps, it relies on rugged, standalone motion sensors installed directly into the classroom ceiling. These sensors act like automated light switches. When they detect people moving, they keep the power on. When the room is empty, they automatically cut the power. To protect  from damage caused by sudden shutting off and on, a heavy-duty electrical switch (called a contactor) is used alongside a built-in time delay.\r\n *The Innovation* \r\nThe true innovation of this project is its low-tech, plug-and-play simplicity. It achieves the exact same energy savings as a high-tech smart school without needing a single line of code or an internet connection. Adjustments are made easily using small, physical dials right on the sensor. It even features a built-in daylight sensor, meaning the lights will stay off if the sun is already keeping the room bright, saving even more power. By removing the need for Wi-Fi and programming, this system creates an affordable, fail-safe solution that any local electrician can install. It instantly *cuts school electricity bills by up to 40%* with absolutely zero software maintenance.", "workingPrinciple": "The system switches the classroom light, fan, and projector on when people are present and off when the room stays empty. An ESP32 board controls everything.\r\nA PIR (Passive Infrared) sensor is fixed inside the room. Every warm body gives out infrared radiation. When a person moves, the infrared reaching the sensor changes, and the sensor sends a HIGH signal to the ESP32. With no movement, the signal stays LOW.\r\nEach time motion is detected, the ESP32 restarts a timer and keeps the room marked as occupied. A relay module, which is an electrically controlled switch, keeps the light, fan, and projector powered.\r\nIf no motion is detected for a set time, for example 5 minutes, the ESP32 sounds a buzzer as a warning. Pressing a cancel button or moving restarts the timer. Otherwise, the ESP32 switches the relays off and the appliances lose power. When the PIR senses movement again, everything switches back on.\r\nAn INA219 sensor measures the voltage and current of the loads to calculate energy used and saved. A 12 V adapter powers the loads, and an LM2596 converter steps it down to 5 V for the ESP32, PIR, and relay.", "majorHardwareComponents": ["ESP32 board: the main controller. It reads the sensor", "runs the timer", "and controls the relays.\n\nPIR sensor (HC-SR501): detects human movement by sensing changes in infrared radiation.\n\n4-channel relay module: an electrically controlled switch that turns the light", "fan", "and projector on or off.\n\nINA219 power sensor: measures the voltage and current of the loads to calculate energy used and saved.\n\nActive buzzer: gives a warning beep before shutdown.\n\nPush button: cancels the shutdown during the warning period.\nLEDs and resistors: show the system state: occupied", "warning", "or empty.\n\n12 V 3 A DC adapter: powers the loads and the electronics.\nLM2596 buck\n\nconverter: steps 12 V down to 5 V for the ESP32", "PIR", "and relay.\n470 µF capacitor: keeps the 5 V supply steady so relay clicks don't reset the ESP32.\nInline fuse: protects the circuit from a short circuit.\n\nBreadboard", "jumper wires", "hookup wire", "and terminal blocks: make the electrical connections."], "useAi": false, "useIot": false, "powerSource": "ac_supply", "intendedBeneficiaries": ["Education", "Government / Public Services", "Industry"], "potentialImpact": "Classrooms often leave lights and fans running when nobody is inside. The Classroom Energy Guardian removes this waste automatically, without relying on teachers or students to remember.\r\n\r\nEnvironmental impact: Switching off appliances in empty rooms cuts unnecessary electricity use, which lowers grid demand and the institution's carbon footprint. As a visible example of green technology, it also teaches students the value of saving energy and builds a habit of conservation.\r\n\r\nEconomic impact: Lighting and cooling make up a large part of a school's electricity bill, so reducing idle running time lowers costs. Fans and light fixtures also run fewer hours, which reduces wear and delays replacement, cutting maintenance spending. The hardware, such as a PIR sensor and a microcontroller, is inexpensive, so the investment can be recovered in a short time.\r\n\r\nTechnical potential: The system can grow from a standalone unit into a connected network that sends occupancy and energy data from every classroom to a central dashboard, so administrators can see where energy is being wasted. Over time, this data can show usage patterns that help schedule lighting and cooling better. The same sensor could also support after-hours intrusion alerts.\r\n\r\nMarket potential: Most schools cannot afford to rewire their buildings, so an easy-to-install, modular retrofit unit suits them well. It also fits smart campus and energy-saving initiatives, and can be installed one classroom at a time as budgets allow.", "productPotential": "yes", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "⚡ Automatic Energy Saving: Prevents electricity wastage caused by lights and fans being left ON.\r\n👀 Smart Occupancy Detection: Detects whether people are present inside the classroom.\r\n🤖 Automatic Control: Reduces the need for manual switching of electrical appliances.\r\n💰 Cost Saving: Lower unnecessary electricity consumption can reduce electricity bills.\r\n🌱 Eco-Friendly: Helps reduce energy wastage and supports a greener campus.\r\n🏫 Real-World Application: Can be implemented in classrooms, laboratories, offices, libraries, and other institutional spaces.\r\n\r\n• The Problem It Solves: Standard automatic sensors immediately cut the lights and fans when they don't see movement, which can leave students stuck in the dark if they sit completely still during a quiet exam or study session.\r\n• The Warning State: Instead of shutting down instantly when the 5-minute timer hits zero, the controller first sounds an audible buzzer alarm. This serves as a clear audio warning that the system thinks the room is empty.\r\n•  When a person hears the buzzer, they have two ways to keep the power on without needing a mobile app or programming:\r\n\t*Wave their hands or stand up so the sensor catches their movement.\r\n\tOr * physically tap a manual \"Cancel\" button on the wall or switchboard.\r\n\r\nWhy worth seeing?\r\nBecause this project converts a common everyday problem—electricity wastage in empty classrooms—into an automatic, practical, and sustainable solution. It combines automation, energy efficiency, and real-world usefulness in one simple system", "safetyHazards": ["none"], "safetyPrecautions": "Low-voltage design: We built the prototype on a 12 V DC supply and used no mains (230 V) wiring, so there was no shock risk during building or testing.\r\nFuse protection: An inline fuse was added to the power line to cut the supply in case of a short circuit.\r\nVoltage check: Before connecting the ESP32, PIR sensor, and relay, we set the LM2596 converter to exactly 5 V using a multimeter.\r\nPower off while wiring: We changed connections only when the circuit was unplugged.\r\nStep-by-step testing: Each part (PIR sensor, relay, power sensor) was tested separately with small loads before everything was connected together.\r\nIsolated relay: We used an optocoupler-isolated relay module and kept every load within its rating.\r\nStable supply: A capacitor was added across the 5 V supply, and a common ground was used, to prevent resets and unstable behaviour.\r\nInsulation and neat wiring: Connections were made with terminal blocks and insulation tape or heat shrink, and wires were routed away from the fan blades.\r\nFire safety: The model classroom is made of foam board, so hot parts and loose wires were kept clear of it, and the circuit was never left running unattended.\r\nSoldering safety: Soldering was done in a ventilated area with the iron resting on a stand.\r\nDry workspace: Liquids were kept away from the electronics.\r\nSafe failure design: A warning buzzer sounds before shutdown, and a cancel button and manual override are included.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T13:43:31.115Z", "updatedAt": "2026-10-14T18:49:23.595Z", "abstract": { "originalName": "Classroom Energy guardian-Detect empty classrooms and automatically manages_20261009_141522_0000.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791639810/aura-registrations/abstract-docs/Classroom%20Energy%20guardian-Detect%20empty%20classrooms%20and%20automatically%20manages_20261009_141522_0000.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Team Guardian/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Team Guardian/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791639810/aura-registrations/id-cards/pm47yfmnrcxg3c6ssdoa.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Team Guardian/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791639810/aura-registrations/id-cards/lusibixb2fhcd1xf4vxq.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Team Guardian/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791639810/aura-registrations/id-cards/peps7gk2rfkjrywv4oaj.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Team Guardian/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791639810/aura-registrations/id-cards/snivp1ojvzh6ctwkwne2.jpg", "exists": true }] }, { "index": 38, "id": "6aca5491ee87b3781d9500fc", "registrationId": "AURA2K26-JBZM7D", "rawTeamName": "Alexandrians", "folderName": "Alexandrians", "folderRelPath": "assets/Teams/Alexandrians", "projectTitle": "Low-Cost Human Following Robot Using Shielded Dual-ESP32 Wi-Fi RSSI Sensing", "teamSize": 3, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 3, "teamLeaderName": "Shambo Ghosh", "teamLeaderEmail": "shamboghosh786@gmail.com", "teamLeaderPhone": "7908920876", "teamMemberDetails": "Sayani Naha | Academy of Technology | ECE | 3rd | 9477733216\r\nSouvik Sil | Academy of Technology | ECE | 3rd | 8100089361", "hardwareProjectCategories": ["Robotics", "IoT & Smart Devices", "Electronics & Communication", "Embedded Systems", "Mechatronics", "Automation & Control"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem: Manual load carrying is a major part of work in warehouses, farms, hospitals, and for porters, especially in developing countries. Existing human-following robots rely on cameras, LiDAR, or heavy computation, making them expensive and power-hungry. Earlier low-cost Wi-Fi RSSI followers are simple but unreliable: noisy signals, left-right readings that flip at distance, and short operating range.\r\n\r\nSolution: We build a low-cost human-following robot that uses Wi-Fi RSSI from the user’s phone. Two ESP32 nodes at the robot’s left and right sides measure signal strength, and a third ESP32 controls the motors through two BTS7960 drivers. The robot steers toward the stronger signal, stops when the user is near, and moves forward when the user is far.\r\n\r\nInnovation: (1) A metal shield between the two antennas increases the left-right RSSI difference. (2) Median and moving-average filtering with a deadband and hysteresis removes jitter and false turns. (3) PWM-based differential steering gives smooth motion instead of abrupt turns. (4) A front distance sensor and signal-loss failsafe make it safe to use. (5) Upgraded hardware (ESP32 nodes, high-current drivers, 4S Li-ion pack) improves reliability. The system needs no camera or cloud, so it stays cheap, compact, and power-efficient, and the human makes route and obstacle decisions.", "solutionDescription": "Problem: Manual load carrying is a major part of work in warehouses, farms, hospitals, and for porters, especially in developing countries. Existing human-following robots rely on cameras, LiDAR, or heavy computation, making them expensive and power-hungry. Earlier low-cost Wi-Fi RSSI followers are simple but unreliable: noisy signals, left-right readings that flip at distance, and short operating range.\r\n\r\nSolution: We build a low-cost human-following robot that uses Wi-Fi RSSI from the user’s phone. Two ESP32 nodes at the robot’s left and right sides measure signal strength, and a third ESP32 controls the motors through two BTS7960 drivers. The robot steers toward the stronger signal, stops when the user is near, and moves forward when the user is far.\r\n\r\nInnovation: (1) A metal shield between the two antennas increases the left-right RSSI difference. (2) Median and moving-average filtering with a deadband and hysteresis removes jitter and false turns. (3) PWM-based differential steering gives smooth motion instead of abrupt turns. (4) A front distance sensor and signal-loss failsafe make it safe to use. (5) Upgraded hardware (ESP32 nodes, high-current drivers, 4S Li-ion pack) improves reliability. The system needs no camera or cloud, so it stays cheap, compact, and power-efficient, and the human makes route and obstacle decisions.", "innovationDescription": "Problem: Manual load carrying is a major part of work in warehouses, farms, hospitals, and for porters, especially in developing countries. Existing human-following robots rely on cameras, LiDAR, or heavy computation, making them expensive and power-hungry. Earlier low-cost Wi-Fi RSSI followers are simple but unreliable: noisy signals, left-right readings that flip at distance, and short operating range.\r\n\r\nSolution: We build a low-cost human-following robot that uses Wi-Fi RSSI from the user’s phone. Two ESP32 nodes at the robot’s left and right sides measure signal strength, and a third ESP32 controls the motors through two BTS7960 drivers. The robot steers toward the stronger signal, stops when the user is near, and moves forward when the user is far.\r\n\r\nInnovation: (1) A metal shield between the two antennas increases the left-right RSSI difference. (2) Median and moving-average filtering with a deadband and hysteresis removes jitter and false turns. (3) PWM-based differential steering gives smooth motion instead of abrupt turns. (4) A front distance sensor and signal-loss failsafe make it safe to use. (5) Upgraded hardware (ESP32 nodes, high-current drivers, 4S Li-ion pack) improves reliability. The system needs no camera or cloud, so it stays cheap, compact, and power-efficient, and the human makes route and obstacle decisions.", "workingPrinciple": "The user carries a phone hotspot (or a small ESP32 tag). Two ESP32 sensing nodes, mounted at the left and right extremes of the robot and separated by a metal shield, connect to it and measure Wi-Fi RSSI. A median filter followed by an exponential moving average removes noise. The left-right RSSI difference gives the user’s bearing, and the average RSSI gives approximate distance. A third ESP32, the main controller, receives both values over UART and applies a deadband with hysteresis to prevent jitter. If the left reading is stronger, the robot steers left; if the right is stronger, it steers right; if balanced but weak, it moves forward; if strong (user close), it stops. PWM signals drive two BTS7960 motor drivers for smooth differential steering with soft start and stop. A front ultrasonic/ToF sensor maintains a safe following distance and stops the robot at obstacles. If the RSSI signal is lost, the robot stops automatically. No camera or cloud is needed.", "majorHardwareComponents": ["3x ESP32 DevKit V1 (2 RSSI sensing nodes", "1 main controller)", "4x Johnson 300 RPM DC geared motors", "2x BTS7960 high-current motor drivers", "4S 18650 Li-ion battery pack", "buck converter (5 V logic supply)", "front ultrasonic/ToF distance sensor", "metal-shield partition between antennas", "4WD chassis", "power switch", "wiring and connectors."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "General Public", "Persons with Disabilities"], "potentialImpact": "A low-cost following robot can carry loads for people who do manual transport: warehouse workers, farmers, hospital staff, and porters. In India, where manual loading is common and labour is poorly paid, it reduces physical strain without changing existing work structure.\r\n\r\nIt can also support persons with disabilities and limited mobility. People who use crutches, walkers, or have reduced upper-body strength often cannot carry bags, tools, or shopping while moving. A robot that follows them hands-free can carry those items, which makes daily tasks, campus travel, and workplace movement more independent. The same applies to elderly users and in places like airports and hospitals.\r\n\r\nExisting human-following robots typically need cameras, LiDAR, or heavy computation, which raises cost. Our approach uses only Wi-Fi RSSI and microcontrollers, keeping the system affordable and low-power. The human makes route and obstacle decisions, so the robot needs no complex navigation. Dual-antenna shielding and filtering improve accuracy over earlier RSSI-only prototypes.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "The robot follows a person using only Wi-Fi signal strength, with no camera or heavy computing. We improve on a published RSSI follower by adding a metal shield between two ESP32 antennas to increase left-right signal contrast, real-time filtering with hysteresis, and PWM-based differential steering. The audience can walk in front of it and watch it track, turn, and stop on its own. We also present measured data (raw vs filtered signals, with and without the shield), showing the improvement. It’s a clear, hands-on demonstration of how low-cost RF sensing can solve a real mobility problem.", "safetyHazards": ["high_power_batteries"], "safetyPrecautions": "The battery wiring is insulated and secured inside the chassis. Motor speed is limited in software with soft start and stop. The robot stops automatically if the RSSI signal is lost or an obstacle is detected by the front sensor. Logic circuits run through a regulated buck converter with common ground, to prevent brownouts. Testing is done in an open space with supervision and a kill switch accessible. Wheels and wiring are kept clear of users.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T15:06:57.027Z", "updatedAt": "2026-10-14T18:49:27.866Z", "abstract": { "originalName": "Abstract_Human_Following_Robot.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791644816/aura-registrations/abstract-docs/Abstract_Human_Following_Robot.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Alexandrians/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Alexandrians/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791644816/aura-registrations/id-cards/cnjyejmwx3nn9hctrh3y.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Alexandrians/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791644815/aura-registrations/id-cards/fywl6e7uub7dl1y7n0kc.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Alexandrians/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791644815/aura-registrations/id-cards/rdrgy55ghcuycfyvznda.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Alexandrians/4.jpg", "url": null, "exists": false }] }, { "index": 39, "id": "6aca7795d56d2e9507ee24e2", "registrationId": "AURA2K26-VGMSU3", "rawTeamName": "The Innovation Squad", "folderName": "The Innovation Squad", "folderRelPath": "assets/Teams/The Innovation Squad", "projectTitle": "Distributed Edge-AI UAV and Ground Sensing IOT WSN Ecosystem for Multi-Tier Crop Health Analytics", "teamSize": 3, "teamAffiliation": "all_aliah", "aliahMembers": 3, "otherInstitutionMembers": 0, "teamLeaderName": "DEEPAN DEB", "teamLeaderEmail": "debdeepan448@gmail.com", "teamLeaderPhone": "9051338512", "teamMemberDetails": "1. Fatma Khatoon | Aliah University | Data Science | Masters 2nd Year | 9163289988\r\n2. Puspam Adak | Aliah University | Electrical Engineering | Masters 2nd Year | 8017787239", "hardwareProjectCategories": ["Robotics", "Embedded Systems", "IoT & Smart Devices", "Electronics & Communication", "AI-Enabled Hardware", "Smart Agriculture", "Drone / Autonomous Systems", "Other"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement :\r\n\r\n- Modern precision agriculture faces technical and economic barriers in multi-tier, full-spectrum vegetation diagnostics. Elite solutions, including multispectral drones and hyperspectral arrays, depend on high-latency cloud architectures, expensive computing payloads (NVIDIA Jetson), and complex, toxic manufacturing, making them unsuitable for resource-constrained farms. Cellular dead zones cause operational failures, while Lithium-Polymer (LiPo) batteries risk thermal runaway and field fires following crashes into mango canopies or dry wheat fields. Furthermore, disconnected aerial analytics and subsurface telemetry leave root-zone stress, nutrient lockout, and localized infestations undetected until crop damage occurs.\r\n\r\nProposed Solution\r\n\r\n- The proposed distributed, three-module Edge-AI Agritech Platform enables affordable precision scouting. The Airborne AI Analytics Payload uses an STM32 flight controller running real-time ArduPilot protocols, isolated from propulsion circuits through optocouplers. Its detachable payload combines an Arduino Nano ESP32 and Orange Pi 5 Pro with an integrated 6 TOPS NPU, running offline YOLOv26-Nano, MobileViTv2, and CoAtNet-0 models compiled using RKNN-Toolkit2 to identify canopy anomalies.\r\n\r\n- The Core Base Ground Module uses an Arduino Nano ESP32 with solderless I2C connections for capacitive soil moisture sensors, BME280 microclimate sensors, and TSL2591 high-dynamic-range light sensors.\r\n\r\n- The Plug-and-Play Sub-Surface Add-On Module integrates an ESP32-C6 coprocessor, RS485 Modbus-connected 7-in-1 NPK/pH/EC soil probe, and multi-depth capacitive moisture cross-validation array.\r\n\r\n- Ground nodes execute Python-based TinyML (TensorFlow Lite Micro) routines, compressing telemetry into a Health Index Vector transmitted through connectionless 2.4GHz ESP-NOW. The drone delivers unified analytical maps to offline smartphone applications through local Wi-Fi Access Point or Bluetooth Low Energy, using SQLite without cloud dependence.\r\n\r\nUnique Novel Innovation :\r\n\r\n- Four advancements distinguish this ecosystem:\r\n\r\na. Zero-Cloud Dual-Spectrum Edge Fusion combines MobileViTv2 aerial analysis with ground-based Python TinyML chemical pattern recognition, correlating canopy stress with subsurface NPK variations offline.\r\n\r\nb. Non-Explosive 3C LiFePO4 Power Dynamics replaces fire-prone LiPo batteries with stable Lithium Iron Phosphate (LiFePO4) 3C cells across aerial and ground modules, reducing combustion and thermal runaway risks.\r\n\r\nc. Connectionless Fly-By Data Gathering uses optimized ESP-NOW to collect compressed telemetry from multiple ground nodes mid-flight, minimizing wireless handshakes and conserving battery life.\r\n\r\nd. 100% Solderless, Safe-to-Touch Architecture employs pre-crimped JST-SH Qwiic, STEMMA QT, Gravity, and Grove interconnects, eliminating toxic lead fluxes and complex assembly tools for safer rural maintenance.", "solutionDescription": "Problem Statement :\r\n\r\n- Modern precision agriculture faces technical and economic barriers in multi-tier, full-spectrum vegetation diagnostics. Elite solutions, including multispectral drones and hyperspectral arrays, depend on high-latency cloud architectures, expensive computing payloads (NVIDIA Jetson), and complex, toxic manufacturing, making them unsuitable for resource-constrained farms. Cellular dead zones cause operational failures, while Lithium-Polymer (LiPo) batteries risk thermal runaway and field fires following crashes into mango canopies or dry wheat fields. Furthermore, disconnected aerial analytics and subsurface telemetry leave root-zone stress, nutrient lockout, and localized infestations undetected until crop damage occurs.\r\n\r\nProposed Solution\r\n\r\n- The proposed distributed, three-module Edge-AI Agritech Platform enables affordable precision scouting. The Airborne AI Analytics Payload uses an STM32 flight controller running real-time ArduPilot protocols, isolated from propulsion circuits through optocouplers. Its detachable payload combines an Arduino Nano ESP32 and Orange Pi 5 Pro with an integrated 6 TOPS NPU, running offline YOLOv26-Nano, MobileViTv2, and CoAtNet-0 models compiled using RKNN-Toolkit2 to identify canopy anomalies.\r\n\r\n- The Core Base Ground Module uses an Arduino Nano ESP32 with solderless I2C connections for capacitive soil moisture sensors, BME280 microclimate sensors, and TSL2591 high-dynamic-range light sensors.\r\n\r\n- The Plug-and-Play Sub-Surface Add-On Module integrates an ESP32-C6 coprocessor, RS485 Modbus-connected 7-in-1 NPK/pH/EC soil probe, and multi-depth capacitive moisture cross-validation array.\r\n\r\n- Ground nodes execute Python-based TinyML (TensorFlow Lite Micro) routines, compressing telemetry into a Health Index Vector transmitted through connectionless 2.4GHz ESP-NOW. The drone delivers unified analytical maps to offline smartphone applications through local Wi-Fi Access Point or Bluetooth Low Energy, using SQLite without cloud dependence.\r\n\r\nUnique Novel Innovation :\r\n\r\n- Four advancements distinguish this ecosystem:\r\n\r\na. Zero-Cloud Dual-Spectrum Edge Fusion combines MobileViTv2 aerial analysis with ground-based Python TinyML chemical pattern recognition, correlating canopy stress with subsurface NPK variations offline.\r\n\r\nb. Non-Explosive 3C LiFePO4 Power Dynamics replaces fire-prone LiPo batteries with stable Lithium Iron Phosphate (LiFePO4) 3C cells across aerial and ground modules, reducing combustion and thermal runaway risks.\r\n\r\nc. Connectionless Fly-By Data Gathering uses optimized ESP-NOW to collect compressed telemetry from multiple ground nodes mid-flight, minimizing wireless handshakes and conserving battery life.\r\n\r\nd. 100% Solderless, Safe-to-Touch Architecture employs pre-crimped JST-SH Qwiic, STEMMA QT, Gravity, and Grove interconnects, eliminating toxic lead fluxes and complex assembly tools for safer rural maintenance.", "innovationDescription": "Problem Statement :\r\n\r\n- Modern precision agriculture faces technical and economic barriers in multi-tier, full-spectrum vegetation diagnostics. Elite solutions, including multispectral drones and hyperspectral arrays, depend on high-latency cloud architectures, expensive computing payloads (NVIDIA Jetson), and complex, toxic manufacturing, making them unsuitable for resource-constrained farms. Cellular dead zones cause operational failures, while Lithium-Polymer (LiPo) batteries risk thermal runaway and field fires following crashes into mango canopies or dry wheat fields. Furthermore, disconnected aerial analytics and subsurface telemetry leave root-zone stress, nutrient lockout, and localized infestations undetected until crop damage occurs.\r\n\r\nProposed Solution\r\n\r\n- The proposed distributed, three-module Edge-AI Agritech Platform enables affordable precision scouting. The Airborne AI Analytics Payload uses an STM32 flight controller running real-time ArduPilot protocols, isolated from propulsion circuits through optocouplers. Its detachable payload combines an Arduino Nano ESP32 and Orange Pi 5 Pro with an integrated 6 TOPS NPU, running offline YOLOv26-Nano, MobileViTv2, and CoAtNet-0 models compiled using RKNN-Toolkit2 to identify canopy anomalies.\r\n\r\n- The Core Base Ground Module uses an Arduino Nano ESP32 with solderless I2C connections for capacitive soil moisture sensors, BME280 microclimate sensors, and TSL2591 high-dynamic-range light sensors.\r\n\r\n- The Plug-and-Play Sub-Surface Add-On Module integrates an ESP32-C6 coprocessor, RS485 Modbus-connected 7-in-1 NPK/pH/EC soil probe, and multi-depth capacitive moisture cross-validation array.\r\n\r\n- Ground nodes execute Python-based TinyML (TensorFlow Lite Micro) routines, compressing telemetry into a Health Index Vector transmitted through connectionless 2.4GHz ESP-NOW. The drone delivers unified analytical maps to offline smartphone applications through local Wi-Fi Access Point or Bluetooth Low Energy, using SQLite without cloud dependence.\r\n\r\nUnique Novel Innovation :\r\n\r\n- Four advancements distinguish this ecosystem:\r\n\r\na. Zero-Cloud Dual-Spectrum Edge Fusion combines MobileViTv2 aerial analysis with ground-based Python TinyML chemical pattern recognition, correlating canopy stress with subsurface NPK variations offline.\r\n\r\nb. Non-Explosive 3C LiFePO4 Power Dynamics replaces fire-prone LiPo batteries with stable Lithium Iron Phosphate (LiFePO4) 3C cells across aerial and ground modules, reducing combustion and thermal runaway risks.\r\n\r\nc. Connectionless Fly-By Data Gathering uses optimized ESP-NOW to collect compressed telemetry from multiple ground nodes mid-flight, minimizing wireless handshakes and conserving battery life.\r\n\r\nd. 100% Solderless, Safe-to-Touch Architecture employs pre-crimped JST-SH Qwiic, STEMMA QT, Gravity, and Grove interconnects, eliminating toxic lead fluxes and complex assembly tools for safer rural maintenance.", "workingPrinciple": "The system operates as a decentralized, cloud-independent edge-computing framework. The Core Ground Module uses an Arduino Nano ESP32 to continuously poll surface microclimate data through BME280, TSL2591, and STEMMA moisture sensors. The plug-and-play Add-On Module measures subsurface NPK chemical structures using an ESP32-C6 gateway over RS485 Modbus.\r\n\r\nGround nodes execute Python-based TinyML (TensorFlow Lite Micro) models to filter, clean, and compress multidimensional telemetry into a lightweight Health Index Vector, reducing bandwidth requirements.\r\n\r\nGround Telemetry + TinyML → (2.4GHz ESP-NOW) → UAV Payload Hub → (Hardware Serial) → Orange Pi 5 Pro NPU → Local Wi-Fi AP/BLE → Farmer Mobile App (SQLite)\r\n\r\nDuring scouting flights, the ground-level Arduino Nano ESP32 transmits compressed vector packets to the drone payload's receiving Arduino Nano ESP32 through a low-overhead, connectionless 2.4GHz ESP-NOW wireless uplink.\r\n\r\nThe payload hub streams ground telemetry through high-speed hardware serial to the Orange Pi 5 Pro companion computer. Its integrated 6 TOPS NPU executes a three-tier offline neural architecture comprising YOLOv26-Nano, MobileViTv2, and CoAtNet-0, dynamically cross-referencing camera frames with subsurface ground data.\r\n\r\nAfter processing, the Orange Pi 5 Pro generates a comprehensive field status report. Upon completing its route, the UAV payload operates as a local Wi-Fi Access Point/Bluetooth Low Energy gateway, transferring the final analytical map directly to the farmer's offline smartphone application. The application updates its internal SQLite database without requiring cloud infrastructure or internet connectivity.", "majorHardwareComponents": ["1. UAV Flight & Detachable AI Payload Module :\nUAV platform with dedicated STM32 F4/F7 flight controller running ArduPilot.\nArduino Nano ESP32 Wi-Fi payload sensor hub.\nOrange Pi 5 Pro with integrated 6 TOPS NPU and 256GB M.2 NVMe SSD.\nICM20948 9-axis IMU", "BME280 barometric sensor", "HC-SR04 ultrasonic sensor", "and Quectel L89HA Multi-GNSS module.\nRedundant flight and payload sensor matrices.\nBidirectional logic-level converters", "high-speed optocouplers", "shock resistors", "and antennas.\nLiFePO4 3C battery (3.2V", "19.2Wh)", "BMS", "and voltage step-down regulators.\n2. Core Base Ground Module :\nArduino Nano ESP32 telemetry hub running MicroPython-based TinyML scripts.\nAdafruit STEMMA Capacitive Soil Sensor (I2C).\n7semi BME280 microclimate sensor.\nAdafruit TSL2591 High Dynamic Range light sensor (STEMMA QT/I2C).\nLiFePO4 3C battery", "BMS", "voltage regulation", "and inline LC noise filters.\n3. Plug-and-Play Sub-Surface Add-On Module :\nWaveshare or Seeed Studio ESP32-C6 coprocessor with RS485 Modbus gateway.\n7-in-1 industrial soil probe measuring Nitrogen", "Phosphorus", "Potassium", "moisture", "electrical conductivity (EC)", "pH", "and temperature.\nSeeed Studio Grove Capacitive Moisture Sensor.\nCytron Maker Soil Moisture Sensor Kit.\nGravity V2.0 Capacitive Soil Moisture Sensor.\n\nIntegration Note: The Add-On Module connects directly to the Core Ground Module through a plug-and-play interface", "sharing its power system and communication infrastructure without requiring separate power supplies or independent wireless protocols."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Agriculture", "Rural Communities", "Other"], "potentialImpact": "1. Transforming Rural Digital Inclusion :\r\nZero-Cloud Field Independence: Operates entirely offline using local ESP-NOW communication and on-device SQLite mobile applications, bringing smart farming tools to remote regions without cellular infrastructure or internet access.\r\n2. Unlocking Multi-Tier Crop Yield Optimization :\r\nVertical Canopy Scaling: Combines aerial vision pipelines with subsurface NPK monitoring across tall fruit trees, such as mango, and low-ground crops, such as wheat, enabling early detection of nutrient deficiencies before visible crop damage.\r\n3. Advancing Sustainable Field Resource Management :\r\nPrecision Chemical Regulation: Provides immediate soil diagnostics to prevent over-fertilisation, reduce chemical input costs, protect groundwater from toxic runoff, and preserve long-term soil health.\r\n4. Setting New Standards for Field Hardware Safety :\r\nCombustion-Resistant Agritech Platforms: Uses stable LiFePO4 batteries to reduce field-fire risks associated with drone crashes into dry crops, protecting agricultural assets and lowering long-term operating costs through extended battery lifespan.\r\n5. Democratising Advanced Agricultural Tools :\r\nSolderless, Open-Source Maintenance: Employs a plug-and-play, non-toxic architecture that enables local technicians to repair modules without expensive equipment, reducing maintenance barriers for small-scale rural farmers.", "productPotential": "yes", "prototypeDevelopmentCost": 68000, "auraDemoHighlight": "Why the Judges Must See It :\r\n\r\nThis platform demonstrates production-ready engineering maturity by addressing critical hardware constraints: cost optimization and field safety. It avoids expensive, power-hungry computing equipment and cloud dependencies, instead using dual-loop microcontroller isolation, connectionless data routing, and non-toxic, completely solderless components. This architecture demonstrates that industrial-grade agricultural analytics can be delivered cost-effectively.\r\n\r\nWhy the Audience Will Be Captivated :\r\n\r\nThe audience witnesses real-time automation in a rugged field environment. A drone flies over a simulation zone and retrieves subsurface data packets from ground sensors through ESP-NOW wireless communication while displaying interactive maps on an offline smartphone application. This live demonstration proves that advanced agricultural technology can operate without internet connectivity and remain accessible to everyday farmers.\r\n\r\nThe Most Impressive Part :\r\n\r\nThe standout achievement is the 100% Offline Edge-AI Data Fusion Pipeline. An airborne 6 TOPS NPU runs a three-tier neural network framework (YOLOv26-Nano, MobileViTv2, CoAtNet-0), while ground microcontrollers execute optimized Python TinyML models. Together, they transform raw data into actionable crop insights directly at the field edge, independently of remote networks.\r\n\r\nThe Most Unique Part :\r\n\r\nThe project's key innovation is its Combustion-Resistant, Explosion-Safe Power Design. Replacing conventional Lithium-Polymer (LiPo) batteries with stable LiFePO4 3C chemistry, combined with automated hardware shutdown protocols, reduces battery-fire risks during canopy crashes and establishes a stronger safety approach for precision agricultural equipment.", "safetyHazards": ["drone_flying_equipment"], "safetyPrecautions": "1. Airborne Propulsion & Impact Fail-Safes :\r\nOptocoupler Logic Isolation: Separates low-voltage STM32 and Orange Pi logic from high-current motor ESC circuits, suppressing inductive back-EMF spikes.\r\nAutomated Motor Kill-Switch: Disables PWM motor outputs when orientation exceeds a 90-degree flip or a severe impact is detected, reducing motor-stall fire risks.\r\nDual-Antenna Spatial Diversity: Uses redundant external Quectel L89HA GNSS antennas to improve navigation signal reception beneath dense tree canopies.\r\nMAVLink Obstacle Override: Triggers auto-hover or return-to-launch when payload sensors detect nearby obstacles or sudden pressure drops.\r\n2. Electrical & Chemical Fire Prevention :\r\nLiFePO4 Battery Chemistry: Uses LiFePO4 3C cells instead of conventional LiPo packs to reduce thermal runaway and fire risks following punctures or impacts.\r\nSegmented Synchronous Regulation: Employs step-down regulators, inline LC filters, and TVS diodes to suppress voltage surges and protect electronics.\r\n3. Subsurface & Ground Ingress Protections :\r\nAnti-Electrolysis Duty Cycles: Cuts probe current between readings to minimize soil electrolysis, protect water quality, and extend probe lifespan.\r\nIndustrial Epoxy Potting: Seals underground electronics against acidic, alkaline, and chemical fertilizer mixtures, reducing short-circuit risks.\r\n4. User Health & Handling Safety :\r\n100% Solderless Assembly: Uses plug-and-play Grove, Gravity, and STEMMA QT connections, simplifying maintenance and avoiding toxic lead exposure during assembly.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T17:36:21.316Z", "updatedAt": "2026-10-14T18:49:33.055Z", "abstract": { "originalName": "AI_Based_Smart_Agritech_System.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1791653780/aura-registrations/abstract-docs/AI_Based_Smart_Agritech_System", "filename": "Abstract.docx", "relPath": "assets/Teams/The Innovation Squad/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "Title\n\nDistributed Edge-AI UAV & Ground Sensing IOT WSN Ecosystem for Multi-Tier Crop Health Analytics\n\nMethodology\n\nThis platform delivers full-spectrum precision agritech analytics across diverse crop heights—from large mango trees to short wheat fields—entirely independent of cloud architecture. The system decouples critical processing domains into three hardware nodes. The UAV Flight Control Frame isolates flight stability (handled by a dedicated STM32 flight controller running ArduPilot and a micro-sensor array) from the Detachable AI Analytics Payload via optocouplers to prevent high-current inductive feedback.\n\nThe AI Payload combines an Arduino Nano ESP32 sensor hub with an Orange Pi 5 Pro companion computer (6 TOPS NPU) executing a three-tiered offline computer vision model (YOLOv26-Nano, MobileViTv2, CoAtNet-0) compiled via RKNN-Toolkit2. Ground data is acquired by the Core Ground Module (Arduino Nano ESP32) polling capacitive soil moisture, micro-climate (BME280), and high-dynamic-range light sensors. Subsurface validation is scaled via a plug-and-play Add-On Module powered by an ESP32-C6 coprocessor that manages a 7-in-1 NPK/pH/EC probe via RS485 Modbus alongside multi-depth moisture check matrices.\n\nPython-based TinyML (TensorFlow Lite Micro) operates natively on the ground boards, compressing telemetry into localized anomaly stress indexes. Ground-to-air telemetry runs connectionless over 2.4GHz ESP-NOW profiles during flight passes. Final unified field reports are fetched offline by the farmer via local Wi-Fi AP or BLE direct transmissions into a decentralized smartphone SQLite database.\n\nProposed Block Diagram\n\nProposed Outcome\n\nThe architecture establishes an affordable, ultra-reliable farming solution that avoids standard vulnerabilities. First, using structurally resilient 3C LiFePO4 battery dynamics managed by segmented, filtered power rails and emergency hardware-software shutdown interrupts completely eliminates field thermal runaway or crash-fire hazards. Second, 100% offline edge execution bypasses rural connectivity deficits, allowing real-time mapping of crop stress distributions without operational reliance on expensive cloud structures or specialized, toxic assemblies. Third, the plug-and-play non-toxic solderless modular design ensures rapid configuration adjustment and safe physical handling, delivering professional industrial-grade multi-tier analytic capabilities directly to resource-constrained agriculturalists." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/The Innovation Squad/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791653780/aura-registrations/id-cards/yherfa6xrvccrkungoii.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/The Innovation Squad/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791653780/aura-registrations/id-cards/pkynmanfzfgy3skbximp.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/The Innovation Squad/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791653780/aura-registrations/id-cards/kyupkrsjmzexpjdrh3gp.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/The Innovation Squad/4.jpg", "url": null, "exists": false }] }, { "index": 40, "id": "6aca7f625275cf77a5f3e1e8", "registrationId": "AURA2K26-2QGC6P", "rawTeamName": "Nexgen", "folderName": "Nexgen", "folderRelPath": "assets/Teams/Nexgen", "projectTitle": "Nexgen", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "SK SUJAUDDIN", "teamLeaderEmail": "sks049061@gmail.com", "teamLeaderPhone": "7501414425", "teamMemberDetails": "Member 1 : Nazmus sakib / Aliah University / BCA/2nd year/+917384088548\r\n\r\nMember 2 : Fahmid Choudhury / Aliah University / ECE /3rd year /+919332589823\r\n\r\nMember 3 : Suhail Hasan / Aliah University / ECE / 3rd year / +916294724171", "hardwareProjectCategories": ["Electronics & Communication", "IoT & Smart Devices", "Embedded Systems", "Robotics", "Renewable Energy / Clean Technology"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Conventional charging and energy consumption systems generally charge users based on fixed packages, time-based usage, or estimated consumption. This can lead to inefficient energy utilization, difficulty in tracking actual consumption, and unused prepaid value. Our project, ENERGY WALLET, proposes a smart pay-as-you-use renewable energy system that measures electrical energy consumption in real time and converts it into a transparent energy credit system.\r\n\r\nThe system will collect energy primarily from renewable sources such as solar panels and store it in a battery-based energy storage system. Users can purchase an energy credit instead of purchasing a fixed charging service. The embedded system continuously measures voltage, current, power and cumulative energy consumption in Wh/kWh. It automatically controls the connected load and deducts the actual consumed energy from the user's energy balance.\r\n\r\nFor example, if a user purchases ₹100 worth of energy credit but consumes only ₹70 worth of energy, the remaining ₹30 will automatically be returned as a digital balance/refund according to the configured tariff. The system can be applied to mobile charging stations, electric vehicle charging, community charging points and other low-to-medium power applications.\r\n\r\nThe key innovation is the combination of renewable energy harvesting, real-time energy metering, prepaid energy credits, automated load control and automatic unused-balance settlement in a single system. This can make renewable energy usage more transparent, measurable and user-centric.", "solutionDescription": "Conventional charging and energy consumption systems generally charge users based on fixed packages, time-based usage, or estimated consumption. This can lead to inefficient energy utilization, difficulty in tracking actual consumption, and unused prepaid value. Our project, ENERGY WALLET, proposes a smart pay-as-you-use renewable energy system that measures electrical energy consumption in real time and converts it into a transparent energy credit system.\r\n\r\nThe system will collect energy primarily from renewable sources such as solar panels and store it in a battery-based energy storage system. Users can purchase an energy credit instead of purchasing a fixed charging service. The embedded system continuously measures voltage, current, power and cumulative energy consumption in Wh/kWh. It automatically controls the connected load and deducts the actual consumed energy from the user's energy balance.\r\n\r\nFor example, if a user purchases ₹100 worth of energy credit but consumes only ₹70 worth of energy, the remaining ₹30 will automatically be returned as a digital balance/refund according to the configured tariff. The system can be applied to mobile charging stations, electric vehicle charging, community charging points and other low-to-medium power applications.\r\n\r\nThe key innovation is the combination of renewable energy harvesting, real-time energy metering, prepaid energy credits, automated load control and automatic unused-balance settlement in a single system. This can make renewable energy usage more transparent, measurable and user-centric.", "innovationDescription": "Conventional charging and energy consumption systems generally charge users based on fixed packages, time-based usage, or estimated consumption. This can lead to inefficient energy utilization, difficulty in tracking actual consumption, and unused prepaid value. Our project, ENERGY WALLET, proposes a smart pay-as-you-use renewable energy system that measures electrical energy consumption in real time and converts it into a transparent energy credit system.\r\n\r\nThe system will collect energy primarily from renewable sources such as solar panels and store it in a battery-based energy storage system. Users can purchase an energy credit instead of purchasing a fixed charging service. The embedded system continuously measures voltage, current, power and cumulative energy consumption in Wh/kWh. It automatically controls the connected load and deducts the actual consumed energy from the user's energy balance.\r\n\r\nFor example, if a user purchases ₹100 worth of energy credit but consumes only ₹70 worth of energy, the remaining ₹30 will automatically be returned as a digital balance/refund according to the configured tariff. The system can be applied to mobile charging stations, electric vehicle charging, community charging points and other low-to-medium power applications.\r\n\r\nThe key innovation is the combination of renewable energy harvesting, real-time energy metering, prepaid energy credits, automated load control and automatic unused-balance settlement in a single system. This can make renewable energy usage more transparent, measurable and user-centric.", "workingPrinciple": "ENERGY WALLET works on the principle of real-time electrical energy measurement and pay-as-you-use energy management. Solar panels generate electricity, which is regulated by a charge controller and stored in a battery. An energy metering module measures voltage, current, power and cumulative energy consumption in Wh/kWh. An ESP32 microcontroller processes these measurements and calculates the consumed energy cost using a predefined tariff. Users purchase prepaid energy credits before starting a charging session. The system continuously deducts the cost of actual consumption from the available credit and displays the remaining balance. A load-control circuit automatically disconnects the output when the purchased credit is exhausted or a safety limit is reached. If the session ends early, the unused balance can be returned to the user's digital wallet or account through the implemented settlement mechanism. The prototype will demonstrate renewable energy utilization, transparent metering, controlled power delivery and fair pay-as-you-use charging.", "majorHardwareComponents": ["1. ESP32 development board for measurement processing and system control.\n2. Solar photovoltaic panel as the primary renewable energy source.\n3. Solar charge controller and rechargeable battery for energy storage.\n4. Electrical energy metering module or suitable voltage and current sensors for measuring power and energy consumption.\n5. Relay or MOSFET-based load switching circuit with appropriate electrical protection.\n6. OLED/LCD display for showing energy consumed", "remaining energy credit and estimated cost.\n7. DC charging output", "USB power module and suitable connectors for the demonstration load.\n8. Push buttons or an input interface for selecting and initiating a charging session.\n9. Wi-Fi connectivity through ESP32 for optional IoT monitoring and transaction records.\n10. Connecting wires", "PCB or breadboard", "fuses and enclosure."], "useAi": false, "useIot": true, "powerSource": "solar", "intendedBeneficiaries": ["General Public", "Industry", "Transportation", "Rural Communities", "Urban Communities"], "potentialImpact": "ENERGY WALLET can make renewable electricity more accessible, transparent and affordable for everyday users. It is designed for students, commuters, EV users, small businesses and communities that need convenient charging services. By measuring actual energy consumption instead of charging only by time or fixed packages, the system helps users understand how much electricity they use and pay fairly for it. Solar energy and battery storage can support charging during suitable operating conditions and reduce dependence on conventional grid electricity. The prepaid energy-credit model allows users to select an affordable budget, while unused credit can be returned through a digital balance or refund mechanism. Potential applications include solar-powered mobile charging stations, community charging points and future EV-charging infrastructure. The project promotes renewable-energy awareness, transparent billing and efficient electricity use. Its wider impact will depend on accurate metering, safe hardware design, reliable payment integration and cost-effective deployment.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "ENERGY WALLET introduces a simple but powerful idea: users should pay for the electrical energy they actually consume, not for unused charging time or an entire prepaid package. Unlike a conventional charging unit, our proposed system combines renewable energy, real-time energy metering, prepaid energy credits, automatic load control and unused-balance settlement in one platform. Users can monitor their energy consumption and remaining balance while the system calculates charges according to actual usage. The concept can be developed for solar-powered mobile charging stations, community energy kiosks and future EV-charging applications. Its distinctive feature is the combination of transparent energy accounting and a pay-as-you-use model, designed to make clean energy services more user-friendly. Our prototype aims to demonstrate how embedded systems can help create a fairer, smarter and more sustainable energy ecosystem.", "safetyHazards": ["fire_combustion"], "safetyPrecautions": "The ENERGY WALLET prototype will be designed with electrical safety as a priority. Initial testing will use low-voltage DC power to minimize the risk of electric shock. A properly rated fuse and overcurrent protection will be incorporated to protect against short circuits and excessive current. The solar panel will be connected through a suitable charge controller, and the battery will use appropriate charging and protection circuitry to reduce the risk of overcharging, overheating and damage. All wiring, connectors and components will be selected according to their voltage and current ratings. Exposed conductive parts will be insulated, and the circuit will be housed in a secure enclosure to prevent accidental contact. The load-control circuit will disconnect the output when the available energy credit is exhausted or an unsafe operating condition is detected, where supported by the implemented design. Testing will be conducted in a dry, supervised environment, with the power disconnected before making wiring changes. The initial demonstration will use a low-voltage charging load rather than a full-size electric vehicle charger. Any future high-power or public charging application will require appropriate electrical isolation, certified protection devices and professional safety assessment.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-10T18:09:38.769Z", "updatedAt": "2026-10-14T18:49:37.756Z", "abstract": { "originalName": "ENERGY_WALLET_AURA_2K26_Submission.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1791655776/aura-registrations/abstract-docs/ENERGY_WALLET_AURA_2K26_Submission", "filename": "Abstract.docx", "relPath": "assets/Teams/Nexgen/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "ENERGY WALLET\n\nSmart Renewable Energy Metering & Pay-as-you-use System\n\nAURA 2K26 • ABSTRACT IDEA\n\nTHE IDEA\n\nMany charging services rely on fixed packages or time-based pricing, making it difficult for users to track the exact energy consumed or recover unused prepaid value. ENERGY WALLET proposes a transparent pay-as-you-use system that measures actual electrical energy consumption and charges users according to a configurable tariff.\n\nHOW IT WORKS\n\nThe prototype will harvest solar energy and store it in a battery through suitable charge-management electronics. An energy-metering stage measures voltage, current, power and cumulative energy (Wh/kWh). An embedded controller such as an ESP32 calculates consumption and updates the user’s available energy credit. A load-control stage enables or disconnects the charging outlet according to available credit and system limits. A display shows energy used and remaining credit.\n\nPROPOSED BLOCK DIAGRAM\n\nSOLAR PV\n\n→\n\nBATTERYCharge management\n\n→\n\nENERGY METERV • I • P • Wh/kWh\n\nUSER CREDIT\n\n→\n\nESP32 / MCUTariff + credit logic\n\n→\n\nLOAD CONTROLProtected switching\n\nDISPLAYEnergy / balance\n\n↔\n\nCONTROLLERConsumption update\n\n→\n\nCHARGING LOADMobile / demo EV load\n\nCORE INNOVATION\n\nUsers purchase energy credit before a charging session and are charged only for the energy actually used. If a session ends with unused credit, the equivalent balance can be automatically returned to the user’s digital wallet or account, depending on the implemented payment method. The key innovation is integrating renewable energy, real-time metering, prepaid energy credit, controlled power delivery and automated unused-balance settlement in one compact system.\n\nPROPOSED OUTCOME & APPLICATIONS\n\nThe prototype aims to demonstrate energy measurement, live credit deduction, load control and unused-balance settlement under controlled conditions. Potential applications include solar-powered mobile charging points, EV-charging demonstrations and community energy kiosks. Safe electrical isolation, calibrated metering and suitable protection would be required before deployment with high-power or public charging equipment.\n\nRENEWABLE ENERGY  |  SMART METERING  |  PAY-AS-YOU-USE  |  AUTO SETTLEMENT" }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Nexgen/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791655777/aura-registrations/id-cards/ubji1qqkwqxc8ksrygrb.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Nexgen/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791655778/aura-registrations/id-cards/ryov6mcqtsd1xysspzvv.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Nexgen/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791655777/aura-registrations/id-cards/ygd4qzw7qcm58tp3ldzc.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Nexgen/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791655777/aura-registrations/id-cards/ds7dv6d5ubjtmbcxs6lv.jpg", "exists": true }] }, { "index": 41, "id": "6acbfe044fdec8fe292e9f18", "registrationId": "AURA2K26-4AJ3LG", "rawTeamName": "Hard Code", "folderName": "Hard Code", "folderRelPath": "assets/Teams/Hard Code", "projectTitle": "SMART BLIND STICK", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "John Ali", "teamLeaderEmail": "johnali2732@gmail.com", "teamLeaderPhone": "9874214690", "teamMemberDetails": "MOHAMMAD MOSHARRAF | CEN254071 | 9088063012\r\nABDUL ALIM | ECE254004 | 9875508006\r\nSAQUIB RAZA | MEN254017 | 8229076518", "hardwareProjectCategories": ["Assistive Technology"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Statement\r\n\r\nVisually impaired people often face difficulties while moving independently because conventional walking sticks cannot detect obstacles located ahead or at different distances. Commercial electronic smart sticks may also be expensive and can require complex electronics or programming. There is a need for an affordable, lightweight, reliable, and easy-to-use mobility aid that can provide immediate warnings about obstacles.\r\n\r\nProposed Solution\r\n\r\nThe proposed Smart Blind Stick is an affordable assistive mobility device that uses an HC-SR04 ultrasonic sensor to detect obstacles. A 9V battery supplies power, which is regulated to 5V using an LM7805 voltage regulator. A timing circuit based on an NE555 generates the required trigger pulses for the ultrasonic sensor. When the ultrasonic waves reflect from an obstacle, the echo signal provides information about the obstacle's distance.\r\n\r\nA BC547 transistor switching circuit processes the detection condition and activates a 5V active buzzer and high-intensity LED when an obstacle enters the defined danger range. This provides instant audible and visual feedback to the user without requiring a microcontroller or software. The proposed system can detect obstacles up to approximately 400 cm.\r\n\r\nInnovation Idea\r\n\r\nThe main innovation is the microcontroller-free design. Instead of using an Arduino or other programmable processor, the system uses discrete electronic components such as an NE555 timer and BC547 transistor for timing and switching. This reduces cost, eliminates programming requirements, and avoids software-related crashes or delays.\r\n\r\nThe compact design can also be retrofitted onto a standard walking cane, making it lightweight and accessible. The combination of ultrasonic obstacle detection with immediate audio and LED alerts provides a simple, low-maintenance, and practical solution for safer and more independent mobility.", "solutionDescription": "Problem Statement\r\n\r\nVisually impaired people often face difficulties while moving independently because conventional walking sticks cannot detect obstacles located ahead or at different distances. Commercial electronic smart sticks may also be expensive and can require complex electronics or programming. There is a need for an affordable, lightweight, reliable, and easy-to-use mobility aid that can provide immediate warnings about obstacles.\r\n\r\nProposed Solution\r\n\r\nThe proposed Smart Blind Stick is an affordable assistive mobility device that uses an HC-SR04 ultrasonic sensor to detect obstacles. A 9V battery supplies power, which is regulated to 5V using an LM7805 voltage regulator. A timing circuit based on an NE555 generates the required trigger pulses for the ultrasonic sensor. When the ultrasonic waves reflect from an obstacle, the echo signal provides information about the obstacle's distance.\r\n\r\nA BC547 transistor switching circuit processes the detection condition and activates a 5V active buzzer and high-intensity LED when an obstacle enters the defined danger range. This provides instant audible and visual feedback to the user without requiring a microcontroller or software. The proposed system can detect obstacles up to approximately 400 cm.\r\n\r\nInnovation Idea\r\n\r\nThe main innovation is the microcontroller-free design. Instead of using an Arduino or other programmable processor, the system uses discrete electronic components such as an NE555 timer and BC547 transistor for timing and switching. This reduces cost, eliminates programming requirements, and avoids software-related crashes or delays.\r\n\r\nThe compact design can also be retrofitted onto a standard walking cane, making it lightweight and accessible. The combination of ultrasonic obstacle detection with immediate audio and LED alerts provides a simple, low-maintenance, and practical solution for safer and more independent mobility.", "innovationDescription": "Problem Statement\r\n\r\nVisually impaired people often face difficulties while moving independently because conventional walking sticks cannot detect obstacles located ahead or at different distances. Commercial electronic smart sticks may also be expensive and can require complex electronics or programming. There is a need for an affordable, lightweight, reliable, and easy-to-use mobility aid that can provide immediate warnings about obstacles.\r\n\r\nProposed Solution\r\n\r\nThe proposed Smart Blind Stick is an affordable assistive mobility device that uses an HC-SR04 ultrasonic sensor to detect obstacles. A 9V battery supplies power, which is regulated to 5V using an LM7805 voltage regulator. A timing circuit based on an NE555 generates the required trigger pulses for the ultrasonic sensor. When the ultrasonic waves reflect from an obstacle, the echo signal provides information about the obstacle's distance.\r\n\r\nA BC547 transistor switching circuit processes the detection condition and activates a 5V active buzzer and high-intensity LED when an obstacle enters the defined danger range. This provides instant audible and visual feedback to the user without requiring a microcontroller or software. The proposed system can detect obstacles up to approximately 400 cm.\r\n\r\nInnovation Idea\r\n\r\nThe main innovation is the microcontroller-free design. Instead of using an Arduino or other programmable processor, the system uses discrete electronic components such as an NE555 timer and BC547 transistor for timing and switching. This reduces cost, eliminates programming requirements, and avoids software-related crashes or delays.\r\n\r\nThe compact design can also be retrofitted onto a standard walking cane, making it lightweight and accessible. The combination of ultrasonic obstacle detection with immediate audio and LED alerts provides a simple, low-maintenance, and practical solution for safer and more independent mobility.", "workingPrinciple": "The Smart Blind Stick works using an HC-SR04 ultrasonic sensor to detect obstacles in front of a visually impaired person. A 9V battery supplies power, which is regulated to 5V using an LM7805 voltage regulator. An NE555-based timing circuit generates trigger pulses for the ultrasonic sensor. The sensor emits ultrasonic waves that reflect off nearby objects and return as echo signals. When an obstacle enters the predefined danger range, a BC547 transistor switching circuit activates a 5V buzzer and an LED to provide audible and visual warnings. The device is designed to offer an affordable, lightweight, and microcontroller-free solution for safer and more independent mobility.", "majorHardwareComponents": ["HC-SR04 Ultrasonic Sensor\nBC547 NPN Transistor\n5V Active Buzzer\nLED\n220Ω Resistor\n1kΩ Resistor\n9V Battery\n9V Battery Clip\nMini Breadboard\nConnecting Wires\nSPST Switch\nPVC Pipe"], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public"], "potentialImpact": "The Smart Blind Stick can improve the daily lives of visually impaired people by helping them detect nearby obstacles and move with greater confidence and independence. Its affordable design makes assistive technology more accessible to people with limited financial resources. The buzzer and LED provide immediate warnings when obstacles enter the predefined danger range. By using simple electronic components without a microcontroller, the device can reduce complexity and maintenance requirements. It can also be attached to a conventional walking stick, potentially making it a practical and low-cost mobility aid for wider public use. The device is intended to support safer mobility but should be used alongside a traditional cane and other established mobility techniques.", "productPotential": "yes", "prototypeDevelopmentCost": 1000, "auraDemoHighlight": "The Smart Blind Stick is worth seeing because it presents an affordable and innovative approach to improving mobility for visually impaired people. Unlike complex electronic devices, it uses simple components without a microcontroller or programming. Its ultrasonic sensor detects obstacles and activates a buzzer and LED to provide immediate warnings. The lightweight, retrofittable design makes it practical and accessible. This project combines low-cost electronics with meaningful social impact, demonstrating how simple engineering can help people move more independently and confidently.", "safetyHazards": ["none", "high_current"], "safetyPrecautions": "The following safety precautions are considered for the Smart Blind Stick: The 9V battery supply is regulated to 5V using an LM7805 voltage regulator to provide a stable power supply. All electronic connections are checked to prevent loose wiring and short circuits. The ultrasonic sensor and circuit components are mounted securely on the stick to avoid damage during use. The buzzer and LED are tested to ensure proper warning signals. The circuit is checked for overheating and electrical faults before operation. The device should be protected from moisture and tested in a controlled environment before practical use. It should be used as an additional aid alongside a conventional white cane.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-11T21:22:12.302Z", "updatedAt": "2026-10-14T18:49:43.703Z", "abstract": { "originalName": "Hard Code.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791753731/aura-registrations/abstract-docs/Hard%20Code.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Hard Code/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Hard Code/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791753731/aura-registrations/id-cards/bwckdn2nnqujdiz1ftrs.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Hard Code/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791753731/aura-registrations/id-cards/awl5jhvhkvbd2w374efm.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Hard Code/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791753731/aura-registrations/id-cards/efpr2px7feoool5avfae.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Hard Code/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791753731/aura-registrations/id-cards/jiesfsrqb0ag5sqmcl9m.jpg", "exists": true }] }, { "index": 42, "id": "6accec3297cf7509c8ea1c1a", "registrationId": "AURA2K26-UVJKKZ", "rawTeamName": "THERON", "folderName": "THERON", "folderRelPath": "assets/Teams/THERON", "projectTitle": "THERMOR-R (Passive Thermal-Surge Adaptive Heatsink)", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "MUNSI MD WASIMUDDIN", "teamLeaderEmail": "wasimuddin1012@gmail.com", "teamLeaderPhone": "9874974607", "teamMemberDetails": "SYED ABID HOSSAIN  |  ALIAH UNIVERSITY  |  MECHANICAL ENGINEERING  |  2nd YEAR  |  7001429039\r\nSOHA FIRDAUS  |  ALIAH UNIVERSITY  |  CIVIL ENGINEERING  |  1st YEAR  |  8653212131\r\nARMIN ARA  |  ALIAH UNIVERSITY  |  CIVIL ENGINEERING  |  1st YEAR  |  8116821576", "hardwareProjectCategories": ["Mechanical Systems", "Mechatronics", "Automation & Control", "Industrial / Manufacturing Technology"], "prototypeType": "Electromechanical System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Addressed: Common heatsinks provide a fixed level of cooling regardless of the thermal load. A large heatsink can provide better cooling but is generally heavier, more expensive, and occupies more space. A small heatsink is more compact but may be incapable of handling a sudden temperature spike. THERMOR-R addresses this problem by providing an adjustable cooling surface according to the thermal load.\r\nHardware Solution: THERMOR-R makes use of a central fixed aluminium heatsink with deployable side-fin panels on hinges. Three 10 W power resistors provide controlled heating via an aluminium spreader. A FAST bimetal strip reacts quickly to a temperature increase, whereas a SLOW bimetal strip with additional thermal mass reacts more slowly to a temperature increase. The difference in movement caused by the two bimetals is used to operate a lever, release a latch, and deploy the side fins by means of a spring. A separate critical-temperature thermostat provides an alternative means of operating the mechanism, and a return spring allows the mechanism to be reset once the temperature has decreased. Thermocouples, MAX6675 modules, an ESP32, and an OLED display are used to monitor temperatures and operating mode.\r\nInnovation: The main innovation of this project is the use of the thermal response of bimetals to mechanically deploy additional cooling surface area, as opposed to a more conventional sensor–microcontroller–motor setup. The difference between the response of the FAST and the SLOW bimetal is effectively used as an indicator of a rapidly increasing temperature, which causes additional cooling surface to be deployed automatically. A separate thermostat is used to provide protection against dangerously high temperatures. The transparent prototype will also serve to demonstrate and experiment with the concept, and allow the mechanism to be compared directly with a conventional heatsink.", "solutionDescription": "Problem Addressed: Common heatsinks provide a fixed level of cooling regardless of the thermal load. A large heatsink can provide better cooling but is generally heavier, more expensive, and occupies more space. A small heatsink is more compact but may be incapable of handling a sudden temperature spike. THERMOR-R addresses this problem by providing an adjustable cooling surface according to the thermal load.\r\nHardware Solution: THERMOR-R makes use of a central fixed aluminium heatsink with deployable side-fin panels on hinges. Three 10 W power resistors provide controlled heating via an aluminium spreader. A FAST bimetal strip reacts quickly to a temperature increase, whereas a SLOW bimetal strip with additional thermal mass reacts more slowly to a temperature increase. The difference in movement caused by the two bimetals is used to operate a lever, release a latch, and deploy the side fins by means of a spring. A separate critical-temperature thermostat provides an alternative means of operating the mechanism, and a return spring allows the mechanism to be reset once the temperature has decreased. Thermocouples, MAX6675 modules, an ESP32, and an OLED display are used to monitor temperatures and operating mode.\r\nInnovation: The main innovation of this project is the use of the thermal response of bimetals to mechanically deploy additional cooling surface area, as opposed to a more conventional sensor–microcontroller–motor setup. The difference between the response of the FAST and the SLOW bimetal is effectively used as an indicator of a rapidly increasing temperature, which causes additional cooling surface to be deployed automatically. A separate thermostat is used to provide protection against dangerously high temperatures. The transparent prototype will also serve to demonstrate and experiment with the concept, and allow the mechanism to be compared directly with a conventional heatsink.", "innovationDescription": "Problem Addressed: Common heatsinks provide a fixed level of cooling regardless of the thermal load. A large heatsink can provide better cooling but is generally heavier, more expensive, and occupies more space. A small heatsink is more compact but may be incapable of handling a sudden temperature spike. THERMOR-R addresses this problem by providing an adjustable cooling surface according to the thermal load.\r\nHardware Solution: THERMOR-R makes use of a central fixed aluminium heatsink with deployable side-fin panels on hinges. Three 10 W power resistors provide controlled heating via an aluminium spreader. A FAST bimetal strip reacts quickly to a temperature increase, whereas a SLOW bimetal strip with additional thermal mass reacts more slowly to a temperature increase. The difference in movement caused by the two bimetals is used to operate a lever, release a latch, and deploy the side fins by means of a spring. A separate critical-temperature thermostat provides an alternative means of operating the mechanism, and a return spring allows the mechanism to be reset once the temperature has decreased. Thermocouples, MAX6675 modules, an ESP32, and an OLED display are used to monitor temperatures and operating mode.\r\nInnovation: The main innovation of this project is the use of the thermal response of bimetals to mechanically deploy additional cooling surface area, as opposed to a more conventional sensor–microcontroller–motor setup. The difference between the response of the FAST and the SLOW bimetal is effectively used as an indicator of a rapidly increasing temperature, which causes additional cooling surface to be deployed automatically. A separate thermostat is used to provide protection against dangerously high temperatures. The transparent prototype will also serve to demonstrate and experiment with the concept, and allow the mechanism to be compared directly with a conventional heatsink.", "workingPrinciple": "THERMOR-R makes use of a passive thermal to mechanical control sequence, where the application of heat itself triggers the cooling system. This commences by the provision of three 10 W power resistors, that apply controlled heat to the heatsink via an aluminium spreader.\r\nAt higher temperatures two bimetal thermal elements act at differing rates, the first being FAST and the second SLOW (having additional thermal mass). The differing actuation rates are apparent at slow heating, where the two actuators move together with only a small difference in distance travelled. However, during a faster temperature rise, the faster responding FAST bimetal moves further than the slower SLOW bimetal, causing a noticeable displacement in a mechanical lever.\r\nThis provides mechanical advantage and unlatches deployable side fins from a holding latch, allowing a loaded spring to swing hinged aluminium side-fin panels outwards, enhancing the surface area available for passive heat dissipation.\r\nA separate critical-temperature thermostat provides backup in the event of an extreme temperature rise (without sufficient FAST-SLOW actuation difference to trigger the deployment mechanism). As temperatures decrease, the thermal elements relax towards their original position, and a return spring acts to reset the side-fin panels towards the closed position. This provides three possible operating modes-NORMAL, BOOST and MAXIMUM COOLING.\r\nFor monitoring and displaying purposes, K-type thermocouples, MAX6675 modules, an ESP32 and an OLED display are used to measure temperatures and indicate the operating mode.", "majorHardwareComponents": ["Aluminium base plate", "aluminium heat-spreader plate", "fixed aluminium heatsink", "aluminium side-fin panels", "small hinges", "FAST bimetal strip", "SLOW bimetal strip", "metal thermal-mass block", "lever arms", "mechanical latch", "deployment springs", "return springs", "critical-temperature thermostat", "thermal paste", "conductive braid", "acrylic sheets", "standoffs", "nuts", "bolts", "washers", "ESP32 DevKit", "K-type thermocouples", "MAX6675 modules", "0.96″ OLED display", "10 W power resistors", "DC power supply", "main switch", "status LEDs", "wires", "connectors."], "useAi": false, "useIot": false, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["Industry", "Transportation"], "potentialImpact": "THERMOR-R would be useful in any industry which is concerned with cooling down power electronics, LED's, charging systems and possibly transportation electronics. It's simplest in it's ability to provide extra cooling when needed. \r\nRather than having a heatsink of a fixed size that is always present and removing heat at a fixed rate, THERMOR-R could allow for a smaller footprint while still allowing extra cooling when temperatures rise. This could be acheived by adding mechanically deployed heat dissipating elements rather than having them always deployed. This would be useful in applications where mechanical simplicity, low power requirements, and passive cooling are desired. Rather than being controlled by electronics to deploy or change, the surface area would be changed by being mechanically pushed out by thermal expansion rather than electronic means. \r\nThe benefit to the end user or manufacturer is potentially much greater cooling performance in a mechanically simpler device than a fixed passive heatsink. The system would need to be tested against conventional heatsinks in order to be able to claim lower temperatures, quicker cooling, reduced costs, or increased reliability.", "productPotential": "potentially", "prototypeDevelopmentCost": 4200, "auraDemoHighlight": "The most impressive part about THERMOR-R is that the heat itself transforms the heatsink physically in order to increase its cooling capacity, mechanically, without the need for anything else.\r\nTypical heatsinks have a static cooling surface, but THERMOR-R takes an entirely different approach in which it is typically compact, but features two bimetal elements which move differently when subjected to rapid increases in temperature, mechanically pushing a lever and releasing a latch, allowing the spring-loaded aluminium fins to automatically deploy, increasing the surface area of the heatsink and thus its cooling capacity.\r\nWhat makes the project especially interesting is that the main procedure is completely passive and mechanical, the electronics only serving the purpose of measuring and validating the temperature. This means that the project offers a physical and mechanical experience of a system which transforms itself in reaction to the temperature, in real time.\r\nThe project acts as a demonstration of thermal expansion, mechanical leverage and energy stored in springs being employed in a single, fully functional mechanism. Rather than a display of electronics, it serves more as a display of mechanical engineering and a clever application of bimetallic mechanics.", "safetyHazards": ["high_temperature", "moving_rotating_machinery", "sharp_mechanical_components"], "safetyPrecautions": "The prototype will be equipped with the following safety measures:\r\nResistor guard: the three 10 W heating resistors will be enclosed/guarded to avoid any accidental touching of hot spots;\r\nTransparent protective enclosure: To avoid any accidental touching of the moving mechanism (deploying fins, hinges, springs, lever and latch) and keep the whole mechanism under surveillance, a clear acrylic enclosure will be placed around the mechanism;\r\nControlled heating: To avoid abrupt temperature increase or overheating, the heating power will be increased stepwise during testing;\r\nSafe material placement: The place where the acrylic enclosure is placed will be kept away from the hottest spots;\r\nSharp-edge protection: The exposed aluminium edging from the fins and other mechanical parts will be finished or enclosed where necessary;\r\nStable mounting: The whole mechanism will be firmly mounted on a stable base during the demonstration;\r\nElectrical isolation/control: A main ON/OFF switch and suitable DC power supply will be employed;\r\nTemperature monitoring: K-type thermocouples will be used to monitor heat source and heatsink temperatures during the tests.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-12T14:18:26.89Z", "updatedAt": "2026-10-14T18:49:48.024Z", "abstract": { "originalName": "Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791814705/aura-registrations/abstract-docs/Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/THERON/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/THERON/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791814705/aura-registrations/id-cards/k9rknqyvemnt5jqpznop.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/THERON/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791814705/aura-registrations/id-cards/v5ul1qvakjaq3jg19e6v.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/THERON/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791814706/aura-registrations/id-cards/jonorvskxmtry8tuobzb.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/THERON/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791814705/aura-registrations/id-cards/xyl4dtibyasbjjkhkqwp.jpg", "exists": true }] }, { "index": 43, "id": "6acf0c1df9caca02de6e4d75", "registrationId": "AURA2K26-TYLYMS", "rawTeamName": "APEX PIONEERS", "folderName": "APEX PIONEERS", "folderRelPath": "assets/Teams/APEX PIONEERS", "projectTitle": "AEGIS - X", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "AFIFA SULTANA", "teamLeaderEmail": "fahim211456@gmail.com", "teamLeaderPhone": "6297112293", "teamMemberDetails": "Member 1 \r\nName -FAHIM ABDULLAH\r\nINSTITUTION - ALIAH UNIVERSITY \r\nDEPARTMENT - PHYSICS \r\nPHONE NUMBER -9382815186\r\nMEMBER 2\r\nNAME- MD EKBAL HOSSAIN \r\nINSTITUTION- ALIAH UNIVERSITY \r\nDEPARTMENT - PHYSICS \r\nPHONE NUMBER - 8597900550\r\nMEMBER 3\r\nNAME - ANOYAR ALAM\r\nINSTITUTION - ALIAH UNIVERSITY \r\nDEPARTMENT - PHYSICS \r\nPHONE NUMBER -9332134849", "hardwareProjectCategories": ["Robotics", "Embedded Systems", "IoT & Smart Devices", "Automation & Control", "Electronics & Communication", "Mechatronics", "Safety & Security Systems"], "prototypeType": "Robotic System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Problem Statement\r\nDuring disasters such as fires, smoke incidents, and hazardous gas leaks, people may have only a limited time to escape safely. Smoke can reduce visibility, familiar exits may become dangerous, and panic can make evacuation decisions difficult. Traditional alarm systems can warn people about danger, but they do not necessarily identify blocked routes or recommend alternative exits. Emergency responders may also face risks when entering hazardous environments. Therefore, an affordable system that combines hazard detection, obstacle monitoring, and intelligent evacuation planning could provide valuable support. AEGIS-X addresses this challenge by demonstrating how robotics can help identify potential dangers and guide evacuation decisions in a controlled environment.\r\n2. Proposed Solution\r\nAEGIS-X is a smart mobile robot designed to detect potential hazards and identify alternative evacuation routes inside a miniature building. An ESP32 microcontroller processes sensor readings and coordinates the robot's movement, alerts, and route-selection algorithm.\r\nA flame sensor detects fire-related infrared signals, an MQ-2 sensor monitors smoke and certain combustible gases, and a temperature sensor measures temperature changes. An ultrasonic sensor detects obstacles along the robot's path. When readings indicate a potential hazard, the system activates a buzzer, displays a warning, and marks the affected corridor as unsafe within the programmed model.\r\nThe robot then evaluates available routes and selects an alternative accessible exit using a predefined path-planning algorithm. LED indicators display the recommended direction, while Wi-Fi can send alerts to a connected mobile device. This approach transforms hazard detection into actionable evacuation guidance rather than providing an alarm alone.\r\n3. Innovation Details\r\nThe main innovation of AEGIS-X is the integration of multi-sensor hazard monitoring, dynamic route selection, and robotic navigation within one coordinated prototype.\r\nIts key features include multi-sensor monitoring, alternative route calculation, obstacle avoidance, emergency alerts, and live status reporting. Unlike a basic sensor-based alarm, AEGIS-X demonstrates how hazard information can influence route decisions. Its performance can be evaluated through repeated tests measuring detection time, route-selection accuracy, obstacle-avoidance success, and false alarms.\r\nThe prototype has potential educational applications in schools, hospitals, offices, and industrial safety demonstrations. It provides a practical platform for exploring robotics, electronics, programming, and emergency planning.\r\nAEGIS-X is an educational prototype, not a replacement for certified fire-safety equipment or professional emergency services.\r\nOur mission is to transform intelligent detection into safer decisions, demonstrating how affordable robotics can contribute to disaster preparedness and the protection of human life.", "solutionDescription": "1. Problem Statement\r\nDuring disasters such as fires, smoke incidents, and hazardous gas leaks, people may have only a limited time to escape safely. Smoke can reduce visibility, familiar exits may become dangerous, and panic can make evacuation decisions difficult. Traditional alarm systems can warn people about danger, but they do not necessarily identify blocked routes or recommend alternative exits. Emergency responders may also face risks when entering hazardous environments. Therefore, an affordable system that combines hazard detection, obstacle monitoring, and intelligent evacuation planning could provide valuable support. AEGIS-X addresses this challenge by demonstrating how robotics can help identify potential dangers and guide evacuation decisions in a controlled environment.\r\n2. Proposed Solution\r\nAEGIS-X is a smart mobile robot designed to detect potential hazards and identify alternative evacuation routes inside a miniature building. An ESP32 microcontroller processes sensor readings and coordinates the robot's movement, alerts, and route-selection algorithm.\r\nA flame sensor detects fire-related infrared signals, an MQ-2 sensor monitors smoke and certain combustible gases, and a temperature sensor measures temperature changes. An ultrasonic sensor detects obstacles along the robot's path. When readings indicate a potential hazard, the system activates a buzzer, displays a warning, and marks the affected corridor as unsafe within the programmed model.\r\nThe robot then evaluates available routes and selects an alternative accessible exit using a predefined path-planning algorithm. LED indicators display the recommended direction, while Wi-Fi can send alerts to a connected mobile device. This approach transforms hazard detection into actionable evacuation guidance rather than providing an alarm alone.\r\n3. Innovation Details\r\nThe main innovation of AEGIS-X is the integration of multi-sensor hazard monitoring, dynamic route selection, and robotic navigation within one coordinated prototype.\r\nIts key features include multi-sensor monitoring, alternative route calculation, obstacle avoidance, emergency alerts, and live status reporting. Unlike a basic sensor-based alarm, AEGIS-X demonstrates how hazard information can influence route decisions. Its performance can be evaluated through repeated tests measuring detection time, route-selection accuracy, obstacle-avoidance success, and false alarms.\r\nThe prototype has potential educational applications in schools, hospitals, offices, and industrial safety demonstrations. It provides a practical platform for exploring robotics, electronics, programming, and emergency planning.\r\nAEGIS-X is an educational prototype, not a replacement for certified fire-safety equipment or professional emergency services.\r\nOur mission is to transform intelligent detection into safer decisions, demonstrating how affordable robotics can contribute to disaster preparedness and the protection of human life.", "innovationDescription": "1. Problem Statement\r\nDuring disasters such as fires, smoke incidents, and hazardous gas leaks, people may have only a limited time to escape safely. Smoke can reduce visibility, familiar exits may become dangerous, and panic can make evacuation decisions difficult. Traditional alarm systems can warn people about danger, but they do not necessarily identify blocked routes or recommend alternative exits. Emergency responders may also face risks when entering hazardous environments. Therefore, an affordable system that combines hazard detection, obstacle monitoring, and intelligent evacuation planning could provide valuable support. AEGIS-X addresses this challenge by demonstrating how robotics can help identify potential dangers and guide evacuation decisions in a controlled environment.\r\n2. Proposed Solution\r\nAEGIS-X is a smart mobile robot designed to detect potential hazards and identify alternative evacuation routes inside a miniature building. An ESP32 microcontroller processes sensor readings and coordinates the robot's movement, alerts, and route-selection algorithm.\r\nA flame sensor detects fire-related infrared signals, an MQ-2 sensor monitors smoke and certain combustible gases, and a temperature sensor measures temperature changes. An ultrasonic sensor detects obstacles along the robot's path. When readings indicate a potential hazard, the system activates a buzzer, displays a warning, and marks the affected corridor as unsafe within the programmed model.\r\nThe robot then evaluates available routes and selects an alternative accessible exit using a predefined path-planning algorithm. LED indicators display the recommended direction, while Wi-Fi can send alerts to a connected mobile device. This approach transforms hazard detection into actionable evacuation guidance rather than providing an alarm alone.\r\n3. Innovation Details\r\nThe main innovation of AEGIS-X is the integration of multi-sensor hazard monitoring, dynamic route selection, and robotic navigation within one coordinated prototype.\r\nIts key features include multi-sensor monitoring, alternative route calculation, obstacle avoidance, emergency alerts, and live status reporting. Unlike a basic sensor-based alarm, AEGIS-X demonstrates how hazard information can influence route decisions. Its performance can be evaluated through repeated tests measuring detection time, route-selection accuracy, obstacle-avoidance success, and false alarms.\r\nThe prototype has potential educational applications in schools, hospitals, offices, and industrial safety demonstrations. It provides a practical platform for exploring robotics, electronics, programming, and emergency planning.\r\nAEGIS-X is an educational prototype, not a replacement for certified fire-safety equipment or professional emergency services.\r\nOur mission is to transform intelligent detection into safer decisions, demonstrating how affordable robotics can contribute to disaster preparedness and the protection of human life.", "workingPrinciple": "AEGIS-X is an intelligent disaster detection and smart evacuation robot designed to demonstrate hazard detection, obstacle avoidance, and alternative route planning in a miniature building. The system uses an ESP32 microcontroller to collect sensor readings, process information, and control the robot's movement.\r\nA flame sensor detects infrared signals associated with flames, while an MQ-2 sensor monitors smoke and certain combustible gases. A temperature sensor measures surrounding temperature, and an HC-SR04 ultrasonic sensor detects obstacles in the robot's path. The ESP32 compares sensor readings with predefined thresholds. When a potential hazard is detected, the system activates a buzzer and warning LEDs, while an OLED or LCD displays relevant information.\r\nFor evacuation demonstration, a miniature building model contains multiple corridors and exits. A predefined map and programmed route-planning algorithm represent the available paths. When a corridor is marked as hazardous in the simulation, the algorithm treats that corridor as unavailable and selects an alternative route toward a designated exit. The robot follows the selected route using its motor driver and four-wheel-drive mechanism. Ultrasonic measurements help it detect obstacles and adjust its movement when necessary.\r\nThe ESP32's Wi-Fi capability can transmit hazard notifications and sensor readings to a mobile device when the communication feature is implemented. The prototype is evaluated through controlled tests measuring hazard response time, route selection, obstacle avoidance, and false alarms. AEGIS-X is an educational demonstration system, not a certified emergency response or life-safety device.", "majorHardwareComponents": ["AEGIS-X integrates electronic sensors", "an embedded controller", "a mobile platform", "and alert components to demonstrate disaster detection and smart evacuation.\nThe ESP32 microcontroller serves as the central processing unit. It collects sensor readings", "processes information", "controls motor movement", "and supports Wi-Fi communication for mobile alerts. A flame sensor detects infrared signals associated with flames", "while the MQ-2 sensor responds to smoke and certain combustible gases. A temperature sensor measures surrounding temperature", "and an HC-SR04 ultrasonic sensor detects obstacles by measuring distance.\nA four-wheel-drive chassis provides mobility. Four DC geared motors drive the wheels", "while an L298N motor driver controls their operation. A rechargeable battery pack powers the robot", "with suitable voltage regulation providing the required supply to electronic components.\nAn OLED or LCD display presents sensor readings and system status. A buzzer and LEDs provide audible and visual warnings when sensor readings exceed predefined thresholds. Jumper wires", "connectors", "switches", "and a breadboard support electrical connections and assembly.\nA miniature building model with multiple corridors and exits demonstrates evacuation route planning. A predefined map and programmed algorithm allow the robot to treat a simulated hazardous corridor as unavailable and select an alternative route. Wi-Fi connectivity can transmit hazard notifications when implemented and tested.\nTogether", "these components create an educational prototype demonstrating hazard monitoring", "obstacle detection", "controlled movement", "and alternative route planning under supervised conditions."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Industry", "Healthcare", "Government / Public Services"], "potentialImpact": "AEGIS-X is designed to benefit the general public, schools, colleges, hospitals, industries, offices, and emergency-management services by demonstrating how intelligent robotics can support hazard awareness and evacuation planning.\r\nFor the general public, the system demonstrates how potential hazards can trigger warnings and help identify alternative evacuation routes. In schools and colleges, it can support practical fire-safety education and emergency preparedness. Hospitals may benefit from exploring evacuation strategies for buildings with multiple corridors and exits. Industries and offices can use the prototype to demonstrate hazard monitoring and route-planning concepts, while public services and emergency planners can study its potential applications in controlled environments.\r\nAEGIS-X aims to improve current approaches by combining several functions in one system. Conventional alarm systems primarily alert occupants to danger, whereas AEGIS-X demonstrates how sensor information can influence route selection. Its environmental sensors monitor potential hazards, ultrasonic sensors detect obstacles, and a programmed algorithm selects an alternative route when a corridor is designated unsafe. Visual indicators, audible alarms, and a display communicate warnings clearly.\r\nThe prototype's performance will be evaluated through repeated experiments measuring detection response time, route-selection accuracy, obstacle avoidance, and false alarms. These measurements can identify weaknesses and guide future improvements.\r\nIts affordable, modular design also allows further development through improved sensors, mapping, and communication features. Although AEGIS-X is an educational prototype rather than a certified safety device, it demonstrates a promising approach to making evacuation planning more responsive, understandable, and accessible.", "productPotential": "yes", "prototypeDevelopmentCost": 3700, "auraDemoHighlight": "AEGIS-X deserves attention because it transforms a conventional hazard-detection concept into an interactive robotic demonstration of intelligent evacuation planning. Its most distinctive feature is the integration of environmental monitoring, obstacle detection, alternative route selection, and emergency alerts within one coordinated prototype.\r\nThe highlight of our project is its Smart Evacuation System. We will construct a miniature building with multiple corridors and exits. When a simulated hazard blocks one corridor, the programmed algorithm marks that route unavailable and selects an alternative accessible path. The robot then demonstrates navigation through the model, while LED indicators and a display communicate the recommended direction. This visible, real-time response allows judges and audiences to observe how hazard information influences the system's decisions.\r\nAnother impressive aspect is the combination of practical engineering disciplines. AEGIS-X integrates an ESP32 microcontroller, multiple sensors, motor control, wireless communication, and route-planning software into a student-built robotic prototype. Its modular design makes the system understandable, testable, and suitable for future improvements.\r\nWe will also evaluate its performance through repeated trials, recording route-selection accuracy, hazard-detection response time, obstacle-avoidance success, and false alarms. Presenting these results will demonstrate measurable performance rather than relying on appearance alone.\r\nAEGIS-X addresses an important human-safety challenge while offering an engaging live demonstration. Its combination of affordability, practical engineering, visible decision-making, and potential social benefit makes it a compelling innovation for AURA 2026.\r\nOur goal is to demonstrate how robotics can turn hazard information into clearer, more informed evacuation decisions.", "safetyHazards": ["moving_rotating_machinery"], "safetyPrecautions": "The AEGIS-X prototype incorporates safety precautions to minimise risks during operation, testing, and demonstration. The robot uses a low-voltage rechargeable battery suitable for a small mobile system. All electrical connections are checked before operation to reduce the risk of short circuits, loose wiring, and overheating. Appropriate voltage regulation ensures that the ESP32 controller and sensors receive their required operating voltage. The battery is handled carefully and protected from water, excessive heat, and physical damage. The moving wheels and motors are potential mechanical hazards. During testing, hands, fingers, clothing, and loose objects are kept away from rotating wheels and moving components. The robot operates on a stable, clear surface to minimise collisions and unexpected movement. The power supply can be disconnected immediately if abnormal behaviour, loose wiring, or overheating occurs. The flame and smoke sensors are tested using safe simulation methods. Real fire, hazardous gases, and dangerous chemicals are avoided during demonstrations. Sensor readings are monitored because environmental conditions may cause false alarms or inaccurate detection. The battery, wiring, motor driver, and electronic components are inspected regularly to identify potential faults. The prototype is operated under supervision, and testing is conducted in a controlled environment. Its limitations are clearly acknowledged because sensor readings alone cannot guarantee accurate hazard detection or safe evacuation. AEGIS-X is intended for educational demonstration and experimental evaluation, not as a certified life-safety device. It does not replace professional fire alarms, established emergency procedures, or trained emergency personnel. These safeguards help reduce operational risks", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-14T04:59:09.697Z", "updatedAt": "2026-10-14T18:49:53.297Z", "abstract": { "originalName": "Auraa.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791953948/aura-registrations/abstract-docs/Auraa.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/APEX PIONEERS/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/APEX PIONEERS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791953948/aura-registrations/id-cards/ezuid7oubvyse4xnvvf1.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/APEX PIONEERS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791953948/aura-registrations/id-cards/yhvjshiz7pwasxblevci.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/APEX PIONEERS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791953948/aura-registrations/id-cards/kruzbh3eskrhwbp0s4lc.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/APEX PIONEERS/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1791953948/aura-registrations/id-cards/ssr9tjna4nqixsadhini.jpg", "exists": true }] }, { "index": 44, "id": "6ad06817e82ac79bf0336627", "registrationId": "REG-044", "rawTeamName": "CYBERPUNKS", "folderName": "CYBERPUNKS", "folderRelPath": "assets/Teams/CYBERPUNKS", "projectTitle": "SENTINEL -  smart emergency notification through impact and event level monitoring", "teamSize": 4, "teamAffiliation": "mixed", "aliahMembers": 3, "otherInstitutionMembers": 1, "teamLeaderName": "Riyan Chowdhury", "teamLeaderEmail": "chowdhuryriyan8080@gmail.com", "teamLeaderPhone": "6296040695", "teamMemberDetails": "Sania Afrin | Aliah University | EEN | First Year |+91 74310 20076\r\nShana Parween | Aliah University | EEN | First Year | +91 96474 77976\r\nSumit Sarkar | Techno International | IT | First Year | +91 62948 07500", "hardwareProjectCategories": ["Embedded Systems", "IoT & Smart Devices", "Safety & Security Systems"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "SENTINEL – Smart Wearable Accident Detection and Emergency Alert System\r\n\r\nProblem Statement: After an accident, a person may be unable to contact family members or request assistance quickly. This can be especially concerning for people travelling alone, elderly individuals, and people in situations where immediate help is difficult to obtain.\r\n\r\nProposed Solution: SENTINEL is a compact, watch-like wearable designed to detect potentially dangerous impacts using an ADXL accelerometer connected to an ESP32 microcontroller. The controller analyses acceleration readings against programmed detection criteria. When a possible accident is identified, the device provides a warning and allows the wearer to cancel a false alarm using a button. If the alert is not cancelled, the system is intended to transmit an emergency notification to registered contacts through an IoT-connected website.\r\n\r\nInnovation: SENTINEL combines motion sensing, user-controlled alert cancellation, embedded processing, and web-based notifications in an affordable wearable concept. Its focus is on accessibility, compact design, and reducing dependence on manual emergency calls. The team will evaluate detection thresholds, false alarms, response time, connectivity, and battery performance during prototype testing.\r\n\r\nProposed Outcome: A working prototype demonstrating the process from motion detection to emergency notification, with scope for future improvements in reliability, miniaturisation, and usability. SENTINEL is an assistive prototype, not a certified medical or emergency-response device.", "solutionDescription": "SENTINEL – Smart Wearable Accident Detection and Emergency Alert System\r\n\r\nProblem Statement: After an accident, a person may be unable to contact family members or request assistance quickly. This can be especially concerning for people travelling alone, elderly individuals, and people in situations where immediate help is difficult to obtain.\r\n\r\nProposed Solution: SENTINEL is a compact, watch-like wearable designed to detect potentially dangerous impacts using an ADXL accelerometer connected to an ESP32 microcontroller. The controller analyses acceleration readings against programmed detection criteria. When a possible accident is identified, the device provides a warning and allows the wearer to cancel a false alarm using a button. If the alert is not cancelled, the system is intended to transmit an emergency notification to registered contacts through an IoT-connected website.\r\n\r\nInnovation: SENTINEL combines motion sensing, user-controlled alert cancellation, embedded processing, and web-based notifications in an affordable wearable concept. Its focus is on accessibility, compact design, and reducing dependence on manual emergency calls. The team will evaluate detection thresholds, false alarms, response time, connectivity, and battery performance during prototype testing.\r\n\r\nProposed Outcome: A working prototype demonstrating the process from motion detection to emergency notification, with scope for future improvements in reliability, miniaturisation, and usability. SENTINEL is an assistive prototype, not a certified medical or emergency-response device.", "innovationDescription": "SENTINEL – Smart Wearable Accident Detection and Emergency Alert System\r\n\r\nProblem Statement: After an accident, a person may be unable to contact family members or request assistance quickly. This can be especially concerning for people travelling alone, elderly individuals, and people in situations where immediate help is difficult to obtain.\r\n\r\nProposed Solution: SENTINEL is a compact, watch-like wearable designed to detect potentially dangerous impacts using an ADXL accelerometer connected to an ESP32 microcontroller. The controller analyses acceleration readings against programmed detection criteria. When a possible accident is identified, the device provides a warning and allows the wearer to cancel a false alarm using a button. If the alert is not cancelled, the system is intended to transmit an emergency notification to registered contacts through an IoT-connected website.\r\n\r\nInnovation: SENTINEL combines motion sensing, user-controlled alert cancellation, embedded processing, and web-based notifications in an affordable wearable concept. Its focus is on accessibility, compact design, and reducing dependence on manual emergency calls. The team will evaluate detection thresholds, false alarms, response time, connectivity, and battery performance during prototype testing.\r\n\r\nProposed Outcome: A working prototype demonstrating the process from motion detection to emergency notification, with scope for future improvements in reliability, miniaturisation, and usability. SENTINEL is an assistive prototype, not a certified medical or emergency-response device.", "workingPrinciple": "SENTINEL is a wearable accident-detection and emergency alert system designed to identify potentially dangerous impacts or sudden movements. The device uses an accelerometer-based motion sensor connected to an ESP32 microcontroller. The sensor measures acceleration along multiple axes, and the ESP32 processes this data to identify movement patterns that may indicate an accident. When a possible accident is detected, the system initiates a warning period during which the wearer can press a cancellation button if they are safe. If the alert is not cancelled, the system is designed to send an emergency notification through an IoT-connected platform to inform registered family members or emergency contacts. The goal is to provide a compact, affordable, and responsive wearable solution for faster accident awareness. Detection thresholds and alert logic will be refined through testing to reduce false alarms.", "majorHardwareComponents": ["ESP32 development board (microcontroller with Wi-Fi and Bluetooth)", "ADXL-series accelerometer module (for measuring acceleration and detecting sudden impacts)", "push button (for cancelling false emergency alerts)", "buzzer (for warning indication)", "rechargeable battery with a suitable charging and protection circuit", "connecting wires", "and a compact watch-like enclosure. The final circuit and sensor thresholds will be refined through prototype testing."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Healthcare"], "potentialImpact": "SENTINEL aims to improve accident awareness by providing an affordable wearable system for detecting potentially dangerous impacts and notifying designated contacts. It could benefit students, elderly individuals, people who travel alone, cyclists, and other users who may need assistance after an accident. By combining motion sensing, a user-controlled cancellation mechanism, and internet-based notifications, the proposed device seeks to reduce delays in communicating a possible emergency. Its compact, watch-like form is intended to make it convenient for everyday use. Compared with systems that depend entirely on a person manually requesting help, SENTINEL to initiate an alert when a potentially serious impact is detected. Prototype testing will focus on detection reliability, false alarms, battery life, connectivity, and usability. SENTINEL is an early-stage assistive technology concept and is not intended to replace emergency services or certified medical devices.", "productPotential": "yes", "prototypeDevelopmentCost": 1600, "auraDemoHighlight": "SENTINEL is an affordable, wearable accident-detection and emergency alert prototype designed to help people get assistance when a potentially dangerous impact occurs. Using an ADXL accelerometer and ESP32 microcontroller, the system aims to detect sudden acceleration patterns, provide a warning and cancellation option, and send notifications to registered emergency contacts through an IoT-connected platform. Its watch-like design focuses on portability, practical everyday use, and affordability. SENTINEL brings together electronics, embedded programming, and web technology to address a real-world safety challenge. Visitors can explore how motion sensing is translated into an emergency alert workflow and how the design can be improved through testing. The project is currently under development, with detection accuracy and false-alarm reduction among its key engineering challenges.", "safetyHazards": ["none"], "safetyPrecautions": "SENTINEL is designed as a low-voltage, battery-powered wearable prototype. The circuit will be assembled with correct polarity and insulated connections to reduce the risk of short circuits. A suitable battery protection and charging circuit will be used, and the device will be checked for abnormal heating before testing. The electronics will be secured inside a compact enclosure to reduce accidental contact with exposed connections. Initial testing will be conducted under controlled conditions, with the device removed immediately if overheating, battery swelling, or unusual behaviour occurs. The prototype is intended for demonstration and evaluation, not as a certified medical or life-safety device.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-15T05:43:51.45Z", "updatedAt": "2026-10-15T05:43:51.45Z", "abstract": { "originalName": "inbound469506224264808083.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1792043030/aura-registrations/abstract-docs/inbound469506224264808083", "filename": "Abstract.docx", "relPath": "assets/Teams/CYBERPUNKS/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "SENTINEL\n\nSmart Emergency Notification through Impact and Event Level Monitoring\n\nProblem Statement\n\nAfter an accident or sudden impact, a person may be unable to contact family members or request assistance promptly. This can be especially concerning for people travelling alone, elderly individuals, and others who may have difficulty making a manual emergency call.\n\nProposed Solution and Methodology\n\nSENTINEL (Smart Emergency Notification through Impact and Event Level Monitoring) is a compact, watch-like wearable prototype intended to identify potentially dangerous impacts. An ADXL-series accelerometer measures acceleration, and an ESP32 microcontroller processes the readings against programmed criteria. When a possible event is detected, the device is intended to issue a warning and provide a cancellation button so the wearer can dismiss a false alarm. If the alert is not cancelled, the ESP32 can use Wi-Fi to send an emergency notification through an IoT-connected website to registered contacts. Detection thresholds and alert behaviour will be refined through controlled testing.\n\nProposed Block Diagram\n\n[ADXL Accelerometer] → [ESP32: Event Analysis] → [Warning + Cancel Button]                                                    ↓ if not cancelled[Registered Contacts] ← [Website / IoT Service] ← [ESP32 Wi-Fi]\n\nInnovation\n\nSENTINEL combines impact sensing, embedded processing, a user-controlled alert cancellation mechanism, and web-based notifications in an affordable wearable concept. Its focus is portability and reducing dependence on manual emergency calls. The project integrates electronics, embedded programming, and web development in one system.\n\nProposed Outcome\n\nThe intended outcome is a prototype demonstrating the workflow from motion sensing to an emergency notification. Testing will focus on detection reliability, false alarms, response time, connectivity, and battery performance. SENTINEL is an assistive prototype and is not a certified medical or emergency-response device.\n\nPlanned hardware: ESP32 development board, ADXL-series accelerometer module, push button, warning buzzer, battery with suitable charging/protection, and prototype enclosure." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/CYBERPUNKS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792043030/aura-registrations/id-cards/vkpmqjthuyifmmdzzz2t.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/CYBERPUNKS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792043030/aura-registrations/id-cards/himfffqid9pthiwyysuc.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/CYBERPUNKS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792043030/aura-registrations/id-cards/oak78fetdidgdtkyrs9m.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/CYBERPUNKS/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792043030/aura-registrations/id-cards/bgl5eusp5bhzsj3d9l19.jpg", "exists": true }] }, { "index": 45, "id": "6ad07527d5cce1f001e80d33", "registrationId": "REG-045", "rawTeamName": "Hamburger", "folderName": "Hamburger", "folderRelPath": "assets/Teams/Hamburger", "projectTitle": "STRATA: Resource-Aware Distributed AI Inference on Heterogeneous Computers", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Bappaditya Kuilya", "teamLeaderEmail": "bappadityakuilya@gmail.com", "teamLeaderPhone": "9883867522", "teamMemberDetails": "Fariduddin Ahmed | University of Engineering and Management,Kolkata | CSE | 3rd Year | 8100242647", "hardwareProjectCategories": ["Other"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Problem Statement:\r\n\r\nRunning large AI models on ordinary computers is challenging because of limited memory and computing resources. Distributing AI workloads across multiple computers introduces additional challenges, including network latency and differences in hardware capabilities.\r\n\r\nHardware Solution:\r\n\r\nSTRATA proposes a distributed AI inference system connecting three laptops or computers to execute different parts of an AI model. A central coordinator will monitor available resources and network conditions to determine a feasible execution plan. Raspberry Pi boards may support coordination and telemetry, while Arduino boards can provide physical status indicators and control. A web dashboard will display system performance, memory usage, and execution decisions.\r\n\r\nInnovation Details:\r\n\r\nSTRATA aims to combine resource-aware scheduling and network-aware planning for distributed AI inference on heterogeneous, CPU-based computers. Instead of relying on fixed workload distribution, the system will investigate how execution plans can adapt to changing resource availability and network conditions. It will also compare predicted performance with actual measurements to evaluate whether distributing inference is beneficial. The goal is to demonstrate a practical, measurable approach to running AI models across ordinary computing hardware.", "solutionDescription": "Problem Statement:\r\n\r\nRunning large AI models on ordinary computers is challenging because of limited memory and computing resources. Distributing AI workloads across multiple computers introduces additional challenges, including network latency and differences in hardware capabilities.\r\n\r\nHardware Solution:\r\n\r\nSTRATA proposes a distributed AI inference system connecting three laptops or computers to execute different parts of an AI model. A central coordinator will monitor available resources and network conditions to determine a feasible execution plan. Raspberry Pi boards may support coordination and telemetry, while Arduino boards can provide physical status indicators and control. A web dashboard will display system performance, memory usage, and execution decisions.\r\n\r\nInnovation Details:\r\n\r\nSTRATA aims to combine resource-aware scheduling and network-aware planning for distributed AI inference on heterogeneous, CPU-based computers. Instead of relying on fixed workload distribution, the system will investigate how execution plans can adapt to changing resource availability and network conditions. It will also compare predicted performance with actual measurements to evaluate whether distributing inference is beneficial. The goal is to demonstrate a practical, measurable approach to running AI models across ordinary computing hardware.", "innovationDescription": "Problem Statement:\r\n\r\nRunning large AI models on ordinary computers is challenging because of limited memory and computing resources. Distributing AI workloads across multiple computers introduces additional challenges, including network latency and differences in hardware capabilities.\r\n\r\nHardware Solution:\r\n\r\nSTRATA proposes a distributed AI inference system connecting three laptops or computers to execute different parts of an AI model. A central coordinator will monitor available resources and network conditions to determine a feasible execution plan. Raspberry Pi boards may support coordination and telemetry, while Arduino boards can provide physical status indicators and control. A web dashboard will display system performance, memory usage, and execution decisions.\r\n\r\nInnovation Details:\r\n\r\nSTRATA aims to combine resource-aware scheduling and network-aware planning for distributed AI inference on heterogeneous, CPU-based computers. Instead of relying on fixed workload distribution, the system will investigate how execution plans can adapt to changing resource availability and network conditions. It will also compare predicted performance with actual measurements to evaluate whether distributing inference is beneficial. The goal is to demonstrate a practical, measurable approach to running AI models across ordinary computing hardware.", "workingPrinciple": "Working Principle of STRATA:\r\n\r\nSTRATA is a proposed CPU-first distributed AI inference system designed to run a supported AI language model across multiple ordinary computers.\r\n\r\nFirst, a central coordinator collects information about each computer, including available memory, computing capacity, and network conditions. Based on this information, it evaluates possible execution plans and checks whether each computer can handle its assigned part of the model within its resource limits.\r\n\r\nNext, the selected model is divided into sequential stages and distributed across connected computers. When a user submits a prompt, the first computer processes it through its assigned model layers and sends the intermediate data to the next computer. Each computer processes its respective layers and forwards the results until the final stage generates the response.\r\n\r\nMeanwhile, STRATA monitors memory usage, network latency, worker health, and inference time. If network conditions or available resources change, the coordinator reevaluates the available plans before the next request and selects a suitable alternative when possible. If no plan satisfies the required constraints, the system reports that no feasible plan is available.\r\n\r\nA dashboard displays the model-stage distribution, system status, performance measurements, and reasons behind the coordinator's decisions. The system's performance will be evaluated through controlled experiments comparing distributed execution with baseline approaches.\r\n\r\nSTRATA aims to make distributed AI inference more resource-aware, measurable, and understandable without treating the computers' memory as one unified pool.", "majorHardwareComponents": ["1. Laptops/Computers (3 units): Serve as the primary computing nodes", "with each computer processing a different stage of the AI model.\n\n2. Raspberry Pi Boards (2 units): Support system coordination", "resource monitoring", "telemetry collection", "and experiment observation.\n\n3. Arduino UNO Q Boards (2 units): Support hardware status monitoring", "node health reporting", "and optional small-scale computing experiments.\n\n4. Arduino Uno Boards (2 units): Provide physical control buttons and LED indicators for starting experiments", "selecting network test scenarios", "and displaying system status.\n\n5. Ethernet Switch and Network Cables: Connect the computers and other compatible devices to enable communication and transfer intermediate model data between processing stages.\n\n6. Smartphones (3 units): Provide access to the dashboard", "system monitoring", "and operator controls over the local network.\n\n7. LEDs", "Push Buttons", "Breadboard", "and Jumper Wires: Support the physical control panel and visual indication of system status.\n\n8. Power Supplies and Power Cables: Supply reliable power to the hardware components during experiments and demonstrations."], "useAi": true, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["Other"], "potentialImpact": "Potential Real-World Impact:\r\n\r\nSTRATA aims to make AI inference more accessible by exploring how large AI models can run across multiple ordinary computers instead of depending entirely on a single high-memory machine or expensive specialized hardware. This could help students, researchers, educational institutions, and small development teams experiment with AI using existing computing resources.\r\n\r\nBy considering available memory, computing capacity, and network conditions, STRATA could help users understand when distributing AI workloads is practical and when communication overhead makes it less effective. Its monitoring dashboard and performance measurements would provide insights into resource usage, execution time, and system behavior.\r\n\r\nThe project could also support learning and research in distributed computing, AI infrastructure, and resource-aware scheduling. In the future, its approach could be explored for small laboratories, educational environments, and organizations seeking cost-conscious ways to experiment with AI workloads.\r\n\r\nSTRATA is currently at the proposal and architecture stage. Its actual benefits, performance, and scalability will need to be validated through implementation and controlled experiments.", "productPotential": "yes", "prototypeDevelopmentCost": 25000, "auraDemoHighlight": "STRATA is worth seeing because it explores how multiple ordinary computers can work together to run an AI model when a single computer has limited memory. Its resource-aware planner will consider computing capacity, available memory, and network conditions to identify a feasible execution plan. The proposed system will combine distributed AI inference, real-time monitoring, and a dashboard that explains execution decisions. Through controlled experiments, STRATA aims to measure performance and demonstrate when distributing AI workloads is beneficial and when it is not. By focusing on practical resource utilization, transparent decisions, and measurable results, STRATA offers an interesting approach to making AI experimentation more accessible using existing computing hardware.", "safetyHazards": ["none"], "safetyPrecautions": "Safety Precautions:\r\n\r\n- Use properly rated power supplies and compatible cables for all electronic components.\r\n- Ensure all electrical connections are secure and insulated to prevent short circuits.\r\n- Keep computers and electronic boards in well-ventilated areas to prevent overheating.\r\n- Switch off and disconnect power before changing wiring or connecting hardware components.\r\n- Keep liquids away from computers, circuit boards, and electrical connections.\r\n- Arrange network and power cables neatly to prevent accidental tripping or disconnection.\r\n- Follow the manufacturer's instructions when installing and operating Raspberry Pi and Arduino boards.\r\n- Monitor system temperatures and hardware status during experiments.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-15T06:39:35.235Z", "updatedAt": "2026-10-15T06:39:35.235Z", "abstract": { "originalName": "ABTRACT_IDEA_STRATA.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046373/aura-registrations/abstract-docs/ABTRACT_IDEA_STRATA.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Hamburger/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Hamburger/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046374/aura-registrations/id-cards/ngdi70l8fq8p1w9zsfw1.png", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Hamburger/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046373/aura-registrations/id-cards/nnchmqzydeze7s6akaxn.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Hamburger/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Hamburger/4.jpg", "url": null, "exists": false }] }, { "index": 46, "id": "6ad0756fd5cce1f001e80d34", "registrationId": "REG-046", "rawTeamName": "Sahaara", "folderName": "Sahaara", "folderRelPath": "assets/Teams/Sahaara", "projectTitle": "IoT-Based Dynamic Health Monitoring and Distress Prediction System for Victims of Atrocities", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "ASHIM MONDAL", "teamLeaderEmail": "ashim.au.een@gmail.com", "teamLeaderPhone": "8016550610", "teamMemberDetails": "Meherun Nesa | Aliah University | NURSING | 3rd Year | 6294295119\r\nJasmina Parvin Mallik | Aliah University | NURSING | 3rd Year | 8372925732\r\nShabnam sultana | Aliah University | NURSING | 3rd Year | 6296533258", "hardwareProjectCategories": ["Biomedical / Healthcare Devices", "IoT & Smart Devices"], "prototypeType": "Other", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Victims of atrocities may experience severe psychological distress, emotional trauma, anxiety, depression, and other mental health challenges. However, timely identification of psychological distress is often difficult due to limited access to mental healthcare services, social stigma, lack of continuous health monitoring, and difficulties in communicating psychological symptoms. Conventional assessment methods primarily depend on interviews, self-reported questionnaires, and clinical evaluations, which may not always facilitate timely preliminary screening or continuous observation of physiological changes associated with stress.\r\nThere is a need for an accessible, technology-assisted system that combines physiological health monitoring with standardized psychological screening to support the early identification of potential distress among victims of atrocities. Such a system should collect physiological parameters, assess questionnaire responses, calculate an appropriate screening score, classify the potential level of distress, and provide relevant guidance for further action.\r\nThe proposed solution is an IoT-based psychological distress screening and health monitoring system integrating portable physiological sensors with an Android application. The system consists of heart rate sensor, temperature, and GSR sensor collect physiological parameters that may be associated with stress or emotional arousal. An application incorporates questionnaire-based assessments using the PHQ-9 and WHO-5. Physiological measurements and questionnaire results are processed according to a defined assessment methodology to determine the screening category. Based on the screening results, the application displays appropriate guidance for low, moderate, borderline, or high-concern cases. For high-concern cases, it can provide mental health professional contact details and encourage prompt clinical evaluation.", "solutionDescription": "Victims of atrocities may experience severe psychological distress, emotional trauma, anxiety, depression, and other mental health challenges. However, timely identification of psychological distress is often difficult due to limited access to mental healthcare services, social stigma, lack of continuous health monitoring, and difficulties in communicating psychological symptoms. Conventional assessment methods primarily depend on interviews, self-reported questionnaires, and clinical evaluations, which may not always facilitate timely preliminary screening or continuous observation of physiological changes associated with stress.\r\nThere is a need for an accessible, technology-assisted system that combines physiological health monitoring with standardized psychological screening to support the early identification of potential distress among victims of atrocities. Such a system should collect physiological parameters, assess questionnaire responses, calculate an appropriate screening score, classify the potential level of distress, and provide relevant guidance for further action.\r\nThe proposed solution is an IoT-based psychological distress screening and health monitoring system integrating portable physiological sensors with an Android application. The system consists of heart rate sensor, temperature, and GSR sensor collect physiological parameters that may be associated with stress or emotional arousal. An application incorporates questionnaire-based assessments using the PHQ-9 and WHO-5. Physiological measurements and questionnaire results are processed according to a defined assessment methodology to determine the screening category. Based on the screening results, the application displays appropriate guidance for low, moderate, borderline, or high-concern cases. For high-concern cases, it can provide mental health professional contact details and encourage prompt clinical evaluation.", "innovationDescription": "Victims of atrocities may experience severe psychological distress, emotional trauma, anxiety, depression, and other mental health challenges. However, timely identification of psychological distress is often difficult due to limited access to mental healthcare services, social stigma, lack of continuous health monitoring, and difficulties in communicating psychological symptoms. Conventional assessment methods primarily depend on interviews, self-reported questionnaires, and clinical evaluations, which may not always facilitate timely preliminary screening or continuous observation of physiological changes associated with stress.\r\nThere is a need for an accessible, technology-assisted system that combines physiological health monitoring with standardized psychological screening to support the early identification of potential distress among victims of atrocities. Such a system should collect physiological parameters, assess questionnaire responses, calculate an appropriate screening score, classify the potential level of distress, and provide relevant guidance for further action.\r\nThe proposed solution is an IoT-based psychological distress screening and health monitoring system integrating portable physiological sensors with an Android application. The system consists of heart rate sensor, temperature, and GSR sensor collect physiological parameters that may be associated with stress or emotional arousal. An application incorporates questionnaire-based assessments using the PHQ-9 and WHO-5. Physiological measurements and questionnaire results are processed according to a defined assessment methodology to determine the screening category. Based on the screening results, the application displays appropriate guidance for low, moderate, borderline, or high-concern cases. For high-concern cases, it can provide mental health professional contact details and encourage prompt clinical evaluation.", "workingPrinciple": "The proposed system operates by integrating physiological health monitoring, questionnaire-based psychological assessment, and automated distress screening through an IoT-enabled hardware device and an Android application. \r\n\r\nInitially, the heart rate, body temperature, and Galvanic Skin Response (GSR) sensors collect physiological parameters from the user. A microcontroller processes the sensor outputs and transmits the collected data wirelessly to the Android application through the HC-05 Bluetooth module. \r\n\r\nSimultaneously, the Android application administers two standardized psychological assessment tools: the Patient Health Questionnaire-9 (PHQ-9) and the WHO-5 Well-Being Index. The user's responses are recorded, and the corresponding scores are calculated according to the established scoring guidelines.\r\n\r\n The physiological measurements and questionnaire results are then evaluated using a predefined assessment framework to support preliminary psychological distress screening. Based on the applicable assessment criteria, the application displays a screening category, such as low, borderline, moderate, or high concern, along with appropriate recommendations. These recommendations may include general well-being guidance, continued monitoring, or consultation with a qualified mental health professional. Relevant mental health service contact information can also be provided when necessary.", "majorHardwareComponents": ["Arduino Uno", "heart rate sensors", "temperature sensors", "Galvanic Skin Response sensors", "OLED"], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Healthcare"], "potentialImpact": "The proposed system can support the early identification of potential psychological distress among victims of atrocities through accessible, technology-assisted health monitoring and standardized psychological screening. By combining physiological sensors with an Android application, it may facilitate preliminary assessment in resource-limited settings and encourage timely referral to mental health professionals. The system has the potential to improve awareness of mental well-being, support healthcare workers in monitoring vulnerable individuals, and reduce barriers to accessing psychological support.", "productPotential": "yes", "prototypeDevelopmentCost": 1800, "auraDemoHighlight": "Our project uniquely combines IoT-based physiological monitoring with standardized psychological assessments in a single, affordable, and portable Android-based system. Its key strength is integrating Engineering and Medical expertise to support preliminary distress screening among victims of atrocities, helping identify individuals who may need timely professional mental health support.", "safetyHazards": ["none"], "safetyPrecautions": "NA", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-15T06:40:47.653Z", "updatedAt": "2026-10-15T06:40:47.653Z", "abstract": { "originalName": "Abstract.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1792046447/aura-registrations/abstract-docs/ABSTRACT", "filename": "Abstract.docx", "relPath": "assets/Teams/Sahaara/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "Title:\n\nIoT-Based Dynamic Health Monitoring and Distress Prediction System for Victims of Atrocities\n\nMethodology:\n\nThe proposed system integrates Internet of things (IoT) - based physiological monitoring, standardized psychological questionnaires, and an Android application for preliminary distress screening among victims of atrocities.\n\nHardware Development: A microcontroller is interfaced with a heart rate sensor, body temperature sensor, and Galvanic Skin Response (GSR) sensor to collect physiological parameters. An HC-05 Bluetooth module enables wireless communication between the hardware and the Android application.\n\nData Acquisition and Transmission: The microcontroller collects sensor measurements and transmits the data to the Android application, where the physiological parameters are displayed for real-time or periodic monitoring.\n\nAndroid Application Development: The application incorporates two standardized questionnaires: the Patient Health Questionnaire-9 (PHQ-9) for assessing depressive symptoms and the WHO-5 Well-Being Index for evaluating psychological well-being. Users respond to the questionnaire items through the mobile interface.\n\nScoring and Assessment: The application calculates questionnaire scores according to the respective scoring guidelines. Physiological measurements are evaluated alongside questionnaire results using a predefined assessment framework to support preliminary distress screening.\n\nRisk Classification and Recommendations: Based on the defined assessment criteria, the system categorizes screening results into low, borderline, moderate, and high-concern levels. Appropriate guidance is displayed, including self-care suggestions, recommendations for professional consultation, and relevant mental health service contact information.\n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring SystemFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring SystemBlock Diagram: \n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring System\n\nFigure 1:  Block Diagram of the Proposed IoT-Based Psychological Distress Screening and Health Monitoring System\n\nProposed Outcome:\n\nThe proposed system is expected to provide a functional IoT-based platform for physiological health monitoring and preliminary psychological distress screening among victims of atrocities. This system will enable the collection and visualization of physiological data alongside standardized psychological assessments using the PHQ-9 and WHO-5 questionnaires. The application will evaluate questionnaire scores and relevant physiological measurements using a predefined assessment framework to identify potential levels of distress and generate appropriate recommendations. Depending on the screening results, the system will provide guidance ranging from general well-being suggestions to recommendations for professional mental health consultation and referral. The proposed platform aims to improve accessibility to preliminary screening and facilitate timely identification of individuals who may require further psychological assessment. In future development, artificial intelligence and machine learning techniques may be incorporated to identify patterns in physiological and questionnaire data and improve screening performance." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Sahaara/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046446/aura-registrations/id-cards/t8k3zyhe3j0nrzyjzir5.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Sahaara/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046446/aura-registrations/id-cards/hgtuwtcusts9uqbxmkvq.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Sahaara/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046446/aura-registrations/id-cards/a6zt9oltjf0rk0ftov4b.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Sahaara/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046446/aura-registrations/id-cards/fywutfzjq0dukmgag4id.jpg", "exists": true }] }, { "index": 47, "id": "6ad09d5ce8557c436d78e000", "registrationId": "REG-047", "rawTeamName": "Mindmates", "folderName": "Mindmates", "folderRelPath": "assets/Teams/Mindmates", "projectTitle": "Development of a Digital Mental Health and Psychological Support System for Students in Higher Education", "teamSize": 4, "teamAffiliation": "mixed", "aliahMembers": 3, "otherInstitutionMembers": 1, "teamLeaderName": "Mrinmoy Samanta", "teamLeaderEmail": "mrinmoysamanta627@gmail.com", "teamLeaderPhone": "8346898532", "teamMemberDetails": "Mrinmoy Samanta \r\nGurunanak institute of technology \r\nB.Tech(ECE)\r\n2025-2029\r\n8346898532\r\nNusrat Khatun \r\nAliah University \r\nBsc nursing \r\n2024 -2028 \r\n8348888078\r\nTahmeda Akhtara \r\nAliah University \r\nNursing (Bsc)\r\n2024-2028\r\n9332393379\r\nRasida Parvin \r\nAliah University \r\nBsc nursing \r\n2024- 2028\r\n9732617895", "hardwareProjectCategories": ["Biomedical / Healthcare Devices"], "prototypeType": "IoT Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "MindMate University is an IoT-based mental wellness support prototype designed to help users monitor selected physiological indicators and access appropriate support resources. Many students experience stress and emotional difficulties but may not recognize the need for timely support. The proposed system uses an ESP32 microcontroller connected to a MAX30102 sensor for heart rate and estimated SpO₂ measurement, a GSR sensor for skin conductance, and a web dashboard for displaying available readings. A live PPG waveform and ESP32 connection status can help users observe sensor activity. The website also provides a questionnaire, assessment results, counselling information, and emergency support options. LED and buzzer alerts may indicate configured conditions. The innovation is the integration of low-cost hardware, real-time monitoring, and accessible web-based support in one prototype. The system is intended for wellness awareness and is not a medical diagnostic device. Physiological readings alone cannot diagnose stress or mental health conditions.", "solutionDescription": "MindMate University is an IoT-based mental wellness support prototype designed to help users monitor selected physiological indicators and access appropriate support resources. Many students experience stress and emotional difficulties but may not recognize the need for timely support. The proposed system uses an ESP32 microcontroller connected to a MAX30102 sensor for heart rate and estimated SpO₂ measurement, a GSR sensor for skin conductance, and a web dashboard for displaying available readings. A live PPG waveform and ESP32 connection status can help users observe sensor activity. The website also provides a questionnaire, assessment results, counselling information, and emergency support options. LED and buzzer alerts may indicate configured conditions. The innovation is the integration of low-cost hardware, real-time monitoring, and accessible web-based support in one prototype. The system is intended for wellness awareness and is not a medical diagnostic device. Physiological readings alone cannot diagnose stress or mental health conditions.", "innovationDescription": "MindMate University is an IoT-based mental wellness support prototype designed to help users monitor selected physiological indicators and access appropriate support resources. Many students experience stress and emotional difficulties but may not recognize the need for timely support. The proposed system uses an ESP32 microcontroller connected to a MAX30102 sensor for heart rate and estimated SpO₂ measurement, a GSR sensor for skin conductance, and a web dashboard for displaying available readings. A live PPG waveform and ESP32 connection status can help users observe sensor activity. The website also provides a questionnaire, assessment results, counselling information, and emergency support options. LED and buzzer alerts may indicate configured conditions. The innovation is the integration of low-cost hardware, real-time monitoring, and accessible web-based support in one prototype. The system is intended for wellness awareness and is not a medical diagnostic device. Physiological readings alone cannot diagnose stress or mental health conditions.", "workingPrinciple": "The system uses an ESP32 microcontroller to collect physiological sensor readings and transmit available data to a web dashboard through Wi-Fi. The MAX30102 sensor measures heart rate and estimates SpO₂, while the GSR sensor measures skin conductance. The ESP32 processes the sensor data and sends it to the website, where users can view live readings, connection status, and a PPG waveform when valid sensor data is available. The website also provides a questionnaire, assessment results, counselling information, and emergency support resources. LEDs and a buzzer can provide alerts based on configured conditions. The system displays unavailable readings as \"--\" when the ESP32 or a sensor is disconnected. It is a wellness-support prototype, not a medical diagnostic system.", "majorHardwareComponents": ["The major hardware components are ESP32 development board", "MAX30102 heart rate and SpO₂ sensor", "GSR sensor module", "temperature sensor", "OLED display", "status LEDs", "buzzer", "breadboard", "jumper wires", "and USB power supply. The ESP32 provides processing and Wi-Fi connectivity. The MAX30102 collects optical pulse signals", "while the GSR sensor measures skin conductance. The temperature sensor provides an additional temperature reading if integrated. The OLED displays selected information locally", "and LEDs and the buzzer provide configured visual and audible alerts. A web dashboard displays the available readings and support information."], "useAi": false, "useIot": true, "powerSource": "usb", "intendedBeneficiaries": ["Healthcare"], "potentialImpact": "MindMate University aims to improve awareness of mental wellness among students by combining physiological monitoring with accessible support information. It may help users observe changes in heart rate, estimated SpO₂, and skin conductance while providing questionnaire-based assessments, counselling information, and emergency contacts. The low-cost ESP32-based design could support educational demonstrations and future wellness projects. The web dashboard enables users to view available readings without requiring an expensive touchscreen. The prototype does not replace professional assessment, and its readings should not be used alone to determine mental health status or medical emergencies.", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "**Why This Project Is Worth Seeing**\r\n\r\nMindSense is an innovative student-focused mental wellness monitoring and psychological support system designed to promote awareness of mental well-being among higher education students. Its most impressive feature is the integration of real-time physiological monitoring with a digital platform that can help students understand their wellness status and access appropriate support resources.\r\n\r\nThe system uses an ESP32 microcontroller with sensors such as MAX30102 and GSR to collect physiological data, including heart rate, SpO₂, and skin conductance. The collected readings can be displayed on a web-based dashboard, enabling live monitoring when the hardware and sensors are properly connected. A PPG graph, visual status indicators, and alert features further improve the demonstration.\r\n\r\nAnother unique aspect of MindSense is its combination of sensor-based monitoring, questionnaire responses, and access to psychological support information, including QR-code-based resources. The project aims to make mental wellness technology more accessible and affordable for students by using low-cost electronic components and a website instead of an expensive touchscreen interface.\r\n\r\nMindSense is worth seeing because it combines embedded systems, IoT, web technology, and student well-being in one practical project. It demonstrates how affordable technology can support mental health awareness and encourage students to seek appropriate help when needed. It is intended as a wellness-support prototype, not a medical diagnostic system.", "safetyHazards": ["none"], "safetyPrecautions": "The prototype operates using a low-voltage USB power supply. All wiring and sensor connections are checked before powering the device. The circuit is kept away from water and conductive surfaces, and exposed connections are handled carefully. Components are used within their specified voltage limits. The device is disconnected before changing wiring. The prototype is used for educational wellness monitoring only and is not intended to provide medical diagnosis or replace professional healthcare support.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-15T09:31:08.513Z", "updatedAt": "2026-10-15T09:31:08.513Z", "abstract": { "originalName": "aura Title.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792056667/aura-registrations/abstract-docs/aura%20Title.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Mindmates/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Mindmates/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792056668/aura-registrations/id-cards/fl8k0qirqdd0mguokcef.png", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Mindmates/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792056667/aura-registrations/id-cards/qx55r0vwz6zuapvov1lg.png", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Mindmates/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792056667/aura-registrations/id-cards/ikeqo00dwgpzuhnrjg5z.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Mindmates/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792056667/aura-registrations/id-cards/elfpirqw2kwzhe8n7eax.png", "exists": true }] }, { "index": 48, "id": "6ad0fe154dedb92b791c33f1", "registrationId": "AURA2K26-FY7JTK", "rawTeamName": "Tech pair", "folderName": "Tech pair", "folderRelPath": "assets/Teams/Tech pair", "projectTitle": "​Smart Access Control System using Arduino", "teamSize": 4, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 4, "teamLeaderName": "Piyush kumar", "teamLeaderEmail": "piyush91424121@gmail.com", "teamLeaderPhone": "9142412138", "teamMemberDetails": "Manish kumar, debojyoti benerjee , Sekh Asraful Haque", "hardwareProjectCategories": ["Embedded Systems"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement:\r\nTraditional security systems rely heavily on physical keys or basic identification methods, which are vulnerable to loss, unauthorized copying, and security breaches. In sensitive environments like research labs, server rooms, and confidential offices, restricted access is essential, but existing smart access solutions are often expensive, complex to integrate, or lack real-time control features.\r\n​Hardware Solution:\r\nTo address this challenge, we developed a smart, reliable, and cost-effective access control system powered by an Arduino board integrated with a 4x4 membrane keypad and electronic locking mechanism. The user enters a secure passcode via the keypad, which is instantly processed by the micro-controller logic. Upon successful passcode authentication, the system signals the actuator to unlock the door, displaying access status clearly on an interface. Incorrect attempts trigger local alerts to prevent unauthorized entry.\r\n​Innovation Details:\r\nOur system’s key innovation lies in its compact, stand-alone architecture combining high reliability with modular scalability. It offers customizable passcodes, low power consumption, and fast input processing without needing complex server setups. Additionally, the system is designed to easily integrate with IoT modules (such as Wi-Fi/Bluetooth) for real-time remote monitoring, activity logging, and instant security notifications, making embedded security accessible and efficient for practical applications.", "solutionDescription": "Problem Statement:\r\nTraditional security systems rely heavily on physical keys or basic identification methods, which are vulnerable to loss, unauthorized copying, and security breaches. In sensitive environments like research labs, server rooms, and confidential offices, restricted access is essential, but existing smart access solutions are often expensive, complex to integrate, or lack real-time control features.\r\n​Hardware Solution:\r\nTo address this challenge, we developed a smart, reliable, and cost-effective access control system powered by an Arduino board integrated with a 4x4 membrane keypad and electronic locking mechanism. The user enters a secure passcode via the keypad, which is instantly processed by the micro-controller logic. Upon successful passcode authentication, the system signals the actuator to unlock the door, displaying access status clearly on an interface. Incorrect attempts trigger local alerts to prevent unauthorized entry.\r\n​Innovation Details:\r\nOur system’s key innovation lies in its compact, stand-alone architecture combining high reliability with modular scalability. It offers customizable passcodes, low power consumption, and fast input processing without needing complex server setups. Additionally, the system is designed to easily integrate with IoT modules (such as Wi-Fi/Bluetooth) for real-time remote monitoring, activity logging, and instant security notifications, making embedded security accessible and efficient for practical applications.", "innovationDescription": "Problem Statement:\r\nTraditional security systems rely heavily on physical keys or basic identification methods, which are vulnerable to loss, unauthorized copying, and security breaches. In sensitive environments like research labs, server rooms, and confidential offices, restricted access is essential, but existing smart access solutions are often expensive, complex to integrate, or lack real-time control features.\r\n​Hardware Solution:\r\nTo address this challenge, we developed a smart, reliable, and cost-effective access control system powered by an Arduino board integrated with a 4x4 membrane keypad and electronic locking mechanism. The user enters a secure passcode via the keypad, which is instantly processed by the micro-controller logic. Upon successful passcode authentication, the system signals the actuator to unlock the door, displaying access status clearly on an interface. Incorrect attempts trigger local alerts to prevent unauthorized entry.\r\n​Innovation Details:\r\nOur system’s key innovation lies in its compact, stand-alone architecture combining high reliability with modular scalability. It offers customizable passcodes, low power consumption, and fast input processing without needing complex server setups. Additionally, the system is designed to easily integrate with IoT modules (such as Wi-Fi/Bluetooth) for real-time remote monitoring, activity logging, and instant security notifications, making embedded security accessible and efficient for practical applications.", "workingPrinciple": "The system operates on a digital input-verification and actuator control principle. A 4x4 matrix membrane keypad is continuously scanned by the Arduino microcontroller to detect keypress inputs from the user. When a sequence of keys is pressed, the microcontroller captures the digital signals and compares the entered passcode string against a predefined, secure passcode stored in its EEPROM/flash memory.\r\n​If the entered passcode matches the stored security key, the microcontroller sends a control signal (HIGH output) to a relay driver module. This energizes the relay switch, which in turn activates the electronic door lock mechanism (such as a solenoid lock or DC motor) to open the door for a designated timeframe. Simultaneously, visual indicators (LEDs) and a buzzer provide success feedback.\r\n​If the passcode is incorrect, the system denies access, triggers a warning beep via the buzzer, and increments an error counter. After a set number of consecutive failed attempts, a temporary lockout or local security alarm is activated to prevent brute-force attacks. The system continuously resets its input buffer to await the next authorized user authentication request.", "majorHardwareComponents": ["Arduino Microcontroller Board: Acts as the central processing unit and brain of the system", "running the compiled control code to process inputs and manage outputs.  \n​4x4 Matrix Membrane Keypad: Used as the primary user input interface for entering secure numeric or alphanumeric passcodes.  \n​Relay Module (1-Channel/2-Channel): Serves as an electrically operated switch that allows the low-voltage Arduino output to safely control the higher-voltage electronic lock mechanism.  \n​Electronic Lock Mechanism: A solenoid lock or electromechanical door strike that physically locks or unlocks the door upon receiving the relay trigger.  \n​Buzzer and LED Indicators: Provides auditory beeps and visual cues for successful access", "error warnings", "and alert notifications.  \n​Power Supply Unit: Regulated DC power source (such as a 5V/12V adapter or battery) to supply stable operating voltage to the Arduino board and connected hardware peripherals.  \n​Connecting Wires and Breadboard / PCB: Used for secure electrical interconnections between the components."], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["Industry", "General Public"], "potentialImpact": "​This system provides a highly secure, reliable, and cost-effective access control solution that significantly improves upon traditional mechanical lock vulnerabilities such as lost keys or unauthorized key duplication.  \r\n​Who benefits from this?\r\nEducational institutions, research laboratories, small-to-medium enterprises, corporate offices, and residential spaces benefit directly by securing sensitive rooms and private areas without high installation costs.  \r\n​How does it improve current standards?\r\nWhile high-end biometric or smart card systems are expensive and complex to maintain, our embedded Arduino-based keypad solution offers an accessible, low-power, and robust alternative. It eliminates the dependency on physical keys, prevents unauthorized entry through digital passcode verification, and introduces affordable automated security for everyday practical use.", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "Judges and visitors should pay attention to this project because it transforms standard, expensive security infrastructure into an affordable, highly efficient, and practical plug-and-play solution.  \r\n​Most Impressive & Unique Aspects:\r\n​Reliable Standalone Performance: It successfully bridges the gap between high-end commercial biometric systems and vulnerable traditional key locks by offering robust digital passcode authentication.  \r\n​Cost-Effectiveness & Simplicity: Built using widely accessible components like an Arduino and a membrane keypad, the entire unit is extremely budget-friendly while maintaining professional-grade reliability.  \r\n​Scalable Architecture: The design features clean modular integration, making it effortlessly adaptable for future expansions such as IoT cloud logging or wireless alerting.  \r\n​This project demonstrates how smart engineering can solve everyday physical security challenges efficiently and economically.", "safetyHazards": ["none"], "safetyPrecautions": "Although our embedded system operates on a low and safe voltage level (5V/12V) with minimal physical hazards, standard electrical safety measures have been strictly integrated:  \r\n​Low-Voltage Operation: The core microcontroller and keypad operate entirely on low DC voltage, completely eliminating any risk of electric shock during handling or demonstration.  \r\n​Isolated Switching: A relay module is used to safely isolate the low-power Arduino control circuit from any external locking mechanism or power supply.  \r\n​Proper Insulation and Wiring: All electronic wiring, pin connections, and power modules are securely insulated and checked to prevent short circuits, loose contacts, or overheating.  \r\n​Fail-Safe Mechanism: The system is designed to default to a secure state in case of power interruption, ensuring reliable operation without hazardous failures.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-15T16:23:49.689Z", "updatedAt": "2026-10-15T16:25:49.791Z", "abstract": { "originalName": "Abstract Write-up.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792081427/aura-registrations/abstract-docs/Abstract%20Write-up.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Tech pair/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Tech pair/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792081428/aura-registrations/id-cards/nptill53iqgiq9gb6jan.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Tech pair/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792081428/aura-registrations/id-cards/gbpqyh2by6faarawqd43.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Tech pair/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792081427/aura-registrations/id-cards/paomtzs1gt5aroihvrbr.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Tech pair/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792081427/aura-registrations/id-cards/day2p83f8ici22pfk3qe.jpg", "exists": true }] }, { "index": 49, "id": "6ad3c1ba9e81220232adca2a", "registrationId": "AURA2K26-2RXUDC", "rawTeamName": "DORA", "folderName": "DORA", "folderRelPath": "assets/Teams/DORA", "projectTitle": "SentinelQ – An Intelligent Hardware Guardian for IoT Security", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Razaul Shoaib", "teamLeaderEmail": "razaulshoaib@gmail.com", "teamLeaderPhone": "7870190316", "teamMemberDetails": "Razaul Shoaib (Leader) | Aliah university | Computer science and engineering | 3rd year | 7870190316\r\n\r\nSaad Ziya | Aliah University | Mechanical Engineering | 2nd year | 9102122331\r\n\r\nSyed Nawedul Hasan | Aliah University | Computer Science and Engineering | 3rd year | 8116985287\r\n\r\nTahira Farheen | Aliah University | Computer Science and Engineering | 2nd year | 9204094287", "hardwareProjectCategories": ["Safety & Security Systems", "IoT & Smart Devices", "Embedded Systems", "Electronics & Communication"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement:\r\nIoT devices are vulnerable to network intrusions, physical tampering, abnormal power consumption, and firmware manipulation. Conventional security systems primarily monitor network traffic and may miss physical or electrical signs of compromise. Many systems also only generate alerts instead of actively containing threats, leaving vulnerable devices exposed.\r\n\r\nProposed Solution:\r\nSentinelQ is a hardware-assisted, intelligent IoT security system built around the Arduino Uno Q. It combines current and power sensing, an IMU-based tamper detector, device-integrity checks, and network-behavior monitoring to establish normal operating patterns. An edge-based detection engine correlates these signals and calculates a dynamic threat score. When suspicious activity is detected, SentinelQ can activate alarms, block or restrict suspicious communication, and trigger a switching mechanism to physically isolate the affected device. A controlled honeypot captures suspicious interactions for analysis, while a web dashboard displays threat levels, device status, evidence, and response events.\r\n\r\nInnovation Details:\r\nSentinelQ transforms hardware from a passive monitoring component into an active cyber-defense layer. Its key innovation is \"multimodal threat correlation\", combining electrical, physical, network, and integrity indicators instead of relying on a single detection source. This approach aims to improve detection confidence and reduce false alarms. The integration of edge intelligence, physical containment, and honeypot-based investigation enables a tangible, real-time demonstration of autonomous IoT defense. All attack simulations and containment tests will be performed within an isolated laboratory environment.", "solutionDescription": "Problem Statement:\r\nIoT devices are vulnerable to network intrusions, physical tampering, abnormal power consumption, and firmware manipulation. Conventional security systems primarily monitor network traffic and may miss physical or electrical signs of compromise. Many systems also only generate alerts instead of actively containing threats, leaving vulnerable devices exposed.\r\n\r\nProposed Solution:\r\nSentinelQ is a hardware-assisted, intelligent IoT security system built around the Arduino Uno Q. It combines current and power sensing, an IMU-based tamper detector, device-integrity checks, and network-behavior monitoring to establish normal operating patterns. An edge-based detection engine correlates these signals and calculates a dynamic threat score. When suspicious activity is detected, SentinelQ can activate alarms, block or restrict suspicious communication, and trigger a switching mechanism to physically isolate the affected device. A controlled honeypot captures suspicious interactions for analysis, while a web dashboard displays threat levels, device status, evidence, and response events.\r\n\r\nInnovation Details:\r\nSentinelQ transforms hardware from a passive monitoring component into an active cyber-defense layer. Its key innovation is \"multimodal threat correlation\", combining electrical, physical, network, and integrity indicators instead of relying on a single detection source. This approach aims to improve detection confidence and reduce false alarms. The integration of edge intelligence, physical containment, and honeypot-based investigation enables a tangible, real-time demonstration of autonomous IoT defense. All attack simulations and containment tests will be performed within an isolated laboratory environment.", "innovationDescription": "Problem Statement:\r\nIoT devices are vulnerable to network intrusions, physical tampering, abnormal power consumption, and firmware manipulation. Conventional security systems primarily monitor network traffic and may miss physical or electrical signs of compromise. Many systems also only generate alerts instead of actively containing threats, leaving vulnerable devices exposed.\r\n\r\nProposed Solution:\r\nSentinelQ is a hardware-assisted, intelligent IoT security system built around the Arduino Uno Q. It combines current and power sensing, an IMU-based tamper detector, device-integrity checks, and network-behavior monitoring to establish normal operating patterns. An edge-based detection engine correlates these signals and calculates a dynamic threat score. When suspicious activity is detected, SentinelQ can activate alarms, block or restrict suspicious communication, and trigger a switching mechanism to physically isolate the affected device. A controlled honeypot captures suspicious interactions for analysis, while a web dashboard displays threat levels, device status, evidence, and response events.\r\n\r\nInnovation Details:\r\nSentinelQ transforms hardware from a passive monitoring component into an active cyber-defense layer. Its key innovation is \"multimodal threat correlation\", combining electrical, physical, network, and integrity indicators instead of relying on a single detection source. This approach aims to improve detection confidence and reduce false alarms. The integration of edge intelligence, physical containment, and honeypot-based investigation enables a tangible, real-time demonstration of autonomous IoT defense. All attack simulations and containment tests will be performed within an isolated laboratory environment.", "workingPrinciple": "SentinelQ uses the Arduino Uno Q to monitor IoT devices through power sensors, an IMU, tamper switches, and network telemetry. It analyzes abnormal electrical behavior, physical disturbances, and suspicious network activity using rule-based detection and optional machine learning. When a threat is detected, it triggers alarms, blocks suspicious communication, or isolates the device using a switching circuit. A web dashboard displays alerts, threat levels, and event logs.", "majorHardwareComponents": ["Arduino Uno Q", "ESP32 development board", "INA219 current sensor", "MPU6050 IMU", "tamper switch", "relay module", "RGB LED", "buzzer", "OLED display (optional)", "Wi-Fi router", "connecting wires", "and regulated power supply."], "useAi": true, "useIot": true, "powerSource": "usb", "intendedBeneficiaries": ["Industry", "Government / Public Services", "Urban Communities", "Education"], "potentialImpact": "Beneficiaries include manufacturers, integrators, and operators of smart homes, industrial automation, critical infrastructure, and smart cities where IoT devices are vulnerable to physical tampering, power manipulation, firmware tampering, and network exploitation. SentinelQ improves standard security by moving beyond network-only monitoring to introduce an active, hardware-centric cyber-physical security layer. It fuses electrical behavior (current sensing), mechanical tampering (IMU vibration), device state/firmware checks, and network telemetry into a unified behavioral profile. By combining rule-based logic with ML-driven anomaly detection to compute dynamic risk scores, it reduces false positives compared to single-signal systems and provides automated containment through physical hardware isolation, rate-limiting, honeypot redirection, and alarms.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "SentinelQ transforms edge security from passive detection into an active physical guardian. The most impressive aspects include its cyber-physical signal correlation, fusing physical metrics like vibration/tampering and power consumption with digital state metrics like firmware integrity and network telemetry right on the edge using the Arduino Uno Q. It demonstrates autonomous physical containment by physically disconnecting or isolating compromised IoT devices through high-speed relay switching, blocking communications, and triggering localized alarms. It also offers advanced dynamic honeypot redirection to transparently redirect malicious sessions for real-time forensic evidence collection in controlled laboratory settings, backed by a live multi-signal companion dashboard.", "safetyHazards": ["none"], "safetyPrecautions": "The prototype will operate using low-voltage power. All electronic connections will be checked before powering on the system. Sensors and wiring will be securely connected, and exposed conductive parts will be insulated to prevent accidental short circuits. The switching mechanism will be used within its rated voltage and current limits. The prototype will be placed on a stable, dry surface with adequate ventilation. Power will be disconnected before changing wiring or hardware components. Testing will be conducted in a controlled environment, and any unexpected heating, sparks, or abnormal operation will result in immediate shutdown.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-17T18:43:06.476Z", "updatedAt": "2026-10-17T18:45:06.62Z", "abstract": { "originalName": "SentinelQ-final.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792262584/aura-registrations/abstract-docs/SentinelQ-final.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/DORA/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/DORA/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792262585/aura-registrations/id-cards/bgizvad6lu6o1ge3rnqk.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/DORA/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792262584/aura-registrations/id-cards/n07wmwdehyinydbrpemv.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/DORA/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792262585/aura-registrations/id-cards/bucy9dokdy5mty7htsht.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/DORA/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792262585/aura-registrations/id-cards/axbxcxcubbsofkeqxlig.jpg", "exists": true }] }, { "index": 50, "id": "6ad61d06d013411f7f895522", "registrationId": "AURA2K26-RK9F9K", "rawTeamName": "ALPHA TECH", "folderName": "ALPHA TECH", "folderRelPath": "assets/Teams/ALPHA TECH", "projectTitle": "SAFE BAND (SMART SAFETY WEARABLE)", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "SOUMYAJIT SARDER", "teamLeaderEmail": "soumyajitsarder77@gmail.com", "teamLeaderPhone": "8637505062", "teamMemberDetails": "ILHAN HASSAN-ALIAH UNIVERSITY-ELECTRICAL ENGINEERING-3RD YEAR-6289534937\r\nMD MASUD ALAM SARDER-ALIAH UNIVERSITY-ELECTRICAL ENGINEERING-1ST YEAR-7364989631\r\nMAMAN RASHID SHAIKH- ALIAH UNIVERSITY-ELECTRICAL ENGINEERING-1ST YEAR -6297573119", "hardwareProjectCategories": ["Safety & Security Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "In emergencies, women often cannot reach for or use a phone to call for help. Fear, restraint or a sudden attack leaves no time, and most safety apps need several manual steps before any alert is sent.\r\n\r\nSafeBand is a low-cost, screenless wearable safety band. An ESP32 microcontroller continuously reads a heart rate sensor (MAX30102) and a motion sensor (MPU6050). When a sudden heart rate spike occurs together with violent, irregular motion, the band vibrates for 10 seconds so the wearer can cancel a false alarm. If it is not cancelled, the band sends a Bluetooth signal to a companion mobile app. The app automatically calls the emergency number and sends an SMS with live GPS location to trusted contacts, while the band sounds a loud siren. A triple-press SOS button also allows an instant manual alert.\r\n\r\nInnovation:\r\n- Two-signal detection (heart rate plus motion) reduces false alarms.\r\n- A 10-second cancel window prevents unnecessary alerts.\r\n- The band needs no SIM or GPS because the phone handles calling and location, which keeps cost and size low.\r\n- Hands-free automatic detection works even when the user cannot touch her phone.\r\n- Safe by design: it uses siren and vibration, not electric shock.", "solutionDescription": "In emergencies, women often cannot reach for or use a phone to call for help. Fear, restraint or a sudden attack leaves no time, and most safety apps need several manual steps before any alert is sent.\r\n\r\nSafeBand is a low-cost, screenless wearable safety band. An ESP32 microcontroller continuously reads a heart rate sensor (MAX30102) and a motion sensor (MPU6050). When a sudden heart rate spike occurs together with violent, irregular motion, the band vibrates for 10 seconds so the wearer can cancel a false alarm. If it is not cancelled, the band sends a Bluetooth signal to a companion mobile app. The app automatically calls the emergency number and sends an SMS with live GPS location to trusted contacts, while the band sounds a loud siren. A triple-press SOS button also allows an instant manual alert.\r\n\r\nInnovation:\r\n- Two-signal detection (heart rate plus motion) reduces false alarms.\r\n- A 10-second cancel window prevents unnecessary alerts.\r\n- The band needs no SIM or GPS because the phone handles calling and location, which keeps cost and size low.\r\n- Hands-free automatic detection works even when the user cannot touch her phone.\r\n- Safe by design: it uses siren and vibration, not electric shock.", "innovationDescription": "In emergencies, women often cannot reach for or use a phone to call for help. Fear, restraint or a sudden attack leaves no time, and most safety apps need several manual steps before any alert is sent.\r\n\r\nSafeBand is a low-cost, screenless wearable safety band. An ESP32 microcontroller continuously reads a heart rate sensor (MAX30102) and a motion sensor (MPU6050). When a sudden heart rate spike occurs together with violent, irregular motion, the band vibrates for 10 seconds so the wearer can cancel a false alarm. If it is not cancelled, the band sends a Bluetooth signal to a companion mobile app. The app automatically calls the emergency number and sends an SMS with live GPS location to trusted contacts, while the band sounds a loud siren. A triple-press SOS button also allows an instant manual alert.\r\n\r\nInnovation:\r\n- Two-signal detection (heart rate plus motion) reduces false alarms.\r\n- A 10-second cancel window prevents unnecessary alerts.\r\n- The band needs no SIM or GPS because the phone handles calling and location, which keeps cost and size low.\r\n- Hands-free automatic detection works even when the user cannot touch her phone.\r\n- Safe by design: it uses siren and vibration, not electric shock.", "workingPrinciple": "SafeBand works by continuously monitoring the wearer's heart rate and body movements using a heart-rate sensor and a motion sensor connected to an ESP32 microcontroller. The sensor data is analysed to identify unusual heart-rate patterns combined with violent movements that may indicate a dangerous situation. If potential danger is detected, the band vibrates for 10 seconds, giving the wearer an opportunity to cancel a false alarm by tapping. If the alert is not cancelled, the system activates the buzzer and communicates with a connected mobile application through Bluetooth Low Energy (BLE). The application can send emergency calls and SMS messages to predefined contacts, along with GPS-based location information and a live tracking link. The user can also manually trigger a silent SOS alert by pressing the dedicated button three times. This combination of automatic detection and manual activation helps users request assistance quickly, even when accessing a phone is difficult.", "majorHardwareComponents": ["1. ESP32 Microcontroller: Main controller for processing sensor data and managing system operations.\n2. Heart-Rate Sensor: Continuously monitors the wearer's heart rate.\n3. Motion Sensor: Detects body movement and unusual physical activity.\n4. SOS Push Button: Allows manual emergency alert activation through a triple press.\n5. Buzzer: Produces a loud sound to attract attention during an emergency.\n6. Vibration Motor: Provides silent alerts and a warning before emergency activation.\n7. Bluetooth Low Energy (BLE): Enables communication between the band and the mobile application.\n8. Battery: Supplies portable power to the wearable device.\n9. GPS-enabled Mobile Phone: Provides location information for emergency alerts through the connected application.\n\nThese components work together to support emergency detection", "user warnings", "and communication with trusted contacts."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public"], "potentialImpact": "SafeBand can benefit women, students, elderly people, and individuals who may face emergencies while travelling or working alone. It helps users request assistance without needing to unlock a phone or navigate a safety application. By combining automatic danger detection, manual SOS activation, vibration alerts, a buzzer, and location sharing through a connected mobile application, SafeBand aims to reduce delays in emergency communication. It can notify trusted contacts and help them identify the user's location more quickly. Its wearable, screenless design offers a simple and portable approach to personal safety. Future improvements such as AI-based detection and voice-triggered alerts could further enhance its reliability and usability.", "productPotential": "yes", "prototypeDevelopmentCost": 3000, "auraDemoHighlight": "SafeBand solves a real problem: in an emergency, a woman often cannot reach for or unlock her phone. Our band acts before she has to.\r\n\r\nWhat makes it worth seeing:\r\n- It detects danger automatically by combining two signals, a sudden heart rate spike and violent motion, so ordinary activities like running rarely trigger it.\r\n- A 10-second vibration countdown lets the wearer cancel a false alarm, which keeps the system practical for daily use.\r\n- It is screenless and low-cost. The phone handles calling and GPS, so the band needs no SIM or GPS module.\r\n- A triple-press SOS button gives an instant manual alert, and a loud siren draws attention nearby.\r\n- It is built to be safe: sirens and vibration only, no electric shock.\r\n\r\nJudges can see the full chain in action: sensing, confirmation, Bluetooth signal, app alert with live location, and siren. It is a simple, affordable idea that could genuinely help women, students and elderly people who travel or work alone.", "safetyHazards": ["none"], "safetyPrecautions": "SafeBand is designed to be safe for the wearer at every level.\r\n\r\n- Low voltage only: the whole device runs on a small 3.7V rechargeable battery. There is no high voltage, high current or mains connection in the wearable.\r\n- Protected battery: the LiPo battery is used with a charging module that has overcharge and short-circuit protection. It is enclosed inside the band case.\r\n- Enclosed electronics: all wires, the ESP32 and the sensors are sealed inside a smooth case, so the wearer never touches exposed circuits. There are no sharp parts.\r\n- No electric shock: we deliberately chose a siren and vibration alerts instead of any shock mechanism, to avoid injury from false alarms.\r\n- Skin safety: the part touching the wrist is a smooth, non-toxic strap and sensor window. The sensor uses low-power light, so there is no harmful radiation.\r\n- False alarm control: a 10-second vibration countdown lets the wearer cancel before any alert is sent.\r\n- Safe demo: during testing we use only friends' numbers, never real emergency numbers, to avoid false emergency calls.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-19T13:37:10.199Z", "updatedAt": "2026-10-19T13:39:10.303Z", "abstract": { "originalName": "SafeBand_Presentation-1.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792417029/aura-registrations/abstract-docs/SafeBand_Presentation-1.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/ALPHA TECH/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/ALPHA TECH/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792417029/aura-registrations/id-cards/cmozbtignnslkn1yqvnd.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/ALPHA TECH/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792417029/aura-registrations/id-cards/wrhmyfmu2bt9rlnj7jze.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/ALPHA TECH/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792417029/aura-registrations/id-cards/dq6yheqxr37sx57jpo9h.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/ALPHA TECH/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792417029/aura-registrations/id-cards/mndmkjg0n9urnpyvitdl.jpg", "exists": true }] }, { "index": 51, "id": "6ad7b7460d61f75d250efaba", "registrationId": "AURA2K26-PLUACP", "rawTeamName": "Virgin Mojito", "folderName": "Virgin Mojito", "folderRelPath": "assets/Teams/Virgin Mojito", "projectTitle": "STRATA: Resource-Aware Distributed AI Inference on Heterogeneous Computers", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Bappaditya Kuilya", "teamLeaderEmail": "fariduddin1.online@gmail.com", "teamLeaderPhone": "9883867522", "teamMemberDetails": "Fariduddin Ahmed | University of engineering and Management, Kolkata | CSE | 3rd Year | 8100242647", "hardwareProjectCategories": ["AI-Enabled Hardware", "Embedded Systems", "IoT & Smart Devices", "Assistive Technology", "Industrial / Manufacturing Technology", "Safety & Security Systems"], "prototypeType": "Standalone Hardware Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "STRATA addresses the challenge of running large AI models on ordinary computers with limited memory and compute power, where a single machine may not be able to run the model, and distributing workloads across computers introduces network latency, communication overhead, and varying hardware capabilities. Proposed solution. STRATA is a proposed CPU-first distributed AI inference system that divides a model into stages and runs them across multiple connected computers. A central coordinator will monitor available memory, compute resources, and network conditions to select a feasible execution plan, while a live dashboard displays worker status, resource usage, communication latency, and inference performance. Innovation details. The innovation lies in combining resource-aware scheduling with network-aware planning, rather than relying on fixed model partitions. STRATA will investigate how changing network conditions affect planning decisions and compare adaptive strategies against static distribution. The project aims to demonstrate both the benefits and limitations of distributed AI inference on ordinary computers.", "solutionDescription": "STRATA addresses the challenge of running large AI models on ordinary computers with limited memory and compute power, where a single machine may not be able to run the model, and distributing workloads across computers introduces network latency, communication overhead, and varying hardware capabilities. Proposed solution. STRATA is a proposed CPU-first distributed AI inference system that divides a model into stages and runs them across multiple connected computers. A central coordinator will monitor available memory, compute resources, and network conditions to select a feasible execution plan, while a live dashboard displays worker status, resource usage, communication latency, and inference performance. Innovation details. The innovation lies in combining resource-aware scheduling with network-aware planning, rather than relying on fixed model partitions. STRATA will investigate how changing network conditions affect planning decisions and compare adaptive strategies against static distribution. The project aims to demonstrate both the benefits and limitations of distributed AI inference on ordinary computers.", "innovationDescription": "STRATA addresses the challenge of running large AI models on ordinary computers with limited memory and compute power, where a single machine may not be able to run the model, and distributing workloads across computers introduces network latency, communication overhead, and varying hardware capabilities. Proposed solution. STRATA is a proposed CPU-first distributed AI inference system that divides a model into stages and runs them across multiple connected computers. A central coordinator will monitor available memory, compute resources, and network conditions to select a feasible execution plan, while a live dashboard displays worker status, resource usage, communication latency, and inference performance. Innovation details. The innovation lies in combining resource-aware scheduling with network-aware planning, rather than relying on fixed model partitions. STRATA will investigate how changing network conditions affect planning decisions and compare adaptive strategies against static distribution. The project aims to demonstrate both the benefits and limitations of distributed AI inference on ordinary computers.", "workingPrinciple": "Working Principle of STRATA:\r\n\r\nSTRATA is a proposed CPU-first distributed AI inference system designed to run a supported AI language model across multiple ordinary computers.\r\n\r\nFirst, a central coordinator collects information about each computer, including available memory, computing capacity, and network conditions. Based on this information, it evaluates possible execution plans and checks whether each computer can handle its assigned part of the model within its resource limits.\r\n\r\nNext, the selected model is divided into sequential stages and distributed across connected computers. When a user submits a prompt, the first computer processes it through its assigned model layers and sends the intermediate data to the next computer. Each computer processes its respective layers and forwards the results until the final stage generates the response.\r\n\r\nMeanwhile, STRATA monitors memory usage, network latency, worker health, and inference time. If network conditions or available resources change, the coordinator reevaluates the available plans before the next request and selects a suitable alternative when possible. If no plan satisfies the required constraints, the system reports that no feasible plan is available.\r\n\r\nA dashboard displays the model-stage distribution, system status, performance measurements, and reasons behind the coordinator's decisions. The system's performance will be evaluated through controlled experiments comparing distributed execution with baseline approaches.\r\n\r\nSTRATA aims to make distributed AI inference more resource-aware, measurable, and understandable without treating the computers' memory as one unified pool.", "majorHardwareComponents": ["1. Laptops/Computers (3 units): Serve as the primary computing nodes", "with each computer processing a different stage of the AI model.\n\n2. Raspberry Pi Boards (2 units): Support system coordination", "resource monitoring", "telemetry collection", "and experiment observation.\n\n3. Arduino UNO Q Boards (2 units): Support hardware status monitoring", "node health reporting", "and optional small-scale computing experiments.\n\n4. Arduino Uno Boards (2 units): Provide physical control buttons and LED indicators for starting experiments", "selecting network test scenarios", "and displaying system status.\n\n5. Ethernet Switch and Network Cables: Connect the computers and other compatible devices to enable communication and transfer intermediate model data between processing stages.\n\n6. Smartphones (3 units): Provide access to the dashboard", "system monitoring", "and operator controls over the local network.\n\n7. LEDs", "Push Buttons", "Breadboard", "and Jumper Wires: Support the physical control panel and visual indication of system status.\n\n8. Power Supplies and Power Cables: Supply reliable power to the hardware components during experiments and demonstrations."], "useAi": true, "useIot": true, "powerSource": "usb", "intendedBeneficiaries": ["General Public", "Industry"], "potentialImpact": "Potential Real-World Impact:\r\n\r\nSTRATA aims to make AI inference more accessible by exploring how large AI models can run across multiple ordinary computers instead of depending entirely on a single high-memory machine or expensive specialized hardware. This could help students, researchers, educational institutions, and small development teams experiment with AI using existing computing resources.\r\n\r\nBy considering available memory, computing capacity, and network conditions, STRATA could help users understand when distributing AI workloads is practical and when communication overhead makes it less effective. Its monitoring dashboard and performance measurements would provide insights into resource usage, execution time, and system behavior.\r\n\r\nThe project could also support learning and research in distributed computing, AI infrastructure, and resource-aware scheduling. In the future, its approach could be explored for small laboratories, educational environments, and organizations seeking cost-conscious ways to experiment with AI workloads.\r\n\r\nSTRATA is currently at the proposal and architecture stage. Its actual benefits, performance, and scalability will need to be validated through implementation and controlled experiments.", "productPotential": "yes", "prototypeDevelopmentCost": 3000, "auraDemoHighlight": "STRATA is worth seeing because it explores how multiple ordinary computers can work together to run an AI model when a single computer has limited memory. Its resource-aware planner will consider computing capacity, available memory, and network conditions to identify a feasible execution plan. The proposed system will combine distributed AI inference, real-time monitoring, and a dashboard that explains execution decisions. Through controlled experiments, STRATA aims to measure performance and demonstrate when distributing AI workloads is beneficial and when it is not. By focusing on practical resource utilization, transparent decisions, and measurable results, STRATA offers an interesting approach to making AI experimentation more accessible using existing computing hardware.", "safetyHazards": ["none"], "safetyPrecautions": "Safety Precautions:\r\n\r\n- Use properly rated power supplies and compatible cables for all electronic components.\r\n- Ensure all electrical connections are secure and insulated to prevent short circuits.\r\n- Keep computers and electronic boards in well-ventilated areas to prevent overheating.\r\n- Switch off and disconnect power before changing wiring or connecting hardware components.\r\n- Keep liquids away from computers, circuit boards, and electrical connections.\r\n- Arrange network and power cables neatly to prevent accidental tripping or disconnection.\r\n- Follow the manufacturer's instructions when installing and operating Raspberry Pi and Arduino boards.\r\n- Monitor system temperatures and hardware status during experiments.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-20T18:47:34.92Z", "updatedAt": "2026-10-20T18:49:35.316Z", "abstract": { "originalName": "ABTRACT_IDEA_STRATA.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792046373/aura-registrations/abstract-docs/ABTRACT_IDEA_STRATA.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Virgin Mojito/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Virgin Mojito/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792522054/aura-registrations/id-cards/zopvvykfwetsayqppavn.png", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Virgin Mojito/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792522053/aura-registrations/id-cards/ytzdksip8s25mumvav1x.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Virgin Mojito/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Virgin Mojito/4.jpg", "url": null, "exists": false }] }, { "index": 52, "id": "6ad86903a971e88aec40d24f", "registrationId": "AURA2K26-EY49VA", "rawTeamName": "Genesis", "folderName": "Genesis", "folderRelPath": "assets/Teams/Genesis", "projectTitle": "RainAlgae- A Rainwater-powered, Self-monitoring Algae Bioreactor for CO2 capture", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Irshadia Neshat", "teamLeaderEmail": "irshadianeshat62@gmail.com", "teamLeaderPhone": "7980013463", "teamMemberDetails": "Md.Atyab Nadim | Aliah University | CSE | 3rd year |  94770 25582\r\nSara Jahan | Aliah University | CSE-BCA | 3rd year | 91429 60892\r\nMd.Kasif Ali  | Aliah University | CSE | 3rd year | 98362 63368", "hardwareProjectCategories": ["IoT & Smart Devices"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement:-\r\n\r\nIndustrial emissions release large amounts of carbon dioxide, and most capture technologies are expensive and hard to place near small factories, leaving them with few practical options. Low-cost algae demonstrations do exist, but they mostly show only that algae are growing. They rarely give measured, repeatable proof of how much CO₂ is actually removed. They also cannot protect the algae if conditions turn harmful, such as the water becoming too acidic or too alkaline. There is a clear need for an affordable, compact system that proves its results with data and looks after its own algae culture.\r\n\r\nProposed Solution:-\r\n\r\nRainAlgae is a compact, low-cost bioreactor that grows Chlorella in filtered, nutrient-enriched rainwater under LED light on a day and night cycle. A CO₂-rich gas stream is diluted with air to a sensor-safe level and bubbled through the algae, which absorb part of the CO₂ through photosynthesis. For safe testing, a yeast-sugar fermentation bottle replaces real factory smoke, which can contain toxic gases.\r\n\r\nTwo NDIR CO₂ sensors measure the gas before and after the algae chamber, while pH, temperature and light sensors monitor the culture. An identical control chamber without algae runs alongside, so the difference shows the algae’s real contribution. An ESP32 sends the readings to a FastAPI backend and a live dashboard that displays capture percentage, CO₂ removed in mg per hour, and a running total. If the pH leaves the safe range, the system raises an alert and pauses the CO₂ supply at critical levels.\r\n\r\nInnovation:-\r\nLive removal tracking: The dashboard calculates capture percentage and CO₂ removed in mg per hour in real time, with a running total and a comparison against the control chamber, so every claim is backed by measured data.\r\npH-based protective alert: Excess dissolved CO₂ acidifies the water, while heavy photosynthesis can push pH too high. The system alerts on either side and automatically pauses the CO₂ supply at critical levels, keeping the culture healthy.\r\nResource-smart, scalable design: It reuses rainwater, uses simple low-cost parts with a safe yeast CO₂ source, and can be built as modular panels near small emission points. Harvested algae can become biofertiliser, so the captured carbon is put to use.", "solutionDescription": "Problem Statement:-\r\n\r\nIndustrial emissions release large amounts of carbon dioxide, and most capture technologies are expensive and hard to place near small factories, leaving them with few practical options. Low-cost algae demonstrations do exist, but they mostly show only that algae are growing. They rarely give measured, repeatable proof of how much CO₂ is actually removed. They also cannot protect the algae if conditions turn harmful, such as the water becoming too acidic or too alkaline. There is a clear need for an affordable, compact system that proves its results with data and looks after its own algae culture.\r\n\r\nProposed Solution:-\r\n\r\nRainAlgae is a compact, low-cost bioreactor that grows Chlorella in filtered, nutrient-enriched rainwater under LED light on a day and night cycle. A CO₂-rich gas stream is diluted with air to a sensor-safe level and bubbled through the algae, which absorb part of the CO₂ through photosynthesis. For safe testing, a yeast-sugar fermentation bottle replaces real factory smoke, which can contain toxic gases.\r\n\r\nTwo NDIR CO₂ sensors measure the gas before and after the algae chamber, while pH, temperature and light sensors monitor the culture. An identical control chamber without algae runs alongside, so the difference shows the algae’s real contribution. An ESP32 sends the readings to a FastAPI backend and a live dashboard that displays capture percentage, CO₂ removed in mg per hour, and a running total. If the pH leaves the safe range, the system raises an alert and pauses the CO₂ supply at critical levels.\r\n\r\nInnovation:-\r\nLive removal tracking: The dashboard calculates capture percentage and CO₂ removed in mg per hour in real time, with a running total and a comparison against the control chamber, so every claim is backed by measured data.\r\npH-based protective alert: Excess dissolved CO₂ acidifies the water, while heavy photosynthesis can push pH too high. The system alerts on either side and automatically pauses the CO₂ supply at critical levels, keeping the culture healthy.\r\nResource-smart, scalable design: It reuses rainwater, uses simple low-cost parts with a safe yeast CO₂ source, and can be built as modular panels near small emission points. Harvested algae can become biofertiliser, so the captured carbon is put to use.", "innovationDescription": "Problem Statement:-\r\n\r\nIndustrial emissions release large amounts of carbon dioxide, and most capture technologies are expensive and hard to place near small factories, leaving them with few practical options. Low-cost algae demonstrations do exist, but they mostly show only that algae are growing. They rarely give measured, repeatable proof of how much CO₂ is actually removed. They also cannot protect the algae if conditions turn harmful, such as the water becoming too acidic or too alkaline. There is a clear need for an affordable, compact system that proves its results with data and looks after its own algae culture.\r\n\r\nProposed Solution:-\r\n\r\nRainAlgae is a compact, low-cost bioreactor that grows Chlorella in filtered, nutrient-enriched rainwater under LED light on a day and night cycle. A CO₂-rich gas stream is diluted with air to a sensor-safe level and bubbled through the algae, which absorb part of the CO₂ through photosynthesis. For safe testing, a yeast-sugar fermentation bottle replaces real factory smoke, which can contain toxic gases.\r\n\r\nTwo NDIR CO₂ sensors measure the gas before and after the algae chamber, while pH, temperature and light sensors monitor the culture. An identical control chamber without algae runs alongside, so the difference shows the algae’s real contribution. An ESP32 sends the readings to a FastAPI backend and a live dashboard that displays capture percentage, CO₂ removed in mg per hour, and a running total. If the pH leaves the safe range, the system raises an alert and pauses the CO₂ supply at critical levels.\r\n\r\nInnovation:-\r\nLive removal tracking: The dashboard calculates capture percentage and CO₂ removed in mg per hour in real time, with a running total and a comparison against the control chamber, so every claim is backed by measured data.\r\npH-based protective alert: Excess dissolved CO₂ acidifies the water, while heavy photosynthesis can push pH too high. The system alerts on either side and automatically pauses the CO₂ supply at critical levels, keeping the culture healthy.\r\nResource-smart, scalable design: It reuses rainwater, uses simple low-cost parts with a safe yeast CO₂ source, and can be built as modular panels near small emission points. Harvested algae can become biofertiliser, so the captured carbon is put to use.", "workingPrinciple": "Working Principle:-\r\n\r\n1. Culture setup. Chlorella grows in filtered, boiled rainwater with added nutrients, under LED light on a day and night cycle.\r\n\r\n2. CO₂ generation and dilution. A yeast-sugar fermentation bottle produces CO₂ as a safe stand-in for factory smoke. This gas is diluted with air to a level the sensors can handle, then bubbled through the algae chamber.\r\n\r\n3. Photosynthetic capture. Under light, the algae absorb part of the dissolved CO₂ through photosynthesis, so the gas leaving the chamber has less CO₂ than the gas entering it.\r\n\r\n4. Measurement. One NDIR CO₂ sensor reads the inlet gas and another reads the outlet gas. pH, temperature and light sensors monitor the culture. An identical control chamber without algae runs under the same conditions, so any difference between the two chambers is due to the algae alone.\r\n\r\n5. Data transmission. An ESP32 controller reads all sensors and sends the data to a FastAPI backend, which stores it and feeds a live dashboard.\r\n\r\n6. Live calculation. The system works out capture percentage from the inlet and outlet readings, converts it to CO₂ removed in mg per hour, and keeps a running total, compared against the control.\r\n\r\n7. Safety control. Dissolved CO₂ makes the water acidic, and heavy photosynthesis can push pH too high. If pH leaves the safe range, the dashboard raises an alert. At critical levels, the ESP32 switches off the pump to pause the CO₂ supply until conditions recover.", "majorHardwareComponents": ["Major Hardware Components:-\n\n1. Bioreactor chambers. Two identical transparent chambers: an algae chamber holding Chlorella in filtered", "nutrient-enriched rainwater", "and a control chamber with the same setup but no algae.\n\n2. ESP32 microcontroller. The central controller. It reads all sensors", "sends data to the backend", "and switches the pump on or off for the safety control.\n\n3. NDIR CO₂ sensors (two). One measures CO₂ in the inlet gas and the other in the outlet gas", "giving the before-and-after readings used to calculate capture. The abstract’s methodology implies the control chamber is measured the same way", "so you may need an additional pair of sensors", "or a way to switch one pair between chambers.\n\n4. pH sensor. Monitors the acidity of the culture water to detect harmful drift in either direction.\n\n5. Temperature sensor. Tracks culture temperature", "which affects algae growth and CO₂ absorption.\n\n6. Light sensor. Measures the light the culture receives during the day and night cycle.\n\n7. LED grow lights. Provide controlled illumination for photosynthesis on a day and night cycle.\n\n8. Air pump with tubing and diffuser. Moves the diluted CO₂ gas through the algae and releases it as bubbles. The ESP32 switches it off to pause the CO₂ supply.\n\n9. Yeast-sugar fermentation bottle. The safe CO₂ source used in place of factory smoke.\n\n10. Power supply and wiring. Powers the ESP32", "sensors", "pump and LEDs."], "useAi": true, "useIot": true, "powerSource": "solar", "intendedBeneficiaries": ["Industry", "General Public"], "potentialImpact": "Potential Real-World Impact:-\r\n\r\n1.Cleaner emissions at small factories. Most capture technologies are built for large plants. RainAlgae’s low-cost, modular panels could be placed near small emission points, which are usually left without options.\r\n\r\n2.Water savings. Using filtered rainwater instead of freshwater reduces demand on local supplies, which matters where water is scarce.\r\n\r\n3.Carbon put to use. Harvested algae can become biofertiliser, so the captured carbon supports farming instead of decaying and re-releasing CO₂.\r\n\r\n4.Trustworthy reporting. Live capture percentage and mg per hour, checked against a no-algae control, give sustainability teams and regulators figures they can verify.\r\n\r\n5.Reliable operation. The pH alert and automatic CO₂ pausing protect the culture, so the system can run with less manual supervision.\r\n\r\n6.A base for further research. The logged data can train a machine learning model, planned as a future enhancement, to predict CO₂ absorption from light and temperature.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "Why It’s Worth Seeing:-\r\n\r\n1.It proves its results. Many algae demos only show green water. RainAlgae shows measured CO₂ removal side by side with a control chamber, so viewers see evidence of the algae’s contribution.\r\n\r\n2.It’s live and visual. The dashboard updates capture percentage, mg per hour and a running total in real time, which makes the science easy to follow even for non-experts.\r\n\r\n3.It protects itself. Watching the pH alert trigger and the system pause the CO₂ supply shows the algae are being looked after automatically.\r\n\r\n4.It combines several fields. Biology, IoT hardware (ESP32 and sensors), a FastAPI backend and a dashboard come together in one working system, so it shows both sustainability and engineering skill.\r\n\r\n5.It’s safe and approachable. A yeast-sugar bottle replaces toxic factory smoke, so it can be demonstrated up close without hazardous gases.\r\n\r\n6.It’s practical. Low-cost parts, reused rainwater and a modular design make it feel buildable, not a distant concept.\r\n\r\n7.It tells a complete story. From emission to capture, measurement, protection and reuse as biofertiliser, the whole carbon journey is visible in one prototype.", "safetyHazards": ["pressurized_systems", "water_near_electrical_equipment"], "safetyPrecautions": "Pressure in the fermentation bottle. A fully sealed bottle with a blocked outlet could build up pressure. \r\nSolution: We use a plastic bottle with a clear gas outlet or airlock.\r\nElectricity near water. \r\nSolution:- Using a low-voltage 12 V supply and keep the electronics in a separate enclosure above the water level.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-21T07:25:55.98Z", "updatedAt": "2026-10-21T07:27:56.186Z", "abstract": { "originalName": "Team_Genesis_abstract(RainAlgae).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792567555/aura-registrations/abstract-docs/Team_Genesis_abstract%28RainAlgae%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Genesis/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Genesis/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792567554/aura-registrations/id-cards/z3h5wgb5fpmqgnxsj3vv.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Genesis/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792567554/aura-registrations/id-cards/opd1v6kt44yuzikbvjfu.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Genesis/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792567554/aura-registrations/id-cards/devutaru9ned95vv8y4l.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Genesis/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792567554/aura-registrations/id-cards/mmqhmz4dcxdwk8yam1x2.jpg", "exists": true }] }, { "index": 53, "id": "6adc6c1a3c8f516560a56bde", "registrationId": "AURA2K26-CVSXEE", "rawTeamName": "FluidOps", "folderName": "FluidOps", "folderRelPath": "assets/Teams/FluidOps", "projectTitle": "Project Cascade", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "HOSSAIN EKTIAR MONDAL", "teamLeaderEmail": "26f3300185@ae.study.iitm.ac.in", "teamLeaderPhone": "7699861734", "teamMemberDetails": "HOSSAIN EKTIAR MONDAL | ALIAH UNIVERSITY | MEN | 2026 | 7699861734\r\nMD AFZAL ALAM | ALIAH UNIVERSITY | CSE | 2026 | 8710051308\r\nSK RAMIJ | ALIAH UNIVERSITY | ECE | 2026 | 9475327112\r\nMD SAYEED | ALIAH UNIVERSITY | CSE | 2026 | 9007119897", "hardwareProjectCategories": ["IoT & Smart Devices", "Embedded Systems", "Automation & Control", "Environmental Technology"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Overhead water tanks in homes, hostels and apartment buildings are usually filled by pumps that people switch on and off by hand. With no easy way to see the level, tanks overflow and waste water and electricity, or run dry and leave users without supply while the pump runs dry and risks damage. This wastage works against sustainability.\r\n\r\nOur solution is a low-cost IoT tank controller. A waterproof JSN-SR04T ultrasonic sensor on the tank lid measures the water level, and an ESP8266 converts it into a percentage and litres and sends it over Wi-Fi to a live web dashboard. The dashboard shows the current level and a graph of water usage over time, and lets users set start and stop thresholds. In automatic mode, the ESP8266 switches the pump through an opto-isolated relay to keep the tank filled just right. In manual mode, the pump is controlled from the website, and the user gets phone notifications for pump on/off, no water and overflow.\r\n\r\nWhat makes it innovative is that the control logic runs on the device itself, so the pump keeps following its rules even if Wi-Fi fails. Built-in safety rules (maximum run time, dry-run detection and sensor-fault shutdown) protect the pump without a float switch, and settings are saved in flash memory so they survive power cuts. Combined with usage analytics and remote control, it is an affordable retrofit for any existing tank and pump.", "solutionDescription": "Overhead water tanks in homes, hostels and apartment buildings are usually filled by pumps that people switch on and off by hand. With no easy way to see the level, tanks overflow and waste water and electricity, or run dry and leave users without supply while the pump runs dry and risks damage. This wastage works against sustainability.\r\n\r\nOur solution is a low-cost IoT tank controller. A waterproof JSN-SR04T ultrasonic sensor on the tank lid measures the water level, and an ESP8266 converts it into a percentage and litres and sends it over Wi-Fi to a live web dashboard. The dashboard shows the current level and a graph of water usage over time, and lets users set start and stop thresholds. In automatic mode, the ESP8266 switches the pump through an opto-isolated relay to keep the tank filled just right. In manual mode, the pump is controlled from the website, and the user gets phone notifications for pump on/off, no water and overflow.\r\n\r\nWhat makes it innovative is that the control logic runs on the device itself, so the pump keeps following its rules even if Wi-Fi fails. Built-in safety rules (maximum run time, dry-run detection and sensor-fault shutdown) protect the pump without a float switch, and settings are saved in flash memory so they survive power cuts. Combined with usage analytics and remote control, it is an affordable retrofit for any existing tank and pump.", "innovationDescription": "Overhead water tanks in homes, hostels and apartment buildings are usually filled by pumps that people switch on and off by hand. With no easy way to see the level, tanks overflow and waste water and electricity, or run dry and leave users without supply while the pump runs dry and risks damage. This wastage works against sustainability.\r\n\r\nOur solution is a low-cost IoT tank controller. A waterproof JSN-SR04T ultrasonic sensor on the tank lid measures the water level, and an ESP8266 converts it into a percentage and litres and sends it over Wi-Fi to a live web dashboard. The dashboard shows the current level and a graph of water usage over time, and lets users set start and stop thresholds. In automatic mode, the ESP8266 switches the pump through an opto-isolated relay to keep the tank filled just right. In manual mode, the pump is controlled from the website, and the user gets phone notifications for pump on/off, no water and overflow.\r\n\r\nWhat makes it innovative is that the control logic runs on the device itself, so the pump keeps following its rules even if Wi-Fi fails. Built-in safety rules (maximum run time, dry-run detection and sensor-fault shutdown) protect the pump without a float switch, and settings are saved in flash memory so they survive power cuts. Combined with usage analytics and remote control, it is an affordable retrofit for any existing tank and pump.", "workingPrinciple": "A JSN-SR04T waterproof ultrasonic sensor is mounted on the tank lid, facing down. It sends a sound pulse and measures the echo time, which gives the distance to the water surface. The ESP8266 takes five readings every few seconds and uses the median to remove ripple and false echoes. After a one-time calibration of the empty and full distances, it converts the distance into a water level percentage and litres.\r\n\r\nThe ESP8266 sends the level and pump status over Wi-Fi through an MQTT cloud broker to a live web dashboard. The dashboard shows the current level and a graph of water usage over time, and lets the user set start and stop thresholds.\r\n\r\nIn automatic mode, the ESP8266 turns the pump ON through an opto-isolated relay when the level falls to the start threshold, and turns it OFF at the stop threshold. In manual mode, the user switches the pump on or off from the website, and phone notifications report pump on/off, no water and overflow.\r\n\r\nThe decision logic runs on the ESP8266 itself, so the pump still follows its rules if Wi-Fi fails. Safety rules in the code stop the pump on a maximum run time, an invalid sensor reading for more than 30 seconds, or no level rise after 10 minutes of running. The relay stays OFF at boot, and thresholds are stored in flash memory so they survive power cuts.", "majorHardwareComponents": ["ESP8266", "JSN-SR04T ultrasonic sensor", "Relay module", "Contactor", "HLK-PM01 power module", "Fuse/MCB", "Resistors", "Water pump", "Terminal block", "Wires", "Cable glands", "IP65 enclosure"], "useAi": false, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["General Public", "Rural Communities", "Urban Communities", "Agriculture"], "potentialImpact": "The system benefits households, hostels, apartment buildings, schools and small farms that depend on overhead tanks filled by electric pumps. It removes the need to watch the tank and decide when to run the pump, which is where most overflow and dry-tank problems start.\r\n\r\nAutomatic control stops overflow, which saves treated water and the electricity used to pump it. The dry-run protection (maximum run time, no-level-rise detection and sensor-fault shutdown) protects the pump from damage, which lowers repair costs. The live level in litres and the usage graph show how much water a building consumes, so users can notice leaks or unusual usage and reduce wastage. Phone notifications warn of no water or overflow while the user is away from home.\r\n\r\nCompared with commercial water-level controllers, this system is built from low-cost, easily available parts, with a total component cost of under ₹2,000. It can be fitted to an existing tank and pump without replacing them. This makes automation affordable for ordinary households and rural areas, and it supports water conservation and sustainability", "productPotential": "yes", "prototypeDevelopmentCost": 1652, "auraDemoHighlight": "This is a live demo that judges can interact with. When the water level changes, the web dashboard updates in real time and shows the level in percentage and litres, along with a graph of water usage over time. Judges can set their own start and stop thresholds and watch the pump switch on and off automatically. They can also switch to manual mode, control the pump from the website, and see a phone notification arrive for pump on/off, no water or overflow.\r\n\r\nWhat makes it stand out is that it solves an everyday problem that almost every home and hostel has, using affordable parts. The control logic runs on the device itself, so the pump keeps following its rules even if Wi-Fi fails. Built-in safety rules protect the pump without a float switch. Monitoring, automation, remote control, usage analytics and alerts all come together in one low-cost device that can be fitted to any existing tank.", "safetyHazards": ["high_voltage", "high_current", "water_near_electrical_equipment"], "safetyPrecautions": "The mains supply goes through a fuse/MCB that protects the circuit from overcurrent. An opto-isolated relay module keeps the ESP8266 electrically isolated from the pump circuit, and a contactor switches the pump when it is 0.5 HP or more, to handle the motor’s inrush current. All electronics sit inside a sealed IP65 enclosure, with cables entering through cable glands, and mains wiring is kept apart from low-voltage wiring. The waterproof JSN-SR04T sensor is mounted above the water line, and a voltage divider protects the ESP8266 from the sensor’s 5V signal.\r\n\r\nThe code adds protection too. The relay stays OFF at boot or reset, and a relay pin that does not flicker at power-up is used. The pump stops after a maximum run time, if the sensor gives an invalid reading for more than 30 seconds, or if the level does not rise within 10 minutes of running, which protects against dry running. A minimum gap between the start and stop levels is enforced in code.\r\n\r\nThe system is first tested with a test lamp instead of the pump, and an experienced person checks the AC wiring before it is powered on.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-24T08:28:10.46Z", "updatedAt": "2026-10-24T08:30:10.641Z", "abstract": { "originalName": "Abstract_Cascade.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792830489/aura-registrations/abstract-docs/Abstract_Cascade.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/FluidOps/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/FluidOps/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792830489/aura-registrations/id-cards/gszy3wy3khtrqvjdzlwo.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/FluidOps/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792830489/aura-registrations/id-cards/pnog3va3cfvhiomyzkru.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/FluidOps/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792830489/aura-registrations/id-cards/wmqhiqh7unswtckkemne.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/FluidOps/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792830489/aura-registrations/id-cards/noy4o7ij2fyfx2uhgzjc.jpg", "exists": true }] }, { "index": 54, "id": "6ade070733bc6c51efc72cd2", "registrationId": "AURA2K26-EX28RL", "rawTeamName": "Penteract", "folderName": "Penteract", "folderRelPath": "assets/Teams/Penteract", "projectTitle": "Anebilin", "teamSize": 2, "teamAffiliation": "all_other", "aliahMembers": 0, "otherInstitutionMembers": 2, "teamLeaderName": "Sayan Ghanty", "teamLeaderEmail": "sayan.ghanty.ece28@heritageit.edu.in", "teamLeaderPhone": "9883565913", "teamMemberDetails": "Rohan Sarkar | HITK |  CHE | 2nd Year | 9836171619", "hardwareProjectCategories": ["Embedded Systems", "Electronics & Communication", "IoT & Smart Devices", "Biomedical / Healthcare Devices", "AI-Enabled Hardware", "Assistive Technology"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Access to affordable health screening remains limited in rural and resource-constrained settings. Conventional blood tests often require needles, trained personnel, laboratory infrastructure, sample transport, and waiting time. These barriers can delay preliminary assessment and make repeated monitoring difficult in community settings. Anebilin is a portable, non-invasive multispectral screening device designed to obtain optical measurements from a finger scan. Its sensing unit uses the AS7343 14-channel spectral sensor to capture visible and near-infrared information. An ESP32-S3 microcontroller performs local signal acquisition, filtering, AC/DC decomposition, spectral normalization, and feature extraction. Near-infrared reference channels and spectral ratios help reduce the effects of skin pigmentation and tissue-related optical variation. Engineered features are processed by machine-learning models to estimate indicators including SpO₂, haemoglobin, bilirubin-related measures, heart rate, heart-rate variability, and respiratory rate. Results can be displayed locally and synchronized through Bluetooth to a digital dashboard. Anebilin combines multispectral sensing, physics-informed signal processing, and embedded machine learning in a compact platform. Rather than relying on a single optical channel or feeding unprocessed readings directly into a model, it analyzes spectral ratios, AC/DC components, and engineered features across multiple wavelengths. This broader spectral approach supports several preliminary indicators from one finger scan, while local processing reduces dependence on external computing infrastructure. Bluetooth connectivity supports digital record keeping and trend monitoring. The device aims to make preliminary screening more accessible, portable, and efficient in clinics, health camps, and community settings, supporting early assessment and follow-up. Anebilin is designed to complement healthcare services and assist screening and monitoring, not replace conventional laboratory tests or clinical diagnosis.", "solutionDescription": "Access to affordable health screening remains limited in rural and resource-constrained settings. Conventional blood tests often require needles, trained personnel, laboratory infrastructure, sample transport, and waiting time. These barriers can delay preliminary assessment and make repeated monitoring difficult in community settings. Anebilin is a portable, non-invasive multispectral screening device designed to obtain optical measurements from a finger scan. Its sensing unit uses the AS7343 14-channel spectral sensor to capture visible and near-infrared information. An ESP32-S3 microcontroller performs local signal acquisition, filtering, AC/DC decomposition, spectral normalization, and feature extraction. Near-infrared reference channels and spectral ratios help reduce the effects of skin pigmentation and tissue-related optical variation. Engineered features are processed by machine-learning models to estimate indicators including SpO₂, haemoglobin, bilirubin-related measures, heart rate, heart-rate variability, and respiratory rate. Results can be displayed locally and synchronized through Bluetooth to a digital dashboard. Anebilin combines multispectral sensing, physics-informed signal processing, and embedded machine learning in a compact platform. Rather than relying on a single optical channel or feeding unprocessed readings directly into a model, it analyzes spectral ratios, AC/DC components, and engineered features across multiple wavelengths. This broader spectral approach supports several preliminary indicators from one finger scan, while local processing reduces dependence on external computing infrastructure. Bluetooth connectivity supports digital record keeping and trend monitoring. The device aims to make preliminary screening more accessible, portable, and efficient in clinics, health camps, and community settings, supporting early assessment and follow-up. Anebilin is designed to complement healthcare services and assist screening and monitoring, not replace conventional laboratory tests or clinical diagnosis.", "innovationDescription": "Access to affordable health screening remains limited in rural and resource-constrained settings. Conventional blood tests often require needles, trained personnel, laboratory infrastructure, sample transport, and waiting time. These barriers can delay preliminary assessment and make repeated monitoring difficult in community settings. Anebilin is a portable, non-invasive multispectral screening device designed to obtain optical measurements from a finger scan. Its sensing unit uses the AS7343 14-channel spectral sensor to capture visible and near-infrared information. An ESP32-S3 microcontroller performs local signal acquisition, filtering, AC/DC decomposition, spectral normalization, and feature extraction. Near-infrared reference channels and spectral ratios help reduce the effects of skin pigmentation and tissue-related optical variation. Engineered features are processed by machine-learning models to estimate indicators including SpO₂, haemoglobin, bilirubin-related measures, heart rate, heart-rate variability, and respiratory rate. Results can be displayed locally and synchronized through Bluetooth to a digital dashboard. Anebilin combines multispectral sensing, physics-informed signal processing, and embedded machine learning in a compact platform. Rather than relying on a single optical channel or feeding unprocessed readings directly into a model, it analyzes spectral ratios, AC/DC components, and engineered features across multiple wavelengths. This broader spectral approach supports several preliminary indicators from one finger scan, while local processing reduces dependence on external computing infrastructure. Bluetooth connectivity supports digital record keeping and trend monitoring. The device aims to make preliminary screening more accessible, portable, and efficient in clinics, health camps, and community settings, supporting early assessment and follow-up. Anebilin is designed to complement healthcare services and assist screening and monitoring, not replace conventional laboratory tests or clinical diagnosis.", "workingPrinciple": "Anebilin works on the principle of multispectral optical sensing combined with digital signal processing and machine learning to estimate physiological indicators non-invasively. During a scan, the user places a finger inside the device’s optical chamber, where optical measurements are collected across visible and near-infrared wavelengths. The AS7343 14-channel spectral sensor captures wavelength-dependent information associated with the interaction of light with biological tissue and blood. These measurements contain variations influenced by blood flow, tissue composition, skin pigmentation, and other optical factors. An ESP32-S3 microcontroller acquires the sensor data and processes it locally. The signal-processing pipeline applies filtering and noise reduction to improve measurement consistency, followed by AC/DC decomposition to separate pulsatile variations associated with blood-volume changes from relatively steady optical components. Spectral normalization and ratio-based analysis are then performed to reduce variations caused by illumination, tissue characteristics, and differences in skin pigmentation. Near-infrared reference channels provide additional information for compensating optical variability. From the processed signals, the system extracts engineered features, including spectral ratios, pulsatile metrics, and relationships between wavelength channels. These features are supplied to machine-learning models trained to estimate selected physiological indicators, including oxygen saturation (SpO2), haemoglobin, bilirubin-related indicators, heart rate, heart-rate variability, and respiratory rate. The calculated estimates are presented through the device interface and can be synchronized via Bluetooth with a digital dashboard for recording and trend monitoring. By combining multispectral measurements, physics-informed signal processing, and embedded machine learning, Anebilin aims to derive multiple preliminary health indicators from a single finger scan. Its outputs are intended for", "majorHardwareComponents": ["Anebilin utilizes several major hardware components to perform non-invasive multispectral health screening. The AS7343 14-channel multispectral sensor captures optical measurements across visible and near-infrared wavelengths", "providing spectral data for physiological indicator estimation. The ESP32-S3 microcontroller serves as the central processing unit", "responsible for sensor data acquisition", "signal filtering", "AC/DC decomposition", "spectral normalization", "feature extraction", "and execution of machine-learning models. An enclosed optical sensing chamber", "fabricated using PETG and TPU", "provides a controlled environment for finger scanning by reducing ambient-light interference and improving measurement consistency. A local display interface presents the estimated health indicators and measurement results to the user. Bluetooth communication enables wireless transfer of measurement data to a digital dashboard for recording and longitudinal monitoring. The mechanical enclosure and supporting assembly protect the electronic components and maintain proper finger positioning during measurements. Together", "these components enable Anebilin to acquire multispectral data", "process it locally", "and generate preliminary estimates of physiological indicators", "including SpO2", "haemoglobin", "bilirubin-related indicators", "heart rate", "heart-rate variability", "and respiratory rate. The exact models of the display", "battery", "and power-management components are not specified in the available project documentation."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Healthcare", "Government / Public Services", "Rural Communities", "Urban Communities"], "potentialImpact": "Anebilin has the potential to improve access to affordable, portable, and non-invasive preliminary health screening, particularly in rural communities and resource-constrained healthcare settings. By combining multispectral optical sensing with embedded processing and machine learning, the device aims to estimate multiple physiological indicators from a single finger scan without requiring blood collection for the measurement process. This could reduce dependence on needles, laboratory infrastructure, sample transportation, and trained personnel for initial screening, making the technology potentially useful in primary health centres, rural clinics, health camps, NGOs, and mobile healthcare units. Its compact design and local processing capabilities could enable screening in locations with limited computing infrastructure, while Bluetooth connectivity could support digital record keeping and longitudinal monitoring. The ability to assess several indicators through one device may help healthcare workers identify individuals who require further clinical evaluation and support follow-up in underserved populations. Anebilin could also contribute to community-level health monitoring by facilitating the collection of structured screening data, potentially helping healthcare organizations identify trends and plan targeted interventions. Its modular architecture offers opportunities for future expansion through additional sensors, improved estimation algorithms, and integration with digital health platforms. Ultimately, Anebilin aims to make preliminary health assessment more accessible, convenient, and scalable. Its real-world impact will depend on rigorous accuracy testing across diverse populations, clinical validation, usability evaluation, and appropriate regulatory assessment. The device is intended to complement established healthcare services and laboratory testing, not replace professional diagnosis or conventional clinical measurements.", "productPotential": "yes", "prototypeDevelopmentCost": 3500, "auraDemoHighlight": "Anebilin is worth seeing because it explores how multispectral sensing and embedded artificial intelligence can bring multiple preliminary health indicators into one compact, non-invasive device. Instead of relying on a single optical channel for a limited measurement, Anebilin uses the AS7343 14-channel spectral sensor to capture information across visible and near-infrared wavelengths. Its combination of spectral analysis, AC/DC signal decomposition, engineered features, and machine-learning models makes the approach distinctive. Powered by the ESP32-S3, the system processes measurements locally, demonstrating how advanced signal processing can be implemented on affordable embedded hardware. The most compelling aspect is its potential to obtain several preliminary indicators—including SpO₂, haemoglobin, bilirubin-related indicators, heart rate, and heart-rate variability—from a single finger scan without blood collection during the measurement. Its compact sensing chamber and Bluetooth-enabled digital monitoring also demonstrate a pathway toward practical use beyond conventional laboratory environments. Anebilin brings together hardware engineering, optical sensing, embedded AI, and healthcare accessibility in a tangible working prototype. It is not merely an idea on paper; it is an attempt to translate multidisciplinary engineering into a technology with potential social value, particularly for rural communities, health camps, and resource-constrained settings. Visitors can explore how optical signals become meaningful computational features and how these features can support preliminary health assessment. **Anebilin is worth seeing because it demonstrates a promising engineering approach to making multi-parameter preliminary screening more portable, accessible, and convenient.** Its performance and clinical usefulness remain subject to further testing and validation.", "safetyHazards": ["none"], "safetyPrecautions": "Anebilin incorporates safety considerations to support non-invasive preliminary health screening. Its optical measurement method does not require blood collection or needle insertion, reducing exposure to sharps, the risk of needle-related injuries, and the generation of associated biomedical waste during scanning. An enclosed optical sensing chamber, fabricated using PETG and TPU, is designed to minimize ambient-light interference and improve measurement consistency. Local data processing on the ESP32-S3 reduces dependence on external computing infrastructure during measurement. The device is intended for preliminary screening and monitoring rather than definitive diagnosis or replacement of conventional laboratory tests. Any abnormal or potentially high-risk readings should be followed by professional medical evaluation and appropriate confirmatory testing. Measurements should be interpreted cautiously because optical readings can be influenced by skin pigmentation, tissue characteristics, blood perfusion, and other physiological factors. The prototype's accuracy and performance require assessment across diverse populations and measurement conditions. Appropriate cleaning of the finger-contact surfaces, careful handling of electronic components, and inspection of the enclosure should be followed during demonstrations and use. The device should be operated according to its electrical and hardware requirements, with damaged components removed from service. **Anebilin is currently a preliminary screening prototype; formal clinical safety, accuracy certification, and regulatory approval have not yet been established.** Further technical testing, clinical validation, and regulatory assessment are necessary before medical-grade deployment.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": true, "previousExhibitionDetails": "UDAAN 2.0 @ HITK |  Double Slash 4.0 @ JU | Hacktonix @ FIEM |", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-25T13:41:27.143Z", "updatedAt": "2026-10-25T13:43:27.412Z", "abstract": { "originalName": "anebilin_aura_2026_abstract (2).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792935685/aura-registrations/abstract-docs/anebilin_aura_2026_abstract%20%282%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Penteract/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Penteract/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792935684/aura-registrations/id-cards/oqey374ww6adp7yuy8g3.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Penteract/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792935684/aura-registrations/id-cards/xmvggpuyshfbfhhmdvft.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Penteract/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Penteract/4.jpg", "url": null, "exists": false }] }, { "index": 55, "id": "6ade0c30e0fbb9549105a7e7", "registrationId": "AURA2K26-X7EQN7", "rawTeamName": "EchoVitals", "folderName": "EchoVitals", "folderRelPath": "assets/Teams/EchoVitals", "projectTitle": "ECHOVITALS  |  ( A radar-based platform for non contact vital health sign sensing. )", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Arman Israfil", "teamLeaderEmail": "armanisrafil.edu@gmail.com", "teamLeaderPhone": "8509556265", "teamMemberDetails": "Md Qais Khan   |    Aliah University  |   Electronics and Communication  |   3rd Year  |  9830646288\r\nSk sahil Ahamed   |    Aliah University  |   Electronics and Communication  |   3rd Year  |  8240381200\r\nMd Faizan   |    Aliah University  |   Electronics and Communication  |   3rd Year  |  8910519446", "hardwareProjectCategories": ["Robotics", "IoT & Smart Devices", "Biomedical / Healthcare Devices", "Embedded Systems", "Electronics & Communication", "Assistive Technology", "Electrical Systems", "Safety & Security Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Statement:\r\n Continuous heart-rate and breathing monitoring is central to patient safety, yet it depends on contact sensors such as ECG electrodes, chest straps and finger clips. These become impractical precisely where monitoring matters most: adhesives irritate the fragile skin of neonates and burn patients, shared probes carry cross-infection risk in isolation wards, trailing wires restrict drivers and elderly patients, and motion or moisture degrade the signal. Sensors that must be worn and kept in place are often removed or mispositioned, forcing clinicians to trade comfort and hygiene against continuity of data and leaving a monitoring gap for the patients who most need continuous observation. \r\nProposed Solution: \r\nEchoVitals is a contactless vital-sign monitor that measures heart rate and breathing rate with no electrodes, straps or wires. A 60 GHz frequency-modulated continuous-wave (FMCW) radar module, mounted 0.4–1.5 m from the subject, tracks the phase of the chest-wall reflection to recover sub-millimetre cardiac motion beneath the much larger movement of breathing. Its onboard DSP performs ranging and signal extraction and streams rate values to an ESP32 microcontroller, which forwards them to a host layer that validates, smooths and displays live heart and breathing rate on a dashboard and optional OLED. The radar senses through clothing and bedding and uses no camera, so it is comfortable, hygienic and privacy-preserving, and the whole platform runs from a single 5 V supply.\r\nInnovation and Novelty:\r\nOur contribution is not the radar itself but a validated, application-level system built around it. First, a validity-gating layer uses the module’s reported target count and range to reject readings when no subject is present or the subject leaves the sensing zone, preventing stale or spurious vitals. Second, we evaluate rigorously rather than anecdotally: heart rate against a reference pulse oximeter and breathing rate against a timed manual count, across multiple volunteers and through fabric barriers, reporting measured error instead of datasheet claims. Third, the design is low-cost and reproducible, using one radar module, one microcontroller and open-source Python. Together these turn a sensing component into a trustworthy monitoring platform for infants, infectious-disease wards, drivers and bedside care, demonstrated live on working hardware.", "solutionDescription": "Problem Statement:\r\n Continuous heart-rate and breathing monitoring is central to patient safety, yet it depends on contact sensors such as ECG electrodes, chest straps and finger clips. These become impractical precisely where monitoring matters most: adhesives irritate the fragile skin of neonates and burn patients, shared probes carry cross-infection risk in isolation wards, trailing wires restrict drivers and elderly patients, and motion or moisture degrade the signal. Sensors that must be worn and kept in place are often removed or mispositioned, forcing clinicians to trade comfort and hygiene against continuity of data and leaving a monitoring gap for the patients who most need continuous observation. \r\nProposed Solution: \r\nEchoVitals is a contactless vital-sign monitor that measures heart rate and breathing rate with no electrodes, straps or wires. A 60 GHz frequency-modulated continuous-wave (FMCW) radar module, mounted 0.4–1.5 m from the subject, tracks the phase of the chest-wall reflection to recover sub-millimetre cardiac motion beneath the much larger movement of breathing. Its onboard DSP performs ranging and signal extraction and streams rate values to an ESP32 microcontroller, which forwards them to a host layer that validates, smooths and displays live heart and breathing rate on a dashboard and optional OLED. The radar senses through clothing and bedding and uses no camera, so it is comfortable, hygienic and privacy-preserving, and the whole platform runs from a single 5 V supply.\r\nInnovation and Novelty:\r\nOur contribution is not the radar itself but a validated, application-level system built around it. First, a validity-gating layer uses the module’s reported target count and range to reject readings when no subject is present or the subject leaves the sensing zone, preventing stale or spurious vitals. Second, we evaluate rigorously rather than anecdotally: heart rate against a reference pulse oximeter and breathing rate against a timed manual count, across multiple volunteers and through fabric barriers, reporting measured error instead of datasheet claims. Third, the design is low-cost and reproducible, using one radar module, one microcontroller and open-source Python. Together these turn a sensing component into a trustworthy monitoring platform for infants, infectious-disease wards, drivers and bedside care, demonstrated live on working hardware.", "innovationDescription": "Problem Statement:\r\n Continuous heart-rate and breathing monitoring is central to patient safety, yet it depends on contact sensors such as ECG electrodes, chest straps and finger clips. These become impractical precisely where monitoring matters most: adhesives irritate the fragile skin of neonates and burn patients, shared probes carry cross-infection risk in isolation wards, trailing wires restrict drivers and elderly patients, and motion or moisture degrade the signal. Sensors that must be worn and kept in place are often removed or mispositioned, forcing clinicians to trade comfort and hygiene against continuity of data and leaving a monitoring gap for the patients who most need continuous observation. \r\nProposed Solution: \r\nEchoVitals is a contactless vital-sign monitor that measures heart rate and breathing rate with no electrodes, straps or wires. A 60 GHz frequency-modulated continuous-wave (FMCW) radar module, mounted 0.4–1.5 m from the subject, tracks the phase of the chest-wall reflection to recover sub-millimetre cardiac motion beneath the much larger movement of breathing. Its onboard DSP performs ranging and signal extraction and streams rate values to an ESP32 microcontroller, which forwards them to a host layer that validates, smooths and displays live heart and breathing rate on a dashboard and optional OLED. The radar senses through clothing and bedding and uses no camera, so it is comfortable, hygienic and privacy-preserving, and the whole platform runs from a single 5 V supply.\r\nInnovation and Novelty:\r\nOur contribution is not the radar itself but a validated, application-level system built around it. First, a validity-gating layer uses the module’s reported target count and range to reject readings when no subject is present or the subject leaves the sensing zone, preventing stale or spurious vitals. Second, we evaluate rigorously rather than anecdotally: heart rate against a reference pulse oximeter and breathing rate against a timed manual count, across multiple volunteers and through fabric barriers, reporting measured error instead of datasheet claims. Third, the design is low-cost and reproducible, using one radar module, one microcontroller and open-source Python. Together these turn a sensing component into a trustworthy monitoring platform for infants, infectious-disease wards, drivers and bedside care, demonstrated live on working hardware.", "workingPrinciple": "EchoVitals measures heart rate and breathing rate from chest-wall motion using a 60 GHz frequency-modulated continuous-wave (FMCW) radar module, with no skin contact. Workflow: (1) The radar transmits low-power frequency chirps toward the subject’s chest from 0.4–1.5 m. (2) Each echo is mixed with the transmitted chirp to produce a beat signal whose frequency encodes distance; a range-FFT isolates the chest wall as a single range bin. (3) The phase of that bin is tracked across successive chirps. Because phase shifts in proportion to displacement, it recovers breathing motion (millimetre scale, about 0.1–0.3 Hz) and the much smaller cardiac motion (about 0.2–0.5 mm, 1–2 Hz). (4) The module’s onboard DSP separates these frequency bands and outputs breathing rate, heart rate, target range and target count over a serial (UART) link. (5) An ESP32 microcontroller reads each frame and forwards it to a Python host layer. (6) The host layer applies validity gating, discarding readings when no subject is present or the subject leaves the monitoring zone, then smooths the remaining values with a short moving average. (7) Live heart rate and breathing rate appear on a dashboard and an optional OLED display. Accuracy is validated against a reference pulse oximeter and a timed manual breath count", "majorHardwareComponents": ["60 GHz FMCW mmWave radar : integrated transceiver", "antenna array \n\nESP32 development board: reads the module’s serial frames and forwards them to the host over USB serial or WiFi. Connected to the radar by four wires (5 V", "GND", "TX", "RX).\n\nHost computer running Python (PySerial", "Matplotlib or Streamlit): performs validity gating", "smoothing and the live dashboard.\n\nSSD1306 OLED display (I2C)", "optional: shows heart rate and breathing rate directly on the device.\nUSB power bank (5 V): single supply for the radar module", "ESP32 and OLED", "making the unit portable.\nMounting stand or small enclosure", "breadboard and jumper wires: hold the sensor at a fixed height and angle towards the chest.\nReference pulse oximeter (validation only): used to measure the system’s heart rate error; breathing rate is checked by a timed manual count."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["Healthcare", "Government / Public Services", "General Public", "Persons with Disabilities", "Other"], "potentialImpact": "Who benefits: neonates and burn patients, whose skin cannot tolerate adhesive electrodes; patients in isolation and infectious-disease wards, where every shared probe is a cross-infection risk; elderly people living alone or in care homes, who can be monitored in bed or in the bathroom without wearing anything; drivers, pilots and train operators, whose alertness and heart health affect many other lives; and ordinary households that want sleep and wellness insight without straps or cameras.\r\n\r\nHow it improves current standards: vital signs are often spot-checked a few times a day because continuous monitoring needs wires, adhesives and patient cooperation. EchoVitals makes continuous monitoring effortless: nothing is attached, nothing needs cleaning between patients, and nothing can be forgotten, loosened or removed. It protects privacy because it captures no images, making monitoring acceptable in bedrooms and bathrooms where cameras never could be. Built from low-cost, off-the-shelf parts and open-source software, it can be replicated at a much lower cost than conventional bedside monitors, bringing continuous monitoring within reach of small clinics, care homes and families.\r\n\r\nLooking ahead, the same platform can raise alerts for breathing pauses or abnormal heart rate, track sleep quality, and extend to multi-bed wards. EchoVitals is a research prototype, not a certified medical device, and our testing against reference instruments is designed to show honestly where it can be trusted.", "productPotential": "yes", "prototypeDevelopmentCost": 4000, "auraDemoHighlight": "Imagine a heartbeat measured from across the room. EchoVitals reads a person’s heart rate and breathing rate without touching them: no electrodes, no straps, no clips and no camera. Judges can sit in front of it and watch their own vital signs appear live on screen, beside a standard pulse oximeter, so the comparison happens in real time rather than on a slide.\r\n\r\nWhat makes it stand out:\r\n\r\nGenuinely contactless: it works through clothing, and we will show it working with fabric placed in between.\r\n\r\nPrivate and hygienic: no images are captured and nothing touches the patient, which suits infants, burn and isolation patients, and elderly care.\r\n\r\nAffordable and reproducible: a handful of low-cost components and open-source code that any college lab can rebuild.\r\n\r\nHonest by design: when the person leaves or the signal is poor, the display flags the reading as unreliable instead of showing a confident but wrong number.", "safetyHazards": ["none"], "safetyPrecautions": "- Low-voltage: powered only by a 5 V USB power bank, no mains connection.\r\n- Low-power radar sensor on a stable stand; nothing touches the body.\r\n- Enclosed, insulated wiring with no exposed conductors.\r\n- No moving parts, heat or chemicals.\r\n- Research prototype, not a medical device; volunteers consent and a team member is always present.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-25T14:03:28.997Z", "updatedAt": "2026-10-25T14:05:29.15Z", "abstract": { "originalName": "EchoVitals_Project_Proposal_Report.docx", "url": "https://res.cloudinary.com/dxkje9whm/raw/upload/v1792937008/aura-registrations/abstract-docs/EchoVitals_Project_Proposal_Report", "filename": "Abstract.docx", "relPath": "assets/Teams/EchoVitals/Abstract.docx", "isDocx": true, "exists": true, "extractedText": "EchoVitals\n\nA radar-based platform for contactless vital health sign sensing.\n\n Heart rate and breathing monitoring in settings where wearable contact-based sensors are impractical.\n\nArman Israfil1,  Sk Sahil Ahamed1,  Md Qais Khan1,  Md Faizan1\n\n1 Dept. of Electronics and Communication Engineering\n\nAliah University\n\nKolkata, India\n\nAbstract: EchoVitals is a low-cost, contactless platform that measures heart rate and breathing rate by reflecting a 60 GHz frequency-modulated continuous-wave (FMCW) radar signal off the chest wall, with no electrodes, straps, or wires. Contact-based sensors are impractical for burn and infectious patients, infants, and high-stress operators, and are uncomfortable for long-term wear (Fig. 1). An integrated FMCW radar module performs on-chip range-gating and phase extraction to separate the heartbeat's sub-millimetre motion from the much larger motion of breathing, and a lightweight host-side layer validates and smooths the resulting readings. We target accuracy comparable to the module's rated performance across the deployment settings in Fig. 2.\n\nIndex Terms : contactless vital-sign monitoring, 60 GHz FMCW radar, mmWave sensing, heart rate, respiration rate.\n\nI. Introduction\n\nA. Problem statement & why and where contact-based devices fail :Continuous contact sensing such as ECG pads, chest straps, and clip-on pulse oximeters  requires wiring. Also, for adhesive types, skin contact is impractical in case of burn and infectious patients, easily irritated for neonates(infants), and restrictive for drivers and pilots. Fig. 1 summarises the recurring failure modes this creates.\n\nFig. 1. Recurring failure modes of contact-based vital sign sensors.\n\nB. Proposed solution:  EchoVitals senses the chest wall directly using a compact radar-on-module: a self-contained transceiver and antenna array paired with an onboard digital signal processor that runs the full frequency-modulated continuous-wave (FMCW) ranging and vital-sign extraction pipeline in hardware. The short wavelength at this frequency band gives the module's phase-based ranging technique the sensitivity needed to resolve the chest wall's sub-millimetre cardiac displacement beneath its much larger respiratory motion, with no external amplification stage. The module reports breathing rate, heart rate, target range, and target count over a standard serial link; the ESP32 microcontroller forwards these values to a host script for validation, smoothing, and display.\n\nC. Deployment settings:  This applies wherever continuous contact sensing is impractical: infants and NICU care, burn and infectious-disease wards, drivers, pilots and train operators, elderly bed and bathroom monitoring, smart mattresses for sleep tracking, and fitness or gym use i.e mapped in Fig. 2. Longer-range scenarios such as search-and-rescue remain future work: the module's rated sensing range (0.4–1.5 m) is built for a fixed, near-body mount, not a moving drone.\n\nFig. 2. Target deployment settings for contactless vital sign sensing.\n\nII. Proposed Implementation\n\nWe build around a single integrated 60 GHz FMCW radar-on-module, which keeps the sensing hardware to one component and removes the need for a discrete amplification stage. The module communicates over a 4-wire serial link (5V, GND, TX, RX) directly to the ESP32 microcontroller; Table I lists the resulting stack.\n\nLayer\n\nTechnology\n\nRole\n\nSensing\n\nIntegrated 60 GHz FMCW radar-on-module with onboard DSP\n\nChirp-based ranging and phase extraction; outputs breathing rate, heart rate, range, and target count\n\nLink\n\nSerial (UART), 115200 baud, 4 wires (5V / GND / TX / RX)\n\nModule to ESP32 microcontroller\n\nMicrocontroller\n\nESP32, C/C++ (Arduino IDE)\n\nForwards frames to host over USB serial or WiFi\n\nHost processing\n\nPython 3, PySerial\n\nFrame parsing, validity gating, temporal smoothing\n\nDisplay\n\nMatplotlib / Streamlit; SSD1306 OLED (I2C, optional)\n\nLive heart rate and breathing rate\n\nValidation\n\nReference pulse oximeter; manual 60 s breath count\n\nAccuracy check against module output\n\nTable I. Technology stack.\n\nIII. Methodology\n\nThe sensing stage is built around a single-chip 60 GHz FMCW radar transceiver. The module emits a sequence of linear frequency chirps and mixes each received echo with the transmitted chirp to produce an intermediate frequency beat signal whose frequency encodes target range. A range-FFT across each chirp resolves the subject's chest wall as a single range bin, and the phase of that bin is tracked chirp-to-chirp to recover sub-millimetre surface displacement,  the basis of micro-Doppler vital-sign sensing. Onboard firmware separates this phase history into two frequency bands: a low-frequency, high-amplitude component corresponding to respiration, and a higher-frequency, low-amplitude component corresponding to the heartbeat, and reports both as periodic rate values together with a target count and range estimate.\n\nOn the host side, EchoVitals treats these periodic values as a lightweight telemetry stream rather than a raw waveform. A parsing layer reads each frame; a validity gate cross-checks the reported target count and range against the expected monitoring zone and discards frames where no subject is present or the subject has left the sensing envelope; and a short moving-average stage smooths the surviving readings before they reach the display. The signal-processing burden , chirp generation, range-gating, and respiration/cardiac band separation is carried entirely by the radar module's onboard DSP, keeping the host implementation small and auditable. The complete signal path and power distribution are shown in Fig. 3.\n\nFig. 3. 60 GHz FMCW system block diagram showing signal path and power distribution.\n\nIV. Desired Output and Expected Results\n\nA working prototype displaying live heart rate and breathing rate on a bedside dashboard, mounted 0.4–1.5 m from a seated or lying subject. We will validate against a reference pulse oximeter for heart rate and a manual 60-second breath count for breathing rate, across at least four consenting team volunteers, and record the module's own reported target confidence alongside each reading. Manufacturer-published figures for this class of module report respiratory accuracy around 90% and cardiac accuracy in the 85–95% range depending on test conditions; we report our own measured error rather than assuming a datasheet figure holds in our setup.\n\nV. Conclusion\n\nEchoVitals shows that reliable, contact-free vital-sign monitoring is achievable with a single integrated 60 GHz FMCW radar module, a microcontroller, and a lightweight validation layer  without the fragile analog front end or complex filtering pipeline that raw-radar approaches typically require. The system measures heart rate and breathing directly from chest-wall motion, targets accuracy comparable to its sensor class through reference-validated testing and is designed for deployment across the patient groups and environments outlined in this proposal. It offers a practical, low-cost foundation for non-contact patient monitoring that can be extended toward broader clinical and field use." }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/EchoVitals/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792937007/aura-registrations/id-cards/znoxiemmurfjiwobaceb.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/EchoVitals/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792937007/aura-registrations/id-cards/uadcpujn7bjnx2tdcrjc.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/EchoVitals/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792937007/aura-registrations/id-cards/rmfzamwmmhvk8tfi573k.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/EchoVitals/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792937007/aura-registrations/id-cards/urxkpfuxkegntt74rlra.jpg", "exists": true }] }, { "index": 56, "id": "6ade16184232d0d3a140b4b5", "registrationId": "AURA2K26-PV7BPL", "rawTeamName": "Cyber Circuits", "folderName": "Cyber Circuits", "folderRelPath": "assets/Teams/Cyber Circuits", "projectTitle": "An IoT-Based Intelligent Drainage Monitoring and Early Blockage Detection System", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Parvez alam", "teamLeaderEmail": "parvezacademy26@gmail.com", "teamLeaderPhone": "9432334547", "teamMemberDetails": "Shaheer and shahnawaz from electronics and communication dept 2nd year . Ahmed ali from electrical department 2nd year .aliah university.", "hardwareProjectCategories": ["IoT & Smart Devices"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem: Urban drains often get partially blocked by plastic, leaves, mud and stones, especially during heavy rain. Conventional drains give no early warning, and overflow becomes visible only after the flow is already restricted, causing waterlogging, road damage and health risks.\r\nSolution: We propose a low-cost IoT-based drainage monitoring system built around an ESP32. A rain sensor detects rainfall and starts monitoring. Two water-level sensors, one upstream (A) and one downstream (B), measure the water level inside the drain. The ESP32 calculates the difference D = A − B and, together with the rainfall condition, classifies the drain as Normal, Warning or Blockage Alert. LEDs and a buzzer give local indication, and Wi-Fi sends a remote notification.\r\nInnovation: The system does not rely on a single high-water-level threshold. Two-point differential monitoring combined with rainfall context detects abnormal drainage behaviour earlier and reduces false alarms from ordinary water-level changes. The modular design can be extended with extra sensor nodes to cover more drain sections, supporting preventive inspection and faster response before severe overflow.", "solutionDescription": "Problem: Urban drains often get partially blocked by plastic, leaves, mud and stones, especially during heavy rain. Conventional drains give no early warning, and overflow becomes visible only after the flow is already restricted, causing waterlogging, road damage and health risks.\r\nSolution: We propose a low-cost IoT-based drainage monitoring system built around an ESP32. A rain sensor detects rainfall and starts monitoring. Two water-level sensors, one upstream (A) and one downstream (B), measure the water level inside the drain. The ESP32 calculates the difference D = A − B and, together with the rainfall condition, classifies the drain as Normal, Warning or Blockage Alert. LEDs and a buzzer give local indication, and Wi-Fi sends a remote notification.\r\nInnovation: The system does not rely on a single high-water-level threshold. Two-point differential monitoring combined with rainfall context detects abnormal drainage behaviour earlier and reduces false alarms from ordinary water-level changes. The modular design can be extended with extra sensor nodes to cover more drain sections, supporting preventive inspection and faster response before severe overflow.", "innovationDescription": "Problem: Urban drains often get partially blocked by plastic, leaves, mud and stones, especially during heavy rain. Conventional drains give no early warning, and overflow becomes visible only after the flow is already restricted, causing waterlogging, road damage and health risks.\r\nSolution: We propose a low-cost IoT-based drainage monitoring system built around an ESP32. A rain sensor detects rainfall and starts monitoring. Two water-level sensors, one upstream (A) and one downstream (B), measure the water level inside the drain. The ESP32 calculates the difference D = A − B and, together with the rainfall condition, classifies the drain as Normal, Warning or Blockage Alert. LEDs and a buzzer give local indication, and Wi-Fi sends a remote notification.\r\nInnovation: The system does not rely on a single high-water-level threshold. Two-point differential monitoring combined with rainfall context detects abnormal drainage behaviour earlier and reduces false alarms from ordinary water-level changes. The modular design can be extended with extra sensor nodes to cover more drain sections, supporting preventive inspection and faster response before severe overflow.", "workingPrinciple": "A rain sensor first detects rainfall and signals the ESP32 microcontroller to start drainage monitoring. Two water-level sensors are placed inside the drain: Sensor A on the upstream side and Sensor B on the downstream side. The ESP32 continuously reads both values.\r\nDuring normal flow, A and B stay close to each other. When a blockage forms, water accumulates upstream while the downstream level stays comparatively lower. The ESP32 calculates the difference D = A − B and evaluates it together with the rainfall condition.\r\nBased on this, a three-level decision logic classifies the drain as Normal, Warning or Blockage Alert. Green, yellow and red LEDs with a buzzer give local indication, and the ESP32 sends a remote notification over Wi-Fi.\r\nBecause it uses two-point differential monitoring with rainfall context instead of a single high-water threshold, it detects blockage earlier and reduces false alarms.", "majorHardwareComponents": ["ESP32 microcontroller (with built-in Wi-Fi)", "2 × water-level sensors (Sensor A upstream", "Sensor B downstream)", "rain sensor module", "green/yellow/red LEDs", "buzzer", "resistors", "breadboard or PCB", "jumper wires", "5V power supply or rechargeable battery with power module", "small drain/channel model for the prototype."], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Government / Public Services"], "potentialImpact": "Urban residents, municipal bodies and city planners benefit most. Blocked drains cause waterlogging, damaged roads, traffic jams, mosquito breeding and disease spread during monsoon. Today, blockages are found only after water overflows or when people complain, and inspection is manual and reactive.\r\nOur system gives an early warning before overflow happens, so authorities can inspect and clear only the drains that need attention instead of checking all of them. This saves time, labour and repair costs, and reduces flood-related losses.\r\nCompared with single-threshold level alarms, the two-point differential method with rainfall context detects abnormal flow earlier and gives fewer false alarms. Being low-cost and modular, it can be scaled across many drain sections, supporting smarter and safer cities.", "productPotential": "yes", "prototypeDevelopmentCost": 3000, "auraDemoHighlight": "Our project solves a real city problem: drain blockages that are noticed only after water has already overflowed. Instead of waiting for a high-water alarm, it compares the water level on both sides of a drain (D = A − B) and uses rainfall as context, so it can warn of a blockage early.\r\nThe most unique aspect is this two-point differential method. It is simple, low-cost (about ₹3,000) and uses only an ESP32 and basic sensors, yet gives three-level status: Normal, Warning and Blockage Alert.\r\nJudges can see it working live. When we partially block the model drain during simulated rain, the status changes in real time, the LEDs and buzzer react, and a Wi-Fi notification is sent.", "safetyHazards": ["none"], "safetyPrecautions": "The prototype runs on low-voltage DC (5V battery supply), so there is no mains or high-voltage exposure. All electronics (ESP32, wiring, buzzer, LEDs) are kept in a sealed, insulated enclosure away from the water. Only the sensor probes are placed in the drain model, and their exposed contacts are waterproofed with insulation. A fuse or protection circuit is used with the battery, and the charging module has overcharge protection. The drain model uses a plastic container with no sharp edges. The demo area is kept dry, and wiring is neatly secured to avoid short circuits.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-25T14:45:44.909Z", "updatedAt": "2026-10-25T14:47:45.016Z", "abstract": { "originalName": "DOC-20260928-WA0009.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792939543/aura-registrations/abstract-docs/DOC-20260928-WA0009.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Cyber Circuits/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Cyber Circuits/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792939544/aura-registrations/id-cards/jt0fyqactt4cwnlczquk.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Cyber Circuits/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792939543/aura-registrations/id-cards/kukkegrmrskcpz2u22oe.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Cyber Circuits/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792939543/aura-registrations/id-cards/mvngeolb0cxjzxz6ojoq.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Cyber Circuits/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792939543/aura-registrations/id-cards/n5ye0iowtofi08jambmk.jpg", "exists": true }] }, { "index": 57, "id": "6ade54569fefa4bce563a101", "registrationId": "AURA2K26-4H5W6C", "rawTeamName": "PulseTech", "folderName": "PulseTech", "folderRelPath": "assets/Teams/PulseTech", "projectTitle": "Unified Railway Infrastructure & Safety Mesh (URISM): A Decentralized IoT Digital Twin with Piezoelectric Energy Harvesting.", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "SARAMAHABSAR", "teamLeaderEmail": "saramahabsar37@gmail.com", "teamLeaderPhone": "8509229629", "teamMemberDetails": "NAME- RASAMAHA ABSAR, ALIAH UNIVERSITY, PH NO- 8250896373, EMAIL ID- rasamahaabsar@gmail.com", "hardwareProjectCategories": ["Embedded Systems", "IoT & Smart Devices", "Safety & Security Systems"], "prototypeType": "IoT Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem\r\n\r\nMillions of people rely on railways every day, yet safety checks still depend heavily on people inspecting tracks and structures by hand. This is slow and infrequent, so small issues, such as a hairline crack in a rail, a bridge slowly losing strength, or a passenger standing too close to a platform edge, can go unnoticed until they become serious. Remote locations make things harder because power and connectivity are limited. Sending large amounts of raw sensor data to a central server adds delays and cost. Platforms, tracks and bridges are also usually monitored separately, so no one gets a clear picture of the whole network.\r\n\r\nSolution\r\n\r\nWe propose a smart monitoring system built from small units placed at key points on platforms, tracks and bridges. Each unit collects local information such as vibration, strain and load, and processes it on the spot, so risks are caught quickly without waiting for a distant server. Piezoelectric harvesters turn vibrations from passing trains into small amounts of electricity, helping power the units. On bridges, continuous structural health monitoring tracks changes in load and stress that may point to hidden weakness. Only essential information, such as alerts and status summaries, is sent onward and shown on a centralised digital twin, a live virtual model of the railway.\r\n\r\nInnovation\r\n\r\nThe novelty lies in combining everything in one framework: unified monitoring of platforms, tracks and bridges, local intelligence, partial self-powering and lightweight communication. Together, these give earlier warnings, fewer manual inspections, lower costs and a safer, more affordable railway.", "solutionDescription": "Problem\r\n\r\nMillions of people rely on railways every day, yet safety checks still depend heavily on people inspecting tracks and structures by hand. This is slow and infrequent, so small issues, such as a hairline crack in a rail, a bridge slowly losing strength, or a passenger standing too close to a platform edge, can go unnoticed until they become serious. Remote locations make things harder because power and connectivity are limited. Sending large amounts of raw sensor data to a central server adds delays and cost. Platforms, tracks and bridges are also usually monitored separately, so no one gets a clear picture of the whole network.\r\n\r\nSolution\r\n\r\nWe propose a smart monitoring system built from small units placed at key points on platforms, tracks and bridges. Each unit collects local information such as vibration, strain and load, and processes it on the spot, so risks are caught quickly without waiting for a distant server. Piezoelectric harvesters turn vibrations from passing trains into small amounts of electricity, helping power the units. On bridges, continuous structural health monitoring tracks changes in load and stress that may point to hidden weakness. Only essential information, such as alerts and status summaries, is sent onward and shown on a centralised digital twin, a live virtual model of the railway.\r\n\r\nInnovation\r\n\r\nThe novelty lies in combining everything in one framework: unified monitoring of platforms, tracks and bridges, local intelligence, partial self-powering and lightweight communication. Together, these give earlier warnings, fewer manual inspections, lower costs and a safer, more affordable railway.", "innovationDescription": "Problem\r\n\r\nMillions of people rely on railways every day, yet safety checks still depend heavily on people inspecting tracks and structures by hand. This is slow and infrequent, so small issues, such as a hairline crack in a rail, a bridge slowly losing strength, or a passenger standing too close to a platform edge, can go unnoticed until they become serious. Remote locations make things harder because power and connectivity are limited. Sending large amounts of raw sensor data to a central server adds delays and cost. Platforms, tracks and bridges are also usually monitored separately, so no one gets a clear picture of the whole network.\r\n\r\nSolution\r\n\r\nWe propose a smart monitoring system built from small units placed at key points on platforms, tracks and bridges. Each unit collects local information such as vibration, strain and load, and processes it on the spot, so risks are caught quickly without waiting for a distant server. Piezoelectric harvesters turn vibrations from passing trains into small amounts of electricity, helping power the units. On bridges, continuous structural health monitoring tracks changes in load and stress that may point to hidden weakness. Only essential information, such as alerts and status summaries, is sent onward and shown on a centralised digital twin, a live virtual model of the railway.\r\n\r\nInnovation\r\n\r\nThe novelty lies in combining everything in one framework: unified monitoring of platforms, tracks and bridges, local intelligence, partial self-powering and lightweight communication. Together, these give earlier warnings, fewer manual inspections, lower costs and a safer, more affordable railway.", "workingPrinciple": "The system works as a continuous cycle of sensing, local processing, energy harvesting, communication and visualisation. 1. Sensing. Monitoring units installed on platforms, tracks and bridges collect real-time data. Platform units detect crowding and people near the edge. Track units measure vibration, strain and movement that may indicate cracks or misalignment. Bridge units record load, stress and structural response as trains pass. 2. Local processing. Each unit has a small processor that analyses its own data on site. It filters out noise, compares readings against normal patterns and flags anything unusual, such as a sudden spike in strain or a gradual rise in stress. Because the decision is made locally, the response is fast. 3. Energy harvesting. When a train passes, it causes vibrations in the rails and bridge. Piezoelectric elements fixed at these points convert the mechanical stress into small electrical charges. A circuit conditions this energy and stores it in a battery or capacitor, which helps power the sensors and processor and reduces dependence on external supply. 4. Essential data transmission. Instead of sending all raw readings, each unit sends only summaries, health indicators and alerts through a wireless link. This keeps delay and bandwidth use low. 5. Digital twin visualisation. The central digital twin receives data from all units and updates a virtual model of the railway. It shows the condition of platforms, tracks and bridges in one view, and compares current behaviour with past trends to spot gradual deterioration. 6. Alert and action. When a risk.", "majorHardwareComponents": ["esp32", "sensors", "battery", "zener diode..etc"], "useAi": false, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Transportation"], "potentialImpact": "Potential Real-World Impact\r\n\r\nSafer journeys. Cracks in rails, tired bridges and risky moments on crowded platforms can be spotted early, before they turn into derailments, collapses or injuries. Local alerts mean staff can respond within moments rather than hours.\r\n\r\nLower costs. Instead of sending crews out on a fixed schedule, railways can repair what actually needs attention. That means fewer routine inspections, less unplanned downtime, and tracks and bridges that last longer because problems are fixed while they are still small.\r\n\r\nLess energy, fewer batteries. Because passing trains help power the units, there is less dependence on the grid and less battery replacement. This also makes monitoring practical in remote stretches where reliable power is hard to find.\r\n\r\nBetter decisions. The digital twin gives railway authorities one clear picture of platforms, tracks and bridges, so planning and prioritising repairs becomes easier. Sending only essential data keeps communication fast and affordable.\r\n\r\nSafer work. Fewer people need to walk along live tracks or climb bridges for inspections, which reduces risk for workers.\r\n\r\nRoom to grow. The design is modular, so it can begin at a single station or bridge and expand across a whole network. Its low cost makes it especially useful for countries like India, where a vast, ageing railway system needs smarter upkeep.\r\n\r\nPublic trust. Fewer accidents and more reliable services help passengers feel confident travelling by rail, supporting wider smart transport goals.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "It tackles a real, life-and-death problem. Railway failures are rare but devastating. This project aims to catch the warning signs early, before a small crack or a weakening bridge becomes a tragedy.\r\n\r\nIt brings everything together. Most systems watch platforms, tracks or bridges separately. This one covers all three in a single framework, giving a complete picture of railway health.\r\n\r\nIt powers itself, at least partly. Passing trains shake the tracks every day, and that wasted vibration is turned into usable electricity. It is a clever way to make monitoring work in remote places without reliable power.\r\n\r\nIt thinks locally. Each unit analyses its own data on the spot, so warnings come quickly instead of waiting on a distant server.\r\n\r\nIt keeps communication light. Only the essential information is sent, which saves bandwidth, cost and time.\r\n\r\nIt shows the whole railway at a glance. The digital twin turns scattered sensor readings into one live, easy-to-read view that helps officials plan and prioritise repairs.\r\n\r\nIt is practical and affordable. Built from widely available components, it can start small at one station or bridge and scale across a national network, making it realistic for countries like India.\r\n\r\nIt makes a human difference. Fewer accidents, safer workers and greater passenger confidence are the real measures of success", "safetyHazards": ["none"], "safetyPrecautions": "Power Isolation: Uses a 12V battery safely stepped down via buck converters to 5V logic with fully insulated wiring.\r\nVoltage Protection: 5.1V Zener diodes and 1MΩ bleed resistors clamp unexpected voltage spikes from piezoelectric harvesters.\r\nEnclosed Circuitry: All components are soldered onto perfboards and housed in protective enclosures beneath the diorama to prevent short circuits.\r\nStructural Stability: The model base and transit bridge are firmly secured to prevent tipping or physical strain during demos.\r\nSoftware Fail-Safes: Automated dashboard monitoring instantly flags any node disconnection or power fluctuation.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-25T19:11:18.085Z", "updatedAt": "2026-10-25T19:13:18.17Z", "abstract": { "originalName": "AURA_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792955476/aura-registrations/abstract-docs/Aura_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/PulseTech/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/PulseTech/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792955476/aura-registrations/id-cards/jdlsbvvpnpja1b8tnsle.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/PulseTech/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792955476/aura-registrations/id-cards/ajxyhep1kk6rg0qbpjxt.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/PulseTech/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/PulseTech/4.jpg", "url": null, "exists": false }] }, { "index": 58, "id": "6adecbd01177b5721ad6fef8", "registrationId": "AURA2K26-EUBYMQ", "rawTeamName": "Safe_Volt LABS", "folderName": "Safe_Volt LABS", "folderRelPath": "assets/Teams/Safe_Volt LABS", "projectTitle": "DUAL-LAYER FIRE DEFENSE : PRE-FAULT ELECTRICAL MONITORING & YOLO-BASED SURVEILLANCE FOR HOSPITALS", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "ARINDAM DAS", "teamLeaderEmail": "arindamdas9883@gmail.com", "teamLeaderPhone": "9883281797", "teamMemberDetails": "AFSANA KHATUN | ALIAH UNIVERSITY | ELECTRICAL | 3RD YEAR | 9734310075 \r\nSURJA PAL |  ALIAH UNIVERSITY | ELECTRICAL | 3RD YEAR | 9564051920\r\nYEASIN MALLICK  ALIAH UNIVERSITY | ELECTRICAL | 3RD YEAR | 8918743891", "hardwareProjectCategories": ["Safety & Security Systems", "Electrical Systems"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Statement:\r\nElectrical fires in hospitals pose a severe risk to patient safety and critical medical equipment. Currently, many public healthcare facilities rely heavily on reactive safety measures, such as standard ceiling-mounted smoke detectors. The main limitation of these traditional systems is that they only trigger after an electrical fault has already escalated into a physical fire, which can lead to equipment damage, power loss, and emergency evacuations. While advanced predictive maintenance systems exist in the industry, they are often too expensive for underfunded public hospitals, leaving a gap in accessible, early-warning safety infrastructure.\r\n\r\nSolution:\r\nWe propose a dual-layer warning system designed to detect fire hazards earlier than traditional methods. The first layer monitors the electrical distribution boards directly. By tracking abnormal temperature rises, current overloads, and the presence of gases (VOCs) released by melting wire insulation, the hardware node can identify a degrading electrical joint before it actively catches fire. The second layer uses a YOLOv8 computer vision model analyzing CCTV camera feeds to monitor the physical hospital wards. This allows the system to visually identify open flames or smoke caused by external factors, providing an immediate secondary alert to the monitoring station.\r\n\r\nInnovation:\r\nThe primary innovation of this project is combining multi-parameter sensor fusion with local AI computer vision using low-cost hardware. Relying on a single sensor often leads to false alarms (e.g., triggering due to summer heat). Our system reduces these errors by cross-referencing electrical load, temperature, and gas levels using a threshold logic matrix to verify a real hazard. Additionally, running the YOLO vision model on a local computer ensures data privacy and fast processing without needing external cloud servers. By integrating affordable IoT microcontrollers (ESP32) with open-source AI, this prototype demonstrates a practical, cost-effective approach to upgrading fire safety in existing public healthcare facilities.", "solutionDescription": "Problem Statement:\r\nElectrical fires in hospitals pose a severe risk to patient safety and critical medical equipment. Currently, many public healthcare facilities rely heavily on reactive safety measures, such as standard ceiling-mounted smoke detectors. The main limitation of these traditional systems is that they only trigger after an electrical fault has already escalated into a physical fire, which can lead to equipment damage, power loss, and emergency evacuations. While advanced predictive maintenance systems exist in the industry, they are often too expensive for underfunded public hospitals, leaving a gap in accessible, early-warning safety infrastructure.\r\n\r\nSolution:\r\nWe propose a dual-layer warning system designed to detect fire hazards earlier than traditional methods. The first layer monitors the electrical distribution boards directly. By tracking abnormal temperature rises, current overloads, and the presence of gases (VOCs) released by melting wire insulation, the hardware node can identify a degrading electrical joint before it actively catches fire. The second layer uses a YOLOv8 computer vision model analyzing CCTV camera feeds to monitor the physical hospital wards. This allows the system to visually identify open flames or smoke caused by external factors, providing an immediate secondary alert to the monitoring station.\r\n\r\nInnovation:\r\nThe primary innovation of this project is combining multi-parameter sensor fusion with local AI computer vision using low-cost hardware. Relying on a single sensor often leads to false alarms (e.g., triggering due to summer heat). Our system reduces these errors by cross-referencing electrical load, temperature, and gas levels using a threshold logic matrix to verify a real hazard. Additionally, running the YOLO vision model on a local computer ensures data privacy and fast processing without needing external cloud servers. By integrating affordable IoT microcontrollers (ESP32) with open-source AI, this prototype demonstrates a practical, cost-effective approach to upgrading fire safety in existing public healthcare facilities.", "innovationDescription": "Problem Statement:\r\nElectrical fires in hospitals pose a severe risk to patient safety and critical medical equipment. Currently, many public healthcare facilities rely heavily on reactive safety measures, such as standard ceiling-mounted smoke detectors. The main limitation of these traditional systems is that they only trigger after an electrical fault has already escalated into a physical fire, which can lead to equipment damage, power loss, and emergency evacuations. While advanced predictive maintenance systems exist in the industry, they are often too expensive for underfunded public hospitals, leaving a gap in accessible, early-warning safety infrastructure.\r\n\r\nSolution:\r\nWe propose a dual-layer warning system designed to detect fire hazards earlier than traditional methods. The first layer monitors the electrical distribution boards directly. By tracking abnormal temperature rises, current overloads, and the presence of gases (VOCs) released by melting wire insulation, the hardware node can identify a degrading electrical joint before it actively catches fire. The second layer uses a YOLOv8 computer vision model analyzing CCTV camera feeds to monitor the physical hospital wards. This allows the system to visually identify open flames or smoke caused by external factors, providing an immediate secondary alert to the monitoring station.\r\n\r\nInnovation:\r\nThe primary innovation of this project is combining multi-parameter sensor fusion with local AI computer vision using low-cost hardware. Relying on a single sensor often leads to false alarms (e.g., triggering due to summer heat). Our system reduces these errors by cross-referencing electrical load, temperature, and gas levels using a threshold logic matrix to verify a real hazard. Additionally, running the YOLO vision model on a local computer ensures data privacy and fast processing without needing external cloud servers. By integrating affordable IoT microcontrollers (ESP32) with open-source AI, this prototype demonstrates a practical, cost-effective approach to upgrading fire safety in existing public healthcare facilities.", "workingPrinciple": "Our system utilizes a parallel workflow.\r\n\r\nPhase 1: Invisible Pre-Fire Detection (Hardware)\r\nInside the electrical panel, the ZMCT103C continuously reads the AC load current. Simultaneously, a thermistor monitors the surface temperature of the critical junctions, while an MQ-2 sensor samples the enclosure's air. The ESP32 processes this using a threshold matrix. If current remains normal but the ambient temperature spikes, it may just be environmental heat. However, if the current is near capacity, the junction temperature rises sharply, and the MQ-2 detects VOCs (melting PVC insulation), the ESP32 confirms a \"Pre-Fire Hazard.\" It immediately triggers a local buzzer and sends a critical cutoff warning to the dashboard.\r\n\r\nPhase 2: Visible Fire Detection (Surveillance)\r\nIn the physical hospital corridors, live video feeds are routed to a central monitoring station. A Python script captures the stream and feeds it frame-by-frame into a pre-trained YOLOv8 neural network. The GPU analyzes the spatial grid of the video for the visual signatures of smoke and hydrocarbon flames.\r\n\r\nIf either the hardware node predicts a panel failure, or the AI detects a physical fire, the central dashboard logs the event, sounds the alarm, and pinpoints the exact zone of the hazard, allowing for targeted maintenance without a hospital-wide panic.", "majorHardwareComponents": ["1. ESP32 Microcontroller: The brain of the hardware node. It provides the necessary ADC pins for sensor data acquisition", "processing power for the threshold matrix", "and built-in Wi-Fi for transmitting telemetry to the central dashboard.\n\n2. ZMCT103C AC Current Transformer: A precision", "non-invasive current sensor. It safely measures the AC load of the monitored circuit without requiring direct electrical contact with live wires", "ensuring safe and accurate overload tracking.\n\n3. Temperature Sensor (10k NTC Thermistor / DS18B20): Placed directly against the wire insulation or circuit breaker casing to measure the localized thermal gradient caused by high-resistance loose connections.\n\n4. MQ-2 Gas / Smoke Sensor: Mounted at the top of the electrical enclosure to act as an \"electronic nose.\" It detects the specific chemical off-gassing and volatile organic compounds (VOCs) released by thermally degrading plastics before visible smoke appears.\n\n5. IP Camera / Smartphone Camera: Acts as the simulated hospital CCTV network", "providing a high-speed", "local Wi-Fi video stream (via SRT or MJPEG) to the processing computer.\n\n6. Central Processing Unit (PC with Nvidia RTX GPU): Handles the heavy computational lifting of running the YOLOv8 object detection model in real-time on the incoming video feeds."], "useAi": true, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["Healthcare", "General Public", "Government / Public Services", "Persons with Disabilities"], "potentialImpact": "This system is designed to democratize critical safety. In developing nations, government and public hospitals serve the vast majority of the population but operate on restrictive budgets. They simply cannot afford multi-million-dollar proprietary smart-building overhauls.\r\n\r\nThe real-world impact of this project is accessible prevention.\r\n\r\nPreservation of Life: By detecting the root cause of electrical fires early, it prevents catastrophic power outages to life-support zones (ventilators, incubators) caused by short circuits.\r\n\r\nElimination of Panic: It allows maintenance staff to preemptively repair a smoldering panel calmly, avoiding the massive risk of evacuating a high-dependency hospital wing.\r\n\r\nUpgrading Legacy Infrastructure: Because the hardware relies on affordable IoT sensors and the software utilizes existing CCTV cameras, this system can be retrofitted into decades-old hospital buildings without requiring extensive rewiring. It elevates the safety standards of underfunded public hospitals to match or exceed those of elite private institutions.", "productPotential": "potentially", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "Judges and audiences should pay attention because this project directly addresses a hidden but critical vulnerability in healthcare infrastructure. In a hospital—particularly in ICUs, NICUs, or operating theaters—a fire or sudden power outage is an immediate threat to patient survival. Traditional safety systems are purely reactive; they wait for smoke to fill a hallway. By the time a standard alarm triggers, life-support equipment is already compromised, and a highly dangerous patient evacuation is necessary.\r\n\r\nThe most impressive and unique aspect of this project is its shift from reaction to early prediction, engineered specifically for these zero-downtime environments. Instead of waiting for a fire to start, the system targets the root cause directly inside the electrical distribution boards. By tracking the precise moment a loose connection causes wire insulation to overheat and off-gas, it issues a targeted maintenance warning long before a spark ever ignites—preventing both the fire and the resulting power failure.\r\n\r\nCoupled with the AI vision layer, which instantly identifies hazards in the physical wards using existing cameras, the project showcases a complete safety ecosystem. It is compelling because it proves that advanced, life-saving predictive safety does not require prohibitively expensive hospital upgrades; it simply requires smart, purposeful engineering.", "safetyHazards": ["high_voltage", "fire_combustion"], "safetyPrecautions": "To ensure absolute safety during the exhibition and development, strict safeguards have been built into the prototype design:1. Galvanic Isolation: We utilize a ZMCT103C current transformer, meaning the ESP32 and our laptops are physically isolated from the AC voltage via magnetic induction. There is no direct electrical connection between the high-voltage load and the microcontrollers.2. Safe Fault Simulation: We do not create actual electrical shorts or open sparks. The \"loose connection\" is safely simulated using a controlled, enclosed ceramic power resistor in series with the load. It safely generates the precise I^2R heat required to trigger the thermal and gas sensors without risking an actual fire.3. Overcurrent Protection: The prototype circuit includes its own dedicated fast-acting fuse and a low-amperage Miniature Circuit Breaker (MCB) independent of the exhibition hall’s power supply, ensuring any accidental overload is instantly neutralized.4. Regulated Power Distribution: High-draw components like the MQ-2 heating coil are powered via a dedicated, heat-sinked voltage regulator, preventing thermal stress or failure of the ESP32’s internal power delivery system.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T03:41:04.244Z", "updatedAt": "2026-10-26T03:43:04.462Z", "abstract": { "originalName": "SAFE_VOLT LABS.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792986062/aura-registrations/abstract-docs/SAFE_VOLT%20LABS.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Safe_Volt LABS/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Safe_Volt LABS/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792986062/aura-registrations/id-cards/xidckmybdrglq58bou0k.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Safe_Volt LABS/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792986062/aura-registrations/id-cards/wjp6cm0g2yigrsdrogxp.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Safe_Volt LABS/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792986062/aura-registrations/id-cards/hechu2rk4w00suhmd7et.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Safe_Volt LABS/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1792986063/aura-registrations/id-cards/xpc3bcpy3uxvo0ohribh.jpg", "exists": true }] }, { "index": 59, "id": "6adf40b80d7b3931306f894f", "registrationId": "AURA2K26-BMNY37", "rawTeamName": "Team BioNexus", "folderName": "Team BioNexus", "folderRelPath": "assets/Teams/Team BioNexus", "projectTitle": "SMARTCARE – IoT-Based Patient Monitoring and Intelligent Emergency Alert System", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "INJAMAM MULHASAN SIDDIQUI", "teamLeaderEmail": "siddiquibibiaisha1001@gmail.com", "teamLeaderPhone": "9525063287", "teamMemberDetails": "JIAUR RAHAMAN | ALIAH UNIVERSITY | EEN | 4TH YEAR | 8597539858\r\nMD ASIF ALI | ALIAH UNIVERSITY | ECE | 3RD YEAR | 9572414228\r\nMD AZIM GAYEN | ALIAH UNIVERSITY | EEN | 4TH YEAR | 7699912797", "hardwareProjectCategories": ["Biomedical / Healthcare Devices"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "**Problem Statement:**\r\n\r\nContinuous monitoring of vital health parameters is essential for identifying potentially abnormal physiological conditions. However, conventional patient monitoring systems can be expensive, less portable, and may lack accessible real-time remote monitoring features. In situations where continuous observation is difficult, abnormal readings may go unnoticed. There is a need for an affordable, portable, and integrated system capable of monitoring multiple health parameters and generating timely alerts.\r\n\r\n**Proposed Solution:**\r\n\r\nSMARTCARE is an ESP32-based IoT patient monitoring and intelligent emergency alert system designed to measure heart rate (BPM), blood oxygen saturation (SpO₂), ECG signals, and temperature in real time.\r\n\r\nThe proposed system integrates MAX30102, AD8232, and temperature sensors with an ESP32 microcontroller. Sensor readings will be processed and transmitted via Wi-Fi to an interactive web dashboard, enabling real-time visualization of physiological parameters, ECG waveforms, and historical trends.\r\n\r\nAn intelligent alert mechanism will continuously evaluate sensor readings, verify signal quality, and detect persistent abnormal conditions before triggering warning or critical alerts through a buzzer and dashboard notifications. The system will also feature an OLED display, historical data logging, and portable battery-powered operation.\r\n\r\n**Innovation Details:**\r\n\r\nSMARTCARE combines biomedical sensing, IoT connectivity, and intelligent alert mechanisms into a single affordable and portable monitoring prototype.\r\n\r\nIts key innovative features include:\r\n\r\n1. **Multi-Parameter Monitoring:** Integration of ECG, heart rate, SpO₂, and temperature monitoring within one compact device.\r\n2. **Intelligent Emergency Alerts:** Configurable thresholds, signal-quality verification, and persistence-based detection to minimize false alarms.\r\n3. **Real-Time Web Dashboard:** Wireless monitoring with live ECG visualization, health parameter tracking, and historical data analysis.\r\n4. **Dual Display System:** Local OLED display and remote browser-based dashboard for convenient access.\r\n5. **Affordable and Portable Design:** Low-cost components, battery-powered operation, and expandable architecture for future cloud or mobile integration.\r\n\r\nSMARTCARE aims to demonstrate an accessible, cost-effective healthcare technology solution that combines real-time monitoring, intelligent alerts, and IoT-based visualization. It is intended as an educational engineering prototype, not a certified medical diagnostic device.", "solutionDescription": "**Problem Statement:**\r\n\r\nContinuous monitoring of vital health parameters is essential for identifying potentially abnormal physiological conditions. However, conventional patient monitoring systems can be expensive, less portable, and may lack accessible real-time remote monitoring features. In situations where continuous observation is difficult, abnormal readings may go unnoticed. There is a need for an affordable, portable, and integrated system capable of monitoring multiple health parameters and generating timely alerts.\r\n\r\n**Proposed Solution:**\r\n\r\nSMARTCARE is an ESP32-based IoT patient monitoring and intelligent emergency alert system designed to measure heart rate (BPM), blood oxygen saturation (SpO₂), ECG signals, and temperature in real time.\r\n\r\nThe proposed system integrates MAX30102, AD8232, and temperature sensors with an ESP32 microcontroller. Sensor readings will be processed and transmitted via Wi-Fi to an interactive web dashboard, enabling real-time visualization of physiological parameters, ECG waveforms, and historical trends.\r\n\r\nAn intelligent alert mechanism will continuously evaluate sensor readings, verify signal quality, and detect persistent abnormal conditions before triggering warning or critical alerts through a buzzer and dashboard notifications. The system will also feature an OLED display, historical data logging, and portable battery-powered operation.\r\n\r\n**Innovation Details:**\r\n\r\nSMARTCARE combines biomedical sensing, IoT connectivity, and intelligent alert mechanisms into a single affordable and portable monitoring prototype.\r\n\r\nIts key innovative features include:\r\n\r\n1. **Multi-Parameter Monitoring:** Integration of ECG, heart rate, SpO₂, and temperature monitoring within one compact device.\r\n2. **Intelligent Emergency Alerts:** Configurable thresholds, signal-quality verification, and persistence-based detection to minimize false alarms.\r\n3. **Real-Time Web Dashboard:** Wireless monitoring with live ECG visualization, health parameter tracking, and historical data analysis.\r\n4. **Dual Display System:** Local OLED display and remote browser-based dashboard for convenient access.\r\n5. **Affordable and Portable Design:** Low-cost components, battery-powered operation, and expandable architecture for future cloud or mobile integration.\r\n\r\nSMARTCARE aims to demonstrate an accessible, cost-effective healthcare technology solution that combines real-time monitoring, intelligent alerts, and IoT-based visualization. It is intended as an educational engineering prototype, not a certified medical diagnostic device.", "innovationDescription": "**Problem Statement:**\r\n\r\nContinuous monitoring of vital health parameters is essential for identifying potentially abnormal physiological conditions. However, conventional patient monitoring systems can be expensive, less portable, and may lack accessible real-time remote monitoring features. In situations where continuous observation is difficult, abnormal readings may go unnoticed. There is a need for an affordable, portable, and integrated system capable of monitoring multiple health parameters and generating timely alerts.\r\n\r\n**Proposed Solution:**\r\n\r\nSMARTCARE is an ESP32-based IoT patient monitoring and intelligent emergency alert system designed to measure heart rate (BPM), blood oxygen saturation (SpO₂), ECG signals, and temperature in real time.\r\n\r\nThe proposed system integrates MAX30102, AD8232, and temperature sensors with an ESP32 microcontroller. Sensor readings will be processed and transmitted via Wi-Fi to an interactive web dashboard, enabling real-time visualization of physiological parameters, ECG waveforms, and historical trends.\r\n\r\nAn intelligent alert mechanism will continuously evaluate sensor readings, verify signal quality, and detect persistent abnormal conditions before triggering warning or critical alerts through a buzzer and dashboard notifications. The system will also feature an OLED display, historical data logging, and portable battery-powered operation.\r\n\r\n**Innovation Details:**\r\n\r\nSMARTCARE combines biomedical sensing, IoT connectivity, and intelligent alert mechanisms into a single affordable and portable monitoring prototype.\r\n\r\nIts key innovative features include:\r\n\r\n1. **Multi-Parameter Monitoring:** Integration of ECG, heart rate, SpO₂, and temperature monitoring within one compact device.\r\n2. **Intelligent Emergency Alerts:** Configurable thresholds, signal-quality verification, and persistence-based detection to minimize false alarms.\r\n3. **Real-Time Web Dashboard:** Wireless monitoring with live ECG visualization, health parameter tracking, and historical data analysis.\r\n4. **Dual Display System:** Local OLED display and remote browser-based dashboard for convenient access.\r\n5. **Affordable and Portable Design:** Low-cost components, battery-powered operation, and expandable architecture for future cloud or mobile integration.\r\n\r\nSMARTCARE aims to demonstrate an accessible, cost-effective healthcare technology solution that combines real-time monitoring, intelligent alerts, and IoT-based visualization. It is intended as an educational engineering prototype, not a certified medical diagnostic device.", "workingPrinciple": "**Working Principle of SMARTCARE**\r\n\r\nSMARTCARE operates on the principle of real-time physiological data acquisition, processing, wireless transmission, and intelligent alert generation using an ESP32 microcontroller.\r\n\r\nThe system integrates multiple sensors to monitor essential health parameters. The MAX30102 sensor uses optical sensing to estimate heart rate (BPM) and blood oxygen saturation (SpO₂), while the AD8232 ECG module captures electrical signals from the heart for waveform visualization. A temperature sensor measures temperature, and the BME280 monitors environmental conditions.\r\n\r\nThe ESP32 collects sensor readings, performs basic signal filtering and processing, and calculates the required parameters. The processed data is transmitted through Wi-Fi to an interactive web dashboard, where users can view real-time measurements, ECG waveforms, historical trends, and device status. An OLED display provides local monitoring without requiring continuous access to the dashboard.\r\n\r\nThe intelligent alert mechanism compares sensor readings against configurable thresholds. To minimize false alarms, the system verifies signal quality and checks whether abnormal readings persist before generating warning or critical alerts through a buzzer and dashboard notifications.\r\n\r\nAdditionally, the system supports data logging for future analysis and operates using a portable battery-powered design.\r\n\r\nSMARTCARE is designed as an affordable educational prototype demonstrating the integration of biomedical sensors, IoT technology, and automated monitoring. It is not intended for clinical diagnosis or as a replacement for certified medical equipment.", "majorHardwareComponents": ["**Major Hardware Components of SMARTCARE**\n\n1. **ESP32 Development Board:** Acts as the central microcontroller", "responsible for sensor data acquisition", "signal processing", "Wi-Fi communication", "and system control.\n\n2. **AD8232 ECG Sensor:** Captures the heart's electrical signals for real-time ECG waveform visualization.\n\n3. **MAX30102 Pulse Oximeter Sensor:** Measures heart rate (BPM) and estimates blood oxygen saturation (SpO₂) using optical sensing technology.\n\n4. **ADS1115 ADC Module:** Provides higher-resolution analog-to-digital conversion for improved ECG signal acquisition.\n\n5. **NTC Temperature Sensor (10K):** Used for temperature measurement within the monitoring system.\n\n6. **BME280 Environmental Sensor:** Measures surrounding temperature and humidity to monitor environmental conditions.\n\n7. **0.96-inch OLED Display:** Displays essential health parameters and device status locally.\n\n8. **Buzzer", "LEDs", "and Push Buttons:** Provide audible and visual alerts along with basic system controls.\n\n9. **Rechargeable Battery and TP4056 Charging Module:** Enable portable operation and battery charging.\n\n10. **Breadboard/PCB", "Connecting Wires", "and Enclosure:** Support circuit assembly", "electrical connections", "and physical protection of the prototype.\n\nThese components work together to develop a compact", "affordable", "and portable IoT-based patient monitoring and intelligent alert system."], "useAi": false, "useIot": true, "powerSource": "dc_power_supply", "intendedBeneficiaries": ["Healthcare"], "potentialImpact": "**Potential Real-World Impact of SMARTCARE**\r\n\r\nSMARTCARE has the potential to make basic health monitoring more affordable, accessible, and convenient through the integration of IoT technology and biomedical sensors. By combining multiple physiological monitoring functions into a single portable device, the proposed system could reduce dependence on separate monitoring instruments for basic health parameter tracking.\r\n\r\n**1. Affordable Health Monitoring:** The low-cost design could make basic monitoring technology more accessible to individuals, small healthcare facilities, and resource-constrained communities.\r\n\r\n**2. Remote Monitoring:** Real-time transmission of heart rate, SpO₂, ECG signals, and temperature readings through a web dashboard could allow caregivers and healthcare professionals to observe physiological trends remotely.\r\n\r\n**3. Timely Alerts:** The intelligent alert mechanism could help users notice persistent abnormal readings through audible warnings and dashboard notifications, encouraging timely attention.\r\n\r\n**4. Rural Healthcare Applications:** With further development and validation, the system could support basic monitoring in rural and underserved areas where access to advanced medical equipment may be limited.\r\n\r\n**5. Educational and Research Applications:** SMARTCARE could serve as a practical platform for students and researchers exploring biomedical instrumentation, embedded systems, IoT, and real-time data processing.\r\n\r\n**6. Future Scalability:** The system could be expanded with cloud connectivity, mobile applications, and additional sensors.\r\n\r\nOverall, SMARTCARE aims to demonstrate the potential of affordable, portable, and connected healthcare technology. As an educational prototype, it would require clinical validation and appropriate safety certification before use in actual patient care.", "productPotential": "yes", "prototypeDevelopmentCost": 5000, "auraDemoHighlight": "**Why SMARTCARE Is Worth Seeing**\r\n\r\nSMARTCARE is more than just a health-monitoring prototype; it demonstrates how affordable technology can be combined with IoT and biomedical sensing to address real-world healthcare challenges.\r\n\r\nWhat makes SMARTCARE worth exploring is its integration of multiple physiological monitoring features into a single compact and portable system. Using an ESP32 microcontroller, the proposed device combines real-time ECG waveform visualization, heart rate monitoring, blood oxygen saturation (SpO₂) estimation, temperature sensing, and intelligent emergency alerts.\r\n\r\n**The key attraction is its interactive live demonstration.** Visitors will be able to explore how sensor readings are acquired, processed, and transmitted wirelessly to a web dashboard, where physiological parameters and trends can be visualized in real time.\r\n\r\nUnlike a basic monitoring setup, SMARTCARE proposes a signal-quality verification mechanism and persistence-based alert logic to reduce false alarms caused by temporary fluctuations or noisy sensor readings.\r\n\r\nWith an estimated development cost of approximately ₹5,000, the project highlights the potential of affordable and portable biomedical monitoring technology.\r\n\r\nSMARTCARE also demonstrates the practical integration of embedded systems, biomedical instrumentation, IoT connectivity, and web development. Its expandable architecture creates opportunities for future cloud integration, mobile applications, and additional sensing capabilities.\r\n\r\n**SMARTCARE is worth seeing because it transforms an important healthcare challenge into an interactive engineering demonstration, combining innovation, affordability, and meaningful real-world potential.**", "safetyHazards": ["none"], "safetyPrecautions": "**Safety Precautions Taken – SMARTCARE**\r\n\r\nSMARTCARE is designed as a low-voltage, DC-powered educational prototype with a focus on electrical safety, reliable operation, and responsible handling of biomedical sensors.\r\n\r\nThe following safety precautions are proposed:\r\n\r\n1. **Low-Voltage Operation:** The ESP32 and sensors will operate using regulated low-voltage DC power to minimize electrical hazards.\r\n\r\n2. **Electrical Isolation:** Proper electrical isolation and safe power arrangements will be ensured for ECG electrodes and patient-connected circuits. ECG testing will only be conducted under appropriate supervision after safety verification.\r\n\r\n3. **Battery Protection:** A suitable rechargeable battery and charging module will be used with appropriate protection against overcharging, overheating, and short circuits.\r\n\r\n4. **Secure Wiring:** All electrical connections will be properly insulated, and components will be securely mounted inside a protective enclosure to prevent accidental contact and short circuits.\r\n\r\n5. **Sensor Safety:** Sensors will be handled carefully, and their operating voltages and connections will be verified before testing.\r\n\r\n6. **Reliable Alert Mechanism:** Signal-quality verification and persistence-based threshold checking will help minimize false alerts caused by noisy or temporary readings.\r\n\r\n7. **Supervised Testing:** Initial testing will be performed using simulated signals wherever possible, followed by supervised testing under appropriate safety conditions.\r\n\r\n8. **Non-Clinical Use:** SMARTCARE will be used strictly for educational demonstrations and will not be presented as a certified medical device or used for clinical diagnosis.\r\n\r\nThese precautions aim to ensure safe development, testing, and demonstration of the proposed system.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T11:59:52.43Z", "updatedAt": "2026-10-26T12:01:52.58Z", "abstract": { "originalName": "SMARTCARE_One_Page_Abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793015991/aura-registrations/abstract-docs/SMARTCARE_One_Page_Abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Team BioNexus/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Team BioNexus/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793015991/aura-registrations/id-cards/lpogq4cpk37mghws1yrw.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Team BioNexus/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793015991/aura-registrations/id-cards/qg1bke1nmg9mm1vyeaxy.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Team BioNexus/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793015991/aura-registrations/id-cards/nzuikbftruzodcdgiyby.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Team BioNexus/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793015991/aura-registrations/id-cards/y30wto5byj72mh0ybqgi.jpg", "exists": true }] }, { "index": 60, "id": "6adf5994223df45ca516fdc6", "registrationId": "AURA2K26-9QLGUF", "rawTeamName": "AeroForge", "folderName": "AeroForge", "folderRelPath": "assets/Teams/AeroForge", "projectTitle": "AeroSentinel : Active Predictive Gas Isolation Matrix", "teamSize": 4, "teamAffiliation": "all_aliah", "aliahMembers": 4, "otherInstitutionMembers": 0, "teamLeaderName": "Sankhadeep Pal", "teamLeaderEmail": "palsankhadeep3@gmail.com", "teamLeaderPhone": "9903980715", "teamMemberDetails": "Ayushi De | Aliah University | MEN | 1st yr | 9330253146\r\nNarmada Raut | Aliah University | CEN | 1st year | 9749606492\r\nJisanalfaed Anjum Alvi | Aliah University | CSE | 2nd year | 6295653139", "hardwareProjectCategories": ["Embedded Systems", "IoT & Smart Devices", "Electrical Systems", "Assistive Technology", "Safety & Security Systems"], "prototypeType": "Embedded System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "Problem Statement : Gas leaks and combustible hazards in homes and industrial facilities can cause fires, explosions, and toxic exposure. Conventional gas detectors primarily rely on fixed concentration thresholds and alarms, leaving subsequent intervention dependent on human reaction. Their limited sampling coverage can also overlook uneven gas distribution caused by gas density, buoyancy, and airflow.\r\n\r\nHardware Solution : AeroSentinel is an active gas-safety system combining multi-level air sampling, sensor fusion, predictive processing, and automated mitigation. A 5V micro air pump and custom dual-level aspiration manifold draw air from near the floor and ceiling into a shared sensing chamber. An MQ-2 sensor monitors combustible-gas and smoke-related signatures, while an MQ-135 provides broader gas-response information, supported by a BME280 for environmental measurements. An Arduino UNO processes sensor readings and evaluates concentration trends to identify developing threats. When the threat criteria are met, a relay matrix can activate a connected exhaust fan and isolate the gas supply through a compatible solenoid valve. An ESP8266 gateway transmits telemetry through MQTT to a web dashboard.\r\n\r\nHardware Innovation : AeroSentinel integrates active air sampling, trend-based hazard assessment, and dual-actuation mitigation within a modular, cost-conscious architecture. Unlike alarm-only approaches, it is designed to initiate physical intervention automatically. Its local processing keeps core response logic independent of internet connectivity, while MQTT-based telemetry supports remote monitoring and future multi-node expansion.", "solutionDescription": "Problem Statement : Gas leaks and combustible hazards in homes and industrial facilities can cause fires, explosions, and toxic exposure. Conventional gas detectors primarily rely on fixed concentration thresholds and alarms, leaving subsequent intervention dependent on human reaction. Their limited sampling coverage can also overlook uneven gas distribution caused by gas density, buoyancy, and airflow.\r\n\r\nHardware Solution : AeroSentinel is an active gas-safety system combining multi-level air sampling, sensor fusion, predictive processing, and automated mitigation. A 5V micro air pump and custom dual-level aspiration manifold draw air from near the floor and ceiling into a shared sensing chamber. An MQ-2 sensor monitors combustible-gas and smoke-related signatures, while an MQ-135 provides broader gas-response information, supported by a BME280 for environmental measurements. An Arduino UNO processes sensor readings and evaluates concentration trends to identify developing threats. When the threat criteria are met, a relay matrix can activate a connected exhaust fan and isolate the gas supply through a compatible solenoid valve. An ESP8266 gateway transmits telemetry through MQTT to a web dashboard.\r\n\r\nHardware Innovation : AeroSentinel integrates active air sampling, trend-based hazard assessment, and dual-actuation mitigation within a modular, cost-conscious architecture. Unlike alarm-only approaches, it is designed to initiate physical intervention automatically. Its local processing keeps core response logic independent of internet connectivity, while MQTT-based telemetry supports remote monitoring and future multi-node expansion.", "innovationDescription": "Problem Statement : Gas leaks and combustible hazards in homes and industrial facilities can cause fires, explosions, and toxic exposure. Conventional gas detectors primarily rely on fixed concentration thresholds and alarms, leaving subsequent intervention dependent on human reaction. Their limited sampling coverage can also overlook uneven gas distribution caused by gas density, buoyancy, and airflow.\r\n\r\nHardware Solution : AeroSentinel is an active gas-safety system combining multi-level air sampling, sensor fusion, predictive processing, and automated mitigation. A 5V micro air pump and custom dual-level aspiration manifold draw air from near the floor and ceiling into a shared sensing chamber. An MQ-2 sensor monitors combustible-gas and smoke-related signatures, while an MQ-135 provides broader gas-response information, supported by a BME280 for environmental measurements. An Arduino UNO processes sensor readings and evaluates concentration trends to identify developing threats. When the threat criteria are met, a relay matrix can activate a connected exhaust fan and isolate the gas supply through a compatible solenoid valve. An ESP8266 gateway transmits telemetry through MQTT to a web dashboard.\r\n\r\nHardware Innovation : AeroSentinel integrates active air sampling, trend-based hazard assessment, and dual-actuation mitigation within a modular, cost-conscious architecture. Unlike alarm-only approaches, it is designed to initiate physical intervention automatically. Its local processing keeps core response logic independent of internet connectivity, while MQTT-based telemetry supports remote monitoring and future multi-node expansion.", "workingPrinciple": "AeroSentinel operates through a continuous workflow of air aspiration, sensor measurement, predictive analysis, autonomous actuation, and remote monitoring.\r\n\r\n1. Active Air Sampling: A 5V micro air pump draws air from near the floor and ceiling through a dual-intake aspiration manifold, directing the samples into a shared sensing chamber.\r\n\r\n2. Sensor Fusion: The MQ-2 detects combustible-gas and smoke-related responses, while the MQ-135 provides broader gas-response measurements. The BME280 supplies environmental measurements to support contextual interpretation. The Arduino UNO processes these sensor readings continuously.\r\n\r\n3. Predictive Threat Assessment: The controller evaluates gas-concentration changes over time rather than relying exclusively on a fixed threshold. Its trend-based processing identifies sustained increases that satisfy the programmed hazard criteria, enabling intervention when a developing threat is detected.\r\n\r\n4. Dual-Actuation Response: When the trigger conditions are met, the Arduino activates a relay matrix to control connected mitigation hardware. One channel can activate an exhaust fan to purge contaminated air, while another controls a compatible normally closed solenoid valve to isolate the gas supply. A manual override preserves operator control.\r\n\r\n5. Edge Telemetry: The ESP8266 gateway receives system data from the Arduino over a serial connection and publishes telemetry using MQTT to a web dashboard for remote monitoring. This communication pathway is separate from the core local safety logic, allowing essential detection and response functions to operate without internet connectivity.\r\n\r\nThis workflow combines continuous monitoring with automated physical intervention to address developing gas hazards.", "majorHardwareComponents": ["Arduino UNO R3 compatible board", "ESP8266", "MQ-2 gas sensor", "MQ-135 gas sensor", "BME280 sensor", "5V micro air pump", "2-channel relay module", "AMS1117-3.3V Regulator", "0.96\" OLED Display", "5V DC power adapter"], "useAi": false, "useIot": true, "powerSource": "ac_supply", "intendedBeneficiaries": ["General Public", "Industry"], "potentialImpact": "AeroSentinel is designed to benefit households, commercial kitchens, small factories, laboratories, and industrial facilities where gas leaks and combustible hazards threaten human life and property.\r\n\r\nConventional gas detectors often serve primarily as warning systems, requiring people or separate control systems to respond after an alarm. AeroSentinel aims to improve this approach by combining dual-level air sampling with trend-based hazard assessment and automatic physical intervention. Sampling air from near the floor and ceiling helps address uneven gas distribution, while continuous analysis of sensor readings supports the identification of sustained increases that may indicate a developing threat.\r\n\r\nIts dual-actuation architecture can activate a connected exhaust fan and trigger gas-source isolation through a compatible solenoid valve. This approach aims to reduce dependence on human reaction time and provide an additional layer of protection beyond alarm-only detection.\r\n\r\nAeroSentinel also prioritizes operational resilience. Its Arduino-based local processing supports core detection and response without dependence on internet connectivity. Meanwhile, the ESP8266 gateway, MQTT communication, and web dashboard enable remote monitoring and provide a foundation for supervising multiple sentinel nodes across larger facilities.\r\n\r\nBy combining accessible microcontrollers, modular hardware, automated mitigation, and scalable telemetry, AeroSentinel aims to make proactive gas-safety capabilities more accessible to smaller establishments as well as industrial users. Following rigorous testing, calibration, and appropriate safety certification, it could complement existing safety systems and contribute to more responsive and resilient gas-hazard management.", "productPotential": "yes", "prototypeDevelopmentCost": 1900, "auraDemoHighlight": "AeroSentinel stands out because it aims to do more than detect danger—it is designed to act on it.\r\n\r\nIts most distinctive feature is a custom dual-level aspiration manifold that actively draws air from near both the floor and ceiling into a shared sensing chamber. Combined with sensor fusion and Arduino-based trend analysis, this approach addresses uneven gas distribution and enables the system to identify sustained rising gas concentrations rather than relying exclusively on fixed thresholds.\r\n\r\nWhat makes the project particularly compelling is its dual-actuation response. When programmed hazard criteria are met, the system can activate an exhaust fan while simultaneously initiating gas-source isolation through a compatible solenoid valve. This transforms the prototype from a conventional alarm concept into an integrated detection-and-mitigation system.\r\n\r\nAeroSentinel also demonstrates how accessible embedded hardware can support a more advanced safety architecture. An Arduino UNO handles local sensing and response, while an ESP8266 gateway uses MQTT to transmit telemetry to a web dashboard. Importantly, the core safety logic is designed to operate independently of internet connectivity.\r\n\r\nJudges and visitors can explore how fluid dynamics, sensor integration, embedded processing, relay-controlled hardware, and networked monitoring work together in a single modular platform.\r\n\r\nAeroSentinel's defining idea is simple: detect a developing hazard, evaluate its progression, and initiate a physical response. By bringing these functions together in a cost-conscious design, the project presents an engaging, practical approach to making proactive gas-safety technology more accessible.", "safetyHazards": ["chemicals"], "safetyPrecautions": "Butane used during demonstrations will be treated as a flammable hazard. Gas-sensing demonstrations will preferably use simulated inputs to avoid releasing combustible gas near powered electronics. The sensor chamber and aspiration manifold will be assessed for ignition risks.\r\n\r\nAppropriately rated electrical protection will address short circuits and overcurrent conditions, while manual override and emergency isolation controls will remain accessible. The system will be designed to detect missing or faulty actuators where supported and enter an appropriate safe state. Sensor faults, power interruptions, and communication failures will be assessed before demonstrations.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T13:45:56.702Z", "updatedAt": "2026-10-26T13:47:56.788Z", "abstract": { "originalName": "Team_AeroForge_abstract.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793022355/aura-registrations/abstract-docs/Team_AeroForge_abstract.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/AeroForge/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/AeroForge/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793022355/aura-registrations/id-cards/dkn8lwlsx2ir4rhptusg.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/AeroForge/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793022355/aura-registrations/id-cards/ozv8ubioqa9lxgnwdfci.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/AeroForge/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793022355/aura-registrations/id-cards/dh7jn7bqdbjsdmdpqz3v.jpg", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/AeroForge/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793022355/aura-registrations/id-cards/a0avhtvv8igk2xjuqdap.jpg", "exists": true }] }, { "index": 61, "id": "6adf5e6494d7a27d25941e0d", "registrationId": "AURA2K26-MDE593", "rawTeamName": "Team Aspire", "folderName": "Team Aspire", "folderRelPath": "assets/Teams/Team Aspire", "projectTitle": "FloodGrid", "teamSize": 2, "teamAffiliation": "mixed", "aliahMembers": 1, "otherInstitutionMembers": 1, "teamLeaderName": "Sourik Seikh", "teamLeaderEmail": "souriksk@gmail.com", "teamLeaderPhone": "7892702345", "teamMemberDetails": "Name - INzamam UL Huda \r\nInstitution - IEM(Salt Lake)\r\nDepartment- IT\r\nYear-1st\r\nPhone -9046100657", "hardwareProjectCategories": ["IoT & Smart Devices"], "prototypeType": "Hardware + Software System", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Fully functional and ready for live demonstration", "problemStatement": "1. Problem Statement\r\n\r\nUrban waterlogging is a recurring problem, particularly during heavy rainfall and monsoon seasons. Blocked or overloaded drainage systems can cause road flooding, traffic congestion, property damage, and safety risks. In many areas, drain conditions are monitored through periodic manual inspections, which may not provide timely information about rapidly rising water levels. The absence of continuous, accessible monitoring makes it difficult to identify critical locations early and prioritize maintenance. There is a need for an affordable, scalable, and technology-driven solution that improves awareness of drainage conditions and supports timely preventive action.\r\n\r\n2. Proposed Solution\r\n\r\nFloodGrid is an IoT-based smart drainage monitoring system designed to monitor water levels at multiple locations through interconnected Arduino UNO R4 WiFi nodes. Each node uses an HC-SR04 ultrasonic sensor to measure the distance to the water surface and estimate the water depth and percentage of the monitored drain's capacity occupied by water. An OLED display provides local readings, while Wi-Fi communication enables the nodes to share information over a common network.\r\n\r\nOne Arduino acts as the master node, collecting readings from the second node and displaying the combined information on a centralized web dashboard. The dashboard presents water-level measurements, node connectivity, and warnings when readings exceed predefined thresholds. This allows users to identify locations that may require inspection or preventive maintenance. The prototype is designed for future expansion to additional monitoring nodes and advanced data-management features.\r\n\r\n3. Innovation Details\r\n\r\nFloodGrid integrates low-cost ultrasonic sensing, embedded computing, wireless communication, and centralized visualization into a modular monitoring system. Its key innovation is the ability to observe multiple drainage locations through one interface rather than relying solely on isolated measurements or manual inspections.\r\n\r\nThe system provides contactless water-level measurement, local visual feedback, and centralized monitoring using readily available hardware. Its modular architecture supports future enhancements such as historical data logging, cloud connectivity, rainfall integration, remote notifications, and analysis of recurring high-water conditions.\r\n\r\nFloodGrid aims to make drainage monitoring more accessible and proactive by transforming water-level measurements into actionable information. While the prototype does not independently confirm blockages or prevent flooding, it demonstrates a practical foundation for smarter urban drainage management and improved flood-risk awareness.", "solutionDescription": "1. Problem Statement\r\n\r\nUrban waterlogging is a recurring problem, particularly during heavy rainfall and monsoon seasons. Blocked or overloaded drainage systems can cause road flooding, traffic congestion, property damage, and safety risks. In many areas, drain conditions are monitored through periodic manual inspections, which may not provide timely information about rapidly rising water levels. The absence of continuous, accessible monitoring makes it difficult to identify critical locations early and prioritize maintenance. There is a need for an affordable, scalable, and technology-driven solution that improves awareness of drainage conditions and supports timely preventive action.\r\n\r\n2. Proposed Solution\r\n\r\nFloodGrid is an IoT-based smart drainage monitoring system designed to monitor water levels at multiple locations through interconnected Arduino UNO R4 WiFi nodes. Each node uses an HC-SR04 ultrasonic sensor to measure the distance to the water surface and estimate the water depth and percentage of the monitored drain's capacity occupied by water. An OLED display provides local readings, while Wi-Fi communication enables the nodes to share information over a common network.\r\n\r\nOne Arduino acts as the master node, collecting readings from the second node and displaying the combined information on a centralized web dashboard. The dashboard presents water-level measurements, node connectivity, and warnings when readings exceed predefined thresholds. This allows users to identify locations that may require inspection or preventive maintenance. The prototype is designed for future expansion to additional monitoring nodes and advanced data-management features.\r\n\r\n3. Innovation Details\r\n\r\nFloodGrid integrates low-cost ultrasonic sensing, embedded computing, wireless communication, and centralized visualization into a modular monitoring system. Its key innovation is the ability to observe multiple drainage locations through one interface rather than relying solely on isolated measurements or manual inspections.\r\n\r\nThe system provides contactless water-level measurement, local visual feedback, and centralized monitoring using readily available hardware. Its modular architecture supports future enhancements such as historical data logging, cloud connectivity, rainfall integration, remote notifications, and analysis of recurring high-water conditions.\r\n\r\nFloodGrid aims to make drainage monitoring more accessible and proactive by transforming water-level measurements into actionable information. While the prototype does not independently confirm blockages or prevent flooding, it demonstrates a practical foundation for smarter urban drainage management and improved flood-risk awareness.", "innovationDescription": "1. Problem Statement\r\n\r\nUrban waterlogging is a recurring problem, particularly during heavy rainfall and monsoon seasons. Blocked or overloaded drainage systems can cause road flooding, traffic congestion, property damage, and safety risks. In many areas, drain conditions are monitored through periodic manual inspections, which may not provide timely information about rapidly rising water levels. The absence of continuous, accessible monitoring makes it difficult to identify critical locations early and prioritize maintenance. There is a need for an affordable, scalable, and technology-driven solution that improves awareness of drainage conditions and supports timely preventive action.\r\n\r\n2. Proposed Solution\r\n\r\nFloodGrid is an IoT-based smart drainage monitoring system designed to monitor water levels at multiple locations through interconnected Arduino UNO R4 WiFi nodes. Each node uses an HC-SR04 ultrasonic sensor to measure the distance to the water surface and estimate the water depth and percentage of the monitored drain's capacity occupied by water. An OLED display provides local readings, while Wi-Fi communication enables the nodes to share information over a common network.\r\n\r\nOne Arduino acts as the master node, collecting readings from the second node and displaying the combined information on a centralized web dashboard. The dashboard presents water-level measurements, node connectivity, and warnings when readings exceed predefined thresholds. This allows users to identify locations that may require inspection or preventive maintenance. The prototype is designed for future expansion to additional monitoring nodes and advanced data-management features.\r\n\r\n3. Innovation Details\r\n\r\nFloodGrid integrates low-cost ultrasonic sensing, embedded computing, wireless communication, and centralized visualization into a modular monitoring system. Its key innovation is the ability to observe multiple drainage locations through one interface rather than relying solely on isolated measurements or manual inspections.\r\n\r\nThe system provides contactless water-level measurement, local visual feedback, and centralized monitoring using readily available hardware. Its modular architecture supports future enhancements such as historical data logging, cloud connectivity, rainfall integration, remote notifications, and analysis of recurring high-water conditions.\r\n\r\nFloodGrid aims to make drainage monitoring more accessible and proactive by transforming water-level measurements into actionable information. While the prototype does not independently confirm blockages or prevent flooding, it demonstrates a practical foundation for smarter urban drainage management and improved flood-risk awareness.", "workingPrinciple": "FloodGrid is an IoT-based smart drainage monitoring system designed to monitor water levels at multiple drain locations and provide early warnings of potential waterlogging.\r\n\r\nEach monitoring node uses an HC-SR04 ultrasonic sensor to measure the distance between the sensor and the water surface. An Arduino UNO R4 WiFi processes the measurements to calculate the estimated water depth and percentage of drain capacity occupied by water, based on the predefined dimensions of the monitoring setup.\r\n\r\nThe readings are displayed locally on a 128×64 OLED screen. Using built-in Wi-Fi connectivity, the monitoring nodes communicate over a shared wireless network. One Arduino acts as the master node, hosting a centralized web dashboard and collecting readings from the second node.\r\n\r\nThe dashboard displays water levels, estimated fill percentages, node connectivity status, and high-water warnings in a single interface. When the water level exceeds a predefined threshold, the system indicates a potential high-water condition, enabling users to identify locations requiring inspection or preventive action.\r\n\r\nFloodGrid features a modular design that can be expanded by adding more monitoring nodes. The system aims to provide affordable, real-time drainage monitoring and centralized observation, helping users respond more quickly to rising water levels and potential urban waterlogging. Future improvements may include historical data logging, cloud integration, and remote notifications for wider deployment.", "majorHardwareComponents": ["1. Arduino UNO R4 WiFi: The main microcontroller responsible for processing sensor readings", "calculating water levels", "managing wireless communication", "and hosting the central dashboard.\n\n2. HC-SR04 Ultrasonic Sensor: Measures the distance between the sensor and the water surface without direct contact", "enabling estimation of water depth and drain fill percentage.\n\n3. 128×64 I²C OLED Display: Displays real-time water-level measurements", "system status", "and warnings locally at each monitoring node.\n\n4. Wi-Fi Connectivity: The built-in Wi-Fi capability of the Arduino UNO R4 WiFi enables communication between monitoring nodes and the centralized dashboard over a shared wireless network.\n\n5. Power Supply: A suitable regulated power source supplies power to the microcontroller", "sensor", "and display for continuous operation.\n\n6. Breadboard and Jumper Wires: Used for circuit assembly", "electrical connections", "and testing during prototype development.\n\n7. Drain Simulation Setup: A container or model drain is used to simulate changing water levels and test the monitoring system under controlled conditions.\n\nFloodGrid initially uses two Arduino UNO R4 WiFi boards", "each paired with an ultrasonic sensor and an OLED display. One board functions as the master node", "collecting measurements from the second node and presenting the combined information through a centralized web dashboard. The modular hardware architecture allows additional monitoring nodes to be incorporated in future versions."], "useAi": true, "useIot": true, "powerSource": "usb", "intendedBeneficiaries": ["Industry", "General Public"], "potentialImpact": "FloodGrid aims to improve urban drainage management through real-time water-level monitoring and early warnings of potential waterlogging. During heavy rainfall and monsoon seasons, rising water levels in drains can contribute to road flooding, traffic disruption, property damage, and public safety risks.\r\n\r\nBy deploying IoT-enabled monitoring nodes at multiple drainage locations, FloodGrid can help authorities identify areas experiencing unusually high water levels through a centralized web dashboard. Timely information can support faster inspections, drain cleaning, and preventive measures before conditions worsen.\r\n\r\nThe system is designed to be affordable, modular, and scalable, making it suitable for demonstration in residential areas, educational campuses, local drainage networks, and other urban environments. Its wireless communication capabilities reduce the need for continuous manual observation at every monitored location.\r\n\r\nFloodGrid can also serve as a foundation for future smart-city applications by incorporating historical data logging, rainfall sensors, cloud connectivity, and remote notifications. These enhancements could help identify recurring waterlogging hotspots, improve maintenance planning, and support data-driven decisions in urban infrastructure management.\r\n\r\nThe primary potential impact of FloodGrid is to improve awareness of rising drain water levels, encourage timely intervention, and contribute to safer, more resilient urban communities. Although the prototype does not directly prevent flooding or confirm drain blockages, it demonstrates how accessible IoT technology can support more proactive drainage monitoring and flood-risk management.", "productPotential": "potentially", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "FloodGrid is an innovative IoT-based smart drainage monitoring system designed to address the real-world problem of urban waterlogging. It demonstrates how affordable electronics and wireless technology can be used to improve drainage monitoring and support early warnings during heavy rainfall.\r\n\r\nWhat makes FloodGrid worth seeing is its ability to monitor multiple drain locations through interconnected Arduino UNO R4 WiFi nodes and display their water-level readings on a single centralized web dashboard. Using ultrasonic sensors, the system measures water levels without direct contact with the water and identifies when readings exceed predefined thresholds.\r\n\r\nThe project combines embedded systems, IoT communication, sensor technology, and web-based visualization in a practical, interactive prototype. Visitors can observe changing sensor readings, compare water levels across monitoring nodes, and see how high-water warnings are generated in real time.\r\n\r\nFloodGrid is designed to be affordable, modular, and scalable, offering potential applications in residential communities, educational campuses, and urban drainage networks. Its architecture can be extended with cloud-based data logging, remote notifications, and additional monitoring locations.\r\n\r\nUnlike a purely theoretical concept, FloodGrid demonstrates a practical approach to making drainage conditions more visible and supporting timely inspections and preventive action. By connecting physical infrastructure with digital monitoring, the project highlights how accessible IoT technology can contribute to smarter cities and more resilient communities.\r\n\r\nFloodGrid represents a step toward proactive drainage management, where timely information can help people respond more effectively to rising water levels and potential waterlogging.", "safetyHazards": ["none"], "safetyPrecautions": "FloodGrid is designed with basic electrical and operational safety measures to ensure safe testing and demonstration.\r\n\r\n1. Low-Voltage Operation: The prototype operates using a 5V USB power supply, reducing electrical hazards during normal operation.\r\n\r\n2. Secure Electrical Connections: All components, including the Arduino UNO R4 WiFi, ultrasonic sensors, and OLED displays, are connected carefully to prevent short circuits, loose connections, and accidental damage.\r\n\r\n3. Water-Electronics Separation: The electronic components are positioned away from the water container to minimize the risk of water splashes reaching the circuitry. Protective enclosures can be used for additional safety.\r\n\r\n4. Sensor Placement: The ultrasonic sensors are mounted securely above the simulated water surface to prevent direct contact with water and ensure stable measurements.\r\n\r\n5. Power Isolation During Maintenance: The power supply is disconnected before changing wiring, adjusting connections, or troubleshooting hardware.\r\n\r\n6. Controlled Testing Environment: Initial testing is conducted using a small, controlled drain model rather than an actual drainage system, reducing exposure to contaminated water and other environmental hazards.\r\n\r\n7. Wireless Communication Safety: The system uses Wi-Fi for data communication, avoiding the need for long signal cables between monitoring nodes.\r\n\r\n8. Regular Inspection: Wiring, power connections, sensor mounting, and component temperatures are checked during operation to identify potential faults.\r\n\r\nThese precautions help improve the safety and reliability of the FloodGrid prototype. Before deployment in real drainage environments, additional measures such as waterproof enclosures, corrosion protection, and appropriate electrical isolation would be required.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T14:06:28.054Z", "updatedAt": "2026-10-26T14:08:28.201Z", "abstract": { "originalName": "FloodGrid_Abstract_Idea.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793023587/aura-registrations/abstract-docs/FloodGrid_Abstract_Idea.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Team Aspire/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Team Aspire/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793023587/aura-registrations/id-cards/frlk3axdphocvdlfdalw.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Team Aspire/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793023587/aura-registrations/id-cards/egoz65wjyhgi5uc20eoo.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Team Aspire/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Team Aspire/4.jpg", "url": null, "exists": false }] }, { "index": 62, "id": "6adf9adb24a8ca63ab856157", "registrationId": "AURA2K26-4VTD78", "rawTeamName": "SafeHer Innovators", "folderName": "SafeHer Innovators", "folderRelPath": "assets/Teams/SafeHer Innovators", "projectTitle": "Smart Women Safety Wearable: A Low-Cost Emergency Alert and Location Tracking System", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "ABU RAIHAN BISWAS", "teamLeaderEmail": "aburaihanbiswas2@gmail.com", "teamLeaderPhone": "9093647489", "teamMemberDetails": "SARAF AL HAQUE | ALIAH UNIVERSITY | ECE | 2025- 2029 | 8145215731", "hardwareProjectCategories": ["IoT & Smart Devices", "Electronics & Communication", "Embedded Systems", "Safety & Security Systems"], "prototypeType": "Wearable Device", "hasWorkingPrototype": "fully_working", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Women’s safety remains a major concern, especially in situations where a person cannot easily access a mobile phone or call for help. Conventional safety solutions often depend on manually using a phone or pressing an emergency button, which may not always be convenient during an emergency.\r\n\r\nOur proposed project, Smart Women Safety Wearable, is a compact, low-cost hardware device designed to provide quick emergency assistance through a wearable form such as a bracelet, pendant, or keychain. The system will use a microcontroller, an SOS button, an inertial measurement unit (IMU), and a GPS module. A GSM module or suitable communication interface will be used to send emergency alerts to predefined contacts.\r\n\r\nThe user can activate Silent SOS by pressing and holding the emergency button. The device will attempt to capture the user’s location and send an alert containing a map link. The IMU will be explored for detecting sudden falls or abnormal movement patterns. A short cancellation window will help reduce false alerts before an automatically triggered emergency notification is sent.\r\n\r\nThe proposed system aims to provide an affordable, portable, and easy-to-use alternative to smartphone-dependent safety solutions. Its key innovation is the integration of manual silent emergency activation, location sharing, and experimental movement-based detection in a single wearable device. The prototype will be evaluated through controlled demonstrations of SOS activation, location reporting, communication reliability, and false-trigger handling. Future improvements may include secure evidence logging and a monitoring dashboard.", "solutionDescription": "Women’s safety remains a major concern, especially in situations where a person cannot easily access a mobile phone or call for help. Conventional safety solutions often depend on manually using a phone or pressing an emergency button, which may not always be convenient during an emergency.\r\n\r\nOur proposed project, Smart Women Safety Wearable, is a compact, low-cost hardware device designed to provide quick emergency assistance through a wearable form such as a bracelet, pendant, or keychain. The system will use a microcontroller, an SOS button, an inertial measurement unit (IMU), and a GPS module. A GSM module or suitable communication interface will be used to send emergency alerts to predefined contacts.\r\n\r\nThe user can activate Silent SOS by pressing and holding the emergency button. The device will attempt to capture the user’s location and send an alert containing a map link. The IMU will be explored for detecting sudden falls or abnormal movement patterns. A short cancellation window will help reduce false alerts before an automatically triggered emergency notification is sent.\r\n\r\nThe proposed system aims to provide an affordable, portable, and easy-to-use alternative to smartphone-dependent safety solutions. Its key innovation is the integration of manual silent emergency activation, location sharing, and experimental movement-based detection in a single wearable device. The prototype will be evaluated through controlled demonstrations of SOS activation, location reporting, communication reliability, and false-trigger handling. Future improvements may include secure evidence logging and a monitoring dashboard.", "innovationDescription": "Women’s safety remains a major concern, especially in situations where a person cannot easily access a mobile phone or call for help. Conventional safety solutions often depend on manually using a phone or pressing an emergency button, which may not always be convenient during an emergency.\r\n\r\nOur proposed project, Smart Women Safety Wearable, is a compact, low-cost hardware device designed to provide quick emergency assistance through a wearable form such as a bracelet, pendant, or keychain. The system will use a microcontroller, an SOS button, an inertial measurement unit (IMU), and a GPS module. A GSM module or suitable communication interface will be used to send emergency alerts to predefined contacts.\r\n\r\nThe user can activate Silent SOS by pressing and holding the emergency button. The device will attempt to capture the user’s location and send an alert containing a map link. The IMU will be explored for detecting sudden falls or abnormal movement patterns. A short cancellation window will help reduce false alerts before an automatically triggered emergency notification is sent.\r\n\r\nThe proposed system aims to provide an affordable, portable, and easy-to-use alternative to smartphone-dependent safety solutions. Its key innovation is the integration of manual silent emergency activation, location sharing, and experimental movement-based detection in a single wearable device. The prototype will be evaluated through controlled demonstrations of SOS activation, location reporting, communication reliability, and false-trigger handling. Future improvements may include secure evidence logging and a monitoring dashboard.", "workingPrinciple": "The system is designed as a compact, battery-powered women’s safety wearable. When the user presses and holds the SOS button, the microcontroller activates Silent SOS mode. The GPS module obtains the user's location, when a valid GPS fix is available. A GSM communication module then sends an emergency SMS containing the alert and location information to predefined emergency contacts. An IMU sensor can be used to monitor sudden falls or unusual movement patterns as possible emergency indicators. A short cancellation window is proposed to help prevent false alerts. The system is designed to use affordable, modular electronic components instead of expensive AI computing hardware. Its performance will depend on GPS availability, network coverage, and component integration.", "majorHardwareComponents": ["ESP32 or a suitable microcontroller", "SOS push-button", "MPU6050 IMU sensor", "GPS module", "GSM module (such as SIM800L", "subject to network compatibility)", "rechargeable battery", "voltage regulator and charging circuit", "connecting wires", "and a compact enclosure. The final component selection will depend on cost", "power requirements", "and prototype testing."], "useAi": false, "useIot": false, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Government / Public Services"], "potentialImpact": "The device is intended to help women and other vulnerable users quickly notify trusted contacts during an emergency without needing to unlock a smartphone. Silent SOS activation can be useful when making a phone call or raising a loud alarm is difficult. Location sharing can help contacts identify the user's approximate position when GPS and mobile networks are available. The proposed movement-sensing feature may provide an additional way to identify possible emergencies, subject to testing. The project focuses on affordability, portability, ease of use, and modular design. It is intended to complement existing safety measures and cannot guarantee rescue or prevent every emergency.", "productPotential": "yes", "prototypeDevelopmentCost": 2500, "auraDemoHighlight": "Aura combines discreet SOS activation, GPS-based location sharing, and a proposed motion-sensing feature in a compact wearable concept. Instead of depending only on a smartphone application or a loud alarm, the device aims to provide a simple hardware-based emergency alert system. Its modular architecture allows the team to start with essential functions and add improvements later without relying on expensive AI hardware. The most important demonstration will be the complete sequence from SOS activation to location retrieval and emergency SMS delivery. The project emphasizes practical affordability, ease of use, and responsible testing.", "safetyHazards": ["none"], "safetyPrecautions": "The prototype is designed to use low-voltage battery-powered electronics. The team will check wiring polarity, insulation, and component ratings before powering the circuit. The battery and charging circuit will be selected to match the required voltage and current ratings. Exposed conductors will be insulated, and the device will be checked for overheating or loose connections during testing. Charging will be supervised, and damaged batteries or wires will not be used. Initial tests will be conducted in a controlled environment before any wearable demonstration.", "requiresContinuousSupervision": true, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T18:24:27.726Z", "updatedAt": "2026-10-26T18:26:27.896Z", "abstract": { "originalName": "AURA2K26_Smart_Women_Safety_Wearable_Abstract_Color (1).pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039066/aura-registrations/abstract-docs/AURA2K26_Smart_Women_Safety_Wearable_Abstract_Color%20%281%29.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/SafeHer Innovators/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/SafeHer Innovators/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039066/aura-registrations/id-cards/ejdaoaud7k6k5wt7d0il.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/SafeHer Innovators/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039066/aura-registrations/id-cards/wim4wn5acd8zglcsyl11.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/SafeHer Innovators/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/SafeHer Innovators/4.jpg", "url": null, "exists": false }] }, { "index": 63, "id": "6adf9afd24a8ca63ab856158", "registrationId": "AURA2K26-HLTV4W", "rawTeamName": "Red Logic Forge", "folderName": "Red Logic Forge", "folderRelPath": "assets/Teams/Red Logic Forge", "projectTitle": "PLC-Based Digital Twin, Predictive Fault Detection Sensor and Actuator for Intelligent Industrial Automation", "teamSize": 2, "teamAffiliation": "all_aliah", "aliahMembers": 2, "otherInstitutionMembers": 0, "teamLeaderName": "Koushik Dey", "teamLeaderEmail": "deykoushik676@gmail.com", "teamLeaderPhone": "7477879205", "teamMemberDetails": "Kashifa Perween | Aliah University | Electronics and Communication Engineering | 3rd Year | 9234230766", "hardwareProjectCategories": ["Automation & Control"], "prototypeType": "IoT Device", "hasWorkingPrototype": "minor_limitations", "currentWorkingStatus": "Functional but requires minor setup/calibration", "problemStatement": "Problem Addressed\r\n\r\nIndustrial automation systems generally detect faults after a machine crosses a critical threshold or stops functioning. Problems such as motor overheating, abnormal current, excessive vibration, water leakage, and reduced flow can progressively damage equipment before conventional protection systems respond. This leads to unplanned downtime, production losses, costly maintenance, and reduced equipment life. Many existing predictive-maintenance solutions also require expensive industrial monitoring infrastructure, making them less accessible to small and medium-scale industries.\r\n\r\nHardware Solution\r\n\r\nWe propose a PLC-based Digital Twin and Predictive Fault Detection System for industrial equipment. Sensors continuously monitor critical parameters such as temperature, current, vibration, flow, and leakage. The sensor signals are processed through suitable signal-conditioning and optocoupler-based isolation circuits before being acquired by the PLC. The PLC controls the physical actuator, such as a motor or pump, and simultaneously transmits real-time operating data to a computing platform through industrial communication protocols.\r\n\r\nThe collected data is used to create a real-time Digital Twin that mirrors the operating state of the physical system. A fault-detection and prediction module analyses sensor values and their trends to identify abnormal behaviour and estimate potential failures.\r\n\r\nInnovation\r\n\r\nThe key innovation is the integration of PLC automation, real-time Digital Twin technology, sensor-based condition monitoring, and predictive fault detection into a cost-effective architecture. Unlike conventional systems that primarily provide an alarm after a fault occurs, our system attempts to identify early degradation patterns and warn the operator before a critical failure.\r\n\r\nThe Digital Twin also provides a visual representation of machine health, enabling real-time monitoring, fault simulation, and maintenance decision-making without directly interfering with the physical equipment. The proposed system is modular, scalable, and suitable for low-cost industrial retrofitting, making predictive maintenance more accessible to small and medium-scale industries while reducing downtime and improving equipment reliability.", "solutionDescription": "Problem Addressed\r\n\r\nIndustrial automation systems generally detect faults after a machine crosses a critical threshold or stops functioning. Problems such as motor overheating, abnormal current, excessive vibration, water leakage, and reduced flow can progressively damage equipment before conventional protection systems respond. This leads to unplanned downtime, production losses, costly maintenance, and reduced equipment life. Many existing predictive-maintenance solutions also require expensive industrial monitoring infrastructure, making them less accessible to small and medium-scale industries.\r\n\r\nHardware Solution\r\n\r\nWe propose a PLC-based Digital Twin and Predictive Fault Detection System for industrial equipment. Sensors continuously monitor critical parameters such as temperature, current, vibration, flow, and leakage. The sensor signals are processed through suitable signal-conditioning and optocoupler-based isolation circuits before being acquired by the PLC. The PLC controls the physical actuator, such as a motor or pump, and simultaneously transmits real-time operating data to a computing platform through industrial communication protocols.\r\n\r\nThe collected data is used to create a real-time Digital Twin that mirrors the operating state of the physical system. A fault-detection and prediction module analyses sensor values and their trends to identify abnormal behaviour and estimate potential failures.\r\n\r\nInnovation\r\n\r\nThe key innovation is the integration of PLC automation, real-time Digital Twin technology, sensor-based condition monitoring, and predictive fault detection into a cost-effective architecture. Unlike conventional systems that primarily provide an alarm after a fault occurs, our system attempts to identify early degradation patterns and warn the operator before a critical failure.\r\n\r\nThe Digital Twin also provides a visual representation of machine health, enabling real-time monitoring, fault simulation, and maintenance decision-making without directly interfering with the physical equipment. The proposed system is modular, scalable, and suitable for low-cost industrial retrofitting, making predictive maintenance more accessible to small and medium-scale industries while reducing downtime and improving equipment reliability.", "innovationDescription": "Problem Addressed\r\n\r\nIndustrial automation systems generally detect faults after a machine crosses a critical threshold or stops functioning. Problems such as motor overheating, abnormal current, excessive vibration, water leakage, and reduced flow can progressively damage equipment before conventional protection systems respond. This leads to unplanned downtime, production losses, costly maintenance, and reduced equipment life. Many existing predictive-maintenance solutions also require expensive industrial monitoring infrastructure, making them less accessible to small and medium-scale industries.\r\n\r\nHardware Solution\r\n\r\nWe propose a PLC-based Digital Twin and Predictive Fault Detection System for industrial equipment. Sensors continuously monitor critical parameters such as temperature, current, vibration, flow, and leakage. The sensor signals are processed through suitable signal-conditioning and optocoupler-based isolation circuits before being acquired by the PLC. The PLC controls the physical actuator, such as a motor or pump, and simultaneously transmits real-time operating data to a computing platform through industrial communication protocols.\r\n\r\nThe collected data is used to create a real-time Digital Twin that mirrors the operating state of the physical system. A fault-detection and prediction module analyses sensor values and their trends to identify abnormal behaviour and estimate potential failures.\r\n\r\nInnovation\r\n\r\nThe key innovation is the integration of PLC automation, real-time Digital Twin technology, sensor-based condition monitoring, and predictive fault detection into a cost-effective architecture. Unlike conventional systems that primarily provide an alarm after a fault occurs, our system attempts to identify early degradation patterns and warn the operator before a critical failure.\r\n\r\nThe Digital Twin also provides a visual representation of machine health, enabling real-time monitoring, fault simulation, and maintenance decision-making without directly interfering with the physical equipment. The proposed system is modular, scalable, and suitable for low-cost industrial retrofitting, making predictive maintenance more accessible to small and medium-scale industries while reducing downtime and improving equipment reliability.", "workingPrinciple": "The proposed system works by continuously checking the condition of an industrial machine using sensors and a PLC. Sensors such as temperature, current and vibration sensors collect information from the machine while it is running. These signals are passed through suitable signal-conditioning and optocoupler isolation circuits before being sent to the PLC.\r\n\r\nThe PLC acts as the main control unit of the system. It receives the sensor readings, processes them according to the programmed logic and controls the actuator, such as a motor. At the same time, the collected data is sent to a computer or monitoring platform through a suitable communication interface.\r\n\r\nA Digital Twin is created on the software side to represent the actual machine. It receives the same real-time data and updates its condition according to what is happening in the physical system. This allows the operator to observe the machine's condition without directly interacting with the equipment.\r\n\r\nThe system continuously compares the current sensor readings with normal operating conditions. If the values start showing an unusual pattern, the system identifies it as a possible sign of a developing fault. The fault detection module then analyses the data and provides an early warning.\r\n\r\nIf the condition becomes critical, the PLC can take a protective action, such as stopping the motor. In this way, the system combines sensors, PLC control, a Digital Twin and predictive fault detection to monitor the machine and help prevent unexpected failures.", "majorHardwareComponents": ["raspberry pi pico 2w", "opto isolator module", "5V AC Supply", "1 UPS", "current sensor", "vibration sensor", "voltage measurement sensor", "electrical power measurement sensor", "smoke sensor", "thermal measurement sensor", "analog 3 axis accelerometer", "cooling fan", "optical isolator", "electronics circuit breaker", "solid state relay", "motor driver"], "useAi": true, "useIot": true, "powerSource": "other", "intendedBeneficiaries": ["Industry"], "potentialImpact": "The proposed system can help industries identify machine problems before they develop into major failures. Instead of waiting for a motor or other equipment to stop working, the system continuously monitors its condition and provides an early warning when unusual behaviour is detected.\r\n\r\nThe Digital Twin gives the operator a virtual representation of the physical machine and displays important parameters such as temperature, current and vibration in real time. This makes it easier to understand the machine’s condition without directly interfering with the equipment.\r\n\r\nOne of the major benefits is reducing unexpected breakdowns and production downtime. Early fault detection can also help industries plan maintenance at the right time, reducing unnecessary repairs and maintenance costs.\r\n\r\nThe system can be particularly useful for small and medium-sized industries because it can be built using commonly available sensors, PLCs and computing platforms instead of expensive monitoring systems. It can also improve safety by allowing the PLC to take protective actions, such as stopping the motor when a critical condition is detected.\r\n\r\nThe proposed system is also scalable. By changing the sensors, actuator and Digital Twin model, the same concept can be adapted for motors, pumps, conveyor systems and other automated industrial equipment.\r\n\r\nOverall, the project aims to make predictive maintenance more affordable and accessible while improving machine reliability, reducing downtime and helping industries make better maintenance decisions.", "productPotential": "yes", "prototypeDevelopmentCost": 2000, "auraDemoHighlight": "The most unique aspect of our project is that it goes beyond simply detecting a fault after it occurs. It aims to identify early signs of a developing fault before the machine reaches a critical condition. By combining a PLC-controlled physical system with a real-time Digital Twin, the project creates a virtual representation of the machine that changes according to its actual operating condition.\r\n\r\nThe Digital Twin receives real-time sensor data and helps visualize important parameters such as temperature, current and vibration. The system compares this data with normal operating conditions and looks for unusual patterns. When abnormal behaviour is identified, it provides an early warning and can allow the PLC to take protective action when necessary.\r\n\r\nJudges should see this project because it combines industrial automation, sensors, PLC control, Digital Twin technology and predictive maintenance into one practical system. Unlike a conventional alarm system, the focus is on understanding machine behaviour and taking action before a major failure occurs.\r\n\r\nThe project is also designed to be low-cost, modular and scalable, so the same concept can be adapted to motors, pumps, conveyor systems and other industrial equipment.\r\n\r\nThe key idea is simple but impactful: instead of waiting for a machine to fail and then reacting, our system continuously monitors, predicts and helps prevent failure. This can reduce downtime, maintenance costs and equipment damage while making predictive maintenance more accessible to smaller industries.", "safetyHazards": ["none"], "safetyPrecautions": "During the development of the project, several safety measures are considered to protect both the users and the hardware. The prototype is designed to operate at safe, low-voltage levels wherever possible, reducing the risk of electrical shock and component damage.\r\n\r\nOptocouplers are used to provide electrical isolation between the PLC control section and field-side circuits. Properly rated relays or contactors are used to control the motor actuator instead of connecting the actuator directly to the PLC output.\r\n\r\nA regulated power supply is used to provide stable voltage to the PLC, sensors and other electronic components. Fuses or suitable circuit protection are included where required to protect the system from overcurrent and short circuits.\r\n\r\nAll electrical connections are properly insulated and secured, and exposed conductors are avoided. Components are mounted properly to prevent loose connections or accidental contact during operation. The motor and moving parts are also kept away from direct handling while the system is running.\r\n\r\nEmergency shutdown or manual isolation is provided so that the actuator can be quickly disconnected if an abnormal condition occurs. Sensor readings and PLC logic are tested first under controlled conditions before operating the complete system.\r\n\r\nThe Digital Twin and fault-detection software are also tested using simulated fault conditions where possible, reducing the need to deliberately create dangerous physical faults.\r\n\r\nThese precautions help ensure that the prototype can be tested safely while protecting the operators, electronic components and actuator.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T18:25:01.001Z", "updatedAt": "2026-10-26T18:27:01.133Z", "abstract": { "originalName": "Untitled document_261026235109.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039099/aura-registrations/abstract-docs/Untitled%20document_261026235109.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/Red Logic Forge/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/Red Logic Forge/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039099/aura-registrations/id-cards/phuiqcocqkej6wcdkala.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/Red Logic Forge/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039099/aura-registrations/id-cards/nvxtlksaojtpo547dzdi.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/Red Logic Forge/3.jpg", "url": null, "exists": false }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/Red Logic Forge/4.jpg", "url": null, "exists": false }] }, { "index": 64, "id": "6adf9c0424a8ca63ab856159", "registrationId": "AURA2K26-7TC59M", "rawTeamName": "SHOWTIME", "folderName": "SHOWTIME", "folderRelPath": "assets/Teams/SHOWTIME", "projectTitle": "HYDROBOT AI", "teamSize": 4, "teamAffiliation": "mixed", "aliahMembers": 3, "otherInstitutionMembers": 1, "teamLeaderName": "Sougata Roy", "teamLeaderEmail": "meetingwithsougata@gmail.com", "teamLeaderPhone": "9382272947", "teamMemberDetails": "DEEPAK DAS BISWAS , INSTITUTE OF ENGINEERING AND MANAGEMENT, CSE, 2ND YEAR , 7365974880\r\nKHAYRUL SHAH , ALIAH UNIVERSITY, PHYSICS, 2ND YEAR, 7319458518\r\nHYATUL SEIKH, ALIAH UNIVERSITY , PHYSICS, 2ND YEAR, 9733737035", "hardwareProjectCategories": ["Robotics", "Drone / Autonomous Systems", "AI-Enabled Hardware", "Automation & Control"], "prototypeType": "Robotic System", "hasWorkingPrototype": "no_prototype", "currentWorkingStatus": "Functional under controlled conditions", "problemStatement": "Problem Statement: Early-stage fire containment and toxic gas detection in industrial, commercial, and residential environments require rapid autonomous intervention. Traditional safety systems rely on basic infrared flame sensors and cellular GSM modules. However, standard IR sensors suffer from high false-positive rates due to ambient sunlight or reflections and lack spatial orientation. Additionally, GSM modules incur recurring costs and fail inside reinforced structures.\r\n\r\nSolution: HydroBot-AI is an autonomous edge-AI vision and sensor-fusion rover for real-time fire suppression and hazardous gas monitoring. It features a dual-brain architecture: a Raspberry Pi running offline deep learning YOLOv8-Nano for computer vision, paired with an ESP32 microcontroller managing motor kinematics, servo aiming, and wireless telemetry. Upon detecting a hazard, the rover navigates to the source, uses a 2-axis metal-gear servo turret to lock onto the flame base, and activates a high-pressure 12V diaphragm pump to extinguish the fire.\r\n\r\nInnovation Details: 100% offline edge-AI processing runs local deep-learning flame and smoke detection without cloud dependency. Dual-interlock false alarm elimination combines visual YOLO bounding boxes with an MLX90614 thermal sensor and an MQ-2 gas sensor for high accuracy. High-efficiency MOSFET actuation uses TB6612FNG and IRF520 modules to eliminate voltage drops and maximize torque and pressure. Zero-tariff Wi-Fi IoT telemetry replaces cellular SIM hardware with asynchronous MQTT protocols over local Wi-Fi to broadcast real-time sensor metrics and alerts with zero ongoing fees.", "solutionDescription": "Problem Statement: Early-stage fire containment and toxic gas detection in industrial, commercial, and residential environments require rapid autonomous intervention. Traditional safety systems rely on basic infrared flame sensors and cellular GSM modules. However, standard IR sensors suffer from high false-positive rates due to ambient sunlight or reflections and lack spatial orientation. Additionally, GSM modules incur recurring costs and fail inside reinforced structures.\r\n\r\nSolution: HydroBot-AI is an autonomous edge-AI vision and sensor-fusion rover for real-time fire suppression and hazardous gas monitoring. It features a dual-brain architecture: a Raspberry Pi running offline deep learning YOLOv8-Nano for computer vision, paired with an ESP32 microcontroller managing motor kinematics, servo aiming, and wireless telemetry. Upon detecting a hazard, the rover navigates to the source, uses a 2-axis metal-gear servo turret to lock onto the flame base, and activates a high-pressure 12V diaphragm pump to extinguish the fire.\r\n\r\nInnovation Details: 100% offline edge-AI processing runs local deep-learning flame and smoke detection without cloud dependency. Dual-interlock false alarm elimination combines visual YOLO bounding boxes with an MLX90614 thermal sensor and an MQ-2 gas sensor for high accuracy. High-efficiency MOSFET actuation uses TB6612FNG and IRF520 modules to eliminate voltage drops and maximize torque and pressure. Zero-tariff Wi-Fi IoT telemetry replaces cellular SIM hardware with asynchronous MQTT protocols over local Wi-Fi to broadcast real-time sensor metrics and alerts with zero ongoing fees.", "innovationDescription": "Problem Statement: Early-stage fire containment and toxic gas detection in industrial, commercial, and residential environments require rapid autonomous intervention. Traditional safety systems rely on basic infrared flame sensors and cellular GSM modules. However, standard IR sensors suffer from high false-positive rates due to ambient sunlight or reflections and lack spatial orientation. Additionally, GSM modules incur recurring costs and fail inside reinforced structures.\r\n\r\nSolution: HydroBot-AI is an autonomous edge-AI vision and sensor-fusion rover for real-time fire suppression and hazardous gas monitoring. It features a dual-brain architecture: a Raspberry Pi running offline deep learning YOLOv8-Nano for computer vision, paired with an ESP32 microcontroller managing motor kinematics, servo aiming, and wireless telemetry. Upon detecting a hazard, the rover navigates to the source, uses a 2-axis metal-gear servo turret to lock onto the flame base, and activates a high-pressure 12V diaphragm pump to extinguish the fire.\r\n\r\nInnovation Details: 100% offline edge-AI processing runs local deep-learning flame and smoke detection without cloud dependency. Dual-interlock false alarm elimination combines visual YOLO bounding boxes with an MLX90614 thermal sensor and an MQ-2 gas sensor for high accuracy. High-efficiency MOSFET actuation uses TB6612FNG and IRF520 modules to eliminate voltage drops and maximize torque and pressure. Zero-tariff Wi-Fi IoT telemetry replaces cellular SIM hardware with asynchronous MQTT protocols over local Wi-Fi to broadcast real-time sensor metrics and alerts with zero ongoing fees.", "workingPrinciple": "HydroBot-AI operates on a dual-brain edge computing workflow. The Raspberry Pi runs a quantized YOLOv8-Nano model offline to detect flames and smoke from video frames. It calculates the target centroid coordinates and sends them via UART serial to the ESP32 microcontroller. The ESP32 drives the motor driver to navigate toward the hazard, positions a 2-axis servo turret to aim the water nozzle, verifies the threat using thermal and gas sensors, and activates the high-pressure water pump while broadcasting Wi-Fi alerts.", "majorHardwareComponents": ["Raspberry Pi 4", "ESP32 DevKit V1 microcontroller", "wide-angle camera", "TB6612FNG motor driver", "4WD chassis and gear motors", "two MG90S metal-gear servos", "MLX90614 infrared thermal sensor", "MQ-2 gas sensor", "HC-SR04 ultrasonic sensors", "12V R385 diaphragm pump", "IRF520 MOSFET module", "XL4015 buck converter", "and 3S 12.6V li-ion battery pack with BMS."], "useAi": true, "useIot": true, "powerSource": "battery", "intendedBeneficiaries": ["General Public", "Industry"], "potentialImpact": "This project benefits industrial warehouses, laboratories, chemical plants, and residential buildings by providing rapid, automated early-stage fire containment and hazardous gas leak detection. It eliminates human risk by deploying an unmanned rover into dangerous or toxic environments before emergency services arrive, reducing property damage and preventing catastrophic accidents.", "productPotential": "yes", "prototypeDevelopmentCost": 15000, "auraDemoHighlight": "HydroBot-AI solves the high false-positive rates of traditional IR sensors by combining offline deep-learning computer vision with contactless thermal and gas sensor fusion. It operates 100 percent offline without cloud dependency, features a high-efficiency MOSFET-driven suppression mechanism, and delivers instant Wi-Fi IoT alerts with zero ongoing cellular SIM costs.", "safetyHazards": ["water_near_electrical_equipment"], "safetyPrecautions": "Safety Precautions Taken: The prototype incorporates a 3S 12.6V lithium-ion battery pack protected by a 20A BMS board to prevent overcharging, short-circuiting, and thermal runaway. All electrical and electronic components are isolated from the water tank and tubing to protect against moisture exposure. The high-pressure water pump is controlled via a solid-state IRF520 MOSFET module with built-in switching isolation, and the system operates on a safe, regulated 5V low-voltage logic level for all microcontrollers and sensors.", "requiresContinuousSupervision": false, "prototypeDevelopedByTeam": "yes", "previouslyExhibited": false, "previousExhibitionDetails": "", "registrationFeeStatus": "no_fee", "registrationFee": 0, "createdAt": "2026-10-26T18:29:24.003Z", "updatedAt": "2026-10-26T18:31:24.089Z", "abstract": { "originalName": "AURA 2K26 Abstract - HydroBot-AI.pdf", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039363/aura-registrations/abstract-docs/AURA%202K26%20Abstract%20-%20HydroBot-AI.pdf", "filename": "Abstract.pdf", "relPath": "assets/Teams/SHOWTIME/Abstract.pdf", "isDocx": false, "exists": true }, "idCards": [{ "slot": 1, "filename": "1.jpg", "relPath": "assets/Teams/SHOWTIME/1.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039362/aura-registrations/id-cards/mv5oecvnzaqod40gfd93.jpg", "exists": true }, { "slot": 2, "filename": "2.jpg", "relPath": "assets/Teams/SHOWTIME/2.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039363/aura-registrations/id-cards/zdtdagtqyrujb4nnrej8.jpg", "exists": true }, { "slot": 3, "filename": "3.jpg", "relPath": "assets/Teams/SHOWTIME/3.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039363/aura-registrations/id-cards/jw35ohpguvxagqyr7lnt.png", "exists": true }, { "slot": 4, "filename": "4.jpg", "relPath": "assets/Teams/SHOWTIME/4.jpg", "url": "https://res.cloudinary.com/dxkje9whm/image/upload/v1793039363/aura-registrations/id-cards/cgahkrqqdyp9cyoun249.jpg", "exists": true }] }];